// ============================================
// REGISTRATION WIZARD FUNCTIONS
// ============================================
function openRegistrationWizard() {
    // Collect signup data
    const name = document.getElementById('signupName').value;
    const phone = document.getElementById('signupPhone').value;
    const email = document.getElementById('signupEmail').value;
    const nida = document.getElementById('signupNida').value;
    const formIndex = document.getElementById('signupFormIndex').value;
    const password = document.getElementById('signupPassword').value;
    const confirmPassword = document.getElementById('signupConfirmPassword').value;
    
    if (!name || !phone || !email || !password) {
        alert('Tafadhali jaza sehemu zote muhimu');
        return;
    }
    
    if (password !== confirmPassword) {
        alert('Nenosiri hazifanani');
        return;
    }
    
    if (password.length < 6) {
        alert('Nenosiri lazima iwe na herufi 6 au zaidi');
        return;
    }
    
    signupTempData = { name, phone, email, nida, formIndex, password };
    
    // Close auth modal and open wizard
    closeAuthWindow();
    document.getElementById('registrationWizard').style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

function closeRegistrationWizard() {
    document.getElementById('registrationWizard').style.display = 'none';
    document.body.style.overflow = 'auto';
    signupTempData = {};
}

// Handle Kin Form Submission
document.getElementById('kinForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const kin1 = {
        name: document.getElementById('kin1Name').value,
        relationship: document.getElementById('kin1Relationship').value,
        phone: document.getElementById('kin1Phone').value,
        email: document.getElementById('kin1Email').value
    };
    
    const kin2 = document.getElementById('kin2Name').value ? {
        name: document.getElementById('kin2Name').value,
        relationship: document.getElementById('kin2Relationship').value,
        phone: document.getElementById('kin2Phone').value,
        email: document.getElementById('kin2Email').value
    } : null;
    
    const kin3 = document.getElementById('kin3Name').value ? {
        name: document.getElementById('kin3Name').value,
        relationship: document.getElementById('kin3Relationship').value,
        phone: document.getElementById('kin3Phone').value,
        email: document.getElementById('kin3Email').value
    } : null;
    
    try {
        // Create user in Firebase Auth
        const userCredential = await auth.createUserWithEmailAndPassword(signupTempData.email, signupTempData.password);
        const user = userCredential.user;
        
        // Save user data to Firestore with pending approval status
        await db.collection('users').doc(user.uid).set({
            name: signupTempData.name,
            phone: signupTempData.phone,
            email: signupTempData.email,
            nida: signupTempData.nida || '',
            formIndex: signupTempData.formIndex || '',
            role: 'user',
            status: 'pending', // pending approval
            kin1: kin1,
            kin2: kin2,
            kin3: kin3,
            enrolledCourses: [],
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        // Create notification for admin
        await db.collection('notifications').add({
            type: 'student_registration',
            message: `Mwanafunzi mpya ${signupTempData.name} amejisajili na anasubiri idhini`,
            userId: user.uid,
            userName: signupTempData.name,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            read: false
        });
        
        alert('Usajili wako umepokelewa! Utapitia idhini na utaarifiwa baada ya kukubaliwa.');
        closeRegistrationWizard();
        
        // Sign out until approved
        await auth.signOut();
        
    } catch (error) {
        console.error('Registration error:', error);
        alert('Kosa: ' + error.message);
    }
});

let isFirstLoad = true;

if (auth) {
    auth.onAuthStateChanged(async (user) => {
                    try {
                        if (user) {
                            console.log('User detected:', user.uid);
                            
                            // Only check explicit login flag
                            const explicitLogin = sessionStorage.getItem('explicitLogin') === 'true';
                            
                            // If NOT explicit login AND there's no currentUser in localStorage, sign out
                            // This allows page refreshes while keeping the session
                            const storedUser = localStorage.getItem('currentUser');
                            
                            if (!explicitLogin && isFirstLoad && !storedUser) {
                                console.log('First load with no stored user - signing out');
                                sessionStorage.clear();
                                await auth.signOut();
                                return;
                            }
                            
                            // Clear the explicit login flag after processing
                            sessionStorage.removeItem('explicitLogin');
                            isFirstLoad = false;
                
                // Get user document
                const userDocRef = db.collection('users').doc(user.uid);
                const userDoc = await userDocRef.get();
                
                if (!userDoc.exists) {
                    console.log('User document not found, signing out');
                    await auth.signOut();
                    showToast('Taarifa zako hazikupatikana. Tafadhali wasiliana na Admin.', 'error');
                    return;
                }
                
                const userData = userDoc.data();
                const userStatus = userData.status || 'pending';
                const userRole = userData.role || 'user';
                
                console.log('User data:', { role: userRole, status: userStatus });
                
                // ============================================
                // STATUS CHECK - ONLY REJECT "pending" for 'user' role
                // ============================================
                if (userStatus === 'pending') {
                    // ONLY show alert and sign out for regular users (students)
                    if (userRole === 'user') {
                        showToast('Akaunti yako inasubiri idhini kutoka kwa Admin. Tafadhali subiri au wasiliana na ofisi.', 'warning');
                        await auth.signOut();
                        return;
                    } else {
                        // Auto-approve for staff, admin, superadmin
                        console.log(`Auto-approving ${userRole} account:`, user.uid);
                        await db.collection('users').doc(user.uid).update({
                            status: 'approved',
                            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                        });
                        userData.status = 'approved';
                    }
                }
                
                if (userStatus === 'rejected') {
                    showToast('Samahani, akaunti yako haikukubaliwa. Tafadhali wasiliana na ofisi.', 'error');
                    await auth.signOut();
                    return;
                }
                
                // Set current user
                currentUser = { uid: user.uid, ...userData };
                localStorage.setItem('currentUser', JSON.stringify(currentUser));
                
                console.log('Current user set:', currentUser.role);
                
                // Update UI elements safely
                const authNavBtn = document.getElementById('authNavBtn');
                const userNavDropdown = document.getElementById('userNavDropdown');
                const userNameText = document.getElementById('userNameText');
                const mobileUserName = document.getElementById('mobileUserName');
                
                if (authNavBtn) authNavBtn.style.display = 'none';
                if (userNavDropdown) userNavDropdown.style.display = 'block';
                if (userNameText) userNameText.textContent = currentUser.name || currentUser.email;
                if (mobileUserName) mobileUserName.textContent = (currentUser.name || currentUser.email).split(' ')[0];
                
                // Close auth modal if open
                const authModal = document.getElementById('authModal');
                if (authModal) authModal.style.display = 'none';
                document.body.style.overflow = 'auto';
                
                // Show dashboard based on role
                console.log('Calling showDashboardByRole with role:', currentUser.role);
                showDashboardByRole(currentUser.role);
                
                // Update navigation avatars
                setTimeout(() => {
                    if (typeof updateNavigationAvatars === 'function') {
                        updateNavigationAvatars();
                    }
                    if (typeof updateAllAvatars === 'function') {
                        updateAllAvatars();
                    }
                }, 500);
                
            } else {
                // User is logged out
                console.log('User logged out');
                currentUser = null;
                localStorage.removeItem('currentUser');
                isFirstLoad = false;
                
                // Reset UI elements
                const authNavBtn = document.getElementById('authNavBtn');
                const userNavDropdown = document.getElementById('userNavDropdown');
                
                if (authNavBtn) authNavBtn.style.display = 'block';
                if (userNavDropdown) userNavDropdown.style.display = 'none';
                
                // Show home page
                const dashboards = document.querySelectorAll('.dashboard');
                const pages = document.querySelectorAll('.page');
                const homePage = document.getElementById('homePage');
                
                dashboards.forEach(dash => {
                    dash.classList.remove('active');
                    dash.style.display = 'none';
                });
                pages.forEach(page => {
                    page.classList.remove('active');
                    page.style.display = 'none';
                });
                if (homePage) {
                    homePage.classList.add('active');
                    homePage.style.display = 'block';
                }
            }
            
        } catch (error) {
            console.error('Auth state error:', error);
            
            if (error.code === 'permission-denied') {
                console.warn('Permission denied - Check Firestore rules');
                showToast('Tatizo la ruhusa kwenye mfumo. Wasiliana na Admin.', 'error');
            } else if (error.code === 'unavailable') {
                console.warn('Service unavailable - Check network connection');
                showToast('Hakuna muunganisho wa mtandao. Angalia intaneti yako.', 'error');
            } else {
                try {
                    if (auth && auth.signOut) {
                        await auth.signOut();
                    }
                } catch (signOutError) {
                    console.error('Error during sign out:', signOutError);
                }
            }
        }
    });
} else {
    console.error('Firebase Auth not initialized');
}

// ============================================
// SIGNUP FUNCTION - NO AUTO LOGIN
// ============================================
async function handleSignup() {
    const signupName = document.getElementById('signupName');
    const signupEmail = document.getElementById('signupEmail');
    const signupPhone = document.getElementById('signupPhone');
    const signupPassword = document.getElementById('signupPassword');
    const signupConfirmPassword = document.getElementById('signupConfirmPassword');
    
    if (!signupName || !signupEmail || !signupPhone || !signupPassword || !signupConfirmPassword) {
        alert('Tafadhali jaza sehemu zote');
        return;
    }
    
    const name = signupName.value;
    const email = signupEmail.value;
    const phone = signupPhone.value;
    const password = signupPassword.value;
    const confirmPassword = signupConfirmPassword.value;
    
    if (!name || !email || !phone || !password) {
        alert('Tafadhali jaza sehemu zote muhimu');
        return;
    }
    
    if (password !== confirmPassword) {
        alert('Nenosiri hazifanani');
        return;
    }
    
    if (password.length < 6) {
        alert('Nenosiri lazima iwe na herufi 6 au zaidi');
        return;
    }
    
    // Show loading state
    const signupBtn = document.querySelector('#signupForm .btn-auth');
    const originalText = signupBtn ? signupBtn.textContent : 'Jisajili';
    if (signupBtn) {
        signupBtn.textContent = 'Inaweka...';
        signupBtn.disabled = true;
    }
    
    try {
        // Create user
        const userCredential = await auth.createUserWithEmailAndPassword(email, password);
        const user = userCredential.user;
        
        // Save user data to Firestore
        await db.collection('users').doc(user.uid).set({
            name: name,
            phone: phone,
            email: email,
            role: 'user',
            status: 'pending',
            enrolledCourses: [],
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        // Sign out immediately after signup (no auto login)
        await auth.signOut();
        
        alert('Usajili umefanikiwa! Akaunti yako inasubiri idhini kutoka kwa Admin.\nUtajulishwa baada ya kukubaliwa.');
        
        // Clear form
        signupName.value = '';
        signupEmail.value = '';
        signupPhone.value = '';
        signupPassword.value = '';
        signupConfirmPassword.value = '';
        
        // Switch to login tab
        switchAuthTab('login');
        
    } catch (error) {
        console.error('Signup error:', error);
        
        let message = 'Kosa wakati wa usajili';
        if (error.code === 'email-already-in-use') {
            message = 'Barua pepe tayari inatumiwa na akaunti nyingine';
        } else if (error.code === 'invalid-email') {
            message = 'Barua pepe si sahihi';
        } else if (error.code === 'weak-password') {
            message = 'Nenosiri ni dhaifu. Tumia herufi 6 au zaidi';
        }
        alert(message);
        
    } finally {
        if (signupBtn) {
            signupBtn.textContent = originalText;
            signupBtn.disabled = false;
        }
    }
}

// ============================================
// LOGIN FUNCTION - FIXED
// ============================================
async function handleLogin() {
    const loginEmail = document.getElementById('loginEmail');
    const loginPassword = document.getElementById('loginPassword');
    
    if (!loginEmail || !loginPassword) {
        alert('Tafadhali jaza barua pepe na nenosiri');
        return;
    }
    
    const email = loginEmail.value.trim();
    const password = loginPassword.value;
    
    if (!email || !password) {
        alert('Tafadhali jaza barua pepe na nenosiri');
        return;
    }
    
    // Show loading state
    const loginBtn = document.querySelector('#loginForm .btn-auth');
    const originalText = loginBtn ? loginBtn.textContent : 'Ingia';
    if (loginBtn) {
        loginBtn.textContent = 'Inaingiza...';
        loginBtn.disabled = true;
    }
    
    try {
        // IMPORTANT: Set flag BEFORE login
        sessionStorage.setItem('explicitLogin', 'true');
        console.log('Login flag set');
        
        await auth.signInWithEmailAndPassword(email, password);
        console.log('Login successful');
        
        // Clear form
        if (loginEmail) loginEmail.value = '';
        if (loginPassword) loginPassword.value = '';
        
        // Close auth window
        closeAuthWindow();
        
    } catch (error) {
        console.error('Login error:', error);
        // Remove flag on error
        sessionStorage.removeItem('explicitLogin');
        
        let message = 'Barua pepe au nenosiri si sahihi';
        if (error.code === 'user-not-found') {
            message = 'Hakuna akaunti iliyopatikana kwa barua pepe hii';
        } else if (error.code === 'wrong-password') {
            message = 'Nenosiri si sahihi';
        } else if (error.code === 'too-many-requests') {
            message = 'Majaribio mengi sana. Jaribu tena baadaye';
        }
        alert(message);
        
    } finally {
        if (loginBtn) {
            loginBtn.textContent = originalText;
            loginBtn.disabled = false;
        }
    }
}

