function openAuthWindow() {
    const authModal = document.getElementById('authModal');
    if (authModal) {
        authModal.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }
}

function switchAuthTab(tab) {
    const tabs = document.querySelectorAll('.auth-tab');
    const forms = document.querySelectorAll('.auth-form');
    
    tabs.forEach(t => t.classList.remove('active'));
    forms.forEach(f => f.classList.remove('active'));
    
    if (tab === 'login') {
        tabs[0].classList.add('active');
        document.getElementById('loginForm').classList.add('active');
    } else {
        tabs[1].classList.add('active');
        document.getElementById('signupForm').classList.add('active');
    }
}

// ============================================
// LOGOUT FUNCTION - CLEAR SESSION
// ============================================
function logout() {
    // Clear all session data
    sessionStorage.clear();
    localStorage.removeItem('currentUser');
    
    auth.signOut()
        .then(() => {
            console.log('User logged out successfully');
            alert('Umetoka kikamilifu!');
            
            // Close any open dropdowns/menus
            closeUserDropdown();
            closeDashboardDropdown();
            closeHamburgerMenu();
            
            // Show home page
            const pages = document.querySelectorAll('.page');
            const homePage = document.getElementById('homePage');
            if (pages) pages.forEach(page => page.classList.remove('active'));
            if (homePage) homePage.classList.add('active');
            
            // Show login button in navigation
            const authNavBtn = document.getElementById('authNavBtn');
            if (authNavBtn) authNavBtn.style.display = 'block';
            
        })
        .catch((error) => {
            console.error('Logout error:', error);
            alert('Kosa wakati wa kutoka');
        });
}


// Toggle desktop nav dropdown - DON'T close mobile menu
function toggleNavDropdown(event, dropdownId) {
    event.preventDefault();
    event.stopPropagation();
    
    const dropdown = document.getElementById(dropdownId);
    const toggle = event.currentTarget;
    
    // Close all other dropdowns first
    document.querySelectorAll('.dropdown-submenu').forEach(menu => {
        if (menu.id !== dropdownId) {
            menu.classList.remove('show');
            const otherToggle = menu.closest('.nav-dropdown')?.querySelector('.dropdown-toggle');
            if (otherToggle) otherToggle.classList.remove('active');
        }
    });
    
    // Toggle current dropdown
    if (dropdown.classList.contains('show')) {
        dropdown.classList.remove('show');
        toggle.classList.remove('active');
    } else {
        dropdown.classList.add('show');
        toggle.classList.add('active');
    }
}

// Toggle mobile section - DON'T close mobile menu
function toggleMobileSection(event, sectionId) {
    event.preventDefault();
    event.stopPropagation();
    
    const section = document.getElementById(sectionId);
    const toggle = event.currentTarget;
    const icon = toggle.querySelector('.mobile-toggle-icon');
    
    // Close all other mobile sections first
    document.querySelectorAll('#userMobileMenu .mobile-submenu').forEach(menu => {
        if (menu.id !== sectionId) {
            menu.style.display = 'none';
            const otherToggle = menu.closest('.mobile-nav-section')?.querySelector('.mobile-toggle-icon');
            if (otherToggle) otherToggle.style.transform = 'rotate(0deg)';
        }
    });
    
    // Toggle current section
    if (section.style.display === 'none' || section.style.display === '') {
        section.style.display = 'block';
        if (icon) icon.style.transform = 'rotate(180deg)';
    } else {
        section.style.display = 'none';
        if (icon) icon.style.transform = 'rotate(0deg)';
    }
}

// Close desktop dropdowns when clicking outside
document.addEventListener('click', function(e) {
    if (!e.target.closest('.nav-dropdown')) {
        document.querySelectorAll('.dropdown-submenu').forEach(menu => {
            menu.classList.remove('show');
        });
        document.querySelectorAll('.dropdown-toggle').forEach(toggle => {
            toggle.classList.remove('active');
        });
    }
});

