// ============================================
// SHOW DASHBOARD BY ROLE - FIXED
// ============================================
function showDashboardByRole(role) {
    console.log('Showing dashboard for role:', role);
    
    // Hide all pages and dashboards first
    document.querySelectorAll('.page').forEach(page => {
        page.classList.remove('active');
        page.style.display = 'none';
    });
    document.querySelectorAll('.dashboard').forEach(dash => {
        dash.classList.remove('active');
        dash.style.display = 'none';
    });
    
    const userName = currentUser?.name || currentUser?.email || 'User';
    
    if (role === 'admin') {
        const dashboard = document.getElementById('adminDashboard');
        const homeTab = document.getElementById('adminHome');
        
        console.log('Admin dashboard element:', dashboard);
        
        if (dashboard) {
            dashboard.classList.add('active');
            dashboard.style.display = 'block';
            
            // Show home tab
            if (homeTab) {
                homeTab.classList.add('active');
                homeTab.style.display = 'block';
            }
            
            // Set admin name
            const nameEl = document.getElementById('adminName');
            const displayEl = document.getElementById('adminNameDisplay');
            const dropdownName = document.getElementById('adminDropdownName');
            
            if (nameEl) nameEl.textContent = userName;
            if (displayEl) displayEl.textContent = userName;
            if (dropdownName) dropdownName.textContent = userName.split(' ')[0];
            
            // Hide home page
            const homePage = document.getElementById('homePage');
            if (homePage) {
                homePage.classList.remove('active');
                homePage.style.display = 'none';
            }
            
            // Load admin data
            setTimeout(() => {
                loadAdminData();
            }, 300);
            
            console.log('✅ Admin dashboard shown');
        } else {
            console.error('❌ adminDashboard element not found in HTML');
        }
        
    } else if (role === 'superadmin') {
        const dashboard = document.getElementById('superadminDashboard');
        
        if (dashboard) {
            dashboard.classList.add('active');
            dashboard.style.display = 'block';
            
            const homeTab = document.getElementById('superHome');
            if (homeTab) {
                homeTab.classList.add('active');
                homeTab.style.display = 'block';
            }
            
            // Set names
            const nameEls = ['superAdminDropdownName', 'superAdminDropdownName2'];
            nameEls.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.textContent = userName.split(' ')[0];
            });
            
            setTimeout(() => {
                loadSuperAdminData();
            }, 300);
            
            console.log('✅ Superadmin dashboard shown');
        }
        
    } else if (role === 'staff') {
        const dashboard = document.getElementById('staffDashboard');
        if (dashboard) {
            dashboard.classList.add('active');
            dashboard.style.display = 'block';
            
            const nameEl = document.getElementById('staffName');
            const displayEl = document.getElementById('staffNameDisplay');
            const welcomeEl = document.getElementById('staffWelcomeName');
            const dropdownName = document.getElementById('staffDropdownName');
            
            if (nameEl) nameEl.textContent = userName;
            if (displayEl) displayEl.textContent = userName;
            if (welcomeEl) welcomeEl.textContent = userName;
            if (dropdownName) dropdownName.textContent = userName.split(' ')[0];
            
            setTimeout(() => {
                loadStaffData();
            }, 300);
        }
        
    } else if (role === 'user') {
        const dashboard = document.getElementById('userDashboard');
        if (dashboard) {
            dashboard.classList.add('active');
            dashboard.style.display = 'block';
            
            const nameEl = document.getElementById('userName');
            const displayEl = document.getElementById('userNameDisplay');
            const welcomeEl = document.getElementById('welcomeUserName');
            
            if (nameEl) nameEl.textContent = userName;
            if (displayEl) displayEl.textContent = userName;
            if (welcomeEl) welcomeEl.textContent = userName;
            
            setTimeout(() => {
                loadUserData();
            }, 300);
        }
    } else {
        console.warn('Unknown role:', role);
        const homePage = document.getElementById('homePage');
        if (homePage) {
            homePage.classList.add('active');
            homePage.style.display = 'block';
        }
    }
    
    // Close any open menus
    closeAllMobileMenus();
}

// ============================================
// HAMBURGER MENU FUNCTIONS
// ============================================
function closeHamburgerMenu() {
    const navLinks = document.getElementById('navLinks');
    if (navLinks && navLinks.classList.contains('active')) {
        navLinks.classList.remove('active');
    }
}

function toggleHamburgerMenu() {
    const navLinks = document.getElementById('navLinks');
    navLinks.classList.toggle('active');
}

function setupHamburgerAutoClose() {
    const navLinks = document.getElementById('navLinks');
    if (!navLinks) return;
    
    const allNavLinks = navLinks.querySelectorAll('a');
    allNavLinks.forEach(link => {
        link.addEventListener('click', () => closeHamburgerMenu());
    });
}

// ============================================
// USER PROFILE & SETTINGS
// ============================================
function showUserProfile() {
    showPage('userProfile');
    loadUserProfileContent();
}

function showUserSettings() {
    showPage('userSettings');
    loadUserSettingsContent();
}

function changePassword() {
    const newPassword = prompt('Weka nenosiri jipya (herufi 6+):');
    if (newPassword && newPassword.length >= 6) {
        auth.currentUser.updatePassword(newPassword)
            .then(() => alert('Nenosiri limebadilishwa kikamilifu!'))
            .catch(err => alert('Kosa: ' + err.message));
    } else if (newPassword) {
        alert('Nenosiri lazima iwe na herufi 6 au zaidi');
    }
}

