function showModuleEnrollSuccess(moduleName) {
    // Remove existing toasts
    document.querySelectorAll('.module-success-toast').forEach(t => t.remove());
    
    const toast = document.createElement('div');
    toast.className = 'module-success-toast';
    toast.innerHTML = `
        <div style="display:flex;align-items:center;gap:0.75rem;">
            <div style="width:40px;height:40px;background:#10b981;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;">
                <i class="fas fa-check" style="color:white;font-size:1.2rem;"></i>
            </div>
            <div>
                <strong style="display:block;font-size:0.9rem;color:#1e293b;">Imefanikiwa!</strong>
                <span style="font-size:0.8rem;color:#64748b;">Umejisajili kwenye moduli ya <strong>"${escapeHtml(moduleName)}"</strong></span>
            </div>
        </div>
    `;
    toast.style.cssText = `
        position:fixed;
        bottom:24px;
        right:24px;
        background:white;
        padding:1rem 1.25rem;
        border-radius:12px;
        box-shadow:0 10px 30px rgba(0,0,0,0.15);
        z-index:9999;
        animation:slideInToast 0.3s ease;
        border-left:4px solid #10b981;
        max-width:400px;
    `;
    
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideOutToast 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

