// ============================================
// LOAD USER TEST RESULTS - UPDATED (Shows marked tests)
// ============================================

async function loadUserTestResults() {
    console.log("Loading user test results...");
    
    const container = document.getElementById('userTestResultsList');
    if (!container) {
        console.error("userTestResultsList element not found");
        return;
    }
    
    if (!currentUser) {
        console.error("No current user");
        container.innerHTML = '<p class="text-center">Hakuna mtumiaji aliyeingia</p>';
        return;
    }
    
    container.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> Inapakia matokeo yako...</div>';
    
    try {
        // Get BOTH exam results AND coursework
        const results = [];
        
        // 1. Get marked exam submissions
        const examSnapshot = await db.collection('examSubmissions')
            .where('studentId', '==', currentUser.uid)
            .where('status', '==', 'marked')
            .get();
        
        examSnapshot.forEach(doc => {
            const data = doc.data();
            results.push({
                id: doc.id,
                type: 'exam',
                title: data.examTitle || 'Mtihani',
                moduleCode: data.moduleCode || 'N/A',
                score: data.score || 0,
                totalMarks: data.totalMarks || 100,
                percentage: data.totalMarks > 0 ? Math.round((data.score / data.totalMarks) * 100) : 0,
                date: data.markedAt?.toDate?.() || data.submittedAt?.toDate?.() || new Date(),
                remarks: data.remarks || '',
                status: 'marked'
            });
        });
        
        // 2. Get coursework results
        const courseworkSnapshot = await db.collection('coursework')
            .where('studentId', '==', currentUser.uid)
            .get();
        
        courseworkSnapshot.forEach(doc => {
            const data = doc.data();
            results.push({
                id: doc.id,
                type: 'coursework',
                title: data.title || data.courseworkTitle || 'Coursework',
                moduleCode: data.moduleCode || data.module || 'N/A',
                score: data.marks || data.score || 0,
                totalMarks: data.maxScore || data.totalMarks || 100,
                percentage: (data.maxScore || data.totalMarks || 100) > 0 ? 
                    Math.round(((data.marks || data.score || 0) / (data.maxScore || data.totalMarks || 100)) * 100) : 0,
                date: data.createdAt?.toDate?.() || new Date(),
                remarks: data.remarks || data.comment || '',
                status: data.status || 'submitted',
                courseworkType: data.type || ''
            });
        });
        
        // Sort by date (newest first)
        results.sort((a, b) => b.date - a.date);
        
        console.log(`Found ${results.length} test results for user`);
        
        if (results.length === 0) {
            container.innerHTML = `
                <div class="empty-state-box">
                    <i class="fas fa-clipboard-list"></i>
                    <h4>Hakuna Matokeo Bado</h4>
                    <p>Hakuna matokeo ya test au mtihani yaliyosahihishwa bado.</p>
                    <p class="hint">Matokeo yataonekana hapa mara baada ya mwalimu kusahihisha.</p>
                </div>`;
            return;
        }
        
        // Build table
        container.innerHTML = `
            <div class="table-wrapper">
                <table class="data-table">
                    <thead>
                        <tr>
                            <th width="50">#</th>
                            <th>Aina</th>
                            <th>Jina la Test/Mtihani</th>
                            <th width="100">Module</th>
                            <th width="100">Alama</th>
                            <th width="80">%</th>
                            <th width="100">Status</th>
                            <th width="100">Tarehe</th>
                            <th width="80">Kitendo</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${results.map((result, idx) => {
                            let typeBadge = '';
                            let statusBadge = '';
                            
                            if (result.type === 'exam') {
                                typeBadge = '<span class="type-badge type-exam">📝 Mtihani</span>';
                            } else {
                                const typeLabel = getTypeDisplay(result.courseworkType || '');
                                typeBadge = `<span class="type-badge ${typeLabel.class || ''}">📋 ${typeLabel.text || 'Coursework'}</span>`;
                            }
                            
                            // Status badge
                            if (result.percentage >= 80) {
                                statusBadge = '<span class="status-badge status-excellent">Bora</span>';
                            } else if (result.percentage >= 60) {
                                statusBadge = '<span class="status-badge status-good">Vizuri</span>';
                            } else if (result.percentage >= 40) {
                                statusBadge = '<span class="status-badge status-poor">Wastani</span>';
                            } else {
                                statusBadge = '<span class="status-badge status-bad">Fanya Vizuri</span>';
                            }
                            
                            const dateStr = result.date.toLocaleDateString('sw-TZ', {
                                year: 'numeric', month: 'short', day: 'numeric'
                            });
                            
                            return `
                                <tr>
                                    <td class="text-center">${idx + 1}</td>
                                    <td>${typeBadge}</td>
                                    <td><strong>${escapeHtml(result.title)}</strong></td>
                                    <td>${escapeHtml(result.moduleCode)}</td>
                                    <td><strong>${result.score}/${result.totalMarks}</strong></td>
                                    <td>
                                        <span class="percentage-badge ${result.percentage >= 60 ? 'good' : 'poor'}">
                                            ${result.percentage}%
                                        </span>
                                    </td>
                                    <td>${statusBadge}</td>
                                    <td>${dateStr}</td>
                                    <td class="text-center">
                                        <button class="btn-view btn-sm" onclick="viewUserTestDetail('${result.id}', '${result.type}')">
                                            <i class="fas fa-eye"></i>
                                        </button>
                                    </td>
                                </tr>
                            `;
                        }).join('')}
                    </tbody>
                </table>
            </div>
            
            <!-- Summary Stats -->
            <div class="test-summary-stats">
                <div class="summary-card">
                    <i class="fas fa-chart-line"></i>
                    <div>
                        <span class="summary-number">${results.length}</span>
                        <span class="summary-label">Jumla ya Mitihani</span>
                    </div>
                </div>
                <div class="summary-card">
                    <i class="fas fa-percentage"></i>
                    <div>
                        <span class="summary-number">
                            ${Math.round(results.reduce((sum, r) => sum + r.percentage, 0) / results.length)}%
                        </span>
                        <span class="summary-label">Wastani</span>
                    </div>
                </div>
            </div>
        `;
        
    } catch (error) {
        console.error("Error loading test results:", error);
        container.innerHTML = `<p class="text-center error-text">Kosa: ${error.message}</p>`;
    }
}

// ============================================
// VIEW USER TEST DETAIL
// ============================================
async function viewUserTestDetail(testId, testType) {
    try {
        let testData;
        
        if (testType === 'exam') {
            const doc = await db.collection('examSubmissions').doc(testId).get();
            if (!doc.exists) {
                showToast('Matokeo hayakupatikana', 'error');
                return;
            }
            testData = { id: doc.id, type: 'exam', ...doc.data() };
        } else {
            const doc = await db.collection('coursework').doc(testId).get();
            if (!doc.exists) {
                showToast('Matokeo hayakupatikana', 'error');
                return;
            }
            testData = { id: doc.id, type: 'coursework', ...doc.data() };
        }
        
        const modal = document.getElementById('userTestDetailModal');
        const content = document.getElementById('userTestDetailContent');
        
        if (!modal || !content) return;
        
        const score = testData.score || testData.marks || 0;
        const total = testData.totalMarks || testData.maxScore || 100;
        const percentage = total > 0 ? Math.round((score / total) * 100) : 0;
        
        let answersHtml = '';
        if (testData.answers && testData.answers.length > 0) {
            answersHtml = testData.answers.map((ans, idx) => {
                const isCorrect = ans.marksObtained >= ans.marks;
                const isPartial = ans.marksObtained > 0 && ans.marksObtained < ans.marks;
                
                let resultClass = isCorrect ? 'correct' : (isPartial ? 'partial' : 'wrong');
                let resultIcon = isCorrect ? '✅' : (isPartial ? '⚠️' : '❌');
                
                let answerDisplay = Array.isArray(ans.answer) ? 
                    ans.answer.map((a, i) => `${i + 1}. ${a || '-'}`).join('<br>') : 
                    (ans.answer || '<em>No answer</em>');
                
                return `
                    <div class="answer-item ${resultClass}">
                        <div class="answer-header">
                            <span>Q${idx + 1}</span>
                            <span class="result-icon">${resultIcon}</span>
                            <span>[${ans.marksObtained || 0}/${ans.marks}]</span>
                        </div>
                        <p><strong>Question:</strong> ${escapeHtml(ans.question)}</p>
                        <p><strong>Your Answer:</strong></p>
                        <div class="answer-box">${answerDisplay}</div>
                        ${ans.correctAnswer ? `<p><strong>Correct:</strong> ${escapeHtml(ans.correctAnswer)}</p>` : ''}
                        ${ans.remarks ? `<p><strong>Remarks:</strong> ${escapeHtml(ans.remarks)}</p>` : ''}
                    </div>
                `;
            }).join('');
        } else {
            answersHtml = '<p class="text-center">No detailed answers available</p>';
        }
        
        content.innerHTML = `
            <div class="test-detail-view">
                <h3>${escapeHtml(testData.examTitle || testData.title || 'Test')}</h3>
                <div class="test-meta">
                    <p><strong>Module:</strong> ${escapeHtml(testData.moduleCode || testData.module || 'N/A')}</p>
                    <p><strong>Score:</strong> <span class="score-highlight">${score}/${total}</span> (${percentage}%)</p>
                    <p><strong>Date:</strong> ${(testData.markedAt || testData.submittedAt || testData.createdAt)?.toDate?.()?.toLocaleDateString('sw-TZ') || '-'}</p>
                    ${testData.remarks ? `<p><strong>Remarks:</strong> ${escapeHtml(testData.remarks)}</p>` : ''}
                </div>
                <hr>
                <h4>Answers</h4>
                <div class="answers-list">
                    ${answersHtml}
                </div>
            </div>
        `;
        
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
        
    } catch (error) {
        console.error('Error viewing test detail:', error);
        showToast('Error: ' + error.message, 'error');
    }
}

function closeUserTestDetailModal() {
    document.getElementById('userTestDetailModal').classList.remove('active');
    document.body.style.overflow = '';
}

