// ============================================
// SHOW STAFF TAB - COMPLETE WITH MARKED TESTS
// ============================================
function showStaffTab(tabName) {
    console.log('Showing staff tab:', tabName);
    
    // Remove active class from all tabs
    document.querySelectorAll('#staffDashboard .dashboard-tab').forEach(function(t) {
        t.classList.remove('active');
        t.style.display = 'none';
    });
    
    // Remove active class from all sidebar buttons
    document.querySelectorAll('#staffDashboard .sidebar-btn').forEach(function(b) {
        b.classList.remove('active');
    });
    
    // Remove active class from nav links (mobile)
    document.querySelectorAll('#staffDashboard .nav-links a').forEach(function(b) {
        b.classList.remove('active');
    });
    
    // Activate selected tab
    var tab = document.getElementById(tabName);
    if (tab) {
        tab.classList.add('active');
        tab.style.display = 'block';
    }
    
    // Activate clicked button
    if (event && event.target) {
        var btn = event.target.closest('.sidebar-btn') || event.target.closest('a');
        if (btn) {
            btn.classList.add('active');
        }
    }
    
    // Close mobile menu if open
    var mobileMenu = document.getElementById('staffMobileMenu');
    var overlay = document.getElementById('staffOverlay');
    if (mobileMenu && mobileMenu.classList.contains('active')) {
        mobileMenu.classList.remove('active');
        if (overlay) overlay.classList.remove('active');
        document.body.style.overflow = '';
    }
    
    // Load data based on tab
    switch (tabName) {
        case 'staffHome':
            // Load home stats if needed
            break;
            
        case 'staffCoursework':
            loadStaffModules();
            loadCourseworkList();
            break;
            
        case 'staffExamResults':
            loadStaffModules();
            loadExamResults();
            break;
            
        case 'staffTimetable':
            loadStaffModules();
            loadTimetable();
            break;
            
        case 'staffProfile':
            loadStaffProfile();
            break;
            
        case 'staffExams':
            loadStaffModulesForSelect();
            loadAllExamData();
            break;
            
        case 'staffMarkedTests':
            loadMarkedExams();
            break;
            
        default:
            console.log('Unknown tab:', tabName);
    }
}



async function loadStaffModules() {
    const staffDoc = await db.collection('users').doc(currentUser.uid).get();
    const modules = staffDoc.data().assignedModules || [];
    
    // Populate module selects for forms
    const moduleSelects = ['courseworkModule', 'examModule', 'timetableModule'];
    moduleSelects.forEach(selectId => {
        const select = document.getElementById(selectId);
        if (select && selectId !== 'courseworkModule') { // courseworkModule is populated separately
            select.innerHTML = '<option value="">Chagua Module</option>';
            modules.forEach(module => {
                select.innerHTML += `<option value="${module.code}">${module.code} - ${module.name}</option>`;
            });
        }
    });
}

async function loadCoursework() {
    if (!currentUser) return;
    
    const container = document.getElementById('courseworkList');
    if (!container) return;
    
    container.innerHTML = '';
    
    try {
        // ============================================
        // FILTER: Only show coursework created by THIS staff member
        // ============================================
        const snapshot = await db.collection('coursework')
            .where('createdBy', '==', currentUser.uid)
            .orderBy('createdAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <div class="item-card" style="justify-content:center;">
                    <div class="item-info" style="text-align:center;">
                        <i class="fas fa-tasks" style="font-size:2rem;color:#94a3b8;margin-bottom:0.5rem;"></i>
                        <p>Hakuna coursework uliyoongeza</p>
                    </div>
                </div>`;
            return;
        }
        
        snapshot.forEach(doc => {
            const cw = doc.data();
            const typeInfo = getTypeDisplay(cw.type || '');
            const statusInfo = getStatusInfo(cw.status || '');
            
            container.innerHTML += `
                <div class="item-card">
                    <div class="item-info">
                        <h4>${escapeHtml(cw.studentName || '-')}</h4>
                        <p>Module: ${escapeHtml(cw.moduleCode || '-')}</p>
                        <p>Aina: <span class="type-badge ${typeInfo.class}">${typeInfo.text}</span></p>
                        <p>Alama: <strong>${cw.marks || '-'}</strong></p>
                        <p>Status: <span class="${statusInfo.class}">${statusInfo.text}</span></p>
                        <p>Tarehe: ${cw.createdAt?.toDate?.()?.toLocaleDateString() || '-'}</p>
                    </div>
                    <div class="item-actions">
                        <button class="btn-edit" onclick="editCoursework('${doc.id}')">Hariri</button>
                        <button class="btn-delete" onclick="deleteCoursework('${doc.id}')">Futa</button>
                    </div>
                </div>
            `;
        });
        
    } catch (error) {
        console.error('Error loading coursework:', error);
        container.innerHTML = '<p class="error-text">Kosa wakati wa kupakia coursework</p>';
    }
}

document.getElementById('courseworkForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const moduleCode = document.getElementById('courseworkModule').value;
    const studentId = document.getElementById('courseworkStudent').value;
    const type = document.getElementById('courseworkType').value;
    const marks = document.getElementById('courseworkMarks').value;
    const status = document.getElementById('courseworkStatus').value;
    
    if (!moduleCode || !studentId || !type || !marks || !status) {
        alert('Tafadhali jaza sehemu zote');
        return;
    }
    
    // Get student name
    const student = selectedModuleStudents.find(s => s.id === studentId);
    const studentName = student ? student.name : '';
    
    // Get module name
    const selectedModule = staffAssignedModules.find(m => m.code === moduleCode);
    const moduleName = selectedModule ? selectedModule.name : moduleCode;
    
    // Show loading
    const submitBtn = document.querySelector('#courseworkForm .btn-primary');
    const originalText = submitBtn?.textContent;
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        // ============================================
        // SAVE WITH createdBy AND createdByName
        // This ensures each staff only sees their own coursework
        // ============================================
        await db.collection('coursework').add({
            moduleCode: moduleCode,
            moduleName: moduleName,
            studentId: studentId,
            studentName: studentName,
            type: type,
            marks: parseFloat(marks),
            status: status,
            createdBy: currentUser.uid, // ← IMPORTANT: Staff who created this
            createdByName: currentUser.name, // ← IMPORTANT: Staff name
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ Coursework imehifadhiwa kikamilifu!', 'success');
        
        // Reset form
        document.getElementById('courseworkForm').reset();
        document.getElementById('courseworkStudent').innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
        
        // Refresh lists
        loadCourseworkList();
        loadUserCoursework();
        
    } catch (error) {
        console.error('Error saving coursework:', error);
        showToast('❌ Kosa wakati wa kuhifadhi: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-save"></i> Hifadhi Coursework';
        }
    }
});

async function deleteCoursework(id) {
    if (confirm('Futa coursework hii?')) {
        await db.collection('coursework').doc(id).delete();
        loadCoursework();
    }
}

async function editCoursework(id) {
    const newTitle = prompt('Hariri jina:');
    if (newTitle) {
        await db.collection('coursework').doc(id).update({ title: newTitle });
        loadCoursework();
    }
}

