async function loadExamResults() {
    // Check if the old container exists
    const oldContainer = document.getElementById('examResultsList');
    const newContainer = document.getElementById('savedResultsBody');
    
    // If old container doesn't exist, use new system
    if (!oldContainer) {
        console.log('Using new exam results system');
        // Load modules for results dropdown
        if (typeof loadModulesForResults === 'function') {
            await loadModulesForResults();
        }
        // Load saved results
        if (newContainer && typeof loadSavedExamResults === 'function') {
            await loadSavedExamResults();
        }
        return;
    }
    
    // Fallback to old system (if old container exists)
    try {
        const snapshot = await db.collection('examResults')
            .orderBy('createdAt', 'desc')
            .get();
        
        oldContainer.innerHTML = '';
        
        if (snapshot.empty) {
            oldContainer.innerHTML = '<p class="text-center">No exam results found</p>';
            return;
        }
        
        snapshot.forEach(doc => {
            const result = doc.data();
            oldContainer.innerHTML += `
                <div class="item-card">
                    <div class="item-info">
                        <h4>${escapeHtml(result.studentName || 'Unknown')}</h4>
                        <p>Module: ${escapeHtml(result.moduleCode || result.module || 'N/A')}</p>
                        <p>Score: ${result.score || result.finalScore || '-'}</p>
                        <p>Grade: ${result.grade || result.finalGrade || '-'}</p>
                        ${result.remarks ? `<p>Remarks: ${escapeHtml(result.remarks)}</p>` : ''}
                    </div>
                    <div class="item-actions">
                        <button class="btn-edit" onclick="editExamResult('${doc.id}')">Edit</button>
                        <button class="btn-delete" onclick="deleteExamResult('${doc.id}')">Delete</button>
                    </div>
                </div>
            `;
        });
        
    } catch (error) {
        console.error('Error loading exam results:', error);
        if (oldContainer) {
            oldContainer.innerHTML = '<p class="error-text">Error loading results</p>';
        }
    }
}

