// ALSO UPDATE loadStaffData TO BE SAFE
// ============================================
async function loadStaffData() {
    try {
        // Load modules for select dropdowns
        const staffDoc = await db.collection('users').doc(currentUser.uid).get();
        const staffModules = staffDoc.data()?.assignedModules || [];
        staffAssignedModules = staffModules;
        
        // Populate module selects
        const moduleSelects = ['courseworkModule', 'examModule', 'timetableModule', 'resultModuleSelect'];
        moduleSelects.forEach(selectId => {
            const select = document.getElementById(selectId);
            if (select) {
                select.innerHTML = '<option value="">-- Chagua Module --</option>';
                staffModules.forEach(module => {
                    select.innerHTML += `<option value="${module.code}">${module.code} - ${module.name}</option>`;
                });
            }
        });
        
        // Safe loading - only load if containers exist
        const promises = [];
        
        if (document.getElementById('courseworkList')) {
            promises.push(loadCourseworkList());
        }
        
        // Always call loadExamResults (it's now safe)
        promises.push(loadExamResults());
        
        if (document.getElementById('timetableList')) {
            promises.push(loadTimetable());
        }
        
        // Load staff profile if container exists
        const profileContainer = document.getElementById('staffProfileContent');
        if (profileContainer) {
            promises.push(loadStaffProfile());
        }
        
        await Promise.all(promises);
        
    } catch (error) {
        console.error('Error loading staff data:', error);
    }
}


