// ============================================
// HANDLE DATE TYPE CHANGE (Specific Date vs Recurring Day)
// ============================================
function handleTimetableDateTypeChange() {
    const dateType = document.getElementById('timetableDateType')?.value;
    const specificGroup = document.getElementById('specificDateGroup');
    const recurringGroup = document.getElementById('recurringDayGroup');
    
    if (dateType === 'specific') {
        if (specificGroup) specificGroup.style.display = 'block';
        if (recurringGroup) recurringGroup.style.display = 'none';
        document.getElementById('timetableDate').required = true;
        document.getElementById('timetableDay').required = false;
    } else if (dateType === 'recurring') {
        if (specificGroup) specificGroup.style.display = 'none';
        if (recurringGroup) recurringGroup.style.display = 'block';
        document.getElementById('timetableDate').required = false;
        document.getElementById('timetableDay').required = true;
    } else {
        if (specificGroup) specificGroup.style.display = 'none';
        if (recurringGroup) recurringGroup.style.display = 'none';
    }
}

// ============================================
// HANDLE TIMETABLE TYPE CHANGE
// ============================================
function handleTimetableTypeChange() {
    const type = document.getElementById('timetableType')?.value;
    const moduleGroup = document.getElementById('timetableModuleGroup');
    
    if (type === 'exam' || type === 'test') {
        if (moduleGroup) moduleGroup.style.display = 'block';
    }
    // Module group is always visible now
}

// ============================================
// LOAD TIMETABLE (Staff) - FILTER BY ASSIGNED MODULES
// ============================================
async function loadTimetable() {
    const container = document.getElementById('timetableList');
    if (!container) return;
    
    container.innerHTML = '<tr><td colspan="8" class="text-center"><div class="loading-spinner">Inapakia ratiba...</div></td></tr>';
    
    try {
        // First load staff modules for both dropdown and filtering
        await loadStaffModulesForTimetable();
        
        // Get staff's assigned module codes
        var staffModuleCodes = [];
        if (staffAssignedModules && staffAssignedModules.length > 0) {
            staffModuleCodes = staffAssignedModules.map(function(m) { return m.code; });
        }
        
        const snapshot = await db.collection('timetable')
            .orderBy('createdAt', 'desc')
            .get();
        
        allTimetableItems = [];
        snapshot.forEach(function(doc) {
            var item = { id: doc.id, ...doc.data() };
            
            // Check if this timetable entry matches staff's modules
            // Show if: module matches assigned module, OR no module specified, OR type is exam/test matching module
            var shouldShow = false;
            
            if (!item.module || item.module === '') {
                // General entry (no module) - show to all staff
                shouldShow = true;
            } else if (staffModuleCodes.indexOf(item.module) !== -1) {
                // Module matches staff's assigned module
                shouldShow = true;
            }
            
            if (shouldShow) {
                allTimetableItems.push(item);
            }
        });
        
        // Sort: recurring days first, then by date
        allTimetableItems.sort(function(a, b) {
            if (a.dateType === 'recurring' && b.dateType !== 'recurring') return -1;
            if (a.dateType !== 'recurring' && b.dateType === 'recurring') return 1;
            
            if (a.dateType === 'recurring' && b.dateType === 'recurring') {
                var days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
                return days.indexOf(a.day) - days.indexOf(b.day);
            }
            
            var dateA = a.date && a.date.toDate ? a.date.toDate() : new Date(a.date || 0);
            var dateB = b.date && b.date.toDate ? b.date.toDate() : new Date(b.date || 0);
            return dateA - dateB;
        });
        
        document.getElementById('timetableItemCount').textContent = allTimetableItems.length;
        
        if (allTimetableItems.length === 0) {
            container.innerHTML = '<tr><td colspan="8" class="text-center">Hakuna ratiba kwa modules zako</td></tr>';
            return;
        }
        
        timetableFilterType = 'all';
        renderTimetableList(allTimetableItems);
        
    } catch (error) {
        console.error('Error loading timetable:', error);
        container.innerHTML = '<tr><td colspan="8" class="text-center error-text">Kosa: ' + error.message + '</td></tr>';
    }
}

// ============================================
// LOAD STAFF MODULES FOR TIMETABLE DROPDOWN
// ============================================
async function loadStaffModulesForTimetable() {
    if (!currentUser) return;
    
    try {
        const staffDoc = await db.collection('users').doc(currentUser.uid).get();
        const modules = staffDoc.data()?.assignedModules || [];
        staffAssignedModules = modules;
        
        // Populate timetable module dropdown
        const moduleSelect = document.getElementById('timetableModule');
        if (moduleSelect) {
            moduleSelect.innerHTML = '<option value="">-- Chagua Module (si lazima) --</option>';
            modules.forEach(function(module) {
                moduleSelect.innerHTML += '<option value="' + module.code + '">' + module.code + ' - ' + module.name + '</option>';
            });
        }
    } catch (error) {
        console.error('Error loading staff modules:', error);
    }
}

// ============================================
// AUTO-LOAD MODULE STAFF WHEN MODULE IS SELECTED
// ============================================
async function autoLoadModuleStaff() {
    var moduleCode = document.getElementById('timetableModule')?.value;
    var facilitatorInput = document.getElementById('timetableFacilitator');
    var staffHint = document.getElementById('timetableStaffHint');
    
    if (!moduleCode || !facilitatorInput) return;
    
    // Clear previous hint
    if (staffHint) staffHint.innerHTML = '';
    
    // If no module selected, don't auto-fill
    if (!moduleCode) {
        facilitatorInput.value = '';
        facilitatorInput.placeholder = 'Jina la mwalimu au msimamizi';
        return;
    }
    
    try {
        // Find the module document
        var moduleQuery = await db.collection('modules')
            .where('code', '==', moduleCode)
            .where('active', '==', true)
            .get();
        
        if (moduleQuery.empty) {
            facilitatorInput.placeholder = 'Jina la mwalimu au msimamizi';
            return;
        }
        
        var moduleData = moduleQuery.docs[0].data();
        var staffIds = moduleData.staffIds || [];
        
        if (staffIds.length === 0) {
            facilitatorInput.placeholder = 'Jina la mwalimu au msimamizi (hakuna staff aliyepangiwa moduli hii)';
            if (staffHint) {
                staffHint.innerHTML = '<i class="fas fa-info-circle"></i> Hakuna mwalimu aliyepangiwa moduli hii. Weka jina mwenyewe.';
                staffHint.style.color = '#f59e0b';
            }
            return;
        }
        
        // Fetch staff names
        var staffNames = [];
        for (var i = 0; i < staffIds.length; i++) {
            try {
                var staffDoc = await db.collection('users').doc(staffIds[i]).get();
                if (staffDoc.exists) {
                    staffNames.push(staffDoc.data().name || 'Unknown');
                }
            } catch (e) {
                console.log('Error fetching staff:', staffIds[i]);
            }
        }
        
        if (staffNames.length > 0) {
            // Auto-fill the facilitator field with staff names
            facilitatorInput.value = staffNames.join(', ');
            
            if (staffHint) {
                staffHint.innerHTML = '<i class="fas fa-check-circle"></i> Mwalimu amepakiwa kiotomatiki kutoka moduli. Unaweza kubadilisha kama inahitajika.';
                staffHint.style.color = '#10b981';
            }
        } else {
            facilitatorInput.placeholder = 'Jina la mwalimu au msimamizi';
        }
        
    } catch (error) {
        console.error('Error loading module staff:', error);
    }
}

// ============================================
// RENDER TIMETABLE LIST
// ============================================
function renderTimetableList(items) {
    const container = document.getElementById('timetableList');
    if (!container) return;
    
    document.getElementById('timetableItemCount').textContent = items.length;
    
    if (!items || items.length === 0) {
        container.innerHTML = '<tr><td colspan="8" class="text-center">Hakuna ratiba inayofanana na vigezo vilivyochaguliwa</td></tr>';
        return;
    }
    
    function fmtDate(dateValue) {
        if (!dateValue) return '-';
        var date;
        if (dateValue.toDate) {
            date = dateValue.toDate();
        } else if (dateValue instanceof Date) {
            date = dateValue;
        } else {
            return String(dateValue);
        }
        return date.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric', weekday: 'short'
        });
    }
    
    container.innerHTML = items.map((item, idx) => {
        const time = item.time || '-';
        const activity = item.activity || 'Shughuli';
        const module = item.module || '-';
        const facilitator = item.facilitator || '-';
        const type = item.type || 'class';
        const dateType = item.dateType || 'specific';
        
        // Date display
        let dateDisplay = '';
        let isToday = false;
        
        if (dateType === 'recurring' && item.day) {
            // Recurring day
            const dayNames = {
                'Monday': 'Jumatatu', 'Tuesday': 'Jumanne', 'Wednesday': 'Jumatano',
                'Thursday': 'Alhamisi', 'Friday': 'Ijumaa', 'Saturday': 'Jumamosi', 'Sunday': 'Jumapili'
            };
            const today = new Date();
            const todayDay = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][today.getDay()];
            isToday = (item.day === todayDay);
            
            dateDisplay = `
                <span class="recurring-date">
                    <i class="fas fa-sync-alt recurring-icon"></i>
                    <strong>${dayNames[item.day] || item.day}</strong>
                    <br><span class="recurring-badge">Kila Wiki</span>
                    ${isToday ? '<br><span class="today-badge">Leo</span>' : ''}
                </span>
            `;
        } else {
            // Specific date
            const date = fmtDate(item.date);
            if (item.date) {
                var itemDate = item.date.toDate ? item.date.toDate() : new Date(item.date);
                var today = new Date();
                isToday = itemDate.toDateString() === today.toDateString();
            }
            
            dateDisplay = `
                <span class="date-display">
                    <strong>${date}</strong>
                    ${isToday ? '<br><span class="today-badge">Leo</span>' : ''}
                </span>
            `;
        }
        
        // Type display
        const typeMap = {
            'class': { label: '📚 Somo', class: 'type-class' },
            'exam': { label: '📝 Mtihani', class: 'type-exam' },
            'test': { label: '📋 Test', class: 'type-test' },
            'activity': { label: '🎯 Shughuli', class: 'type-activity' },
            'meeting': { label: '👥 Mkutano', class: 'type-meeting' },
            'workshop': { label: '🔧 Warsha', class: 'type-workshop' },
            'other': { label: '📌 Nyingine', class: 'type-other' }
        };
        
        const typeInfo = typeMap[type] || { label: type, class: '' };
        
        return `
            <tr class="${isToday ? 'timetable-today-row' : ''} ${dateType === 'recurring' ? 'recurring-row' : ''}">
                <td class="text-center">${idx + 1}</td>
                <td class="text-center">
                    ${dateDisplay}
                </td>
                <td class="text-center">
                    <span class="time-display">
                        <i class="far fa-clock"></i> ${escapeHtml(time)}
                    </span>
                </td>
                <td>
                    <div class="activity-info">
                        <strong>${escapeHtml(activity)}</strong>
                        ${item.description ? `<br><small class="text-muted">${escapeHtml(item.description).substring(0, 60)}</small>` : ''}
                        ${item.venue ? `<br><small class="venue-text"><i class="fas fa-map-marker-alt"></i> ${escapeHtml(item.venue)}</small>` : ''}
                    </div>
                </td>
                <td>
                    ${module !== '-' ? `<span class="module-tag-small">${escapeHtml(module)}</span>` : '<span class="text-muted">-</span>'}
                </td>
                <td>
                    <span class="facilitator-text">
                        <i class="fas fa-user"></i> ${escapeHtml(facilitator)}
                    </span>
                </td>
                <td class="text-center">
                    <span class="type-badge ${typeInfo.class}">${typeInfo.label}</span>
                </td>
                <td class="text-center">
                    <div style="display:flex;gap:0.3rem;justify-content:center;">
                        <button class="btn-edit btn-sm" onclick="editTimetableItem('${item.id}')" title="Hariri">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="btn-delete btn-sm" onclick="deleteTimetableItem('${item.id}')" title="Futa">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

// ============================================
// SAVE TIMETABLE (Add/Edit) - WITH RECURRING SUPPORT
// ============================================
document.getElementById('timetableForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const editId = document.getElementById('timetableEditId').value;
    const type = document.getElementById('timetableType').value;
    const dateType = document.getElementById('timetableDateType').value;
    const date = document.getElementById('timetableDate').value;
    const day = document.getElementById('timetableDay').value;
    const time = document.getElementById('timetableTime').value.trim();
    const duration = document.getElementById('timetableDuration').value.trim();
    const activity = document.getElementById('timetableActivity').value.trim();
    const module = document.getElementById('timetableModule').value;
    const facilitator = document.getElementById('timetableFacilitator').value.trim();
    const venue = document.getElementById('timetableVenue').value.trim();
    const group = document.getElementById('timetableGroup').value.trim();
    const description = document.getElementById('timetableDescription').value.trim();
    
    // Validation
    if (!type) { showToast('Tafadhali chagua aina ya shughuli', 'error'); return; }
    if (!dateType) { showToast('Tafadhali chagua aina ya tarehe', 'error'); return; }
    if (!time) { showToast('Tafadhali weka muda', 'error'); return; }
    if (!activity) { showToast('Tafadhali weka jina la shughuli', 'error'); return; }
    
    if (dateType === 'specific' && !date) {
        showToast('Tafadhali chagua tarehe', 'error'); return;
    }
    if (dateType === 'recurring' && !day) {
        showToast('Tafadhali chagua siku', 'error'); return;
    }
    
    const submitBtn = document.getElementById('timetableSubmitBtn');
    const originalText = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    
    try {
        const timetableData = {
            type: type,
            dateType: dateType,
            time: time,
            duration: duration || '',
            activity: activity,
            module: module || '',
            facilitator: facilitator || '',
            venue: venue || '',
            group: group || '',
            description: description || '',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (dateType === 'specific') {
            timetableData.date = firebase.firestore.Timestamp.fromDate(new Date(date));
            timetableData.day = '';
        } else {
            timetableData.day = day;
            timetableData.date = null;
        }
        
        if (editId) {
            await db.collection('timetable').doc(editId).update(timetableData);
            showToast('✅ Ratiba imesasishwa!', 'success');
        } else {
            timetableData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            timetableData.createdBy = currentUser ? currentUser.uid : 'unknown';
            await db.collection('timetable').add(timetableData);
            showToast('✅ Ratiba imeongezwa!', 'success');
        }
        
        resetTimetableForm();
        await loadTimetable();
        
    } catch (error) {
        console.error('Error saving timetable:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    } finally {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalText;
    }
});

// ============================================
// EDIT TIMETABLE ITEM - WITH STAFF AUTO-LOAD
// ============================================
async function editTimetableItem(id) {
    var item = allTimetableItems.find(function(i) { return i.id === id; });
    if (!item) {
        showToast('Ratiba haikupatikana', 'error');
        return;
    }
    
    // Populate form
    document.getElementById('timetableEditId').value = id;
    document.getElementById('timetableType').value = item.type || 'class';
    document.getElementById('timetableDateType').value = item.dateType || 'specific';
    document.getElementById('timetableTime').value = item.time || '';
    document.getElementById('timetableDuration').value = item.duration || '';
    document.getElementById('timetableActivity').value = item.activity || '';
    document.getElementById('timetableModule').value = item.module || '';
    document.getElementById('timetableFacilitator').value = item.facilitator || '';
    document.getElementById('timetableVenue').value = item.venue || '';
    document.getElementById('timetableGroup').value = item.group || '';
    document.getElementById('timetableDescription').value = item.description || '';
    
    // Set date or day
    if (item.dateType === 'recurring' && item.day) {
        document.getElementById('timetableDay').value = item.day;
    } else if (item.date) {
        var d = item.date.toDate ? item.date.toDate() : new Date(item.date);
        document.getElementById('timetableDate').value = d.toISOString().split('T')[0];
    }
    
    handleTimetableDateTypeChange();
    handleTimetableTypeChange();
    
    // Auto-load staff if module is selected and facilitator is empty
    var facilitatorValue = document.getElementById('timetableFacilitator').value;
    if (item.module && (!facilitatorValue || facilitatorValue === '')) {
        await autoLoadModuleStaff();
    }
    
    // Update UI
    document.getElementById('timetableSubmitBtn').innerHTML = '<i class="fas fa-save"></i> Sasisha Ratiba';
    document.getElementById('timetableSubmitBtn').style.background = '#10b981';
    document.getElementById('timetableCancelEditBtn').style.display = 'inline-flex';
    
    // Scroll to form
    document.getElementById('timetableForm').scrollIntoView({ behavior: 'smooth' });
    showToast('📝 Unahariri: ' + item.activity, 'info');
}

// ============================================
// DELETE TIMETABLE ITEM
// ============================================
async function deleteTimetableItem(id) {
    if (!confirm('Una uhakika unataka kufuta ratiba hii? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('timetable').doc(id).delete();
        showToast('✅ Ratiba imefutwa!', 'success');
        await loadTimetable();
    } catch (error) {
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

