// ============================================
// FILTER & SEARCH TIMETABLE
// ============================================
function filterTimetable(type) {
    timetableFilterType = type;
    
    document.querySelectorAll('#staffTimetable .filter-tab').forEach(tab => {
        tab.classList.remove('active');
    });
    
    let filtered = allTimetableItems;
    
    if (type !== 'all') {
        filtered = allTimetableItems.filter(i => i.type === type);
    }
    
    const searchTerm = document.getElementById('timetableSearchInput')?.value.toLowerCase() || '';
    if (searchTerm) {
        filtered = filtered.filter(i =>
            (i.activity && i.activity.toLowerCase().includes(searchTerm)) ||
            (i.module && i.module.toLowerCase().includes(searchTerm)) ||
            (i.facilitator && i.facilitator.toLowerCase().includes(searchTerm)) ||
            (i.venue && i.venue.toLowerCase().includes(searchTerm))
        );
    }
    
    renderTimetableList(filtered);
}

function searchTimetable() {
    const searchTerm = document.getElementById('timetableSearchInput')?.value.toLowerCase() || '';
    
    let filtered = allTimetableItems;
    
    if (timetableFilterType !== 'all') {
        filtered = filtered.filter(i => i.type === timetableFilterType);
    }
    
    if (searchTerm) {
        filtered = filtered.filter(i =>
            (i.activity && i.activity.toLowerCase().includes(searchTerm)) ||
            (i.module && i.module.toLowerCase().includes(searchTerm)) ||
            (i.facilitator && i.facilitator.toLowerCase().includes(searchTerm)) ||
            (i.venue && i.venue.toLowerCase().includes(searchTerm))
        );
    }
    
    renderTimetableList(filtered);
}

