// ============================================
// UPDATED showAdminTab WITH INITIALIZATION
// ============================================
function showAdminTab(tabName) {
    document.querySelectorAll('#adminDashboard .dashboard-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('#adminDashboard .nav-links a').forEach(b => b.classList.remove('active'));
    
    const tab = document.getElementById(tabName);
    if (tab) tab.classList.add('active');
    
    if (event && event.target) {
        const link = event.target.closest('a');
        if (link) link.classList.add('active');
    }
    
    // Load data based on tab
    if (tabName === 'adminManageGallery') {
        loadGalleryForAdmin();
        // Re-initialize gallery upload form
        
    } else if (tabName === 'adminManageMedia') {
        loadMediaForAdmin();

    } else if (tabName === 'adminManageUsers') {
        loadUsersManagement();
    } else if (tabName === 'adminManageStudents') {
        loadStudentsManageList();
    } else if (tabName === 'adminManageStaff') {
        loadStaffList();
        loadModulesForStaff();
    } else if (tabName === 'adminAnnouncements') {
        loadAnnouncements();
    } else if (tabName === 'adminManageText') {
        loadTextSections();
    }
}

// ============================================
// TOAST NOTIFICATION
// ============================================
function showToast(message, type = 'success') {
    // Remove existing toasts
    document.querySelectorAll('.custom-toast').forEach(t => t.remove());
    
    const toast = document.createElement('div');
    toast.className = `custom-toast toast-${type}`;
    toast.innerHTML = `
        <i class="fas fa-${type === 'success' ? 'check-circle' : type === 'error' ? 'exclamation-circle' : 'info-circle'}"></i>
        <span>${message}</span>
    `;
    toast.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: ${type === 'success' ? '#10b981' : type === 'error' ? '#ef4444' : '#f59e0b'};
        color: white;
        padding: 12px 24px;
        border-radius: 12px;
        z-index: 10000;
        display: flex;
        align-items: center;
        gap: 10px;
        box-shadow: 0 10px 25px rgba(0,0,0,0.2);
        animation: slideIn 0.3s ease;
        font-size: 0.9rem;
        font-weight: 500;
    `;
    
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(100%)';
        toast.style.transition = 'all 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}


