// Get avatar URL from name
function getAvatarUrl(name, size = 40) {
    if (!name) name = 'User';
    const initials = name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
    return `https://ui-avatars.com/api/?name=${encodeURIComponent(initials)}&background=e65c1e&color=fff&size=${size}`;
}

// Get user status info
function getUserStatusInfo(status) {
    const statusMap = {
        'pending': { class: 'status-pending', text: 'Pending' },
        'approved': { class: 'status-active', text: 'Active' },
        'rejected': { class: 'status-inactive', text: 'Inactive' },
        'suspended': { class: 'status-suspended', text: 'Suspended' }
    };
    return statusMap[status] || { class: 'status-unknown', text: status };
}

