// Download profile image
async function downloadUserProfileImage() {
    if (!currentViewingUserId) return;
    
    const userDoc = await db.collection('users').doc(currentViewingUserId).get();
    const user = userDoc.data();
    
    if (user.profileImage) {
        try {
            // Fetch image and download
            const response = await fetch(user.profileImage);
            const blob = await response.blob();
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `profile_${user.name || 'user'}_${currentViewingUserId}.jpg`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Error downloading image:', error);
            alert('Kosa wakati wa kupakua picha');
        }
    } else {
        alert('Mtumiaji hana picha ya profile');
    }
}

function closeViewUserModal() {
    document.getElementById('viewUserModal').classList.remove('active');
    document.body.style.overflow = '';
    currentViewingUserId = null;
}

