function startSlideshow() {
    if (slideInterval) clearInterval(slideInterval);
    const allSlides = document.querySelectorAll('.slide');
    if (allSlides.length === 0) return;
    
    allSlides[0].classList.add('active-slide');
    slideInterval = setInterval(() => {
        const slidesElements = document.querySelectorAll('.slide');
        slidesElements.forEach(s => s.classList.remove('active-slide'));
        currentSlide = (currentSlide + 1) % slidesElements.length;
        slidesElements[currentSlide].classList.add('active-slide');
    }, 5000);
}

