// ============================================
// PASSWORD TOGGLE FUNCTIONALITY
// ============================================

function addPasswordToggles() {
    // Add password toggle to all password fields
    const passwordFields = document.querySelectorAll('input[type="password"]');
    
    passwordFields.forEach(field => {
        // Check if toggle already exists
        if (field.parentElement.querySelector('.password-toggle')) return;
        
        const toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'password-toggle';
        toggle.innerHTML = '<i class="fas fa-eye"></i>';
        
        toggle.addEventListener('click', () => {
            const type = field.getAttribute('type') === 'password' ? 'text' : 'password';
            field.setAttribute('type', type);
            toggle.innerHTML = type === 'password' ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
        });
        
        field.parentElement.style.position = 'relative';
        field.parentElement.appendChild(toggle);
    });
}

// Call this after DOM loads
document.addEventListener('DOMContentLoaded', () => {
    addPasswordToggles();
});

