// ============================================
// NAVBAR MANAGEMENT FUNCTIONS
// ============================================

function setActiveNavbar(role) {
    // Set body attribute for CSS to handle navbar visibility
    document.body.setAttribute('data-role', role || 'home');
    
    // Also handle via JavaScript for older browsers
    const homeNav = document.getElementById('homeNavbar');
    const userNav = document.getElementById('userDashboardNav');
    const staffNav = document.getElementById('staffDashboardNav');
    const adminNav = document.getElementById('adminDashboardNav');
    const superAdminNav = document.getElementById('superAdminDashboardNav');
    
    // Hide all navbars first
    if (homeNav) homeNav.style.display = 'none';
    if (userNav) userNav.style.display = 'none';
    if (staffNav) staffNav.style.display = 'none';
    if (adminNav) adminNav.style.display = 'none';
    if (superAdminNav) superAdminNav.style.display = 'none';
    
    // Show appropriate navbar
    if (role === 'user') {
        if (userNav) userNav.style.display = 'block';
        updateUserNavName();
    } else if (role === 'staff') {
        if (staffNav) staffNav.style.display = 'block';
        updateStaffNavName();
    } else if (role === 'admin') {
        if (adminNav) adminNav.style.display = 'block';
        updateAdminNavName();
    } else if (role === 'superadmin') {
        if (superAdminNav) superAdminNav.style.display = 'block';
        updateSuperAdminNavName();
    } else {
        if (homeNav) homeNav.style.display = 'block';
    }
}

function updateUserNavName() {
    if (currentUser) {
        const navName = document.getElementById('userNavName');
        if (navName) navName.textContent = currentUser.name || currentUser.email;
    }
}

function updateStaffNavName() {
    if (currentUser) {
        const navName = document.getElementById('staffNavName');
        if (navName) navName.textContent = currentUser.name || currentUser.email;
    }
}

function updateAdminNavName() {
    if (currentUser) {
        const navName = document.getElementById('adminNavName');
        if (navName) navName.textContent = currentUser.name || currentUser.email;
    }
}

function updateSuperAdminNavName() {
    if (currentUser) {
        const navName = document.getElementById('superAdminNavName');
        if (navName) navName.textContent = currentUser.name || currentUser.email;
    }
}

