// ============================================
// SUPER ADMIN RESPONSIVE NAVIGATION FIX
// ============================================

// Initialize super admin navigation
function initSuperAdminNavigation() {
    const menuBtn = document.getElementById('superAdminMobileMenuBtn');
    const mobileMenu = document.getElementById('superAdminMobileMenu');
    const overlay = document.getElementById('superAdminOverlay');
    const closeBtn = mobileMenu?.querySelector('.close-menu');
    
    // Add class for CSS targeting
    if (menuBtn) menuBtn.classList.add('superadmin-mobile-btn');
    
    // Find desktop menu
    const desktopMenu = document.getElementById('superAdminDesktopMenu');
    if (desktopMenu) desktopMenu.classList.add('superadmin-desktop-menu');
    
    // Mobile menu toggle
    if (menuBtn && mobileMenu) {
        // Remove old event listeners by cloning
        const newBtn = menuBtn.cloneNode(true);
        menuBtn.parentNode.replaceChild(newBtn, menuBtn);
        
        newBtn.onclick = function(e) {
            e.preventDefault();
            e.stopPropagation();
            
            const isActive = mobileMenu.classList.contains('active');
            
            if (isActive) {
                closeSuperMobileMenu(mobileMenu, overlay);
            } else {
                closeAllMobileMenus();
                mobileMenu.classList.add('active');
                if (overlay) overlay.classList.add('active');
                document.body.style.overflow = 'hidden';
            }
        };
    }
    
    // Close button in menu header
    if (closeBtn) {
        const newCloseBtn = closeBtn.cloneNode(true);
        closeBtn.parentNode.replaceChild(newCloseBtn, closeBtn);
        
        newCloseBtn.onclick = function() {
            closeSuperMobileMenu(mobileMenu, overlay);
        };
    }
    
    // Overlay click to close
    if (overlay) {
        const newOverlay = overlay.cloneNode(true);
        overlay.parentNode.replaceChild(newOverlay, overlay);
        
        newOverlay.onclick = function() {
            closeSuperMobileMenu(mobileMenu, overlay);
        };
    }
    
    // Close menu when clicking navigation links
    if (mobileMenu) {
        const menuLinks = mobileMenu.querySelectorAll('a');
        menuLinks.forEach(link => {
            link.addEventListener('click', function() {
                closeSuperMobileMenu(mobileMenu, overlay);
            });
        });
    }
    
    // Handle window resize
    window.addEventListener('resize', function() {
        if (window.innerWidth > 1024) {
            if (mobileMenu && mobileMenu.classList.contains('active')) {
                closeSuperMobileMenu(mobileMenu, overlay);
            }
        }
    });
    
    // Dropdown toggle for desktop
    const dropdownBtn = document.getElementById('superAdminDropdownBtn');
    const dropdownMenu = document.getElementById('superAdminDropdownMenu');
    
    if (dropdownBtn && dropdownMenu) {
        const newDropdownBtn = dropdownBtn.cloneNode(true);
        dropdownBtn.parentNode.replaceChild(newDropdownBtn, dropdownBtn);
        
        newDropdownBtn.onclick = function(e) {
            e.stopPropagation();
            dropdownMenu.classList.toggle('active');
        };
        
        // Close dropdown when clicking outside
        document.addEventListener('click', function(e) {
            if (dropdownMenu && dropdownMenu.classList.contains('active')) {
                if (!dropdownMenu.contains(e.target) && e.target !== newDropdownBtn) {
                    dropdownMenu.classList.remove('active');
                }
            }
        });
    }
    
    // Also handle second dropdown button if exists
    const dropdownBtn2 = document.getElementById('superAdminDropdownBtn2');
    const dropdownMenu2 = document.getElementById('superAdminDropdownMenu2');
    
    if (dropdownBtn2 && dropdownMenu2) {
        const newDropdownBtn2 = dropdownBtn2.cloneNode(true);
        dropdownBtn2.parentNode.replaceChild(newDropdownBtn2, dropdownBtn2);
        
        newDropdownBtn2.onclick = function(e) {
            e.stopPropagation();
            dropdownMenu2.classList.toggle('active');
        };
        
        document.addEventListener('click', function(e) {
            if (dropdownMenu2 && dropdownMenu2.classList.contains('active')) {
                if (!dropdownMenu2.contains(e.target) && e.target !== newDropdownBtn2) {
                    dropdownMenu2.classList.remove('active');
                }
            }
        });
    }
}

function closeSuperMobileMenu(mobileMenu, overlay) {
    if (mobileMenu) mobileMenu.classList.remove('active');
    if (overlay) overlay.classList.remove('active');
    document.body.style.overflow = '';
}

function closeAllMobileMenus() {
    document.querySelectorAll('.mobile-menu').forEach(menu => {
        menu.classList.remove('active');
    });
    document.querySelectorAll('.menu-overlay').forEach(overlay => {
        overlay.classList.remove('active');
    });
    document.body.style.overflow = '';
}



// ============================================
// FIX showDashboardByRole for superadmin
// ============================================

showDashboardByRole = function(role) {
    if (role === 'superadmin') {
        // Hide all pages and dashboards
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.dashboard').forEach(d => {
            d.classList.remove('active');
            d.style.display = 'none';
        });
        
        // Show superadmin dashboard
        const dashboard = document.getElementById('superadminDashboard');
        if (dashboard) {
            dashboard.classList.add('active');
            dashboard.style.display = 'block';
            
            // Show home tab
            const homeTab = document.getElementById('superHome');
            if (homeTab) {
                homeTab.classList.add('active');
            }
            
            // Set user names
            const userName = currentUser?.name || currentUser?.email || 'Super Admin';
            ['superAdminDropdownName', 'superAdminDropdownName2'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.textContent = userName;
            });
            
            // Initialize navigation
            setTimeout(initSuperAdminNavigation, 100);
            
            // Load data
            loadSuperAdminData();
            
            console.log('✅ Superadmin dashboard shown');
        }
    } else {
        // Call original for other roles
        originalShowDashboardByRole(role);
    }
};

// ============================================
// LOAD SUPER ADMIN DATA SAFELY
// ============================================
async function loadSuperAdminData() {
    console.log('Loading superadmin stats...');
    
    const statsContainer = document.getElementById('superStats');
    if (!statsContainer) return;
    
    statsContainer.innerHTML = '<div style="text-align:center;padding:2rem;color:#64748b;">Inapakia takwimu...</div>';
    
    try {
        const [users, modules, admins, staff, students] = await Promise.all([
            db.collection('users').get().catch(() => ({ size: 0 })),
            db.collection('modules').get().catch(() => ({ size: 0 })),
            db.collection('users').where('role', '==', 'admin').get().catch(() => ({ size: 0 })),
            db.collection('users').where('role', '==', 'staff').get().catch(() => ({ size: 0 })),
            db.collection('users').where('role', '==', 'user').get().catch(() => ({ size: 0 }))
        ]);
        
        statsContainer.innerHTML = `
            <div class="stats-grid">
                <div class="stat-card">
                    <h3>Watumiaji Wote</h3>
                    <div class="stat-number">${users.size || 0}</div>
                </div>
                <div class="stat-card">
                    <h3>Modules</h3>
                    <div class="stat-number">${modules.size || 0}</div>
                </div>
                <div class="stat-card">
                    <h3>Admins</h3>
                    <div class="stat-number">${admins.size || 0}</div>
                </div>
                <div class="stat-card">
                    <h3>Staff</h3>
                    <div class="stat-number">${staff.size || 0}</div>
                </div>
                <div class="stat-card">
                    <h3>Wanafunzi</h3>
                    <div class="stat-number">${students.size || 0}</div>
                </div>
            </div>
        `;
        
        console.log('✅ Stats loaded');
    } catch (error) {
        console.error('Error loading stats:', error);
        statsContainer.innerHTML = `<p style="color:red;text-align:center;padding:2rem;">Error: ${error.message}</p>`;
    }
}

