// ============================================
// SCROLL TO SECTION FUNCTION
// ============================================
function scrollToSection(sectionId) {
    // Remove 'section' from the ID if it's added
    let targetId = sectionId;
    
    // Check if the section element exists
    let section = document.getElementById(targetId);
    
    // If not found, try with '-section' suffix
    if (!section) {
        section = document.getElementById(`${targetId}-section`);
    }
    
    // If still not found, try to find by class or data attribute
    if (!section) {
        section = document.querySelector(`[data-section="${targetId}"]`);
    }
    
    if (section) {
        // Get the navigation bar height for offset
        const navBar = document.querySelector('.nav-home, .navbar');
        const navHeight = navBar ? navBar.offsetHeight : 70;
        
        // Calculate position with offset
        const elementPosition = section.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.pageYOffset - navHeight;
        
        // Smooth scroll to element
        window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
        });
        
        // Update URL hash without jumping
        history.pushState(null, null, `#${targetId}`);
        
        // Close mobile menu if open
        closeAllMobileMenus();
    } else {
        console.warn(`Section "${sectionId}" not found`);
    }
}

// ============================================
// ALTERNATIVE SIMPLE VERSION (If above doesn't work)
// ============================================
function scrollToSimple(sectionId) {
    const element = document.getElementById(sectionId);
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
    }
}

// ============================================
// ROBUST SCROLL FUNCTION WITH ERROR HANDLING
// ============================================
function smoothScroll(targetId) {
    // Try multiple ways to find the target element
    let target = document.getElementById(targetId);
    
    if (!target) {
        target = document.getElementById(targetId + '-section');
    }
    
    if (!target) {
        target = document.querySelector(`[data-id="${targetId}"]`);
    }
    
    if (!target) {
        target = document.querySelector(`.${targetId}-section`);
    }
    
    if (target) {
        const navHeight = document.querySelector('.navbar, .nav-home')?.offsetHeight || 70;
        const targetPosition = target.getBoundingClientRect().top + window.pageYOffset;
        const offsetPosition = targetPosition - navHeight;
        
        window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
        });
    } else {
        console.warn(`Target element "${targetId}" not found`);
        // Fallback: try to find any section with that name in class
        const fallback = document.querySelector(`section[id*="${targetId}"]`);
        if (fallback) {
            fallback.scrollIntoView({ behavior: 'smooth' });
        }
    }
}

// Make it available globally
window.scrollToSection = scrollToSection;
window.smoothScroll = smoothScroll;

