// PASSWORD TOGGLE VISIBILITY FUNCTIONS
// ============================================

// Main function to toggle password visibility
function togglePasswordVisibility(inputId) {
    const input = document.getElementById(inputId);
    if (!input) return;
    
    // Find the toggle button
    const toggleBtn = input.parentElement.querySelector('.password-toggle-btn');
    
    if (input.type === 'password') {
        input.type = 'text';
        if (toggleBtn) {
            toggleBtn.innerHTML = '<i class="fas fa-eye-slash"></i>';
        }
    } else {
        input.type = 'password';
        if (toggleBtn) {
            toggleBtn.innerHTML = '<i class="fas fa-eye"></i>';
        }
    }
}

// Alternative function that accepts the button element directly
function togglePasswordFromButton(button) {
    const input = button.previousElementSibling;
    if (!input) return;
    
    if (input.type === 'password') {
        input.type = 'text';
        button.innerHTML = '<i class="fas fa-eye-slash"></i>';
    } else {
        input.type = 'password';
        button.innerHTML = '<i class="fas fa-eye"></i>';
    }
}


// Password strength checker
function checkPasswordStrength(password) {
    let strength = 0;
    
    if (password.length >= 6) strength++;
    if (password.length >= 10) strength++;
    if (/[A-Z]/.test(password)) strength++;
    if (/[0-9]/.test(password)) strength++;
    if (/[^A-Za-z0-9]/.test(password)) strength++;
    
    const strengthText = ['Dhaifu sana', 'Dhaifu', 'Wastani', 'Nzuri', 'Imara'];
    const strengthColor = ['#ef4444', '#f59e0b', '#eab308', '#84cc16', '#10b981'];
    
    return {
        level: strength,
        text: strengthText[strength],
        color: strengthColor[strength]
    };
}

// Add password strength indicator to signup form
const signupPassword = document.getElementById('signupPassword');
if (signupPassword) {
    const strengthIndicator = document.createElement('div');
    strengthIndicator.className = 'password-strength';
    strengthIndicator.style.fontSize = '0.7rem';
    strengthIndicator.style.marginTop = '0.25rem';
    signupPassword.parentElement.appendChild(strengthIndicator);
    
    signupPassword.addEventListener('input', (e) => {
        const strength = checkPasswordStrength(e.target.value);
        strengthIndicator.textContent = `Nguvu: ${strength.text}`;
        strengthIndicator.style.color = strength.color;
    });
}

