// ============================================
// AUTO-ADD TOGGLE TO ALL PASSWORD FIELDS
// ============================================
function initAllPasswordToggles() {
    const passwordInputs = document.querySelectorAll('input[type="password"]');
    
    passwordInputs.forEach(input => {
        // Check if already has wrapper
        let wrapper = input.closest('.password-wrapper');
        
        if (!wrapper) {
            // Create wrapper
            wrapper = document.createElement('div');
            wrapper.className = 'password-wrapper';
            input.parentNode.insertBefore(wrapper, input);
            wrapper.appendChild(input);
        }
        
        // Check if toggle already exists
        let toggle = wrapper.querySelector('.password-toggle');
        
        if (!toggle) {
            // Create toggle button
            toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'password-toggle';
            toggle.innerHTML = '<i class="fas fa-eye"></i>';
            toggle.setAttribute('onclick', `togglePassword('${input.id}', this)`);
            wrapper.appendChild(toggle);
        }
    });
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    initAllPasswordToggles();
});

