// Open User Settings Modal
function openUserSettingsModal() {
    loadUserSettingsData();
    document.getElementById('userSettingsModal').classList.add('active');
    document.body.style.overflow = 'hidden';
}

// Close User Settings Modal
function closeUserSettingsModal() {
    document.getElementById('userSettingsModal').classList.remove('active');
    document.body.style.overflow = '';
}

// Load User Settings Data
async function loadUserSettingsData() {
    const userDoc = await db.collection('users').doc(currentUser.uid).get();
    const user = userDoc.data();
    
    // Personal info
    document.getElementById('settingsFullName').value = user.name || '';
    document.getElementById('settingsPhoneNumber').value = user.phone || '';
    document.getElementById('settingsEmailAddress').value = user.email || '';
    document.getElementById('settingsNida').value = user.nida || '';
    document.getElementById('settingsFormIndex').value = user.formIndex || '';
    
    // Profile image
    const profileImg = document.getElementById('settingsProfileImage');
    if (profileImg) {
        profileImg.src = user.profileImage || 'https://via.placeholder.com/100?text=Photo';
    }
    
    // Notification preferences
    const userPrefs = user.preferences || {};
    document.getElementById('emailNotifications').checked = userPrefs.emailNotifications || false;
    document.getElementById('smsNotifications').checked = userPrefs.smsNotifications || false;
    document.getElementById('courseNotifications').checked = userPrefs.courseNotifications || false;
    
    // Language preference
    document.getElementById('languagePreference').value = user.language || 'sw';
}

// Preview Settings Profile Image
function previewSettingsProfileImage(event) {
    const file = event.target.files[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = function(e) {
            const preview = document.getElementById('settingsProfileImage');
            if (preview) {
                preview.src = e.target.result;
            }
        };
        reader.readAsDataURL(file);
    }
}

// Upload Settings Profile Picture
async function uploadSettingsProfilePicture(file, userId) {
    if (!file) return null;
    
    const progressDiv = document.getElementById('settingsUploadProgress');
    if (progressDiv) progressDiv.style.display = 'block';
    
    try {
        const fileExtension = file.name.split('.').pop();
        const fileName = `profile_${userId}_${Date.now()}.${fileExtension}`;
        const storageRef = storage.ref(`profile_pictures/${fileName}`);
        
        const uploadTask = storageRef.put(file);
        
        uploadTask.on('state_changed', 
            (snapshot) => {
                const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
                const progressBar = document.querySelector('#settingsUploadProgress .progress-bar');
                if (progressBar) {
                    progressBar.style.width = progress + '%';
                }
            },
            (error) => {
                console.error('Upload error:', error);
                if (progressDiv) progressDiv.style.display = 'none';
            }
        );
        
        await uploadTask;
        const downloadURL = await storageRef.getDownloadURL();
        
        if (progressDiv) progressDiv.style.display = 'none';
        return downloadURL;
        
    } catch (error) {
        console.error('Error:', error);
        if (progressDiv) progressDiv.style.display = 'none';
        return null;
    }
}

// Save User Settings
document.getElementById('userSettingsForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const name = document.getElementById('settingsFullName').value;
    const phone = document.getElementById('settingsPhoneNumber').value;
    const nida = document.getElementById('settingsNida').value;
    const formIndex = document.getElementById('settingsFormIndex').value;
    const profileImageFile = document.getElementById('settingsProfileInput').files[0];
    const emailNotifications = document.getElementById('emailNotifications').checked;
    const smsNotifications = document.getElementById('smsNotifications').checked;
    const courseNotifications = document.getElementById('courseNotifications').checked;
    const language = document.getElementById('languagePreference').value;
    
    try {
        let profileImageUrl = currentUser.profileImage;
        
        if (profileImageFile) {
            profileImageUrl = await uploadSettingsProfilePicture(profileImageFile, currentUser.uid);
        }
        
        const updateData = {
            name: name,
            phone: phone,
            nida: nida,
            formIndex: formIndex,
            language: language,
            preferences: {
                emailNotifications,
                smsNotifications,
                courseNotifications
            },
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (profileImageUrl) {
            updateData.profileImage = profileImageUrl;
        }
        
        await db.collection('users').doc(currentUser.uid).update(updateData);
        
        // Update currentUser
        currentUser.name = name;
        if (profileImageUrl) currentUser.profileImage = profileImageUrl;
        localStorage.setItem('currentUser', JSON.stringify(currentUser));
        
        showSuccessMessage('Mipangilio imehifadhiwa kikamilifu!');
        closeUserSettingsModal();
        
        // Update UI
        const userNameElements = document.querySelectorAll('#userDropdownName, #staffDropdownName, #adminDropdownName, #superAdminDropdownName');
        userNameElements.forEach(el => {
            if (el) el.textContent = name.split(' ')[0];
        });
        
    } catch (error) {
        console.error('Error:', error);
        alert('Kosa wakati wa kuhifadhi: ' + error.message);
    }
});

// ============================================
// CHANGE PASSWORD MODAL FUNCTIONS
// ============================================

// Open Change Password Modal
function openChangePasswordModal() {
    document.getElementById('changePasswordModal').classList.add('active');
    document.body.style.overflow = 'hidden';
    resetPasswordForm();
}

// Close Change Password Modal
function closeChangePasswordModal() {
    document.getElementById('changePasswordModal').classList.remove('active');
    document.body.style.overflow = '';
    resetPasswordForm();
}

// Reset Password Form
function resetPasswordForm() {
    document.getElementById('currentPassword').value = '';
    document.getElementById('newPassword').value = '';
    document.getElementById('confirmNewPassword').value = '';
    resetPasswordStrength();
    document.getElementById('passwordMatchMessage').innerHTML = '';
}

// Reset Password Strength
function resetPasswordStrength() {
    const segments = document.querySelectorAll('.strength-segment');
    segments.forEach(segment => {
        segment.classList.remove('active');
        segment.style.background = '#e2e8f0';
    });
    document.getElementById('passwordStrengthText').textContent = '';
}

// Check Password Strength
function checkPasswordStrength(password) {
    const segments = document.querySelectorAll('.strength-segment');
    let strength = 0;
    let requirements = {
        length: password.length >= 6,
        uppercase: /[A-Z]/.test(password),
        lowercase: /[a-z]/.test(password),
        number: /[0-9]/.test(password),
        special: /[!@#$%^&*]/.test(password)
    };
    
    // Update requirements list
    updatePasswordRequirement('reqLength', requirements.length);
    updatePasswordRequirement('reqUppercase', requirements.uppercase);
    updatePasswordRequirement('reqLowercase', requirements.lowercase);
    updatePasswordRequirement('reqNumber', requirements.number);
    updatePasswordRequirement('reqSpecial', requirements.special);
    
    // Calculate strength
    if (requirements.length) strength++;
    if (requirements.uppercase) strength++;
    if (requirements.lowercase) strength++;
    if (requirements.number) strength++;
    if (requirements.special) strength++;
    
    // Update visual segments
    const colors = ['#ef4444', '#f59e0b', '#eab308', '#84cc16', '#10b981'];
    const texts = ['Dhaifu sana', 'Dhaifu', 'Wastani', 'Nzuri', 'Imara'];
    
    for (let i = 0; i < segments.length; i++) {
        if (i < strength) {
            segments[i].classList.add('active');
            segments[i].style.background = colors[Math.min(i, colors.length - 1)];
        } else {
            segments[i].classList.remove('active');
            segments[i].style.background = '#e2e8f0';
        }
    }
    
    document.getElementById('passwordStrengthText').textContent = texts[strength - 1] || '';
    document.getElementById('passwordStrengthText').style.color = colors[strength - 1] || '#64748b';
    
    return strength >= 3;
}

// Update Password Requirement
function updatePasswordRequirement(elementId, isValid) {
    const element = document.getElementById(elementId);
    if (element) {
        if (isValid) {
            element.classList.add('valid');
            element.querySelector('i').className = 'fas fa-check-circle';
        } else {
            element.classList.remove('valid');
            element.querySelector('i').className = 'fas fa-circle';
        }
    }
}

// Check Password Match
function checkPasswordMatch() {
    const newPassword = document.getElementById('newPassword').value;
    const confirmPassword = document.getElementById('confirmNewPassword').value;
    const messageSpan = document.getElementById('passwordMatchMessage');
    
    if (confirmPassword.length > 0) {
        if (newPassword === confirmPassword) {
            messageSpan.innerHTML = '<i class="fas fa-check-circle"></i> Nenosiri zinalingana';
            messageSpan.className = 'match-message valid';
        } else {
            messageSpan.innerHTML = '<i class="fas fa-exclamation-circle"></i> Nenosiri hazifanani';
            messageSpan.className = 'match-message invalid';
        }
    } else {
        messageSpan.innerHTML = '';
    }
}

// Toggle Password Visibility
function togglePasswordVisibility(inputId) {
    const input = document.getElementById(inputId);
    const wrapper = input.parentElement;
    const toggleBtn = wrapper.querySelector('.password-toggle');
    
    if (input.type === 'password') {
        input.type = 'text';
        toggleBtn.innerHTML = '<i class="fas fa-eye-slash"></i>';
    } else {
        input.type = 'password';
        toggleBtn.innerHTML = '<i class="fas fa-eye"></i>';
    }
}

// Submit Change Password
document.getElementById('changePasswordForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const currentPassword = document.getElementById('currentPassword').value;
    const newPassword = document.getElementById('newPassword').value;
    const confirmPassword = document.getElementById('confirmNewPassword').value;
    
    if (!currentPassword || !newPassword || !confirmPassword) {
        alert('Tafadhali jaza sehemu zote');
        return;
    }
    
    if (newPassword !== confirmPassword) {
        alert('Nenosiri jipya hazifanani');
        return;
    }
    
    if (newPassword.length < 6) {
        alert('Nenosiri jipya lazima iwe na herufi 6 au zaidi');
        return;
    }
    
    const btn = document.getElementById('changePasswordBtn');
    btn.disabled = true;
    btn.textContent = 'Inabadilisha...';
    
    try {
        const user = auth.currentUser;
        const credential = firebase.auth.EmailAuthProvider.credential(user.email, currentPassword);
        await user.reauthenticateWithCredential(credential);
        await user.updatePassword(newPassword);
        
        showSuccessMessage('Nenosiri limebadilishwa kikamilifu!');
        closeChangePasswordModal();
        
    } catch (error) {
        console.error('Error:', error);
        if (error.code === 'auth/wrong-password') {
            alert('Nenosiri la sasa si sahihi');
        } else {
            alert('Kosa: ' + error.message);
        }
    } finally {
        btn.disabled = false;
        btn.textContent = 'Badilisha Nenosiri';
    }
});

