// Load Staff Profile Data
async function loadStaffProfileData() {
    const container = document.getElementById('staffProfileContent');
    if (!container) {
        console.error('staffProfileContent element not found');
        return;
    }
    
    if (!currentUser) {
        console.error('No current user found');
        container.innerHTML = '<p class="error-text">Hakuna mtumiaji aliyeingia</p>';
        return;
    }
    
    try {
        console.log('Loading staff profile for user:', currentUser.uid);
        container.innerHTML = '<div class="loading-spinner">Inapakia taarifa zako...</div>';
        
        const userDoc = await db.collection('users').doc(currentUser.uid).get();
        
        if (!userDoc.exists) {
            container.innerHTML = '<p class="error-text">Taarifa za staff hazikupatikana</p>';
            return;
        }
        
        const staff = userDoc.data();
        console.log('Staff data loaded:', staff);
        
        const modules = staff.assignedModules || [];
        
        // Get status display
        let statusClass = 'status-active';
        let statusText = 'Active';
        
        if (staff.status === 'inactive') {
            statusClass = 'status-inactive';
            statusText = 'Inactive';
        } else if (staff.status === 'suspended') {
            statusClass = 'status-suspended';
            statusText = 'Suspended';
        }
        
        container.innerHTML = `
            <div class="staff-profile-card">
                <div class="staff-profile-header">
                    <div class="staff-profile-avatar">
                        <img src="${staff.profileImage || 'https://via.placeholder.com/120?text=Staff'}" alt="Profile Photo" onerror="this.src='https://via.placeholder.com/120?text=Staff'">
                    </div>
                    <div class="staff-profile-name">${escapeHtml(staff.name) || '-'}</div>
                    <div class="staff-profile-role">${staff.role === 'staff' ? 'Mwalimu / Staff' : staff.role}</div>
                    <span class="status-badge ${statusClass}">${statusText}</span>
                </div>
                <div class="staff-profile-info">
                    <div class="info-section">
                        <h4><i class="fas fa-address-card"></i> Taarifa za Msingi</h4>
                        <div class="info-row">
                            <div class="info-label">Username</div>
                            <div class="info-value">${escapeHtml(staff.username) || '-'}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Barua pepe</div>
                            <div class="info-value">${escapeHtml(staff.email) || '-'}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Namba ya Simu</div>
                            <div class="info-value">${escapeHtml(staff.phone) || 'Hajajazwa'}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Aliyejiunga</div>
                            <div class="info-value">${staff.createdAt?.toDate().toLocaleDateString() || 'Hivi karibuni'}</div>
                        </div>
                    </div>
                    
                    <div class="info-section">
                        <h4><i class="fas fa-cubes"></i> Modules Zilizopangiwa</h4>
                        <div class="modules-list">
                            ${modules.length > 0 ? modules.map(m => `<span class="module-badge">${escapeHtml(m.code)} - ${escapeHtml(m.name)}</span>`).join('') : '<span class="text-muted">Hakuna module zilizopangiwa</span>'}
                        </div>
                    </div>
                </div>
            </div>
        `;
        
    } catch (error) {
        console.error('Error loading staff profile:', error);
        container.innerHTML = `<p class="error-text">Kosa wakati wa kupakia profile: ${error.message}</p>`;
    }
}

// Escape HTML to prevent XSS
function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

