// ============================================
// PREVIEW STAFF PROFILE PICTURE
// ============================================
function previewStaffProfilePic(event) {
    var file = event.target.files[0];
    if (!file) return;
    
    // Validate file type
    var validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif'];
    if (validTypes.indexOf(file.type.toLowerCase()) === -1) {
        showToast('Tafadhali chagua picha sahihi (JPG, PNG, WebP, GIF)', 'error');
        event.target.value = '';
        return;
    }
    
    // Validate file size (5MB max)
    if (file.size > 5 * 1024 * 1024) {
        showToast('Picha ni kubwa sana. Kiwango cha juu ni 5MB', 'error');
        event.target.value = '';
        return;
    }
    
    var reader = new FileReader();
    reader.onload = function(e) {
        var preview = document.getElementById('editStaffAvatarPreview');
        if (preview) {
            preview.src = e.target.result;
        }
    };
    reader.readAsDataURL(file);
}

// ============================================
// SAVE EDIT STAFF PROFILE
// ============================================
document.getElementById('editStaffProfileForm')?.addEventListener('submit', async function(e) {
    e.preventDefault();
    
    if (!currentUser) return;
    
    // Get form values
    var name = document.getElementById('editStaffFullName').value.trim();
    var username = document.getElementById('editStaffUsername').value.trim();
    var gender = document.getElementById('editStaffGender').value;
    var dob = document.getElementById('editStaffDOB').value;
    var nationality = document.getElementById('editStaffNationality').value.trim();
    var address = document.getElementById('editStaffAddress').value.trim();
    var phone = document.getElementById('editStaffPhone').value.trim();
    var nida = document.getElementById('editStaffNida').value.trim();
    var formIndex = document.getElementById('editStaffFormIndex').value.trim();
    var bio = document.getElementById('editStaffBio').value.trim();
    var profilePicFile = document.getElementById('editStaffProfilePicInput').files[0];
    
    // Validation
    if (!name) {
        showToast('Tafadhali weka jina lako', 'error');
        return;
    }
    
    if (!username) {
        showToast('Tafadhali weka username', 'error');
        return;
    }
    
    var submitBtn = document.querySelector('#editStaffProfileForm .btn-primary');
    var originalText = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    
    try {
        var updateData = {
            name: name,
            username: username,
            gender: gender || '',
            dateOfBirth: dob || '',
            nationality: nationality || '',
            address: address || '',
            phone: phone || '',
            nida: nida || '',
            formIndex: formIndex || '',
            bio: bio || '',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        // Upload profile picture if selected
        if (profilePicFile) {
            try {
                var storageRef = firebase.storage().ref();
                var fileName = 'profile_pictures/' + currentUser.uid + '/' + Date.now() + '.jpg';
                var fileRef = storageRef.child(fileName);
                
                // Compress and upload
                var compressedFile = await compressImageForProfile(profilePicFile);
                await fileRef.put(compressedFile);
                var downloadURL = await fileRef.getDownloadURL();
                
                updateData.profileImage = downloadURL;
            } catch (uploadError) {
                console.error('Error uploading profile picture:', uploadError);
                // Continue without profile picture if upload fails
            }
        }
        
        // Update Firestore
        await db.collection('users').doc(currentUser.uid).update(updateData);
        
        // Update currentUser object
        if (currentUser) {
            Object.keys(updateData).forEach(function(key) {
                currentUser[key] = updateData[key];
            });
            localStorage.setItem('currentUser', JSON.stringify(currentUser));
        }
        
        showToast('✅ Profile imehifadhiwa kikamilifu!', 'success');
        closeEditStaffProfileModal();
        
        // Reload profile display
        await loadStaffProfile();
        
        // Update UI elements
        updateStaffDisplayNames(name);
        
    } catch (error) {
        console.error('Error updating profile:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    } finally {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalText;
    }
});

// ============================================
// UPDATE STAFF DISPLAY NAMES
// ============================================
function updateStaffDisplayNames(name) {
    if (!name) return;
    
    var shortName = name.split(' ')[0];
    
    // Update dropdown name
    var dropdownName = document.getElementById('staffDropdownName');
    if (dropdownName) dropdownName.textContent = shortName;
    
    // Update profile name
    var profileName = document.getElementById('staffProfileName');
    if (profileName) profileName.textContent = name;
    
    // Update display name
    var displayName = document.getElementById('staffNameDisplay');
    if (displayName) displayName.textContent = name;
    
    // Update welcome name
    var welcomeName = document.getElementById('staffWelcomeName');
    if (welcomeName) welcomeName.textContent = shortName;
}

// ============================================
// COMPRESS IMAGE FOR PROFILE
// ============================================
function compressImageForProfile(file) {
    return new Promise(function(resolve, reject) {
        var reader = new FileReader();
        reader.readAsDataURL(file);
        
        reader.onload = function(e) {
            var img = new Image();
            img.src = e.target.result;
            
            img.onload = function() {
                var canvas = document.createElement('canvas');
                var maxDimension = 500;
                
                var width = img.width;
                var height = img.height;
                
                if (width > height) {
                    if (width > maxDimension) {
                        height = (maxDimension / width) * height;
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = (maxDimension / height) * width;
                        height = maxDimension;
                    }
                }
                
                canvas.width = width;
                canvas.height = height;
                
                var ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0, width, height);
                
                canvas.toBlob(function(blob) {
                    var compressedFile = new File([blob], 'profile.jpg', {
                        type: 'image/jpeg',
                        lastModified: Date.now()
                    });
                    resolve(compressedFile);
                }, 'image/jpeg', 0.8);
            };
            
            img.onerror = reject;
        };
        
        reader.onerror = reject;
    });
}

