// Load students by selected module (only from assigned modules)
// ============================================
// LOAD STUDENTS BY MODULE - FIXED VERSION
// ============================================

async function loadStudentsByModule() {
    console.log("loadStudentsByModule called");
    
    const moduleSelect = document.getElementById('courseworkModule');
    if (!moduleSelect) {
        console.error("courseworkModule select not found");
        return;
    }
    
    const moduleCode = moduleSelect.value;
    console.log("Selected module code:", moduleCode);
    
    if (!moduleCode) {
        document.getElementById('courseworkStudent').innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
        document.getElementById('studentSearchInput').value = '';
        allStudents = [];
        selectedModuleStudents = [];
        return;
    }
    
    // Show loading
    const studentSelect = document.getElementById('courseworkStudent');
    studentSelect.innerHTML = '<option value="">Inapakia wanafunzi...</option>';
    
    try {
        // Get module details
        const moduleQuery = await db.collection('modules').where('code', '==', moduleCode).get();
        let moduleName = moduleCode;
        let moduleId = null;
        
        if (!moduleQuery.empty) {
            const moduleDoc = moduleQuery.docs[0];
            moduleName = moduleDoc.data().name;
            moduleId = moduleDoc.id;
            console.log("Module found:", moduleName, "ID:", moduleId);
        } else {
            console.log("Module not found in modules collection with code:", moduleCode);
            // Try to get from assigned modules
            if (staffAssignedModules && staffAssignedModules.length > 0) {
                const assigned = staffAssignedModules.find(m => m.code === moduleCode);
                if (assigned) {
                    moduleName = assigned.name;
                }
            }
        }
        
        // Get all users with role 'user' and status 'approved'
        console.log("Fetching students...");
        const usersSnapshot = await db.collection('users')
            .where('role', '==', 'user')
            .where('status', '==', 'approved')
            .get();
        
        console.log("Total users found:", usersSnapshot.size);
        
        const students = [];
        
        for (const doc of usersSnapshot.docs) {
            const user = doc.data();
            const enrolledCourses = user.enrolledCourses || [];
            
            console.log(`Checking student: ${user.name}`, "Enrolled courses:", enrolledCourses);
            
            // Check if student is enrolled in ANY course (since modules belong to courses)
            // We need to check if the student is enrolled in the parent course of this module
            let isEnrolled = false;
            
            if (moduleId) {
                // Get parent course of this module
                const moduleDoc = await db.collection('modules').doc(moduleId).get();
                if (moduleDoc.exists) {
                    const moduleData = moduleDoc.data();
                    const parentCourseId = moduleData.courseId;
                    
                    if (parentCourseId && enrolledCourses.includes(parentCourseId)) {
                        isEnrolled = true;
                        console.log(`Student ${user.name} is enrolled in parent course`);
                    }
                }
            }
            
            // Alternative: Check by course name
            if (!isEnrolled && moduleName) {
                // Check if student has any course that might contain this module
                for (const courseId of enrolledCourses) {
                    const courseDoc = await db.collection('courses').doc(courseId).get();
                    if (courseDoc.exists) {
                        const courseData = courseDoc.data();
                        // Check if this course has modules that include this module code
                        const modulesForCourse = await db.collection('modules')
                            .where('courseId', '==', courseId)
                            .where('code', '==', moduleCode)
                            .get();
                        
                        if (!modulesForCourse.empty) {
                            isEnrolled = true;
                            console.log(`Student ${user.name} is enrolled via course check`);
                            break;
                        }
                    }
                }
            }
            
            if (isEnrolled) {
                students.push({
                    id: doc.id,
                    name: user.name,
                    email: user.email,
                    phone: user.phone || ''
                });
            }
        }
        
        console.log("Students found for module:", students.length);
        
        selectedModuleStudents = students;
        allStudents = students;
        
        // Populate student select
        if (students.length === 0) {
            studentSelect.innerHTML = '<option value="">-- Hakuna wanafunzi waliojisajili kwenye moduli hii --</option>';
        } else {
            studentSelect.innerHTML = students.map(student =>
                `<option value="${student.id}">${student.name} - ${student.email}</option>`
            ).join('');
        }
        
        // Clear search input
        const searchInput = document.getElementById('studentSearchInput');
        if (searchInput) searchInput.value = '';
        
    } catch (error) {
        console.error('Error loading students:', error);
        studentSelect.innerHTML = '<option value="">-- Kosa wakati wa kupakia wanafunzi --</option>';
        alert('Kosa wakati wa kupakia wanafunzi: ' + error.message);
    }
}

// Filter student list based on search input
function filterStudentList() {
    const searchTerm = document.getElementById('studentSearchInput').value.toLowerCase();
    const filtered = allStudents.filter(student => 
        student.name.toLowerCase().includes(searchTerm) || 
        student.email.toLowerCase().includes(searchTerm)
    );
    
    const studentSelect = document.getElementById('courseworkStudent');
    if (filtered.length === 0) {
        studentSelect.innerHTML = '<option value="">-- Hakuna matokeo --</option>';
    } else {
        studentSelect.innerHTML = filtered.map(student => 
            `<option value="${student.id}">${student.name} - ${student.email}</option>`
        ).join('');
    }
}

// Get status display text and class
function getStatusInfo(status) {
    const statusMap = {
        'excellent': { text: 'Excellent', class: 'status-excellent' },
        'good': { text: 'Good', class: 'status-good' },
        'poor': { text: 'Poor', class: 'status-poor' },
        'bad': { text: 'Bad', class: 'status-bad' }
    };
    return statusMap[status] || { text: status, class: 'status-poor' };
}

// Get assessment type display
function getTypeDisplay(type) {
    const typeMap = {
        'quiz': { text: 'Quiz', class: 'type-quiz' },
        'take_home': { text: 'Take Home', class: 'type-take_home' },
        'test1': { text: 'Test 1', class: 'type-test1' },
        'test2': { text: 'Test 2', class: 'type-test2' },
        'test3': { text: 'Test 3', class: 'type-test3' },
        'test4': { text: 'Test 4', class: 'type-test4' },
        'test5': { text: 'Test 5', class: 'type-test5' },
        'individual_assignment': { text: 'Individual Assignment', class: 'type-individual_assignment' },
        'group_assignment': { text: 'Group Assignment', class: 'type-group_assignment' },
        'assignment1': { text: 'Assignment 1', class: 'type-assignment1' },
        'assignment2': { text: 'Assignment 2', class: 'type-assignment2' },
        'assignment3': { text: 'Assignment 3', class: 'type-assignment3' },
        'assignment4': { text: 'Assignment 4', class: 'type-assignment4' }
    };
    return typeMap[type] || { text: type, class: '' };
}

// Save Coursework
document.getElementById('courseworkForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const moduleCode = document.getElementById('courseworkModule').value;
    const studentId = document.getElementById('courseworkStudent').value;
    const type = document.getElementById('courseworkType').value;
    const marks = document.getElementById('courseworkMarks').value;
    const status = document.getElementById('courseworkStatus').value;
    
    if (!moduleCode || !studentId || !type || !marks || !status) {
        alert('Tafadhali jaza sehemu zote');
        return;
    }
    
    // Get student name
    const student = selectedModuleStudents.find(s => s.id === studentId);
    const studentName = student ? student.name : '';
    
    // Get module name
    const selectedModule = staffAssignedModules.find(m => m.code === moduleCode);
    const moduleName = selectedModule ? selectedModule.name : moduleCode;
    
    try {
        await db.collection('coursework').add({
            moduleCode: moduleCode,
            moduleName: moduleName,
            studentId: studentId,
            studentName: studentName,
            type: type,
            marks: parseFloat(marks),
            status: status,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: currentUser.uid,
            createdByName: currentUser.name
        });
        
        alert('Coursework imehifadhiwa kikamilifu!');
        
        // Reset form
        document.getElementById('courseworkForm').reset();
        document.getElementById('courseworkStudent').innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
        
        // Refresh lists
        loadCourseworkList();
        loadUserCoursework();
        
    } catch (error) {
        console.error('Error saving coursework:', error);
        alert('Kosa wakati wa kuhifadhi: ' + error.message);
    }
});

// ============================================
// LOAD COURSEWORK LIST - FILTERED BY CURRENT STAFF
// Only shows coursework created by this staff member
// ============================================
async function loadCourseworkList() {
    const container = document.getElementById('courseworkList');
    
    if (!container) {
        console.error('courseworkList container not found');
        return;
    }
    
    if (!currentUser) {
        container.innerHTML = '<tr><td colspan="8" class="text-center">Hakuna mtumiaji aliyeingia</td></tr>';
        return;
    }
    
    container.innerHTML = '<tr><td colspan="8" class="text-center"><div class="loading-spinner">Inapakia coursework zako...</div></tr>';
    
    try {
        // ============================================
        // FILTER: Only show coursework created by THIS staff member
        // ============================================
        const snapshot = await db.collection('coursework')
            .where('createdBy', '==', currentUser.uid)
            .orderBy('createdAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <tr>
                    <td colspan="8" class="text-center">
                        <div style="padding:2rem;text-align:center;color:#64748b;">
                            <i class="fas fa-tasks" style="font-size:2.5rem;display:block;margin-bottom:1rem;color:#94a3b8;"></i>
                            <h4 style="color:#475569;margin-bottom:0.5rem;">Hakuna Coursework</h4>
                            <p style="font-size:0.9rem;">Hujaongeza coursework yoyote bado.</p>
                            <p style="font-size:0.8rem;color:#94a3b8;">Ongeza coursework kwa kutumia form hapo juu.</p>
                        </div>
                    </td>
                </tr>`;
            return;
        }
        
        let html = '';
        let index = 1;
        
        snapshot.forEach(doc => {
            const cw = doc.data();
            const typeInfo = getTypeDisplay(cw.type || '');
            const statusInfo = getStatusInfo(cw.status || '');
            const date = cw.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ', {
                year: 'numeric', month: 'short', day: 'numeric'
            }) || '-';
            
            html += `
                <tr>
                    <td class="text-center">${index++}</td>
                    <td><strong>${escapeHtml(cw.studentName || '-')}</strong></td>
                    <td><span class="module-tag-small">${escapeHtml(cw.moduleCode || '-')}</span></td>
                    <td><span class="type-badge ${typeInfo.class}">${typeInfo.text}</span></td>
                    <td class="text-center"><strong>${cw.marks || '-'}</strong></td>
                    <td><span class="${statusInfo.class}">${statusInfo.text}</span></td>
                    <td class="text-center">${date}</td>
                    <td class="text-center">
                        <div class="action-buttons" style="display:flex;gap:0.3rem;justify-content:center;">
                            <button class="btn-edit btn-sm" onclick="openEditCourseworkModal('${doc.id}')" title="Hariri">
                                <i class="fas fa-edit"></i> Hariri
                            </button>
                            <button class="btn-delete btn-sm" onclick="deleteCoursework('${doc.id}')" title="Futa">
                                <i class="fas fa-trash"></i> Futa
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        });
        
        container.innerHTML = html;
        
        // Update coursework table header if needed
        const tableHeader = document.querySelector('.coursework-table-container h3');
        if (tableHeader) {
            tableHeader.innerHTML = `
                <i class="fas fa-list"></i> Orodha ya Coursework 
                <span style="font-size:0.7rem;color:#94a3b8;font-weight:400;margin-left:0.5rem;">
                    (Zangu Pekee - ${snapshot.size} rekodi)
                </span>`;
        }
        
        console.log(`✅ Loaded ${snapshot.size} coursework records for staff: ${currentUser.name}`);
        
    } catch (error) {
        console.error('Error loading coursework:', error);
        container.innerHTML = `<tr><td colspan="8" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

// ============================================
// LOAD USER COURSEWORK - GROUPED BY MODULE
// ============================================
async function loadUserCoursework() {
    if (!currentUser) return;
    
    const container = document.getElementById('userCourseworkList');
    
    if (!container) return;
    
    container.innerHTML = '<tr><td colspan="5" class="text-center"><i class="fas fa-spinner fa-spin"></i> Inapakia coursework...</td></tr>';
    
    try {
        const snapshot = await db.collection('coursework')
            .where('studentId', '==', currentUser.uid)
            .orderBy('createdAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = '<tr><td colspan="5" class="text-center">Hakuna matokeo ya coursework bado</td></tr>';
            return;
        }
        
        // Group coursework by module
        const moduleGroups = {};
        
        snapshot.forEach(doc => {
            const cw = doc.data();
            const moduleCode = cw.moduleCode || 'Unknown';
            const moduleName = cw.moduleName || moduleCode;
            
            if (!moduleGroups[moduleCode]) {
                moduleGroups[moduleCode] = {
                    moduleCode: moduleCode,
                    moduleName: moduleName,
                    coursework: []
                };
            }
            
            moduleGroups[moduleCode].coursework.push({
                id: doc.id,
                ...cw
            });
        });
        
        // Convert to array and sort
        const modules = Object.values(moduleGroups);
        modules.sort((a, b) => a.moduleName.localeCompare(b.moduleName));
        
        // Helper function
        function fmtNum(num) {
            var n = parseFloat(num || 0);
            return n % 1 === 0 ? n.toString() : n.toFixed(1);
        }
        
        container.innerHTML = modules.map(module => {
            // Calculate total marks for this module
            const totalMarks = module.coursework.reduce((sum, cw) => sum + (parseFloat(cw.marks) || 0), 0);
            const courseworkCount = module.coursework.length;
            const lastUpdated = module.coursework[0]?.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-';
            
            return `
                <tr class="module-coursework-row">
                    <td class="text-center" style="vertical-align:middle;">
                        <span class="module-icon-circle">
                            <i class="fas fa-book"></i>
                        </span>
                    </td>
                    <td>
                        <strong>${escapeHtml(module.moduleName)}</strong>
                        <br><small class="text-muted">${escapeHtml(module.moduleCode)}</small>
                    </td>
                    <td class="text-center">
                        <span class="coursework-count-badge">${courseworkCount} assessments</span>
                    </td>
                    <td class="text-center">
                        <strong class="total-marks-text">${fmtNum(totalMarks)}</strong>
                    </td>
                    <td class="text-center">
                        <button class="btn-view-coursework" onclick="viewModuleCoursework('${escapeHtml(module.moduleCode)}', '${escapeHtml(module.moduleName)}')">
                            <i class="fas fa-eye"></i> Tazama
                        </button>
                    </td>
                </tr>
            `;
        }).join('');
        
    } catch (error) {
        console.error('Error loading coursework:', error);
        container.innerHTML = `<tr><td colspan="5" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

// ============================================
// VIEW MODULE COURSEWORK (Modal)
// ============================================
async function viewModuleCoursework(moduleCode, moduleName) {
    if (!currentUser) return;
    
    const modal = document.getElementById('moduleCourseworkModal');
    const content = document.getElementById('moduleCourseworkContent');
    
    if (!modal || !content) return;
    
    content.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> Inapakia...</div>';
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
    
    try {
        const snapshot = await db.collection('coursework')
            .where('studentId', '==', currentUser.uid)
            .orderBy('createdAt', 'desc')
            .get();
        
        // Filter by module
        const courseworkList = [];
        snapshot.forEach(doc => {
            const cw = doc.data();
            if (cw.moduleCode === moduleCode) {
                courseworkList.push({ id: doc.id, ...cw });
            }
        });
        
        function fmtNum(num) {
            var n = parseFloat(num || 0);
            return n % 1 === 0 ? n.toString() : n.toFixed(1);
        }
        
        if (courseworkList.length === 0) {
            content.innerHTML = `
                <div class="empty-mini-state">
                    <i class="fas fa-info-circle"></i>
                    <p>Hakuna coursework kwa moduli hii</p>
                </div>`;
            return;
        }
        
        // Calculate totals
        const totalMarks = courseworkList.reduce((sum, cw) => sum + (parseFloat(cw.marks) || 0), 0);
        
        content.innerHTML = `
            <div class="module-coursework-detail">
                <div class="detail-header">
                    <h3><i class="fas fa-book"></i> ${escapeHtml(moduleName)}</h3>
                    <span class="module-code-badge">${escapeHtml(moduleCode)}</span>
                </div>
                
                <div class="coursework-summary-box">
                    <div class="summary-item">
                        <span class="summary-label">Jumla ya Assessments</span>
                        <span class="summary-value">${courseworkList.length}</span>
                    </div>
                    <div class="summary-item highlight">
                        <span class="summary-label">Jumla ya Alama</span>
                        <span class="summary-value">${fmtNum(totalMarks)}</span>
                    </div>
                </div>
                
                <div class="table-responsive" style="margin-top:1rem;">
                    <table class="data-table">
                        <thead>
                            <tr>
                                <th width="50">#</th>
                                <th>Aina ya Assessment</th>
                                <th width="80">Alama</th>
                                <th width="100">Status</th>
                                <th width="110">Tarehe</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${courseworkList.map((cw, idx) => {
                                const typeInfo = getTypeDisplay(cw.type || '');
                                const statusInfo = getStatusInfo(cw.status || '');
                                const marks = fmtNum(cw.marks || 0);
                                const date = cw.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-';
                                
                                return `
                                    <tr>
                                        <td class="text-center">${idx + 1}</td>
                                        <td><span class="type-badge ${typeInfo.class}">${typeInfo.text}</span></td>
                                        <td class="text-center"><strong>${marks}</strong></td>
                                        <td><span class="${statusInfo.class}">${statusInfo.text}</span></td>
                                        <td class="text-center">${date}</td>
                                    </tr>
                                `;
                            }).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
        
    } catch (error) {
        console.error('Error loading module coursework:', error);
        content.innerHTML = `<p class="error-text">Kosa: ${error.message}</p>`;
    }
}

