// Edit Coursework
async function editCoursework(id, currentMarks, currentStatus) {
    const newMarks = prompt('Hariri alama (marks):', currentMarks);
    if (newMarks === null) return;
    
    const newStatus = prompt('Hariri status (excellent, good, poor, bad):', currentStatus);
    if (newStatus === null) return;
    
    const validStatuses = ['excellent', 'good', 'poor', 'bad'];
    if (!validStatuses.includes(newStatus.toLowerCase())) {
        alert('Status lazima iwe: excellent, good, poor, au bad');
        return;
    }
    
    try {
        await db.collection('coursework').doc(id).update({
            marks: parseFloat(newMarks),
            status: newStatus.toLowerCase(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        alert('Coursework imehaririwa!');
        loadCourseworkList();
        loadUserCoursework();
        
    } catch (error) {
        console.error('Error editing coursework:', error);
        alert('Kosa: ' + error.message);
    }
}

// Delete Coursework
async function deleteCoursework(id) {
    if (confirm('Una uhakika unataka kufuta coursework hii?')) {
        try {
            await db.collection('coursework').doc(id).delete();
            loadCourseworkList();
            loadUserCoursework();
            alert('Coursework imefutwa!');
        } catch (error) {
            console.error('Error deleting coursework:', error);
            alert('Kosa wakati wa kufuta: ' + error.message);
        }
    }
}

