// ============================================
// LOAD USER DATA (REFRESH CURRENT USER & CLEANUP)
// ============================================

async function loadUserData() {
    // Refresh currentUser from Firestore to get latest enrolledCourses
    if (currentUser && currentUser.uid) {
        try {
            const userDoc = await db.collection('users').doc(currentUser.uid).get();
            if (userDoc.exists) {
                const userData = userDoc.data();
                let enrolledCourses = userData.enrolledCourses || [];
                
                // CLEANUP: Remove invalid/empty course IDs
                const validCourses = [];
                for (const courseId of enrolledCourses) {
                    if (courseId && courseId.trim() !== '') {
                        const courseDoc = await db.collection('courses').doc(courseId).get();
                        if (courseDoc.exists) {
                            validCourses.push(courseId);
                        } else {
                            console.log('Removing invalid course ID:', courseId);
                        }
                    }
                }
                
                // Update Firestore if we removed any invalid courses
                if (validCourses.length !== enrolledCourses.length) {
                    await db.collection('users').doc(currentUser.uid).update({
                        enrolledCourses: validCourses,
                        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                    });
                    enrolledCourses = validCourses;
                    console.log('Cleaned up enrolled courses. New count:', validCourses.length);
                }
                
                // Update currentUser with cleaned data
                currentUser = {
                    uid: currentUser.uid,
                    ...userData,
                    enrolledCourses: enrolledCourses
                };
                localStorage.setItem('currentUser', JSON.stringify(currentUser));
                console.log('Refreshed currentUser data. Enrolled courses:', enrolledCourses);
            }
        } catch (e) {
            console.log('Could not refresh user data:', e);
        }
    }
    
    await Promise.all([
        loadUserCourses(),
        loadAvailableCoursesForUser(),
        loadUserTestResults(),
        loadUserExamResults(),
        loadUserBills(),
        loadUserTimetable(),
        loadUserNotifications(),
        loadUserCoursework()
    ]);
}

