// EXPORT FUNCTIONS (Updated)
// ============================================

async function exportCourseworkPDF() {
    const { jsPDF } = window.jspdf;
    const snapshot = await db.collection('coursework').orderBy('createdAt', 'desc').get();
    const coursework = [];
    snapshot.forEach(doc => coursework.push(doc.data()));
    
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text('Coursework Report', 20, 20);
    doc.setFontSize(10);
    doc.text(`Imetolewa: ${new Date().toLocaleDateString()}`, 20, 30);
    
    let y = 50;
    coursework.forEach((item, index) => {
        if (y > 270) { doc.addPage(); y = 20; }
        const statusInfo = getStatusInfo(item.status);
        doc.text(`${index + 1}. ${item.studentName || 'No name'}`, 20, y);
        doc.text(`   Module: ${item.moduleCode || '-'} | Aina: ${item.type || '-'}`, 25, y + 6);
        doc.text(`   Alama: ${item.marks || '-'} | Status: ${statusInfo.text}`, 25, y + 12);
        y += 25;
    });
    
    doc.save(`coursework_report_${new Date().toISOString().slice(0,10)}.pdf`);
}

async function exportCourseworkExcel() {
    const snapshot = await db.collection('coursework').orderBy('createdAt', 'desc').get();
    const data = [['#', 'Mwanafunzi', 'Module', 'Aina', 'Alama', 'Status', 'Tarehe']];
    let index = 1;
    
    snapshot.forEach(doc => {
        const cw = doc.data();
        const typeInfo = getTypeDisplay(cw.type);
        const statusInfo = getStatusInfo(cw.status);
        data.push([
            index++,
            cw.studentName || '',
            cw.moduleCode || '',
            typeInfo.text,
            cw.marks || '',
            statusInfo.text,
            cw.createdAt?.toDate().toLocaleDateString() || ''
        ]);
    });
    
    const ws = XLSX.utils.aoa_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Coursework');
    XLSX.writeFile(wb, `coursework_report_${new Date().toISOString().slice(0,10)}.xlsx`);
}

