// Open Edit Coursework Modal
async function openEditCourseworkModal(courseworkId) {
    console.log('Opening edit modal for coursework:', courseworkId);
    
    try {
        // Fetch coursework data
        const courseworkDoc = await db.collection('coursework').doc(courseworkId).get();
        
        if (!courseworkDoc.exists) {
            alert('Coursework haikupatikana');
            return;
        }
        
        currentEditCoursework = { id: courseworkDoc.id, ...courseworkDoc.data() };
        
        // Populate form fields
        document.getElementById('editCourseworkId').value = currentEditCoursework.id;
        document.getElementById('editStudentName').value = currentEditCoursework.studentName || '-';
        document.getElementById('editModuleCode').value = `${currentEditCoursework.moduleCode || '-'}`;
        document.getElementById('editCourseworkType').value = currentEditCoursework.type || '';
        document.getElementById('editCourseworkMarks').value = currentEditCoursework.marks || '';
        document.getElementById('editCourseworkStatus').value = currentEditCoursework.status || '';
        
        // Show modal
        const modal = document.getElementById('editCourseworkModal');
        if (modal) {
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        }
        
    } catch (error) {
        console.error('Error loading coursework:', error);
        alert('Kosa wakati wa kupakia data: ' + error.message);
    }
}

