// Save Edit Coursework
document.getElementById('editCourseworkForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const courseworkId = document.getElementById('editCourseworkId').value;
    const type = document.getElementById('editCourseworkType').value;
    const marks = document.getElementById('editCourseworkMarks').value;
    const status = document.getElementById('editCourseworkStatus').value;
    
    if (!type || !marks || !status) {
        alert('Tafadhali jaza sehemu zote');
        return;
    }
    
    // Validate status
    const validStatuses = ['excellent', 'good', 'poor', 'bad'];
    if (!validStatuses.includes(status)) {
        alert('Status lazima iwe: excellent, good, poor, au bad');
        return;
    }
    
    // Validate marks
    if (isNaN(marks) || marks < 0) {
        alert('Tafadhali weka alama sahihi');
        return;
    }
    
    try {
        // Update coursework in Firestore
        await db.collection('coursework').doc(courseworkId).update({
            type: type,
            marks: parseFloat(marks),
            status: status,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedBy: currentUser.uid,
            updatedByName: currentUser.name
        });
        
        alert('Coursework imehaririwa kikamilifu!');
        closeEditCourseworkModal();
        
        // Refresh lists
        if (typeof loadCourseworkList === 'function') {
            loadCourseworkList();
        }
        if (typeof loadUserCoursework === 'function') {
            loadUserCoursework();
        }
        
    } catch (error) {
        console.error('Error updating coursework:', error);
        alert('Kosa wakati wa kuhifadhi: ' + error.message);
    }
});

// Show success message modal
function showEditSuccessModal() {
    const modal = document.getElementById('editSuccessModal');
    if (modal) {
        modal.classList.add('active');
        setTimeout(() => {
            modal.classList.remove('active');
        }, 2000);
    } else {
        alert('Coursework imehaririwa kikamilifu!');
    }
}


// ============================================
// ADD COURSE - SINGLE EVENT LISTENER
// ============================================

// Remove any existing form and recreate fresh
const oldForm = document.getElementById('addCourseForm');
if (oldForm) {
    // Remove all existing listeners by replacing with new form
    const newForm = oldForm.cloneNode(true);
    oldForm.parentNode.replaceChild(newForm, oldForm);
    
    // Add single event listener
    newForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        e.stopPropagation();
        
        console.log('Adding course - single event only');
        
        const code = document.getElementById('courseCode')?.value.trim();
        const name = document.getElementById('courseName')?.value.trim();
        const description = document.getElementById('courseDescription')?.value;
        const duration = document.getElementById('courseDuration')?.value;
        const fee = parseFloat(document.getElementById('courseFee')?.value) || 0;
        
        if (!code || !name) {
            alert('Tafadhali weka code na jina la kozi');
            return;
        }
        
        // Check if already exists
        const existing = await db.collection('courses').where('code', '==', code.toUpperCase()).get();
        if (!existing.empty) {
            alert(`Kozi "${code}" tayari ipo!`);
            return;
        }
        
// In your add course function, make sure active is ALWAYS true
const courseData = {
    code: code.toUpperCase(),
    name: name,
    description: description || '',
    duration: duration || 'Miezi 6',
    fee: fee || 0,
    active: true, // ← MUHIMU SANA: Always set to true
    order: 0,
    icon: 'book',
    createdAt: firebase.firestore.FieldValue.serverTimestamp()
};
        
        try {
            await db.collection('courses').add(courseData);
            alert(`Kozi "${name}" imeongezwa!`);
            
            // Clear form
            document.getElementById('courseCode').value = '';
            document.getElementById('courseName').value = '';
            document.getElementById('courseDescription').value = '';
            document.getElementById('courseFee').value = '';
            
            // Refresh lists
            await loadCoursesList();
            await loadPublicCourses();
            await loadCourseSelectForModules();
            
        } catch (error) {
            console.error('Error:', error);
            alert('Kosa: ' + error.message);
        }
    });
}

// Deactivate Course
async function deactivateCourse(courseId) {
    if (confirm('Una uhakika unataka kuzima kozi hii?')) {
        await db.collection('courses').doc(courseId).update({
            active: false,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        loadCoursesList();
        loadPublicCourses();
    }
}

// Activate Course
async function activateCourse(courseId) {
    await db.collection('courses').doc(courseId).update({
        active: true,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    loadCoursesList();
    loadPublicCourses();
}

