// ============================================
// LOAD PUBLIC COURSES - FIXED VERSION
// ============================================

async function loadPublicCourses() {
    console.log("Loading public courses...");
    const container = document.getElementById('publicCourseGrid');
    if (!container) {
        console.error("publicCourseGrid element not found");
        return;
    }
    
    try {
        // FIRST: Get ALL courses to see what's happening
        const allCourses = await db.collection('courses').get();
        console.log(`Total courses in database: ${allCourses.size}`);
        
        // SECOND: Get only active courses
        const activeSnapshot = await db.collection('courses')
            .where('active', '==', true)
            .get();
        
        console.log(`Active courses found: ${activeSnapshot.size}`);
        
        // Debug: Show all courses and their active status
        allCourses.forEach(doc => {
            const data = doc.data();
            const isActive = data.active;
            console.log(`Course: ${data.code} - ${data.name} | active: ${isActive} | type: ${typeof isActive}`);
        });
        
        if (activeSnapshot.empty) {
            // If no active courses, show message
            if (allCourses.size > 0) {
                container.innerHTML = `
                    <div class="no-courses-message">
                        <p>⚠️ Kozi zipo lakini hazijaamilishwa.</p>
                        <p>Tafadhali wasiliana na Super Admin.</p>
                    </div>
                `;
                // Also show debugging info
                console.warn("No active courses found but there are", allCourses.size, "courses in database");
            } else {
                container.innerHTML = '<p class="text-center">Hakuna kozi kwa sasa</p>';
            }
            return;
        }
        
        // Display active courses
        container.innerHTML = '';
        let displayCount = 0;
        
        for (const doc of activeSnapshot.docs) {
            const course = doc.data();
            const courseId = doc.id;
            const iconClass = course.icon || 'book';
            const duration = course.duration || 'Miezi 6';
            
            console.log(`Displaying: ${course.code} - ${course.name}`);
            displayCount++;
            
            container.innerHTML += `
                <div class="course-card" onclick="openCourseDetails('${courseId}')">
                    <div class="course-icon">
                        <i class="fas fa-${iconClass}"></i>
                    </div>
                    <h3>${escapeHtml(course.name)}</h3>
                    <span class="course-duration-badge">${escapeHtml(duration)}</span>
                </div>
            `;
        }
        
        console.log(`✅ Successfully displayed ${displayCount} courses on landing page`);
        
    } catch (error) {
        console.error("Error loading public courses:", error);
        container.innerHTML = '<p class="text-center error-text">Kosa wakati wa kupakia kozi: ' + error.message + '</p>';
    }
}



// ============================================
// ENROLL IN COURSE - RESTRICTED TO ONE COURSE
// ============================================

async function enrollInCourse(courseId, courseName) {
    const enrolled = currentUser.enrolledCourses || [];
    
    // Check if user already has a course
    if (enrolled.length >= 1) {
        // User already has one course - show message to contact admin
        showCourseLimitModal(courseId, courseName);
        return;
    }
    
    // Enroll the user
    enrolled.push(courseId);
    await db.collection('users').doc(currentUser.uid).update({
        enrolledCourses: enrolled,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    currentUser.enrolledCourses = enrolled;
    
    showSuccessMessage(`✅ Umejisajili kwenye "${courseName}" kikamilifu!`);
    
    // Refresh both sections
    await loadUserCourses();
    await loadAvailableCoursesForUser();
    await loadCourseSelectForUserModules();
}


