// ============================================
// LOAD AVAILABLE COURSES - WITH LIMIT CHECK (FIXED v2)
// ============================================

async function loadAvailableCoursesForUser() {
    const container = document.getElementById('availableCourses');
    
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia kozi zinazopatikana...</div>';
    
    try {
        if (!currentUser) {
            container.innerHTML = `
                <div class="empty-state-box">
                    <i class="fas fa-user-slash"></i>
                    <h4>Hujaingia</h4>
                    <p>Tafadhali ingia kwanza kuona kozi.</p>
                </div>
            `;
            return;
        }
        
        // Get enrolled courses and filter out empty/invalid IDs
        const allEnrolled = currentUser.enrolledCourses || [];
        const enrolled = allEnrolled.filter(id => id && id.trim() !== '');
        
        // If enrolled array changed (had empty IDs), update currentUser
        if (enrolled.length !== allEnrolled.length) {
            currentUser.enrolledCourses = enrolled;
            localStorage.setItem('currentUser', JSON.stringify(currentUser));
        }
        
        const hasCourse = enrolled.length >= 1;
        
        console.log('Available courses check - Enrolled IDs:', enrolled, 'Count:', enrolled.length);
        
        // If user has courses, show limit message
        if (hasCourse) {
            let currentCourseName = 'Unknown';
            
            try {
                const courseDoc = await db.collection('courses').doc(enrolled[0]).get();
                if (courseDoc.exists) {
                    currentCourseName = courseDoc.data().name || 'Unknown';
                } else {
                    // Remove invalid course ID
                    const updatedCourses = enrolled.filter(id => id !== enrolled[0]);
                    await db.collection('users').doc(currentUser.uid).update({
                        enrolledCourses: updatedCourses
                    });
                    currentUser.enrolledCourses = updatedCourses;
                    localStorage.setItem('currentUser', JSON.stringify(currentUser));
                    
                    // Reload the section
                    loadAvailableCoursesForUser();
                    return;
                }
            } catch (e) {
                console.log('Could not fetch course name:', e);
            }
            
            container.innerHTML = `
                <div class="limit-info-box">
                    <div class="limit-info-icon">
                        <i class="fas fa-info-circle"></i>
                    </div>
                    <h4>Umekwisha Jisajili</h4>
                    <p>Umeshasajiliwa kwenye kozi ya <strong>"${escapeHtml(currentCourseName)}"</strong>.</p>
                    <p class="limit-note">Ili kusajili kozi nyingine, tafadhali wasiliana na Admin.</p>
                    
                    <div class="admin-contact-mini">
                        <p><i class="fas fa-phone"></i> +255 784 358 227</p>
                        <p><i class="fas fa-envelope"></i> info@songwevtc.ac.tz</p>
                    </div>
                </div>
            `;
            return;
        }
        
        // User has NO courses - show available courses
        const snapshot = await db.collection('courses')
            .where('active', '==', true)
            .get();
        
        const available = [];
        snapshot.forEach(doc => {
            if (!enrolled.includes(doc.id)) {
                available.push({ id: doc.id, ...doc.data() });
            }
        });
        
        if (available.length === 0) {
            container.innerHTML = `
                <div class="empty-state-box success">
                    <i class="fas fa-check-circle"></i>
                    <h4>Hongera!</h4>
                    <p>Kozi zote zinazopatikana tayari umejisajili.</p>
                </div>
            `;
            return;
        }
        
        // Build table with available courses
        let html = `
            <div class="table-wrapper">
                <table class="data-table">
                    <thead>
                        <tr>
                            <th width="50">#</th>
                            <th>Jina la Kozi</th>
                            <th width="120">Code</th>
                            <th width="150">Muda</th>
                            <th width="180">Kitendo</th>
                        </tr>
                    </thead>
                    <tbody>
        `;
        
        available.forEach((course, index) => {
            const courseName = escapeHtml(course.name || 'Unknown Course');
            const courseCode = escapeHtml(course.code || 'N/A');
            const duration = escapeHtml(course.duration || 'Miezi 6');
            
            html += `
                <tr>
                    <td class="text-center">${index + 1}</td>
                    <td>
                        <div class="course-name-with-icon">
                            <span class="table-course-icon">
                                <i class="fas fa-${course.icon || 'book'}"></i>
                            </span>
                            <strong>${courseName}</strong>
                        </div>
                    </td>
                    <td><span class="code-tag">${courseCode}</span></td>
                    <td>
                        <span class="duration-info">
                            <i class="fas fa-clock"></i> ${duration}
                        </span>
                    </td>
                    <td class="text-center">
                        <button class="btn-enroll-table" onclick="enrollInCourse('${course.id}', '${courseName}')">
                            <i class="fas fa-plus-circle"></i> Jisajili Kozi
                        </button>
                    </td>
                </tr>
            `;
        });
        
        html += `
                    </tbody>
                </table>
            </div>
        `;
        
        container.innerHTML = html;
        
    } catch (error) {
        console.error('Error loading available courses:', error);
        container.innerHTML = `
            <div class="empty-state-box error">
                <i class="fas fa-exclamation-triangle"></i>
                <h4>Imeshindwa Kupakia</h4>
                <p>${error.message}</p>
                <button class="btn-retry" onclick="loadAvailableCoursesForUser()">
                    <i class="fas fa-redo"></i> Jaribu Tena
                </button>
            </div>
        `;
    }
}

