// ============================================
// VIEW COURSE MODULES (Modal) - FIXED
// ============================================

async function viewCourseModules(courseId, courseName) {
    try {
        // Update modal header - with null checks
        const modalCourseNameEl = document.getElementById('modalCourseName');
        const modalModuleCountEl = document.getElementById('modalModuleCount');
        
        if (modalCourseNameEl) modalCourseNameEl.textContent = courseName || 'Unknown';
        if (modalModuleCountEl) modalModuleCountEl.textContent = 'Moduli: Inapakia...';
        
        // Show modal
        const modal = document.getElementById('courseModulesViewModal');
        if (!modal) {
            console.error('courseModulesViewModal not found in HTML');
            alert('Modal element missing. Please check HTML.');
            return;
        }
        
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
        
        // Get modules
        const modulesSnapshot = await db.collection('modules')
            .where('courseId', '==', courseId)
            .where('active', '==', true)
            .orderBy('order', 'asc')
            .get();
        
        const modules = [];
        modulesSnapshot.forEach(doc => {
            modules.push({ id: doc.id, ...doc.data() });
        });
        
        // Update count
        if (modalModuleCountEl) modalModuleCountEl.textContent = `Moduli: ${modules.length}`;
        
        const tbody = document.getElementById('courseModulesTableBody');
        const empty = document.getElementById('courseModulesEmpty');
        const tableWrapper = document.getElementById('modulesTableWrapper');
        
        // Check if elements exist
        if (!tbody) {
            console.error('courseModulesTableBody not found');
            return;
        }
        
        if (modules.length === 0) {
            // Show empty state
            if (tableWrapper) tableWrapper.style.display = 'none';
            if (empty) empty.style.display = 'block';
        } else {
            // Show table
            if (tableWrapper) tableWrapper.style.display = 'block';
            if (empty) empty.style.display = 'none';
            
            tbody.innerHTML = modules.map((mod, idx) => `
                <tr>
                    <td class="text-center">${idx + 1}</td>
                    <td><span class="code-tag">${escapeHtml(mod.code || 'N/A')}</span></td>
                    <td><strong>${escapeHtml(mod.name || 'Unknown')}</strong></td>
                    <td class="text-center">${mod.credits || '0'}</td>
                    <td>${escapeHtml(mod.description || 'Hakuna maelezo').substring(0, 60)}${(mod.description || '').length > 60 ? '...' : ''}</td>
                    <td class="text-center"><span class="status-badge status-active">Active</span></td>
                </tr>
            `).join('');
        }
        
    } catch (error) {
        console.error('Error loading modules:', error);
        
        // Try to show error in modal if possible
        const tbody = document.getElementById('courseModulesTableBody');
        if (tbody) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="6" class="text-center error-text">
                        <i class="fas fa-exclamation-triangle"></i> 
                        Kosa: ${error.message || 'Unknown error'}
                    </td>
                </tr>
            `;
        }
    }
}

