// ============================================
// STUDENT NAVIGATION (User Dashboard)
// ============================================
function initStudentNavigation() {
    const menuBtn = document.getElementById('userMobileMenuBtn');
    const mobileMenu = document.getElementById('userMobileMenu');
    const overlay = document.getElementById('userOverlay');
    const closeBtn = mobileMenu?.querySelector('.close-menu');
    const dropdownBtn = document.getElementById('userDropdownBtn');
    const dropdownMenu = document.getElementById('userDropdownMenu');
    
    // Mobile Menu Toggle
    if (menuBtn && mobileMenu) {
        menuBtn.onclick = function(e) {
            e.stopPropagation();
            const isActive = mobileMenu.classList.contains('active');
            
            if (isActive) {
                mobileMenu.classList.remove('active');
                if (overlay) overlay.classList.remove('active');
                document.body.style.overflow = '';
            } else {
                closeAllMobileMenus();
                mobileMenu.classList.add('active');
                if (overlay) overlay.classList.add('active');
                document.body.style.overflow = 'hidden';
            }
            
            // Close dropdown if open
            if (dropdownMenu) dropdownMenu.classList.remove('active');
        };
        
        // Close button in menu header
        if (closeBtn) {
            closeBtn.onclick = function() {
                mobileMenu.classList.remove('active');
                if (overlay) overlay.classList.remove('active');
                document.body.style.overflow = '';
            };
        }
        
        // Overlay click to close
        if (overlay) {
            overlay.onclick = function() {
                mobileMenu.classList.remove('active');
                overlay.classList.remove('active');
                document.body.style.overflow = '';
            };
        }
        
        // Close menu when clicking any navigation link
        mobileMenu.querySelectorAll('a').forEach(link => {
            link.addEventListener('click', () => {
                mobileMenu.classList.remove('active');
                if (overlay) overlay.classList.remove('active');
                document.body.style.overflow = '';
            });
        });
    }
    
    // User Dropdown Toggle (Profile/Settings/Logout)
    if (dropdownBtn && dropdownMenu) {
        dropdownBtn.onclick = function(e) {
            e.stopPropagation();
            dropdownMenu.classList.toggle('active');
        };
        
        // Close dropdown when clicking outside
        document.addEventListener('click', function(e) {
            if (dropdownBtn && !dropdownBtn.contains(e.target) &&
                dropdownMenu && !dropdownMenu.contains(e.target)) {
                dropdownMenu.classList.remove('active');
            }
        });
        
        // Close dropdown when clicking a menu item
        dropdownMenu.querySelectorAll('a').forEach(link => {
            link.addEventListener('click', () => {
                dropdownMenu.classList.remove('active');
            });
        });
    }
    
    // Handle window resize - close mobile menu on desktop
    window.addEventListener('resize', () => {
        if (window.innerWidth > 768) {
            if (mobileMenu) mobileMenu.classList.remove('active');
            if (overlay) overlay.classList.remove('active');
            document.body.style.overflow = '';
        }
    });
}

// Initialize student navigation on page load
document.addEventListener('DOMContentLoaded', function() {
    initStudentNavigation();
});

