// Load courses list (inayojumuisha kozi zote, hata zisizo active)
async function loadCoursesList() {
    console.log('Loading courses from Firestore...');
    const container = document.getElementById('coursesList');
    if (!container) return;
    
    try {
        const snapshot = await db.collection('courses').orderBy('createdAt', 'desc').get();
        
        if (snapshot.empty) {
            container.innerHTML = '<p class="text-center">Hakuna kozi zilizoongezwa</p>';
            return;
        }
        
        container.innerHTML = '';
        for (const doc of snapshot.docs) {
            const course = doc.data();
            container.innerHTML += `
                <div class="item-card">
                    <div class="item-info">
                        <h4><strong>${escapeHtml(course.code)}</strong> - ${escapeHtml(course.name)}</h4>
                        <p>${escapeHtml(course.description || 'Hakuna maelezo')}</p>
                        <p><strong>Duration:</strong> ${course.duration} | <strong>Fee:</strong> TZS ${(course.fee || 0).toLocaleString()}</p>
                        <p><strong>Status:</strong> <span class="${course.active ? 'status-active' : 'status-inactive'}">${course.active ? 'Active' : 'Inactive'}</span></p>
                    </div>
                    <div class="item-actions">
                        <button class="btn-edit" onclick="editCourse('${doc.id}')">Hariri</button>
                        ${course.active ? 
                            `<button class="btn-deactivate" onclick="deactivateCourse('${doc.id}')">Zima</button>` : 
                            `<button class="btn-activate" onclick="activateCourse('${doc.id}')">Washa</button>`
                        }
                        <button class="btn-delete" onclick="deleteCourse('${doc.id}')">Futa</button>
                    </div>
                </div>
            `;
        }
    } catch (error) {
        console.error('Error loading courses:', error);
        container.innerHTML = '<p class="error-text">Kosa wakati wa kupakia kozi</p>';
    }
}


// Edit course (simple)
async function editCourse(courseId) {
    const doc = await db.collection('courses').doc(courseId).get();
    if (!doc.exists) return;
    const course = doc.data();
    const newName = prompt('Hariri jina la kozi:', course.name);
    if (newName && newName.trim() !== course.name) {
        await db.collection('courses').doc(courseId).update({
            name: newName.trim(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        await loadCoursesList();
        await loadPublicCourses();
    }
}

