async function openCourseDetails(courseId) {
    console.log('Opening course details modal for:', courseId);
    
    try {
        const courseDoc = await db.collection('courses').doc(courseId).get();
        
        if (!courseDoc.exists) {
            alert('Taarifa za kozi hazikupatikana');
            return;
        }
        
        const course = courseDoc.data();
        currentCourseDetails = { id: courseDoc.id, ...course };
        
        // Get icon class
        const iconClass = course.icon || 'book';
        const duration = course.duration || 'Miezi 6';
        const fee = course.fee || 0;
        const description = course.description || 'Hakuna maelezo ya ziada';
        
        // Build modal content with FULL details
        const content = document.getElementById('courseDetailsContent');
        content.innerHTML = `
            <div class="course-detail-card">
                <div class="course-detail-icon">
                    <i class="fas fa-${iconClass}"></i>
                </div>
                <h2>${escapeHtml(course.name)}</h2>
                <p class="course-code">Code: ${escapeHtml(course.code)}</p>
                
                <div class="detail-section">
                    <h4><i class="fas fa-clock"></i> Muda wa Kozi</h4>
                    <p>${duration}</p>
                </div>
                
                <div class="detail-section">
                    <h4><i class="fas fa-money-bill"></i> Ada ya Kozi</h4>
                    <p>TZS ${fee.toLocaleString()}</p>
                </div>
                
                <div class="detail-section">
                    <h4><i class="fas fa-align-left"></i> Maelezo Kamili</h4>
                    <p>${escapeHtml(description)}</p>
                </div>
                
                <div class="detail-section">
                    <h4><i class="fas fa-cubes"></i> Moduli Zinazotarajiwa</h4>
                    <div id="courseModulesList" class="modules-list">
                        <div class="loading-modules">Inapakia moduli...</div>
                    </div>
                </div>
            </div>
        `;
        
        // Load modules for this course
        await loadModulesForCourseDisplay(courseId);
        
        // Show modal
        const modal = document.getElementById('courseDetailsModal');
        if (modal) {
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        }
        
    } catch (error) {
        console.error('Error loading course details:', error);
        alert('Kosa wakati wa kupakia maelezo ya kozi');
    }
}

// Load modules for course display
async function loadModulesForCourseDisplay(courseId) {
    const modulesContainer = document.getElementById('courseModulesList');
    if (!modulesContainer) return;
    
    try {
        const modulesSnapshot = await db.collection('modules')
            .where('courseId', '==', courseId)
            .where('active', '==', true)
            .orderBy('order', 'asc')
            .get();
        
        if (modulesSnapshot.empty) {
            modulesContainer.innerHTML = '<p class="text-muted">Hakuna moduli zilizopangwa bado</p>';
            return;
        }
        
        let modulesHtml = '';
        modulesSnapshot.forEach(doc => {
            const module = doc.data();
            modulesHtml += `
                <div class="module-item">
                    <div class="module-info">
                        <span class="module-code">${escapeHtml(module.code)}</span>
                        <span class="module-name">${escapeHtml(module.name)}</span>
                    </div>
                    <div class="module-credits">Credits: ${module.credits || '0'}</div>
                </div>
            `;
        });
        
        modulesContainer.innerHTML = modulesHtml;
        
    } catch (error) {
        console.error('Error loading modules:', error);
        modulesContainer.innerHTML = '<p class="error-text">Kosa wakati wa kupakia moduli</p>';
    }
}

// Close course details modal
function closeCourseDetailsModal() {
    const modal = document.getElementById('courseDetailsModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
    currentCourseDetails = null;
}

// Enroll from modal
function enrollFromModal() {
    if (!currentCourseDetails) return;
    
    // Check if user is logged in
    if (!currentUser) {
        alert('Tafadhali ingia kwanza kabla ya kujisajili');
        closeCourseDetailsModal();
        openAuthWindow();
        return;
    }
    
    // Check if user is student (role === 'user')
    if (currentUser.role !== 'user') {
        alert('Ni wanafunzi tu wanaoweza kujisajili kozi');
        return;
    }
    
    // Call enrollment function
    if (typeof enrollInCourse === 'function') {
        enrollInCourse(currentCourseDetails.id, currentCourseDetails.name);
    }
    closeCourseDetailsModal();
}
