// ADD COURSE - CLEAN SINGLE VERSION
// ============================================

// Make sure this runs after DOM is ready
document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('addCourseForm');
    if (!form) {
        console.log('Add course form not found - waiting...');
        return;
    }
    
    console.log('Add course form found - setting up handler');
    
    // Remove any existing handlers
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        e.stopPropagation();
        
        console.log('Add course submitted');
        
        // Get values
        const code = document.getElementById('courseCode')?.value.trim().toUpperCase();
        const name = document.getElementById('courseName')?.value.trim();
        const description = document.getElementById('courseDescription')?.value;
        const duration = document.getElementById('courseDuration')?.value;
        const fee = parseFloat(document.getElementById('courseFee')?.value) || 0;
        
        // Validate
        if (!code) {
            alert('Tafadhali weka course code');
            return;
        }
        if (!name) {
            alert('Tafadhali weka jina la kozi');
            return;
        }
        
        // Disable button
        const btn = newForm.querySelector('button[type="submit"]');
        const originalText = btn?.textContent;
        if (btn) {
            btn.disabled = true;
            btn.textContent = 'Inaangalia...';
        }
        
        try {
            // Check if course exists
            const existing = await db.collection('courses').where('code', '==', code).get();
            
            if (!existing.empty) {
                const existingCourse = existing.docs[0].data();
                alert(`❌ Kozi yenye code "${code}" tayari ipo!\nJina: ${existingCourse.name}\nStatus: ${existingCourse.active ? 'Active' : 'Inactive'}`);
                if (btn) {
                    btn.disabled = false;
                    btn.textContent = originalText;
                }
                return;
            }
            
            // Add course
            await db.collection('courses').add({
                code: code,
                name: name,
                description: description || '',
                duration: duration || 'Miezi 6',
                fee: fee,
                active: true,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
            
            alert(`✅ Kozi "${name}" imeongezwa kikamilifu!`);
            
            // Clear form
            document.getElementById('courseCode').value = '';
            document.getElementById('courseName').value = '';
            document.getElementById('courseDescription').value = '';
            document.getElementById('courseFee').value = '';
            
            // Refresh lists
            if (typeof loadCoursesList === 'function') loadCoursesList();
            if (typeof loadPublicCourses === 'function') loadPublicCourses();
            
        } catch (error) {
            console.error('Error:', error);
            alert('Kosa: ' + error.message);
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.textContent = originalText;
            }
        }
    });
});

