// ============================================
// ADD MODULE - SINGLE EVENT LISTENER (FIXED)
// ============================================

// Wait for DOM to be fully loaded
document.addEventListener('DOMContentLoaded', function() {
    // Get the form element
    const moduleForm = document.getElementById('addModuleForm');
    
    if (!moduleForm) {
        console.log('Add module form not found');
        return;
    }
    
    // Remove any existing form and recreate fresh to avoid duplicate listeners
    const newModuleForm = moduleForm.cloneNode(true);
    moduleForm.parentNode.replaceChild(newModuleForm, moduleForm);
    
    // Add single event listener
    newModuleForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        e.stopPropagation();
        
        console.log('Add module submitted - single event only');
        
        // Get values
        const courseId = document.getElementById('moduleParentCourse')?.value;
        const code = document.getElementById('moduleCode')?.value.trim().toUpperCase();
        const name = document.getElementById('moduleName')?.value.trim();
        const description = document.getElementById('moduleDescription')?.value.trim();
        const credits = parseFloat(document.getElementById('moduleCredits')?.value) || 0;
        const order = parseInt(document.getElementById('moduleOrder')?.value) || 0;
        
        // Get selected staff
        const staffSelect = document.getElementById('moduleStaff');
        const selectedStaff = staffSelect ? Array.from(staffSelect.selectedOptions).map(opt => opt.value) : [];
        
        // Validate
        if (!courseId) {
            alert('Tafadhali chagua kozi');
            return;
        }
        
        if (!code) {
            alert('Tafadhali weka module code');
            return;
        }
        
        if (!name) {
            alert('Tafadhali weka jina kamili la moduli');
            return;
        }
        
        // Disable submit button to prevent double submission
        const submitBtn = newModuleForm.querySelector('button[type="submit"]');
        const originalText = submitBtn?.textContent;
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.textContent = 'Inaongeza...';
        }
        
        try {
            // Check if module code already exists
            const existingModule = await db.collection('modules').where('code', '==', code).get();
            if (!existingModule.empty) {
                alert(`Module yenye code "${code}" tayari ipo! Tumia code nyingine.`);
                if (submitBtn) {
                    submitBtn.disabled = false;
                    submitBtn.textContent = originalText;
                }
                return;
            }
            
            // Get course details
            const courseDoc = await db.collection('courses').doc(courseId).get();
            const course = courseDoc.data();
            
            // Create module data
            const moduleData = {
                code: code,
                name: name,
                description: description || '',
                credits: credits,
                order: order,
                courseId: courseId,
                courseName: course.name,
                staffIds: selectedStaff,
                active: true,
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            };
            
            // Add to Firestore
            const docRef = await db.collection('modules').add(moduleData);
            console.log('Module added with ID:', docRef.id);
            
            alert(`✅ Moduli "${name}" imeongezwa kikamilifu!`);
            
            // Reset form
            newModuleForm.reset();
            document.getElementById('moduleParentCourse').value = '';
            if (staffSelect) staffSelect.value = '';
            
            // Refresh the modules list
            await loadModulesList();
            
        } catch (error) {
            console.error('Error adding module:', error);
            alert('Kosa wakati wa kuongeza moduli: ' + error.message);
        } finally {
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = originalText;
            }
        }
    });
});

// Edit Module
async function editModule(moduleId) {
    const moduleDoc = await db.collection('modules').doc(moduleId).get();
    if (!moduleDoc.exists) return;
    
    const module = moduleDoc.data();
    
    const newName = prompt('Hariri jina la moduli:', module.name);
    if (newName && newName.trim() !== module.name) {
        await db.collection('modules').doc(moduleId).update({
            name: newName.trim(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        await loadModulesList();
        alert('Moduli imehaririwa!');
    }
}

// Delete Module
async function deleteModule(moduleId) {
    if (!confirm('Una uhakika unataka kufuta moduli hii? Hii haiwezi kurejeshwa!')) {
        return;
    }
    
    try {
        await db.collection('modules').doc(moduleId).delete();
        alert('Moduli imefutwa!');
        await loadModulesList();
    } catch (error) {
        console.error('Error deleting module:', error);
        alert('Kosa: ' + error.message);
    }
}
// ============================================
// LOAD MODULES LIST - FIXED (No Duplicates)
// ============================================
async function loadModulesList() {
    console.log("Loading modules list...");
    const container = document.getElementById('superModulesList') || document.getElementById('modulesList');
    
    if (!container) {
        console.error('Modules list container not found');
        return;
    }
    
    // CLEAR THE CONTAINER COMPLETELY FIRST
    container.innerHTML = '<div class="loading-spinner">Inapakia moduli...</div>';
    
    try {
        const snapshot = await db.collection('modules').get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <div style="text-align:center;padding:3rem;color:#94a3b8;">
                    <i class="fas fa-cubes" style="font-size:3rem;display:block;margin-bottom:1rem;"></i>
                    <p style="font-size:1.1rem;color:#64748b;">Hakuna moduli zilizoongezwa</p>
                    <small>Ongeza moduli kwa kutumia form hapo juu</small>
                </div>`;
            return;
        }
        
        // Get all courses for reference
        const coursesSnapshot = await db.collection('courses').get();
        const coursesMap = {};
        coursesSnapshot.forEach(doc => {
            coursesMap[doc.id] = doc.data();
        });
        
        // Get all staff for reference
        const staffSnapshot = await db.collection('users')
            .where('role', '==', 'staff')
            .get();
        const staffMap = {};
        staffSnapshot.forEach(doc => {
            staffMap[doc.id] = doc.data().name || 'Unknown';
        });
        
        // BUILD HTML ONCE (not appending, replacing)
        let html = '';
        
        snapshot.forEach(doc => {
            const module = doc.data();
            const courseName = coursesMap[module.courseId]?.name || module.courseName || 'N/A';
            const courseCode = coursesMap[module.courseId]?.code || 'N/A';
            const staffNames = (module.staffIds || []).map(id => staffMap[id] || id).join(', ');
            
            html += `
                <div class="item-card" id="module-${doc.id}">
                    <div class="item-info">
                        <h4><strong>${escapeHtml(module.code)}</strong> - ${escapeHtml(module.name)}</h4>
                        <p><strong>Kozi:</strong> ${escapeHtml(courseCode)} - ${escapeHtml(courseName)}</p>
                        <p><strong>Maelezo:</strong> ${escapeHtml(module.description || 'Hakuna maelezo')}</p>
                        <p><strong>Credits:</strong> ${module.credits || '-'} | <strong>Order:</strong> ${module.order || '-'}</p>
                        ${staffNames ? `<p><strong>Staff:</strong> ${escapeHtml(staffNames)}</p>` : ''}
                        <p><strong>Status:</strong> <span class="${module.active ? 'status-active' : 'status-inactive'}">${module.active ? 'Active' : 'Inactive'}</span></p>
                    </div>
                    <div class="item-actions">
                        <button class="btn-edit" onclick="editModuleItem('${doc.id}')"><i class="fas fa-edit"></i> Hariri</button>
                        <button class="btn-delete" onclick="deleteModuleItem('${doc.id}', '${escapeHtml(module.name)}')"><i class="fas fa-trash"></i> Futa</button>
                    </div>
                </div>
            `;
        });
        
        // SET INNERHTML ONCE (not append)
        container.innerHTML = html;
        
        console.log(`✅ Loaded ${snapshot.size} modules`);
        
    } catch (error) {
        console.error('Error loading modules:', error);
        container.innerHTML = `<p style="color:red;text-align:center;">Kosa: ${error.message}</p>`;
    }
}
 
// Filter Registered Modules by Code
function filterRegisteredModules() {
    const searchTerm = document.getElementById('searchRegisteredModule')?.value.trim().toUpperCase();
    const modules = document.querySelectorAll('#userModulesList .module-card');
    
    let visibleCount = 0;
    
    modules.forEach(module => {
        const moduleCode = module.getAttribute('data-module-code')?.toUpperCase() || '';
        
        if (!searchTerm || moduleCode.includes(searchTerm)) {
            module.style.display = 'block';
            visibleCount++;
        } else {
            module.style.display = 'none';
        }
    });
    
    // Update count
    document.getElementById('moduleCount').textContent = visibleCount;
    
    // Show message if no results
    const container = document.getElementById('userModulesList');
    const noResultsMsg = document.getElementById('noSearchResults');
    
    if (visibleCount === 0 && searchTerm) {
        if (!noResultsMsg) {
            const msgDiv = document.createElement('div');
            msgDiv.id = 'noSearchResults';
            msgDiv.className = 'empty-modules';
            msgDiv.innerHTML = `
                <i class="fas fa-search"></i>
                <p>Hakuna moduli inayolingana na "${searchTerm}"</p>
                <button onclick="clearModuleSearch()" class="btn-outline">Ondoa Utafutaji</button>
            `;
            container.appendChild(msgDiv);
        }
    } else if (noResultsMsg) {
        noResultsMsg.remove();
    }
}

// Clear Module Search
function clearModuleSearch() {
    const searchInput = document.getElementById('searchRegisteredModule');
    if (searchInput) {
        searchInput.value = '';
        filterRegisteredModules();
    }
}

// View Module Details Modal
async function viewModuleDetails(moduleId) {
    const moduleDoc = await db.collection('modules').doc(moduleId).get();
    if (!moduleDoc.exists) return;
    
    const module = moduleDoc.data();
    
    // Determine module type
    let moduleType = 'Non-Core';
    let typeColor = '#fef3c7';
    let typeTextColor = '#92400e';
    
    if (module.credits && module.credits >= 4) {
        moduleType = 'Core (Required)';
        typeColor = '#dcfce7';
        typeTextColor = '#166534';
    } else if (module.isCore) {
        moduleType = 'Core (Required)';
        typeColor = '#dcfce7';
        typeTextColor = '#166534';
    }
    
    const content = `
        <div class="module-detail-modal">
            <div class="module-detail-icon">
                <i class="fas fa-cube"></i>
            </div>
            <h2>${escapeHtml(module.name)}</h2>
            <p class="detail-code">Code: ${escapeHtml(module.code)}</p>
            
            <div class="detail-section">
                <h4><i class="fas fa-tag"></i> Aina ya Moduli</h4>
                <p><span style="background: ${typeColor}; color: ${typeTextColor}; padding: 0.25rem 0.75rem; border-radius: 2rem; font-size: 0.8rem;">${moduleType}</span></p>
            </div>
            
            <div class="detail-section">
                <h4><i class="fas fa-star"></i> Credits</h4>
                <p>${module.credits || '0'} credits</p>
            </div>
            
            <div class="detail-section">
                <h4><i class="fas fa-align-left"></i> Maelezo ya Moduli</h4>
                <p>${escapeHtml(module.description || 'Hakuna maelezo ya ziada.')}</p>
            </div>
            
            <div class="detail-section">
                <h4><i class="fas fa-book"></i> Kozi</h4>
                <p>${escapeHtml(module.courseName || '-')}</p>
            </div>
        </div>
    `;
    
    document.getElementById('moduleDetailsContent').innerHTML = content;
    document.getElementById('moduleDetailsModal').classList.add('active');
    document.body.style.overflow = 'hidden';
}

// Close Module Details Modal
function closeModuleDetailsModal() {
    document.getElementById('moduleDetailsModal').classList.remove('active');
    document.body.style.overflow = '';
}








// ============================================
// GOOGLE MAPS FULLSCREEN FUNCTION
// ============================================

function toggleFullscreenMap() {
    const mapWrapper = document.getElementById('mapWrapper');
    const expandBtn = document.querySelector('.expand-map-btn');
    const iframe = document.querySelector('#googleMapIframe');
    
    if (!mapWrapper) return;
    
    if (mapWrapper.classList.contains('fullscreen')) {
        // Exit fullscreen
        mapWrapper.classList.remove('fullscreen');
        expandBtn.innerHTML = '<i class="fas fa-expand"></i>';
        
        // Restore original iframe size
        if (iframe) {
            iframe.style.height = '350px';
        }
        
        // Remove any extra styles
        document.body.style.overflow = '';
        
    } else {
        // Enter fullscreen
        mapWrapper.classList.add('fullscreen');
        expandBtn.innerHTML = '<i class="fas fa-compress"></i>';
        
        // Make iframe full size
        if (iframe) {
            iframe.style.height = '100%';
        }
        
        // Prevent body scroll
        document.body.style.overflow = 'hidden';
        
        // Add close button if not exists
        if (!document.querySelector('.fullscreen-close')) {
            const closeBtn = document.createElement('button');
            closeBtn.className = 'fullscreen-close';
            closeBtn.innerHTML = '<i class="fas fa-times"></i> Funga';
            closeBtn.onclick = toggleFullscreenMap;
            closeBtn.style.cssText = `
                position: fixed;
                top: 20px;
                left: 20px;
                z-index: 10000;
                background: #ef4444;
                color: white;
                border: none;
                padding: 10px 15px;
                border-radius: 8px;
                cursor: pointer;
                font-weight: 600;
            `;
            mapWrapper.appendChild(closeBtn);
        }
    }
}

// Close fullscreen on escape key
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        const mapWrapper = document.getElementById('mapWrapper');
        if (mapWrapper && mapWrapper.classList.contains('fullscreen')) {
            toggleFullscreenMap();
        }
    }
});

// ============================================
// FULLSCREEN MAP FUNCTION
// ============================================

function toggleFullscreenMap() {
    const mapContainer = document.getElementById('mapContainer');
    const expandBtn = document.querySelector('.expand-map');
    const iframe = document.getElementById('locationMap');
    
    if (!mapContainer) return;
    
    if (mapContainer.classList.contains('fullscreen')) {
        // Exit fullscreen
        mapContainer.classList.remove('fullscreen');
        if (expandBtn) expandBtn.innerHTML = '<i class="fas fa-expand"></i>';
        if (iframe) iframe.style.height = '350px';
        document.body.style.overflow = '';
        
        // Remove close button
        const closeBtn = document.querySelector('.fullscreen-close');
        if (closeBtn) closeBtn.remove();
        
    } else {
        // Enter fullscreen
        mapContainer.classList.add('fullscreen');
        if (expandBtn) expandBtn.innerHTML = '<i class="fas fa-compress"></i>';
        if (iframe) iframe.style.height = '100%';
        document.body.style.overflow = 'hidden';
        
        // Add close button
        if (!document.querySelector('.fullscreen-close')) {
            const closeBtn = document.createElement('button');
            closeBtn.className = 'fullscreen-close';
            closeBtn.innerHTML = '<i class="fas fa-times"></i> Funga Ramani';
            closeBtn.onclick = toggleFullscreenMap;
            mapContainer.appendChild(closeBtn);
        }
    }
}

// Close fullscreen on escape key
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        const mapContainer = document.getElementById('mapContainer');
        if (mapContainer && mapContainer.classList.contains('fullscreen')) {
            toggleFullscreenMap();
        }
    }
});


