// Jina la eneo (badala ya kiungo kifupi)
const LOCATION_NAME = "Songwe Vocational Training Centre Tanzania";
const LOCATION_QUERY = "Songwe+Mlowo+Tanzania";

// Kitufe cha kupata maelekezo (kwa kutumia GPS au eneo la sasa)
function initDirections() {
    const btn = document.getElementById('getDirectionsBtn');
    if (!btn) return;

    btn.addEventListener('click', () => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => {
                    const userLat = position.coords.latitude;
                    const userLng = position.coords.longitude;
                    const destination = encodeURIComponent(LOCATION_NAME);
                    const url = `https://www.google.com/maps/dir/${userLat},${userLng}/${destination}/`;
                    window.open(url, '_blank');
                },
                () => {
                    // Ikiwa GPS haipatikani
                    const url = `https://www.google.com/maps/dir//${encodeURIComponent(LOCATION_NAME)}/`;
                    window.open(url, '_blank');
                }
            );
        } else {
            const url = `https://www.google.com/maps/dir//${encodeURIComponent(LOCATION_NAME)}/`;
            window.open(url, '_blank');
        }
    });
}

// Kitufe cha kufungua Google Maps kwenye kichupo kipya
function initOpenMap() {
    const btn = document.getElementById('openMapBtn');
    if (!btn) return;

    btn.addEventListener('click', () => {
        const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(LOCATION_NAME)}`;
        window.open(url, '_blank');
    });
}

// Kitufe cha kufungua ramani kubwa (iframe alternative)
function initFullMap() {
    const btn = document.getElementById('fullMapBtn');
    if (!btn) return;

    btn.addEventListener('click', () => {
        const url = `https://www.google.com/maps/place/${encodeURIComponent(LOCATION_NAME)}/`;
        window.open(url, '_blank');
    });
}

