// Preview slide image before upload
function previewSlideImage(event) {
    const file = event.target.files[0];
    if (file) {
        // Validate file type
        const validTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
        if (!validTypes.includes(file.type)) {
            alert('Please select a valid image file (JPG, PNG, WebP, or GIF)');
            event.target.value = '';
            return;
        }
        
        // Validate file size (max 10MB)
        if (file.size > 10 * 1024 * 1024) {
            alert('Image size must be less than 10MB');
            event.target.value = '';
            return;
        }
        
        const reader = new FileReader();
        reader.onload = function(e) {
            const preview = document.getElementById('slideImagePreview');
            const placeholder = document.getElementById('slideImagePlaceholder');
            
            preview.src = e.target.result;
            preview.style.display = 'block';
            placeholder.style.display = 'none';
        };
        reader.readAsDataURL(file);
    }
}

// Reset slide form
function resetSlideForm() {
    document.getElementById('addSlideForm').reset();
    document.getElementById('slideImagePreview').style.display = 'none';
    document.getElementById('slideImagePlaceholder').style.display = 'flex';
    document.getElementById('slideImageInput').value = '';
    document.getElementById('slideUploadProgress').style.display = 'none';
}

// Upload slide image to Firebase Storage
async function uploadSlideImage(file) {
    if (!file) throw new Error('No file selected');
    
    const progressDiv = document.getElementById('slideUploadProgress');
    const progressBar = progressDiv.querySelector('.progress-bar');
    progressDiv.style.display = 'block';
    
    try {
        const fileExtension = file.name.split('.').pop();
        const fileName = `slideshow/slide_${Date.now()}.${fileExtension}`;
        const storageRef = storage.ref(fileName);
        
        const uploadTask = storageRef.put(file);
        
        uploadTask.on('state_changed', 
            (snapshot) => {
                const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
                progressBar.style.width = progress + '%';
            },
            (error) => {
                console.error('Upload error:', error);
                progressDiv.style.display = 'none';
                throw error;
            }
        );
        
        await uploadTask;
        const downloadURL = await storageRef.getDownloadURL();
        
        progressDiv.style.display = 'none';
        return downloadURL;
        
    } catch (error) {
        progressDiv.style.display = 'none';
        throw error;
    }
}

// Add Slide Form Submit
document.getElementById('addSlideForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const title = document.getElementById('slideTitle').value.trim();
    const description = document.getElementById('slideDescription').value.trim();
    const buttonLink = document.getElementById('slideButtonLink').value.trim();
    const buttonText = document.getElementById('slideButtonText').value.trim();
    const order = parseInt(document.getElementById('slideOrder').value) || 0;
    const active = document.getElementById('slideActive').value === 'true';
    const imageFile = document.getElementById('slideImageInput').files[0];
    
    if (!title) {
        alert('Please enter a slide title');
        return;
    }
    
    if (!imageFile) {
        alert('Please select an image to upload');
        return;
    }
    
    const submitBtn = e.target.querySelector('button[type="submit"]');
    const originalText = submitBtn.textContent;
    submitBtn.disabled = true;
    submitBtn.textContent = 'Uploading...';
    
    try {
        // Upload image
        const imageUrl = await uploadSlideImage(imageFile);
        
        // Save slide data to Firestore
        await db.collection('slideshow').add({
            title: title,
            description: description,
            imageUrl: imageUrl,
            buttonLink: buttonLink || '',
            buttonText: buttonText || '',
            order: order,
            active: active,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: currentUser.uid
        });
        
        alert('✅ Slide added successfully!');
        resetSlideForm();
        await loadSlidesList();
        await loadPublicSlideshow();
        
    } catch (error) {
        console.error('Error adding slide:', error);
        alert('Error: ' + error.message);
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = originalText;
    }
});

// Load slides list
async function loadSlidesList() {
    const container = document.getElementById('slidesList');
    if (!container) return;
    
    try {
        const snapshot = await db.collection('slideshow')
            .orderBy('order', 'asc')
            .orderBy('createdAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <div class="empty-state">
                    <i class="fas fa-images"></i>
                    <p>No slides added yet</p>
                    <small>Add your first slide using the form above</small>
                </div>
            `;
            return;
        }
        
        container.innerHTML = '';
        
        snapshot.forEach(doc => {
            const slide = doc.data();
            const slideId = doc.id;
            
            container.innerHTML += `
                <div class="slide-card ${slide.active ? 'active' : 'inactive'}">
                    <div class="slide-card-image">
                        <img src="${slide.imageUrl}" alt="${slide.title}" onerror="this.src='https://via.placeholder.com/300x200?text=No+Image'">
                        ${slide.active ? '<span class="active-badge">Active</span>' : '<span class="inactive-badge">Inactive</span>'}
                    </div>
                    <div class="slide-card-info">
                        <h4>${escapeHtml(slide.title)}</h4>
                        <p>${escapeHtml(slide.description || 'No description')}</p>
                        <div class="slide-card-meta">
                            <span>Order: ${slide.order || 0}</span>
                            ${slide.buttonText ? `<span>Button: ${escapeHtml(slide.buttonText)}</span>` : ''}
                        </div>
                        <div class="slide-card-actions">
                            <button class="btn-edit btn-sm" onclick="editSlide('${slideId}')">
                                <i class="fas fa-edit"></i> Edit
                            </button>
                            <button class="btn-toggle btn-sm" onclick="toggleSlide('${slideId}', ${slide.active})">
                                <i class="fas fa-${slide.active ? 'eye-slash' : 'eye'}"></i>
                                ${slide.active ? 'Deactivate' : 'Activate'}
                            </button>
                            <button class="btn-delete btn-sm" onclick="deleteSlide('${slideId}')">
                                <i class="fas fa-trash"></i> Delete
                            </button>
                        </div>
                    </div>
                </div>
            `;
        });
        
    } catch (error) {
        console.error('Error loading slides:', error);
        container.innerHTML = '<p class="error-text">Error loading slides</p>';
    }
}

// Edit slide
async function editSlide(slideId) {
    const slideDoc = await db.collection('slideshow').doc(slideId).get();
    if (!slideDoc.exists) return;
    
    const slide = slideDoc.data();
    
    // Populate form for editing
    document.getElementById('slideTitle').value = slide.title || '';
    document.getElementById('slideDescription').value = slide.description || '';
    document.getElementById('slideButtonLink').value = slide.buttonLink || '';
    document.getElementById('slideButtonText').value = slide.buttonText || '';
    document.getElementById('slideOrder').value = slide.order || 0;
    document.getElementById('slideActive').value = slide.active ? 'true' : 'false';
    
    // Show existing image
    if (slide.imageUrl) {
        document.getElementById('slideImagePreview').src = slide.imageUrl;
        document.getElementById('slideImagePreview').style.display = 'block';
        document.getElementById('slideImagePlaceholder').style.display = 'none';
    }
    
    // Change form to update mode
    const form = document.getElementById('addSlideForm');
    const submitBtn = form.querySelector('button[type="submit"]');
    submitBtn.innerHTML = '<i class="fas fa-save"></i> Update Slide';
    submitBtn.setAttribute('data-editing', slideId);
    submitBtn.style.background = '#10b981';
    
    // Scroll to form
    form.scrollIntoView({ behavior: 'smooth' });
}

// Override form submit for editing
const originalSubmitHandler = document.getElementById('addSlideForm')?.onsubmit;
document.getElementById('addSlideForm')?.addEventListener('submit', async function(e) {
    const submitBtn = this.querySelector('button[type="submit"]');
    const editingId = submitBtn?.getAttribute('data-editing');
    
    if (editingId) {
        e.preventDefault();
        
        const title = document.getElementById('slideTitle').value.trim();
        const description = document.getElementById('slideDescription').value.trim();
        const buttonLink = document.getElementById('slideButtonLink').value.trim();
        const buttonText = document.getElementById('slideButtonText').value.trim();
        const order = parseInt(document.getElementById('slideOrder').value) || 0;
        const active = document.getElementById('slideActive').value === 'true';
        const imageFile = document.getElementById('slideImageInput').files[0];
        
        if (!title) {
            alert('Please enter a slide title');
            return;
        }
        
        submitBtn.disabled = true;
        submitBtn.textContent = 'Updating...';
        
        try {
            const updateData = {
                title: title,
                description: description,
                buttonLink: buttonLink,
                buttonText: buttonText,
                order: order,
                active: active,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            };
            
            // Upload new image if selected
            if (imageFile) {
                updateData.imageUrl = await uploadSlideImage(imageFile);
            }
            
            await db.collection('slideshow').doc(editingId).update(updateData);
            
            alert('✅ Slide updated successfully!');
            resetSlideForm();
            
            // Reset button
            submitBtn.innerHTML = '<i class="fas fa-plus"></i> Add Slide';
            submitBtn.removeAttribute('data-editing');
            submitBtn.style.background = '#e65c1e';
            
            await loadSlidesList();
            await loadPublicSlideshow();
            
        } catch (error) {
            console.error('Error updating slide:', error);
            alert('Error: ' + error.message);
        } finally {
            submitBtn.disabled = false;
            submitBtn.textContent = submitBtn.getAttribute('data-editing') ? 'Update Slide' : 'Add Slide';
        }
    }
});

// Toggle slide active/inactive
async function toggleSlide(slideId, currentActive) {
    try {
        await db.collection('slideshow').doc(slideId).update({
            active: !currentActive,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        await loadSlidesList();
        await loadPublicSlideshow();
        
    } catch (error) {
        console.error('Error toggling slide:', error);
        alert('Error: ' + error.message);
    }
}

// Delete slide
async function deleteSlide(slideId) {
    if (!confirm('Are you sure you want to delete this slide? This cannot be undone!')) {
        return;
    }
    
    try {
        // Get slide data to delete image from storage
        const slideDoc = await db.collection('slideshow').doc(slideId).get();
        const slide = slideDoc.data();
        
        // Delete from Firestore
        await db.collection('slideshow').doc(slideId).delete();
        
        // Try to delete image from storage
        if (slide.imageUrl) {
            try {
                const imageRef = storage.refFromURL(slide.imageUrl);
                await imageRef.delete();
            } catch (storageError) {
                console.log('Could not delete storage file:', storageError);
            }
        }
        
        alert('✅ Slide deleted successfully!');
        await loadSlidesList();
        await loadPublicSlideshow();
        
    } catch (error) {
        console.error('Error deleting slide:', error);
        alert('Error: ' + error.message);
    }
}



