// Load slides list - SIMPLIFIED VERSION (no composite index needed)
async function loadSlidesList() {
    const container = document.getElementById('slidesList');
    if (!container) {
        console.error('slidesList container not found');
        return;
    }
    
    try {
        // Use a simpler query that doesn't require composite index
        const snapshot = await db.collection('slideshow')
            .orderBy('createdAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <div class="empty-state">
                    <i class="fas fa-images"></i>
                    <p>No slides added yet</p>
                    <small>Add your first slide using the form above</small>
                </div>
            `;
            return;
        }
        
        container.innerHTML = '';
        
        // Sort manually by order if needed
        const slides = [];
        snapshot.forEach(doc => {
            slides.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by order, then by date
        slides.sort((a, b) => {
            const orderA = a.order || 0;
            const orderB = b.order || 0;
            if (orderA !== orderB) return orderA - orderB;
            
            const dateA = a.createdAt?.toDate() || new Date(0);
            const dateB = b.createdAt?.toDate() || new Date(0);
            return dateB - dateA;
        });
        
        // Display slides
        slides.forEach(slide => {
            container.innerHTML += `
                <div class="slide-card ${slide.active ? 'active' : 'inactive'}">
                    <div class="slide-card-image">
                        <img src="${slide.imageUrl}" alt="${escapeHtml(slide.title)}" 
                             onerror="this.src='https://via.placeholder.com/300x200?text=No+Image'">
                        ${slide.active ? 
                            '<span class="active-badge">Active</span>' : 
                            '<span class="inactive-badge">Inactive</span>'}
                    </div>
                    <div class="slide-card-info">
                        <h4>${escapeHtml(slide.title)}</h4>
                        <p>${escapeHtml(slide.description || 'No description')}</p>
                        <div class="slide-card-meta">
                            <span>Order: ${slide.order || 0}</span>
                            ${slide.buttonText ? `<span>Button: ${escapeHtml(slide.buttonText)}</span>` : ''}
                        </div>
                        <div class="slide-card-actions">
                            <button class="btn-edit btn-sm" onclick="editSlide('${slide.id}')">
                                <i class="fas fa-edit"></i> Edit
                            </button>
                            <button class="btn-toggle btn-sm" onclick="toggleSlide('${slide.id}', ${slide.active})">
                                <i class="fas fa-${slide.active ? 'eye-slash' : 'eye'}"></i>
                                ${slide.active ? 'Deactivate' : 'Activate'}
                            </button>
                            <button class="btn-delete btn-sm" onclick="deleteSlide('${slide.id}')">
                                <i class="fas fa-trash"></i> Delete
                            </button>
                        </div>
                    </div>
                </div>
            `;
        });
        
        console.log(`✅ Loaded ${slides.length} slides`);
        
    } catch (error) {
        console.error('Error loading slides:', error);
        container.innerHTML = `
            <p class="error-text">
                Error loading slides: ${error.message}
                <br><small>Please check your Firestore indexes or try again later.</small>
            </p>
        `;
    }
}

async function loadPublicSlideshow() {
    const container = document.getElementById('slideshowContainer');
    if (!container) return;
    
    try {
        const snapshot = await db.collection('slideshow')
            .where('active', '==', true)
            .get();
        
        slides = [];
        snapshot.forEach(doc => {
            slides.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by order
        slides.sort((a, b) => (a.order || 0) - (b.order || 0));
        
        // Clear existing slides
        const existingSlides = container.querySelectorAll('.slide');
        existingSlides.forEach(slide => slide.remove());
        
        if (slides.length === 0) {
            // Default slide
            const defaultSlide = document.createElement('div');
            defaultSlide.className = 'slide active-slide';
            defaultSlide.innerHTML = `
                <img src="https://picsum.photos/id/20/1920/1080" alt="Welcome" loading="lazy">
                <div class="slide-caption">
                    <h3>Karibu Songwe VTC</h3>
                    <p>Taasisi ya mafunzo ya kitaalamu</p>
                </div>
            `;
            container.appendChild(defaultSlide);
        } else {
            let isFirst = true;
            
            slides.forEach(slide => {
                const slideDiv = document.createElement('div');
                slideDiv.className = `slide ${isFirst ? 'active-slide' : ''}`;
                
                if (slide.type === 'video') {
                    // Video slide
                    const videoId = getYouTubeId(slide.mediaUrl);
                    if (videoId) {
                        slideDiv.innerHTML = `
                            <iframe width="100%" height="100%" 
                                    src="https://www.youtube.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}" 
                                    frameborder="0" allow="autoplay; encrypted-media" allowfullscreen>
                            </iframe>
                            <div class="slide-caption">
                                <h3>${escapeHtml(slide.title)}</h3>
                                ${slide.description ? `<p>${escapeHtml(slide.description)}</p>` : ''}
                                ${slide.buttonText ? `
                                    <a href="${slide.buttonLink || '#'}" class="slide-button">${escapeHtml(slide.buttonText)}</a>
                                ` : ''}
                            </div>
                        `;
                    }
                } else {
                    // Image slide
                    slideDiv.innerHTML = `
                        <img src="${slide.mediaUrl}" alt="${escapeHtml(slide.title)}" loading="${isFirst ? 'eager' : 'lazy'}" 
                             onerror="this.src='https://picsum.photos/id/20/1920/1080'">
                        <div class="slide-caption">
                            <h3>${escapeHtml(slide.title)}</h3>
                            ${slide.description ? `<p>${escapeHtml(slide.description)}</p>` : ''}
                            ${slide.buttonText ? `
                                <a href="${slide.buttonLink || '#'}" class="slide-button">${escapeHtml(slide.buttonText)}</a>
                            ` : ''}
                        </div>
                    `;
                }
                
                container.appendChild(slideDiv);
                isFirst = false;
            });
        }
        
        // Start slideshow
        if (slides.length > 0) {
            startSlideshow();
        }
        
    } catch (error) {
        console.error('Error loading slideshow:', error);
    }
}

// ============================================
// OPTIMIZED IMAGE UPLOAD WITH COMPRESSION
// ============================================

// Add image compression before upload
async function compressImage(file, maxWidth = 1920, maxHeight = 1080, quality = 0.8) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        
        reader.onload = function(e) {
            const img = new Image();
            img.src = e.target.result;
            
            img.onload = function() {
                // Create canvas for resizing
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                
                // Calculate new dimensions
                if (width > maxWidth) {
                    height = (maxWidth / width) * height;
                    width = maxWidth;
                }
                if (height > maxHeight) {
                    width = (maxHeight / height) * width;
                    height = maxHeight;
                }
                
                canvas.width = width;
                canvas.height = height;
                
                const ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0, width, height);
                
                // Convert to blob with reduced quality
                canvas.toBlob((blob) => {
                    const compressedFile = new File([blob], file.name, {
                        type: 'image/jpeg',
                        lastModified: Date.now()
                    });
                    
                    // Log size reduction
                    const originalSize = (file.size / 1024 / 1024).toFixed(2);
                    const compressedSize = (compressedFile.size / 1024 / 1024).toFixed(2);
                    console.log(`Image compressed: ${originalSize}MB → ${compressedSize}MB (${Math.round((1 - compressedFile.size/file.size) * 100)}% reduction)`);
                    
                    resolve(compressedFile);
                }, 'image/jpeg', quality);
            };
            
            img.onerror = reject;
        };
        
        reader.onerror = reject;
    });
}

// Optimized upload with progress bar
async function uploadSlideImageOptimized(file, progressCallback) {
    if (!file) throw new Error('No file selected');
    
    try {
        // First, compress the image
        const compressedFile = await compressImage(file);
        
        // Generate unique filename
        const timestamp = Date.now();
        const randomString = Math.random().toString(36).substring(7);
        const fileExtension = 'jpg'; // Always use jpg for compressed images
        const fileName = `slideshow/slide_${timestamp}_${randomString}.${fileExtension}`;
        const storageRef = storage.ref(fileName);
        
        // Create upload metadata
        const metadata = {
            contentType: 'image/jpeg',
            cacheControl: 'public, max-age=31536000', // Cache for 1 year
        };
        
        // Start upload
        const uploadTask = storageRef.put(compressedFile, metadata);
        
        // Track progress
        uploadTask.on('state_changed', 
            (snapshot) => {
                const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
                if (progressCallback) {
                    progressCallback(progress);
                }
            },
            (error) => {
                console.error('Upload error:', error);
                throw error;
            }
        );
        
        // Wait for completion
        await uploadTask;
        
        // Get download URL
        const downloadURL = await storageRef.getDownloadURL();
        
        console.log('Upload complete:', downloadURL);
        return downloadURL;
        
    } catch (error) {
        console.error('Upload failed:', error);
        throw error;
    }
}

// ============================================
// IMPROVED SLIDE FORM SUBMIT WITH FEEDBACK
// ============================================

document.getElementById('addSlideForm')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const title = document.getElementById('slideTitle').value.trim();
    const description = document.getElementById('slideDescription').value.trim();
    const buttonLink = document.getElementById('slideButtonLink').value.trim();
    const buttonText = document.getElementById('slideButtonText').value.trim();
    const order = parseInt(document.getElementById('slideOrder').value) || 0;
    const active = document.getElementById('slideActive').value === 'true';
    const imageFile = document.getElementById('slideImageInput').files[0];
    
    if (!title) {
        showToast('Please enter a slide title', 'error');
        return;
    }
    
    if (!imageFile) {
        showToast('Please select an image to upload', 'error');
        return;
    }
    
    // Check if editing
    const submitBtn = e.target.querySelector('button[type="submit"]');
    const editingId = submitBtn?.getAttribute('data-editing');
    
    // Show loading overlay
    showLoadingOverlay(editingId ? 'Updating Slide...' : 'Adding Slide...');
    
    const originalText = submitBtn.textContent;
    submitBtn.disabled = true;
    
    try {
        let imageUrl;
        
        // Upload image with progress
        if (imageFile || !editingId) {
            await updateLoadingStatus('Compressing image...');
            
            imageUrl = await uploadSlideImageOptimized(imageFile, (progress) => {
                updateLoadingProgress(progress);
                updateLoadingStatus(`Uploading image... ${Math.round(progress)}%`);
            });
        }
        
        await updateLoadingStatus('Saving slide data...');
        
        const slideData = {
            title: title,
            description: description,
            buttonLink: buttonLink,
            buttonText: buttonText,
            order: order,
            active: active,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (imageUrl) {
            slideData.imageUrl = imageUrl;
        }
        
        if (editingId) {
            // Update existing slide
            await db.collection('slideshow').doc(editingId).update(slideData);
        } else {
            // Add new slide
            slideData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            slideData.createdBy = currentUser.uid;
            await db.collection('slideshow').add(slideData);
        }
        
        // Success!
        hideLoadingOverlay();
        showToast(editingId ? '✅ Slide updated successfully!' : '✅ Slide added successfully!', 'success');
        
        // Reset form
        resetSlideForm();
        
        // Reset button if editing
        if (editingId) {
            submitBtn.innerHTML = '<i class="fas fa-plus"></i> Add Slide';
            submitBtn.removeAttribute('data-editing');
            submitBtn.style.background = '#e65c1e';
        }
        
        // Refresh lists
        await Promise.all([
            loadSlidesList(),
            loadPublicSlideshow()
        ]);
        
    } catch (error) {
        console.error('Error saving slide:', error);
        hideLoadingOverlay();
        showToast('Error: ' + error.message, 'error');
        
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = editingId ? 'Update Slide' : 'Add Slide';
    }
});

// ============================================
// LOADING OVERLAY FUNCTIONS
// ============================================

function showLoadingOverlay(message = 'Saving...') {
    // Remove existing overlay if any
    hideLoadingOverlay();
    
    const overlay = document.createElement('div');
    overlay.className = 'saving-overlay';
    overlay.id = 'savingOverlay';
    overlay.innerHTML = `
        <div class="saving-modal">
            <div class="saving-spinner">
                <i class="fas fa-spinner fa-spin"></i>
            </div>
            <h3 id="savingMessage">${message}</h3>
            <div class="saving-progress-bar">
                <div class="saving-progress-fill" id="savingProgressFill"></div>
            </div>
            <p class="saving-hint">Please wait while we process your image...</p>
        </div>
    `;
    overlay.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.7);
        z-index: 9999;
        display: flex;
        align-items: center;
        justify-content: center;
    `;
    document.body.appendChild(overlay);
}

function updateLoadingStatus(message) {
    const statusElement = document.getElementById('savingMessage');
    if (statusElement) {
        statusElement.textContent = message;
    }
}

function updateLoadingProgress(progress) {
    const progressBar = document.getElementById('savingProgressFill');
    if (progressBar) {
        progressBar.style.width = progress + '%';
    }
}

function hideLoadingOverlay() {
    const overlay = document.getElementById('savingOverlay');
    if (overlay) {
        overlay.remove();
    }
}

// ============================================
// TOAST NOTIFICATION SYSTEM
// ============================================

function showToast(message, type = 'success') {
    // Remove existing toasts
    const existingToasts = document.querySelectorAll('.custom-toast');
    existingToasts.forEach(toast => toast.remove());
    
    const toast = document.createElement('div');
    toast.className = `custom-toast toast-${type}`;
    toast.innerHTML = `
        <i class="fas fa-${type === 'success' ? 'check-circle' : type === 'error' ? 'exclamation-circle' : 'info-circle'}"></i>
        <span>${message}</span>
    `;
    toast.style.cssText = `
        position: fixed;
        bottom: 20px;
        right: 20px;
        background: ${type === 'success' ? '#10b981' : type === 'error' ? '#ef4444' : '#3b82f6'};
        color: white;
        padding: 12px 20px;
        border-radius: 12px;
        z-index: 10000;
        display: flex;
        align-items: center;
        gap: 10px;
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
        animation: slideInRight 0.3s ease;
        max-width: 90%;
        font-size: 0.9rem;
    `;
    
    document.body.appendChild(toast);
    
    // Auto remove after 3 seconds
    setTimeout(() => {
        toast.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

// ============================================
// OPTIMIZED SLIDES LIST LOADING
// ============================================

// Cache slides data to avoid repeated fetches
let slidesCache = null;
let slidesCacheTime = null;
const CACHE_DURATION = 30000; // 30 seconds

async function loadSlidesList(forceRefresh = false) {
    const container = document.getElementById('slidesList');
    if (!container) return;
    
    // Use cache if available and not expired
    if (!forceRefresh && slidesCache && slidesCacheTime && (Date.now() - slidesCacheTime < CACHE_DURATION)) {
        renderSlidesList(slidesCache, container);
        return;
    }
    
    try {
        const snapshot = await db.collection('slideshow')
            .orderBy('createdAt', 'desc')
            .get();
        
        const slides = [];
        snapshot.forEach(doc => {
            slides.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by order
        slides.sort((a, b) => (a.order || 0) - (b.order || 0));
        
        // Update cache
        slidesCache = slides;
        slidesCacheTime = Date.now();
        
        renderSlidesList(slides, container);
        
    } catch (error) {
        console.error('Error loading slides:', error);
        container.innerHTML = `
            <div class="error-state">
                <i class="fas fa-exclamation-triangle"></i>
                <p>Error loading slides</p>
                <small>${error.message}</small>
                <button onclick="loadSlidesList(true)" class="btn-retry">
                    <i class="fas fa-redo"></i> Retry
                </button>
            </div>
        `;
    }
}

function renderSlidesList(slides, container) {
    if (!slides || slides.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <i class="fas fa-images"></i>
                <p>No slides added yet</p>
                <small>Add your first slide using the form above</small>
            </div>
        `;
        return;
    }
    
    container.innerHTML = '';
    
    slides.forEach(slide => {
        container.innerHTML += `
            <div class="slide-card ${slide.active ? 'active' : 'inactive'}">
                <div class="slide-card-image">
                    <img src="${slide.imageUrl}" alt="${escapeHtml(slide.title)}" 
                         loading="lazy"
                         onerror="this.src='https://via.placeholder.com/300x200?text=No+Image'">
                    <span class="${slide.active ? 'active-badge' : 'inactive-badge'}">
                        ${slide.active ? 'Active' : 'Inactive'}
                    </span>
                </div>
                <div class="slide-card-info">
                    <h4>${escapeHtml(slide.title)}</h4>
                    <p>${escapeHtml(slide.description || 'No description')}</p>
                    <div class="slide-card-meta">
                        <span>Order: ${slide.order || 0}</span>
                        ${slide.buttonText ? `<span>Button: ${escapeHtml(slide.buttonText)}</span>` : ''}
                    </div>
                    <div class="slide-card-actions">
                        <button class="btn-edit btn-sm" onclick="editSlide('${slide.id}')">
                            <i class="fas fa-edit"></i> Edit
                        </button>
                        <button class="btn-toggle btn-sm" onclick="toggleSlide('${slide.id}', ${slide.active})">
                            <i class="fas fa-${slide.active ? 'eye-slash' : 'eye'}"></i>
                            ${slide.active ? 'Deactivate' : 'Activate'}
                        </button>
                        <button class="btn-delete btn-sm" onclick="deleteSlide('${slide.id}')">
                            <i class="fas fa-trash"></i> Delete
                        </button>
                    </div>
                </div>
            </div>
        `;
    });
}

