async function loadUsersManagement() {
    console.log('Loading users management...');
    const container = document.getElementById('usersManagementList');
    
    if (!container) {
        console.error('usersManagementList container not found');
        return;
    }
    
    container.innerHTML = '<tr><td colspan="7" class="text-center">Loading users...</td></tr>';
    
    try {
        const snapshot = await db.collection('users')
            .where('role', '==', 'user')
            .orderBy('createdAt', 'desc')
            .get();
        
        allUsers = [];
        
        if (snapshot.empty) {
            container.innerHTML = '<tr><td colspan="7" class="text-center">No users found</td></tr>';
            return;
        }
        
        snapshot.forEach(doc => {
            allUsers.push({ id: doc.id, ...doc.data() });
        });
        
        renderUsersList(allUsers);
        console.log(`Loaded ${allUsers.length} users`);
        
    } catch (error) {
        console.error('Error loading users:', error);
        container.innerHTML = `<tr><td colspan="7" class="text-center text-danger">Error: ${error.message}</td></tr>`;
    }
}

