// ========== SAVE USER EDIT ==========
async function saveUserEdit(event) {
    event.preventDefault();
    
    const userId = document.getElementById('editUserId').value;
    const name = document.getElementById('editUserFullName').value.trim();
    const username = document.getElementById('editUserUsername').value.trim();
    const email = document.getElementById('editUserEmail').value.trim();
    const phone = document.getElementById('editUserPhone').value.trim();
    const nida = document.getElementById('editUserNida').value.trim();
    const formIndex = document.getElementById('editUserFormIndex').value.trim();
    const dob = document.getElementById('editUserDOB').value;
    const gender = document.getElementById('editUserGender').value;
    const address = document.getElementById('editUserAddress').value.trim();
    const status = document.getElementById('editUserStatus').value;
    const newPassword = document.getElementById('editUserNewPassword').value;
    const confirmPassword = document.getElementById('editUserConfirmPassword').value;
    const rejectReason = status === 'rejected' ? document.getElementById('editUserRejectReason')?.value : '';
    
    // Validate
    if (!name || !email) {
        showToast('Name and email are required', 'error');
        return;
    }
    
    if (newPassword && newPassword !== confirmPassword) {
        showToast('Passwords do not match', 'error');
        return;
    }
    
    const submitBtn = event.target.querySelector('button[type="submit"]');
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    
    try {
        const updateData = {
            name, username, email, phone, nida, formIndex,
            dateOfBirth: dob, gender, address, status,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (rejectReason) {
            updateData.rejectReason = rejectReason;
        }
        
        // Update Firestore
        await db.collection('users').doc(userId).update(updateData);
        
        // Change password if provided
        if (newPassword && newPassword.length >= 6) {
            // Note: Admin cannot directly change user password via client SDK
            // This would need a Cloud Function. For now, store a flag.
            await db.collection('passwordChangeRequests').add({
                userId: userId,
                requestedBy: currentUser.uid,
                requestedAt: firebase.firestore.FieldValue.serverTimestamp(),
                status: 'pending'
            });
            showToast('⚠️ Password change requested. Contact Super Admin.', 'warning');
        }
        
        // Send notification to user
        await db.collection('notifications').add({
            userId: userId,
            type: 'account_updated',
            message: `Your account has been updated by admin. Status: ${status}`,
            read: false,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ User updated successfully!', 'success');
        closeEditUserModal();
        loadUsersManagement();
        
    } catch (error) {
        console.error('Error updating user:', error);
        showToast('❌ Failed to update user: ' + error.message, 'error');
    } finally {
        submitBtn.disabled = false;
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Save Changes';
    }
}

// ========== OPEN USER COURSES MODAL ==========
async function openUserCoursesModal(userId) {
    currentViewingUser = userId;
    
    try {
        const userDoc = await db.collection('users').doc(userId).get();
        if (!userDoc.exists) return;
        
        const user = userDoc.data();
        const enrolledCourses = user.enrolledCourses || [];
        
        // Get all available courses
        const allCoursesSnapshot = await db.collection('courses')
            .where('active', '==', true)
            .get();
        
        const allCourses = [];
        allCoursesSnapshot.forEach(doc => {
            allCourses.push({ id: doc.id, ...doc.data() });
        });
        
        // Separate enrolled and available
        const enrolledList = [];
        const availableList = [];
        
        for (const course of allCourses) {
            const courseData = {
                ...course,
                enrolled: enrolledCourses.includes(course.id)
            };
            
            if (courseData.enrolled) {
                enrolledList.push(courseData);
            } else {
                availableList.push(courseData);
            }
        }
        
        const content = document.getElementById('userCoursesModalContent');
        content.innerHTML = `
            <div class="courses-management">
                <div class="user-info-mini">
                    <img src="${user.profileImage || getAvatarUrl(user.name, 50)}" 
                         alt="${user.name}" 
                         onerror="this.src='${getAvatarUrl(user.name, 50)}'">
                    <div>
                        <h4>${escapeHtml(user.name)}</h4>
                        <p>${escapeHtml(user.email)}</p>
                    </div>
                </div>
                
                <hr class="section-divider">
                
                <div class="courses-section">
                    <h4><i class="fas fa-check-circle"></i> Enrolled Courses (${enrolledList.length})</h4>
                    ${enrolledList.length > 0 ? enrolledList.map(course => `
                        <div class="course-management-card enrolled">
                            <div class="course-info">
                                <strong>${escapeHtml(course.name)}</strong>
                                <span class="course-code">${escapeHtml(course.code)}</span>
                                <span class="course-duration">${escapeHtml(course.duration)}</span>
                            </div>
                            <button onclick="removeUserCourse('${userId}', '${course.id}', '${escapeHtml(course.name)}')" 
                                    class="btn-remove-course">
                                <i class="fas fa-times"></i> Remove
                            </button>
                        </div>
                    `).join('') : '<p class="text-muted">No courses enrolled</p>'}
                </div>
                
                <hr class="section-divider">
                
                <div class="courses-section">
                    <h4><i class="fas fa-plus-circle"></i> Available Courses (${availableList.length})</h4>
                    ${availableList.length > 0 ? `
                        <div class="available-courses-list">
                            ${availableList.map(course => `
                                <div class="course-management-card available">
                                    <div class="course-info">
                                        <strong>${escapeHtml(course.name)}</strong>
                                        <span class="course-code">${escapeHtml(course.code)}</span>
                                        <span class="course-duration">${escapeHtml(course.duration)}</span>
                                        ${course.fee ? `<span class="course-fee">TZS ${course.fee.toLocaleString()}</span>` : ''}
                                    </div>
                                    <button onclick="addUserCourse('${userId}', '${course.id}', '${escapeHtml(course.name)}')" 
                                            class="btn-add-course">
                                        <i class="fas fa-plus"></i> Add
                                    </button>
                                </div>
                            `).join('')}
                        </div>
                    ` : '<p class="text-muted">No available courses</p>'}
                </div>
                
                <div class="info-notice">
                    <i class="fas fa-info-circle"></i>
                    <p>Note: Users can only register for one course themselves. Additional courses must be added by admin.</p>
                </div>
            </div>
        `;
        
        document.getElementById('userCoursesModal').classList.add('active');
        document.body.style.overflow = 'hidden';
        
    } catch (error) {
        console.error('Error loading courses:', error);
        showToast('Error loading courses', 'error');
    }
}

