// ========== UPDATE ALL AVATARS ==========
function updateAllAvatars() {
    const user = currentUser;
    if (!user) return;
    
    const avatarUrl = user.profileImage || getAvatarUrl(user.name || user.email || 'User');
    const userName = user.name || 'User';
    const userEmail = user.email || '';
    
    // Update profile modal avatar
    updateAvatarElement('profileAvatar', avatarUrl);
    updateAvatarElement('editAvatarPreview', avatarUrl);
    updateAvatarElement('settingsAvatar', avatarUrl);
    
    // Update profile info
    updateElementText('profileName', userName);
    updateElementText('settingsUserName', userName);
    updateElementText('settingsUserEmail', userEmail);
    
    // Update role badge
    const roleBadge = document.getElementById('profileRole');
    if (roleBadge) {
        const roleText = getRoleText(user.role);
        const roleClass = getRoleClass(user.role);
        roleBadge.textContent = roleText;
        roleBadge.className = `profile-role-badge ${roleClass}`;
    }
    
    // Update all profile picture displays
    updateAllProfilePictureDisplays();
    updateNavigationAvatars();
}

// ========== GET AVATAR URL ==========
function getAvatarUrl(name, size = 150) {
    if (!name) name = 'User';
    const initials = name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
    const bgColor = stringToColor(name).replace('#', '');
    const textColor = 'ffffff';
    return `https://ui-avatars.com/api/?name=${initials}&background=${bgColor}&color=${textColor}&size=${size}&bold=true&format=svg`;
}

// ========== GENERATE RANDOM AVATAR ==========
async function generateRandomAvatar() {
    if (!currentUser) return;
    
    const styles = [
        'pixel-art', 'bottts', 'gridy', 'thumbs', 'identicon', 'avataaars',
        'jdenticon', 'lorelei', 'micah', 'miniavs', 'adventurer', 'big-smile'
    ];
    
    const randomStyle = styles[Math.floor(Math.random() * styles.length)];
    const seed = currentUser.uid || currentUser.email || 'user';
    
    const randomAvatarUrl = `https://api.dicebear.com/7.x/${randomStyle}/svg?seed=${seed}&backgroundColor=b6e3f4,c0aede,d1d4f9,ffd5dc,ffdfbf`;
    
    try {
        // Save the avatar URL
        await saveProfilePictureToFirestore(randomAvatarUrl);
        
        // Update local user
        currentUser.profileImage = randomAvatarUrl;
        localStorage.setItem('currentUser', JSON.stringify(currentUser));
        
        // Update all displays
        updateAllAvatars();
        updateAllProfilePictureDisplays();
        updateNavigationAvatars();
        
        showToast('🎨 Avatar generated successfully!', 'success');
        
    } catch (error) {
        console.error('Error generating avatar:', error);
        showToast('❌ Failed to generate avatar', 'error');
    }
}

// ========== UPDATE AVATAR ELEMENT ==========
function updateAvatarElement(elementId, imageUrl) {
    const element = document.getElementById(elementId);
    if (!element) return;
    
    if (element.tagName === 'IMG') {
        element.src = imageUrl;
        element.onerror = function() {
            const fallbackName = currentUser?.name || 'User';
            this.src = getAvatarUrl(fallbackName, 150);
        };
    } else if (element.style) {
        element.style.backgroundImage = `url(${imageUrl})`;
        element.style.backgroundSize = 'cover';
        element.style.backgroundPosition = 'center';
    }
}

// ========== UPDATE ELEMENT TEXT ==========
function updateElementText(elementId, text) {
    const element = document.getElementById(elementId);
    if (element) {
        element.textContent = text || '';
    }
}

// ========== GET ROLE TEXT ==========
function getRoleText(role) {
    const roles = {
        'superadmin': 'Super Admin',
        'admin': 'Administrator',
        'staff': 'Staff / Instructor',
        'user': 'Student'
    };
    return roles[role] || 'User';
}

// ========== GET ROLE CLASS ==========
function getRoleClass(role) {
    const classes = {
        'superadmin': 'role-superadmin',
        'admin': 'role-admin',
        'staff': 'role-staff',
        'user': 'role-student'
    };
    return classes[role] || 'role-student';
}

// ========== UPLOAD PROFILE PICTURE ONLY ==========
async function uploadProfilePictureOnly(event) {
    const file = event.target.files[0];
    if (!file) return;
    
    // Validate
    const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
    if (!validTypes.includes(file.type.toLowerCase())) {
        showToast('❌ Invalid file type. Use JPG, PNG, GIF, or WebP', 'error');
        event.target.value = '';
        return;
    }
    
    const maxSize = 5 * 1024 * 1024;
    if (file.size > maxSize) {
        showToast('❌ Image too large. Max 5MB allowed', 'error');
        event.target.value = '';
        return;
    }
    
    // Show loading
    const progressDiv = document.getElementById('editUploadProgress') || document.getElementById('profileUploadProgress');
    if (progressDiv) progressDiv.style.display = 'block';
    
    try {
        // Compress and upload
        const compressedFile = await compressImageForAvatar(file);
        const downloadURL = await uploadAvatarToStorage(compressedFile);
        
        // Save to Firestore
        await saveProfilePictureToFirestore(downloadURL);
        
        // Update local user
        currentUser.profileImage = downloadURL;
        localStorage.setItem('currentUser', JSON.stringify(currentUser));
        
        // Update all displays
        updateAllAvatars();
        updateAllProfilePictureDisplays();
        updateNavigationAvatars();
        
        showToast('✅ Profile photo updated!', 'success');
        
    } catch (error) {
        console.error('Upload error:', error);
        showToast('❌ Upload failed: ' + error.message, 'error');
    } finally {
        if (progressDiv) progressDiv.style.display = 'none';
        event.target.value = '';
    }
}

// ========== COMPRESS IMAGE FOR AVATAR ==========
async function compressImageForAvatar(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        
        reader.onload = function(e) {
            const img = new Image();
            img.src = e.target.result;
            
            img.onload = function() {
                const canvas = document.createElement('canvas');
                const maxSize = 500;
                
                let width = img.width;
                let height = img.height;
                
                if (width > height) {
                    if (width > maxSize) {
                        height = (maxSize / width) * height;
                        width = maxSize;
                    }
                } else {
                    if (height > maxSize) {
                        width = (maxSize / height) * width;
                        height = maxSize;
                    }
                }
                
                canvas.width = width;
                canvas.height = height;
                
                const ctx = canvas.getContext('2d');
                
                // Create circular mask
                ctx.beginPath();
                const centerX = width / 2;
                const centerY = height / 2;
                const radius = Math.min(width, height) / 2;
                ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
                ctx.clip();
                ctx.drawImage(img, 0, 0, width, height);
                
                canvas.toBlob((blob) => {
                    const compressedFile = new File([blob], 'avatar.jpg', {
                        type: 'image/jpeg',
                        lastModified: Date.now()
                    });
                    
                    console.log(`📸 Avatar compressed: ${(file.size/1024).toFixed(1)}KB → ${(compressedFile.size/1024).toFixed(1)}KB`);
                    resolve(compressedFile);
                }, 'image/jpeg', 0.85);
            };
            
            img.onerror = reject;
        };
        
        reader.onerror = reject;
    });
}

// ========== UPLOAD AVATAR TO STORAGE ==========
async function uploadAvatarToStorage(file) {
    if (!currentUser) throw new Error('User not logged in');
    
    const storageRef = firebase.storage().ref();
    const fileName = `avatars/${currentUser.uid}/${Date.now()}.jpg`;
    const fileRef = storageRef.child(fileName);
    
    const metadata = {
        contentType: 'image/jpeg',
        cacheControl: 'public, max-age=31536000',
        customMetadata: {
            userId: currentUser.uid,
            type: 'avatar',
            uploadedAt: new Date().toISOString()
        }
    };
    
    await fileRef.put(file, metadata);
    const downloadURL = await fileRef.getDownloadURL();
    
    return downloadURL;
}

