// ========== 1. EDIT USER PROFILE DETAILS ==========
async function editUserProfile(event) {
    event.preventDefault();
    
    const submitBtn = event.target.querySelector('button[type="submit"]');
    const originalText = submitBtn?.textContent;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Saving...';
    }
    
    try {
        // Get form values
        const name = document.getElementById('editFullName')?.value.trim();
        const phone = document.getElementById('editPhone')?.value.trim();
        const nida = document.getElementById('editNida')?.value.trim();
        const formIndex = document.getElementById('editFormIndex')?.value.trim();
        const bio = document.getElementById('editBio')?.value.trim();
        const address = document.getElementById('editAddress')?.value.trim();
        const dateOfBirth = document.getElementById('editDateOfBirth')?.value;
        const gender = document.getElementById('editGender')?.value;
        const nationality = document.getElementById('editNationality')?.value.trim();
        
        // Validation
        if (!name) {
            showToast('Name is required', 'error');
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = originalText;
            }
            return;
        }
        
        if (!phone) {
            showToast('Phone number is required', 'error');
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = originalText;
            }
            return;
        }
        
        // Prepare update data
        const updateData = {
            name: name,
            phone: phone,
            nida: nida || '',
            formIndex: formIndex || '',
            bio: bio || '',
            address: address || '',
            dateOfBirth: dateOfBirth || '',
            gender: gender || '',
            nationality: nationality || '',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        // Update Firestore
        await db.collection('users').doc(currentUser.uid).update(updateData);
        
        // Update local user object
        Object.assign(currentUser, updateData);
        localStorage.setItem('currentUser', JSON.stringify(currentUser));
        
        // Update UI elements
        updateUserDisplayNames(currentUser.name);
        
        showToast('✅ Profile updated successfully!', 'success');
        
        // Close modal if open
        if (typeof closeEditProfileModal === 'function') {
            closeEditProfileModal();
        }
        
        // Refresh profile display
        if (typeof loadProfileModalContent === 'function') {
            loadProfileModalContent();
        }
        
    } catch (error) {
        console.error('Error updating profile:', error);
        showToast('❌ Failed to update profile: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = originalText;
        }
    }
}

// ========== 2. UPLOAD PROFILE PICTURE (SEPARATE FROM EDIT) ==========
async function uploadProfilePictureOnly(event) {
    const file = event.target.files[0];
    if (!file) return;
    
    // Validate file type
    const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
    if (!validTypes.includes(file.type.toLowerCase())) {
        showToast('❌ Invalid file type. Use JPG, PNG, GIF, or WebP', 'error');
        event.target.value = '';
        return;
    }
    
    // Validate file size (max 5MB)
    const maxSize = 5 * 1024 * 1024;
    if (file.size > maxSize) {
        showToast('❌ Image size must be less than 5MB', 'error');
        event.target.value = '';
        return;
    }
    
    // Prevent multiple uploads
    if (profileUploadInProgress) {
        showToast('⚠️ Upload in progress. Please wait.', 'warning');
        return;
    }
    
    profileUploadInProgress = true;
    
    // Show loading
    showUploadProgress(true);
    updateUploadButtons('uploading');
    
    try {
        // Compress image
        const compressedFile = await compressImageForProfile(file);
        
        // Upload to Firebase Storage
        const downloadURL = await uploadToFirebaseStorage(compressedFile);
        
        // Save URL to Firestore
        await saveProfilePictureToFirestore(downloadURL);
        
        // Update local user object
        if (currentUser) {
            currentUser.profileImage = downloadURL;
            localStorage.setItem('currentUser', JSON.stringify(currentUser));
        }
        
        // Update all profile picture displays
        updateAllProfilePictureDisplays();
        updateNavigationAvatars();
        
        showToast('✅ Profile picture updated!', 'success');
        
    } catch (error) {
        console.error('Upload error:', error);
        showToast('❌ Failed to upload: ' + error.message, 'error');
    } finally {
        profileUploadInProgress = false;
        showUploadProgress(false);
        updateUploadButtons('default');
        event.target.value = '';
    }
}

// ========== 3. COMPRESS IMAGE FOR PROFILE ==========
async function compressImageForProfile(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        
        reader.onload = function(e) {
            const img = new Image();
            img.src = e.target.result;
            
            img.onload = function() {
                const canvas = document.createElement('canvas');
                const maxDimension = 500; // Max 500px for profile pictures
                
                let width = img.width;
                let height = img.height;
                
                // Calculate new dimensions maintaining aspect ratio
                if (width > height) {
                    if (width > maxDimension) {
                        height = (maxDimension / width) * height;
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = (maxDimension / height) * width;
                        height = maxDimension;
                    }
                }
                
                canvas.width = width;
                canvas.height = height;
                
                const ctx = canvas.getContext('2d');
                
                // Create circular crop if needed
                ctx.beginPath();
                ctx.arc(width/2, height/2, Math.min(width, height)/2, 0, Math.PI * 2);
                ctx.clip();
                ctx.drawImage(img, 0, 0, width, height);
                
                canvas.toBlob((blob) => {
                    const compressedFile = new File([blob], 'profile.jpg', {
                        type: 'image/jpeg',
                        lastModified: Date.now()
                    });
                    
                    console.log(`📸 Compressed: ${(file.size/1024).toFixed(1)}KB → ${(compressedFile.size/1024).toFixed(1)}KB`);
                    resolve(compressedFile);
                }, 'image/jpeg', 0.8);
            };
            
            img.onerror = reject;
        };
        
        reader.onerror = reject;
    });
}

// ========== 4. UPLOAD TO FIREBASE STORAGE ==========
async function uploadToFirebaseStorage(file) {
    if (!currentUser) throw new Error('User not logged in');
    
    const storageRef = firebase.storage().ref();
    const fileName = `profile_pictures/${currentUser.uid}/${Date.now()}.jpg`;
    const fileRef = storageRef.child(fileName);
    
    // Upload with metadata
    const metadata = {
        contentType: 'image/jpeg',
        cacheControl: 'public, max-age=31536000',
        customMetadata: {
            userId: currentUser.uid,
            uploadedAt: new Date().toISOString()
        }
    };
    
    const uploadTask = fileRef.put(file, metadata);
    
    // Track progress
    uploadTask.on('state_changed', 
        (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            updateUploadProgress(progress);
        },
        (error) => {
            console.error('Storage error:', error);
            throw error;
        }
    );
    
    // Wait for completion
    await uploadTask;
    
    // Get download URL
    const downloadURL = await fileRef.getDownloadURL();
    console.log('✅ Uploaded to Storage:', fileName);
    
    return downloadURL;
}

