// ========== 9. GET DEFAULT AVATAR ==========
function getDefaultAvatar() {
    if (currentUser?.name) {
        const initials = currentUser.name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
        const bgColor = stringToColor(currentUser.name);
        const textColor = getContrastColor(bgColor);
        return `https://ui-avatars.com/api/?name=${initials}&background=${bgColor.replace('#', '')}&color=${textColor.replace('#', '')}&size=150&bold=true&format=svg`;
    }
    return 'https://via.placeholder.com/150?text=User';
}

// ========== 10. HELPER FUNCTIONS ==========
function stringToColor(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const colors = ['256f8a', '27ae60', '8e44ad', '2980b9', 'c0392b', 'd35400', '16a085'];
    return '#' + colors[Math.abs(hash) % colors.length];
}

function getContrastColor(hex) {
    const r = parseInt(hex.substr(1,2), 16);
    const g = parseInt(hex.substr(3,2), 16);
    const b = parseInt(hex.substr(5,2), 16);
    return (r*0.299 + g*0.587 + b*0.114) > 186 ? '000000' : 'FFFFFF';
}

function showUploadProgress(show) {
    const progressEl = document.getElementById('profileUploadProgress');
    if (progressEl) progressEl.style.display = show ? 'block' : 'none';
}

function updateUploadProgress(percent) {
    const fillEl = document.querySelector('#profileUploadProgress .progress-fill');
    if (fillEl) fillEl.style.width = percent + '%';
}

function updateUploadButtons(state) {
    const buttons = document.querySelectorAll('.upload-profile-btn');
    buttons.forEach(btn => {
        if (state === 'uploading') {
            btn.disabled = true;
            btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Uploading...';
        } else {
            btn.disabled = false;
            btn.innerHTML = '<i class="fas fa-camera"></i> Change Photo';
        }
    });
}

