// ========== PREVIEW CERTIFICATE FILE ==========
function previewCertificateFile(event, type) {
    const file = event.target.files[0];
    if (!file) return;
    
    // Validate file type
    const validTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    if (!validTypes.includes(file.type)) {
        showToast('❌ Invalid file type. Use PDF, JPG, or PNG', 'error');
        event.target.value = '';
        return;
    }
    
    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
        showToast('❌ File too large. Max 5MB allowed', 'error');
        event.target.value = '';
        return;
    }
    
    const placeholder = document.getElementById(`${type}Placeholder`);
    const preview = document.getElementById(`${type}Preview`);
    const previewImg = document.getElementById(`${type}PreviewImg`);
    const fileName = document.getElementById(`${type}FileName`);
    
    if (placeholder && preview) {
        placeholder.style.display = 'none';
        preview.style.display = 'flex';
        
        if (file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onload = function(e) {
                if (previewImg) previewImg.src = e.target.result;
            };
            reader.readAsDataURL(file);
        } else {
            if (previewImg) previewImg.src = 'https://via.placeholder.com/100?text=PDF';
        }
        
        if (fileName) fileName.textContent = file.name;
    }
}

// ========== UPLOAD CERTIFICATE ==========
async function uploadCertificate(formElement, event) {
    event.preventDefault();
    
    const type = formElement.dataset.type;
    const fileInput = document.getElementById(`${type}File`);
    const file = fileInput.files[0];
    
    if (!file) {
        showToast('❌ Please select a file to upload', 'error');
        return;
    }
    
    // Validate required fields
    const school = document.getElementById(`${type}School`)?.value.trim();
    const year = document.getElementById(`${type}Year`)?.value;
    
    if (!school || !year) {
        showToast('❌ Please fill in all required fields', 'error');
        return;
    }
    
    // Prevent duplicate uploads
    if (certificateUploadInProgress[type]) {
        showToast('⚠️ Upload already in progress', 'warning');
        return;
    }
    
    certificateUploadInProgress[type] = true;
    
    // Show progress
    const progressDiv = document.getElementById(`${type}Progress`);
    if (progressDiv) progressDiv.style.display = 'block';
    
    const submitBtn = formElement.querySelector('button[type="submit"]');
    const originalText = submitBtn?.textContent;
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Uploading...';
    }
    
    try {
        // Upload file to Firebase Storage
        const fileURL = await uploadCertificateFile(file, type);
        
        // Save certificate data to Firestore
        const certData = {
            type: type,
            school: school,
            year: parseInt(year),
            division: document.getElementById(`${type}Division`)?.value || '',
            subjects: document.getElementById(`${type}Subjects`)?.value || '',
            fileURL: fileURL,
            fileName: file.name,
            fileType: file.type,
            fileSize: file.size,
            status: 'pending', // pending, approved, rejected
            uploadedAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        await saveCertificateData(certData);
        
        // Update UI
        updateCertificateStatus(type, 'pending');
        
        // Reset form
        formElement.reset();
        document.getElementById(`${type}Placeholder`).style.display = 'flex';
        document.getElementById(`${type}Preview`).style.display = 'none';
        fileInput.value = '';
        
        showToast('✅ Certificate uploaded successfully!', 'success');
        
        // Refresh lists
        loadUploadedCertificates();
        loadCertificateStatus();
        
    } catch (error) {
        console.error('Upload error:', error);
        showToast('❌ Upload failed: ' + error.message, 'error');
    } finally {
        certificateUploadInProgress[type] = false;
        
        if (progressDiv) progressDiv.style.display = 'none';
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText;
        }
    }
}

// ========== UPLOAD CERTIFICATE FILE TO STORAGE ==========
async function uploadCertificateFile(file, type) {
    if (!currentUser) throw new Error('User not logged in');
    
    const storageRef = firebase.storage().ref();
    const fileName = `certificates/${currentUser.uid}/${type}/${Date.now()}_${file.name}`;
    const fileRef = storageRef.child(fileName);
    
    const metadata = {
        contentType: file.type,
        customMetadata: {
            userId: currentUser.uid,
            certificateType: type,
            uploadedAt: new Date().toISOString()
        }
    };
    
    // Track progress
    const uploadTask = fileRef.put(file, metadata);
    
    uploadTask.on('state_changed', 
        (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            const progressFill = document.querySelector(`#${type}Progress .progress-fill`);
            if (progressFill) progressFill.style.width = progress + '%';
        },
        (error) => {
            console.error('Storage error:', error);
            throw error;
        }
    );
    
    await uploadTask;
    const downloadURL = await fileRef.getDownloadURL();
    
    return downloadURL;
}

// ========== SAVE CERTIFICATE DATA TO FIRESTORE ==========
async function saveCertificateData(certData) {
    if (!currentUser) throw new Error('User not logged in');
    
    // Check if certificate of this type already exists
    const existingSnapshot = await db.collection('certificates')
        .where('userId', '==', currentUser.uid)
        .where('type', '==', certData.type)
        .get();
    
    if (!existingSnapshot.empty) {
        // Update existing certificate
        const existingDoc = existingSnapshot.docs[0];
        await db.collection('certificates').doc(existingDoc.id).update(certData);
    } else {
        // Add new certificate
        await db.collection('certificates').add({
            ...certData,
            userId: currentUser.uid,
            userName: currentUser.name,
            userEmail: currentUser.email,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
    }
    
    // Create notification for admin
    await db.collection('notifications').add({
        type: 'certificate_upload',
        message: `${currentUser.name} uploaded ${certData.type} certificate`,
        userId: currentUser.uid,
        userName: currentUser.name,
        certificateType: certData.type,
        read: false,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
}

// ========== LOAD UPLOADED CERTIFICATES ==========
async function loadUploadedCertificates() {
    const container = document.getElementById('uploadedCertificatesList');
    if (!container || !currentUser) return;
    
    try {
        const snapshot = await db.collection('certificates')
            .where('userId', '==', currentUser.uid)
            .orderBy('uploadedAt', 'desc')
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = `
                <div class="no-certs-state">
                    <i class="fas fa-file-upload"></i>
                    <p>No certificates uploaded yet</p>
                    <small>Upload your educational certificates above</small>
                </div>
            `;
            return;
        }
        
        container.innerHTML = '';
        
        snapshot.forEach(doc => {
            const cert = doc.data();
            const certId = doc.id;
            const isImage = cert.fileType?.startsWith('image/');
            const statusInfo = getCertificateStatusInfo(cert.status);
            
            container.innerHTML += `
                <div class="uploaded-cert-card ${cert.status}">
                    <div class="cert-preview">
                        ${isImage ? 
                            `<img src="${cert.fileURL}" alt="${cert.type}" onerror="this.src='https://via.placeholder.com/200?text=Certificate'">` :
                            `<div class="pdf-preview">
                                <i class="fas fa-file-pdf"></i>
                                <span>PDF</span>
                            </div>`
                        }
                    </div>
                    <div class="cert-info">
                        <h5>${getCertificateTypeName(cert.type)}</h5>
                        <p><i class="fas fa-school"></i> ${cert.school}</p>
                        <p><i class="fas fa-calendar"></i> ${cert.year}</p>
                        ${cert.division ? `<p><i class="fas fa-star"></i> Division ${cert.division}</p>` : ''}
                        <span class="cert-status-badge ${statusInfo.class}">${statusInfo.text}</span>
                    </div>
                    <div class="cert-actions">
                        <button onclick="viewCertificate('${certId}')" class="btn-sm btn-view">
                            <i class="fas fa-eye"></i> View
                        </button>
                        <button onclick="downloadCertificate('${cert.fileURL}', '${cert.fileName}')" class="btn-sm btn-download">
                            <i class="fas fa-download"></i> Download
                        </button>
                        <button onclick="deleteCertificate('${certId}')" class="btn-sm btn-delete">
                            <i class="fas fa-trash"></i> Delete
                        </button>
                    </div>
                </div>
            `;
        });
        
    } catch (error) {
        console.error('Error loading certificates:', error);
        container.innerHTML = '<p class="error-text">Error loading certificates</p>';
    }
}

// ========== LOAD CERTIFICATE STATUS ==========
async function loadCertificateStatus() {
    if (!currentUser) return;
    
    try {
        const snapshot = await db.collection('certificates')
            .where('userId', '==', currentUser.uid)
            .get();
        
        const statuses = {
            olevel: { status: 'not_uploaded', text: 'Not Uploaded' },
            alevel: { status: 'not_uploaded', text: 'Not Uploaded' },
            other: []
        };
        
        snapshot.forEach(doc => {
            const cert = doc.data();
            if (cert.type === 'olevel' || cert.type === 'alevel') {
                statuses[cert.type] = { status: cert.status, text: getCertificateStatusInfo(cert.status).text };
            } else {
                statuses.other.push(cert);
            }
        });
        
        // Update status displays
        updateStatusDisplay('olevelStatus', statuses.olevel.text, statuses.olevel.status);
        updateStatusDisplay('alevelStatus', statuses.alevel.text, statuses.alevel.status);
        updateStatusDisplay('otherCertsStatus', `${statuses.other.length} Uploaded`, 'info');
        
        // Update status badges
        updateStatusBadge('olevelStatusBadge', statuses.olevel.status);
        updateStatusBadge('alevelStatusBadge', statuses.alevel.status);
        
    } catch (error) {
        console.error('Error loading status:', error);
    }
}

// ========== UPDATE STATUS DISPLAY ==========
function updateStatusDisplay(elementId, text, status) {
    const element = document.getElementById(elementId);
    if (!element) return;
    
    element.textContent = text;
    element.className = `cert-status-text ${status}`;
}

// ========== UPDATE STATUS BADGE ==========
function updateStatusBadge(elementId, status) {
    const element = document.getElementById(elementId);
    if (!element) return;
    
    const statusInfo = getCertificateStatusInfo(status);
    element.innerHTML = `<span class="${statusInfo.class}">${statusInfo.text}</span>`;
}

// ========== GET CERTIFICATE STATUS INFO ==========
function getCertificateStatusInfo(status) {
    const statusMap = {
        'pending': { class: 'status-pending', text: 'Pending Review' },
        'approved': { class: 'status-approved', text: 'Verified ✓' },
        'rejected': { class: 'status-rejected', text: 'Rejected' },
        'not_uploaded': { class: 'status-not-uploaded', text: 'Not Uploaded' }
    };
    return statusMap[status] || { class: '', text: status };
}

// ========== GET CERTIFICATE TYPE NAME ==========
function getCertificateTypeName(type) {
    const names = {
        'olevel': 'O-Level Certificate (Form IV)',
        'alevel': 'A-Level Certificate (Form VI)',
        'diploma': 'Diploma Certificate',
        'degree': 'Degree Certificate',
        'other': 'Other Certificate'
    };
    return names[type] || type;
}

// ========== VIEW CERTIFICATE ==========
function viewCertificate(certId) {
    db.collection('certificates').doc(certId).get().then(doc => {
        if (doc.exists) {
            const cert = doc.data();
            window.open(cert.fileURL, '_blank');
        }
    });
}

// ========== DOWNLOAD CERTIFICATE ==========
function downloadCertificate(url, fileName) {
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName || 'certificate';
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

// ========== DELETE CERTIFICATE ==========
async function deleteCertificate(certId) {
    if (!confirm('Are you sure you want to delete this certificate? This cannot be undone.')) return;
    
    try {
        // Get certificate data
        const certDoc = await db.collection('certificates').doc(certId).get();
        if (!certDoc.exists) return;
        
        const cert = certDoc.data();
        
        // Delete file from storage
        try {
            const storageRef = firebase.storage().refFromURL(cert.fileURL);
            await storageRef.delete();
        } catch (storageError) {
            console.log('Could not delete storage file:', storageError);
        }
        
        // Delete document from Firestore
        await db.collection('certificates').doc(certId).delete();
        
        showToast('✅ Certificate deleted successfully!', 'success');
        
        // Refresh lists
        loadUploadedCertificates();
        loadCertificateStatus();
        
    } catch (error) {
        console.error('Delete error:', error);
        showToast('❌ Failed to delete certificate', 'error');
    }
}

// ========== ADD OTHER CERTIFICATE ==========
function addOtherCertificate() {
    const title = prompt('Enter certificate name/title:');
    if (!title) return;
    
    const type = prompt('Enter certificate type (e.g., diploma, degree, short course):');
    if (!type) return;
    
    // Create file input dynamically
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.pdf,.jpg,.jpeg,.png';
    
    fileInput.onchange = async function(event) {
        const file = event.target.files[0];
        if (!file) return;
        
        // Validate
        const validTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
        if (!validTypes.includes(file.type)) {
            showToast('❌ Invalid file type', 'error');
            return;
        }
        
        if (file.size > 5 * 1024 * 1024) {
            showToast('❌ File too large', 'error');
            return;
        }
        
        // Upload
        try {
            const fileURL = await uploadCertificateFile(file, type);
            
            await saveCertificateData({
                type: type,
                school: title,
                year: parseInt(prompt('Enter year obtained:') || new Date().getFullYear()),
                division: '',
                subjects: '',
                fileURL: fileURL,
                fileName: file.name,
                fileType: file.type,
                fileSize: file.size,
                status: 'pending',
                uploadedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
            
            showToast('✅ Certificate uploaded!', 'success');
            loadUploadedCertificates();
            loadCertificateStatus();
            
        } catch (error) {
            showToast('❌ Upload failed', 'error');
        }
    };
    
    fileInput.click();
}

