// ============================================
// GLOBAL STATE VARIABLES
// ============================================

// ============================================
// HELPER FUNCTIONS
// ============================================



function formatDate(timestamp) {
    if (!timestamp) return 'N/A';
    const date = timestamp?.toDate ? timestamp.toDate() : new Date(timestamp);
    return date.toLocaleDateString('en-US', { 
        year: 'numeric', 
        month: 'short', 
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}

// ============================================
// TOAST NOTIFICATION
// ============================================
function showToastMessage(message, type = 'success') {
    // Remove existing toasts
    document.querySelectorAll('.custom-toast').forEach(t => t.remove());
    
    const toast = document.createElement('div');
    toast.className = `custom-toast toast-${type}`;
    toast.innerHTML = `
        <i class="fas fa-${type === 'success' ? 'check-circle' : type === 'error' ? 'exclamation-circle' : 'info-circle'}"></i>
        <span>${message}</span>
    `;
    toast.style.cssText = `
        position: fixed;
        bottom: 20px;
        right: 20px;
        background: ${type === 'success' ? '#10b981' : type === 'error' ? '#ef4444' : '#3b82f6'};
        color: white;
        padding: 12px 20px;
        border-radius: 12px;
        z-index: 10000;
        display: flex;
        align-items: center;
        gap: 10px;
        box-shadow: 0 10px 25px rgba(0,0,0,0.2);
        animation: slideInRight 0.3s ease;
        font-size: 0.9rem;
        font-weight: 500;
    `;
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

// ============================================
// 1. GALLERY - IMAGE URL PREVIEW
// ============================================

function previewGalleryUrl(url) {
    const previewContainer = document.getElementById('galleryUrlPreview');
    const previewImg = document.getElementById('galleryUrlPreviewImg');
    const previewStatus = document.getElementById('galleryPreviewStatus');
    
    if (!previewContainer || !previewImg) return;
    
    // Hide if empty
    if (!url || url.trim() === '') {
        previewContainer.style.display = 'none';
        return;
    }
    
    // Show preview
    previewContainer.style.display = 'block';
    
    // Update status
    if (previewStatus) {
        previewStatus.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inapakia preview...';
        previewStatus.style.color = '#64748b';
    }
    
    // Try to load image
    previewImg.src = url;
    previewImg.onload = function() {
        if (previewStatus) {
            previewStatus.innerHTML = '<i class="fas fa-check-circle"></i> Picha imepakia kikamilifu ✓';
            previewStatus.style.color = '#10b981';
        }
    };
    previewImg.onerror = function() {
        previewImg.src = 'https://via.placeholder.com/400x300?text=Picha+Haiwezi+Kupakia%0A(Angalia+URL)';
        if (previewStatus) {
            previewStatus.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Picha haijapakia - angalia link yako';
            previewStatus.style.color = '#ef4444';
        }
    };
}

function removeGalleryUrlPreview() {
    const previewContainer = document.getElementById('galleryUrlPreview');
    const urlInput = document.getElementById('galleryImageUrl');
    
    if (previewContainer) previewContainer.style.display = 'none';
    if (urlInput) urlInput.value = '';
}

// ============================================
// 2. GALLERY - SAVE (ADD/UPDATE)
// ============================================

async function saveGalleryItem() {
    const title = document.getElementById('galleryTitle')?.value.trim();
    const type = document.getElementById('galleryType')?.value;
    const description = document.getElementById('galleryDescription')?.value.trim();
    const imageUrl = document.getElementById('galleryImageUrl')?.value.trim();
    
    // ========== VALIDATION ==========
    if (!title) {
        showToastMessage('❌ Tafadhali weka kichwa cha picha', 'error');
        document.getElementById('galleryTitle')?.focus();
        return;
    }
    
    if (!type) {
        showToastMessage('❌ Tafadhali chagua aina ya picha', 'error');
        return;
    }
    
    if (!imageUrl) {
        showToastMessage('❌ Tafadhali weka link ya picha', 'error');
        document.getElementById('galleryImageUrl')?.focus();
        return;
    }
    
    // Validate URL format
    try {
        new URL(imageUrl);
    } catch (e) {
        showToastMessage('❌ Link si sahihi. Hakikisha inaanza na https://', 'error');
        document.getElementById('galleryImageUrl')?.focus();
        return;
    }
    
    // ========== SAVE ==========
    const submitBtn = document.getElementById('gallerySubmitBtn');
    const originalText = submitBtn?.innerHTML;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        const galleryData = {
            title: title,
            type: type,
            description: description || '',
            imageUrl: imageUrl,
            sourceType: 'link',
            active: true,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (galleryEditingId) {
            // UPDATE existing
            await db.collection('gallery').doc(galleryEditingId).update(galleryData);
            showToastMessage('✅ Picha imesasishwa kikamilifu!', 'success');
            galleryEditingId = null;
            resetGalleryForm();
        } else {
            // ADD new
            galleryData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('gallery').add(galleryData);
            showToastMessage('✅ Picha imeongezwa kwenye gallery!', 'success');
            resetGalleryForm();
        }
        
        // Refresh lists
        await loadGalleryForAdmin();
        await loadPublicGallery();
        
    } catch (error) {
        console.error('Error saving gallery:', error);
        showToastMessage('❌ Imeshindwa kuhifadhi: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-plus"></i> Ongeza Picha kwenye Gallery';
        }
    }
}

function resetGalleryForm() {
    // Reset form fields
    const form = document.getElementById('galleryUploadForm');
    if (form) form.reset();
    
    // Clear preview
    const previewContainer = document.getElementById('galleryUrlPreview');
    if (previewContainer) previewContainer.style.display = 'none';
    
    // Clear URL input
    const urlInput = document.getElementById('galleryImageUrl');
    if (urlInput) urlInput.value = '';
    
    // Reset editing state
    galleryEditingId = null;
    
    // Reset submit button
    const submitBtn = document.getElementById('gallerySubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-plus"></i> Ongeza Picha kwenye Gallery';
        submitBtn.style.background = '';
        submitBtn.style.color = '';
    }
    
    const cancelEditBtn = document.getElementById('galleryCancelEditBtn');
    if (cancelEditBtn) cancelEditBtn.style.display = 'none';
}

// ============================================
// 3. GALLERY - FORM EVENT LISTENER
// ============================================

function initGalleryForm() {
    const form = document.getElementById('galleryUploadForm');
    if (!form) return;
    
    // Remove any existing listeners
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', function(e) {
        e.preventDefault();
        saveGalleryItem();
    });
    
    console.log('✅ Gallery form initialized');
}

// ============================================
// 4. GALLERY - ADMIN LIST
// ============================================

async function loadGalleryForAdmin() {
    const container = document.getElementById('galleryManageList');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> Inapakia picha...</div>';
    
    try {
        const snapshot = await db.collection('gallery')
            .orderBy('createdAt', 'desc')
            .get();
        
        allGalleryItems = [];
        snapshot.forEach(doc => {
            allGalleryItems.push({ id: doc.id, ...doc.data() });
        });
        
        renderGalleryAdmin(allGalleryItems);
        updateGalleryStats();
        
    } catch (error) {
        console.error('Error loading gallery:', error);
        container.innerHTML = `<p class="error-text">Imeshindwa kupakia: ${error.message}</p>`;
    }
}

function renderGalleryAdmin(items) {
    const container = document.getElementById('galleryManageList');
    if (!container) return;
    
    if (!items || items.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <i class="fas fa-images"></i>
                <p>Hakuna picha kwenye gallery</p>
                <small>Ongeza picha kwa kutumia form hapo juu. Weka link ya picha kutoka mtandaoni.</small>
            </div>`;
        return;
    }
    
    container.innerHTML = items.map(item => `
        <div class="gallery-admin-card">
            <div class="gallery-admin-image">
                <img src="${item.imageUrl}" 
                     alt="${escapeHtml(item.title)}" 
                     loading="lazy"
                     onerror="this.src='https://via.placeholder.com/400x300?text=Picha+Haiwezi+Kupakia'">
                <span class="gallery-type-label">${escapeHtml(item.type || 'other')}</span>
            </div>
            <div class="gallery-admin-info">
                <h4>${escapeHtml(item.title)}</h4>
                ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                <div class="gallery-admin-meta">
                    <small><i class="fas fa-calendar"></i> ${formatDate(item.createdAt)}</small>
                    <span class="badge-link">🔗 Link</span>
                </div>
                <div class="gallery-admin-actions">
                    <button class="btn-sm btn-view" onclick="window.open('${item.imageUrl}', '_blank')" title="Fungua picha">
                        <i class="fas fa-external-link-alt"></i> Tazama
                    </button>
                    <button class="btn-sm btn-edit" onclick="editGalleryItem('${item.id}')" title="Hariri">
                        <i class="fas fa-edit"></i> Hariri
                    </button>
                    <button class="btn-sm btn-delete" onclick="deleteGalleryItem('${item.id}')" title="Futa">
                        <i class="fas fa-trash"></i> Futa
                    </button>
                </div>
            </div>
        </div>
    `).join('');
}

function updateGalleryStats() {
    const totalEl = document.getElementById('galleryTotalCount');
    if (totalEl) {
        totalEl.textContent = `Jumla: ${allGalleryItems.length} picha`;
    }
}

function filterGalleryAdmin(type) {
    // Update active button
    document.querySelectorAll('#adminManageGallery .filter-btn').forEach(btn => {
        btn.classList.remove('active');
    });
    const activeBtn = document.querySelector(`#adminManageGallery .filter-btn[onclick*="${type}"]`);
    if (activeBtn) activeBtn.classList.add('active');
    
    // Filter items
    const filtered = type === 'all' ? allGalleryItems : allGalleryItems.filter(i => i.type === type);
    renderGalleryAdmin(filtered);
}

function searchGalleryItems() {
    const searchTerm = document.getElementById('gallerySearchInput')?.value.toLowerCase() || '';
    const filtered = allGalleryItems.filter(item =>
        item.title?.toLowerCase().includes(searchTerm) ||
        item.description?.toLowerCase().includes(searchTerm) ||
        item.type?.toLowerCase().includes(searchTerm)
    );
    renderGalleryAdmin(filtered);
}

// ============================================
// 5. GALLERY - EDIT
// ============================================

async function editGalleryItem(id) {
    const doc = await db.collection('gallery').doc(id).get();
    if (!doc.exists) {
        showToastMessage('❌ Picha haikupatikana', 'error');
        return;
    }
    
    const item = doc.data();
    galleryEditingId = id;
    
    // Populate form
    document.getElementById('galleryTitle').value = item.title || '';
    document.getElementById('galleryType').value = item.type || 'campus';
    document.getElementById('galleryDescription').value = item.description || '';
    document.getElementById('galleryImageUrl').value = item.imageUrl || '';
    
    // Show preview
    previewGalleryUrl(item.imageUrl);
    
    // Update submit button
    const submitBtn = document.getElementById('gallerySubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Sasisha Picha';
        submitBtn.style.background = '#10b981';
        submitBtn.style.color = 'white';
    }
    
    // Show cancel button
    const cancelBtn = document.getElementById('galleryCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'inline-flex';
    
    // Scroll to form
    document.getElementById('galleryUploadForm').scrollIntoView({ behavior: 'smooth' });
    showToastMessage('📝 Unahariri: ' + item.title, 'info');
}

// ============================================
// 6. GALLERY - DELETE
// ============================================

async function deleteGalleryItem(id) {
    if (!confirm('Una uhakika unataka kufuta picha hii? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('gallery').doc(id).delete();
        showToastMessage('✅ Picha imefutwa!', 'success');
        await loadGalleryForAdmin();
        await loadPublicGallery();
    } catch (error) {
        console.error('Error deleting:', error);
        showToastMessage('❌ Imeshindwa kufuta: ' + error.message, 'error');
    }
}

// ============================================
// 7. PUBLIC GALLERY DISPLAY
// ============================================

async function loadPublicGallery() {
    const container = document.getElementById('galleryGrid');
    if (!container) return;
    
    try {
        const snapshot = await db.collection('gallery')
            .where('active', '==', true)
            .orderBy('createdAt', 'desc')
            .get();
        
        allGalleryItems = [];
        snapshot.forEach(doc => {
            allGalleryItems.push({ id: doc.id, ...doc.data() });
        });
        
        galleryFilter = 'all';
        galleryDisplayCount = 12;
        renderPublicGallery();
        
    } catch (error) {
        console.error('Error loading public gallery:', error);
        container.innerHTML = `<p class="error-text">Imeshindwa kupakia gallery</p>`;
    }
}

function renderPublicGallery() {
    const container = document.getElementById('galleryGrid');
    if (!container) return;
    
    let items = allGalleryItems;
    
    // Apply filter
    if (galleryFilter !== 'all') {
        items = items.filter(item => item.type === galleryFilter);
    }
    
    // Apply pagination
    const visible = items.slice(0, galleryDisplayCount);
    const hasMore = items.length > galleryDisplayCount;
    
    // Store for lightbox
    window._galleryVisible = visible;
    
    if (!visible.length) {
        container.innerHTML = `
            <div class="gallery-empty">
                <i class="fas fa-images"></i>
                <h3>Hakuna picha bado</h3>
                <p>Picha zitakapoongezwa zitawonekana hapa</p>
            </div>`;
        document.getElementById('galleryLoadMore').style.display = 'none';
        return;
    }
    
    container.innerHTML = visible.map((item, index) => `
        <div class="gallery-item" onclick="openLightbox(${index})">
            <div class="gallery-image-wrapper">
                <img src="${item.imageUrl}" 
                     alt="${escapeHtml(item.title)}" 
                     loading="lazy"
                     onerror="this.src='https://via.placeholder.com/400x300?text=Picha+Haiwezi+Kupakia'">
                <div class="gallery-overlay">
                    <i class="fas fa-search-plus"></i>
                </div>
            </div>
            <div class="gallery-item-info">
                <h4>${escapeHtml(item.title)}</h4>
                ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                <span class="gallery-type-badge">${escapeHtml(item.type || 'other')}</span>
            </div>
        </div>
    `).join('');
    
    document.getElementById('galleryLoadMore').style.display = hasMore ? 'block' : 'none';
}

function filterGallery(type) {
    galleryFilter = type;
    galleryDisplayCount = 12;
    
    // Update tabs
    document.querySelectorAll('.gallery-tab').forEach(tab => tab.classList.remove('active'));
    const activeTab = document.querySelector(`.gallery-tab[onclick*="${type}"]`);
    if (activeTab) activeTab.classList.add('active');
    
    renderPublicGallery();
}

function loadMoreGallery() {
    galleryDisplayCount += 12;
    renderPublicGallery();
}

// ============================================
// 8. LIGHTBOX
// ============================================

function openLightbox(index) {
    const images = window._galleryVisible || allGalleryItems;
    if (!images || images.length === 0) return;
    
    lightboxImages = images;
    currentLightboxIndex = Math.max(0, Math.min(index, images.length - 1));
    
    const lightbox = document.getElementById('galleryLightbox');
    if (lightbox) {
        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
    }
    
    showLightboxImage(currentLightboxIndex);
}

function showLightboxImage(index) {
    const img = document.getElementById('lightboxImage');
    const title = document.getElementById('lightboxTitle');
    const desc = document.getElementById('lightboxDescription');
    
    if (!lightboxImages || !lightboxImages[index]) return;
    
    const item = lightboxImages[index];
    
    if (img) {
        img.src = item.imageUrl || '';
        img.onerror = function() {
            this.src = 'https://via.placeholder.com/800x600?text=Picha+Haiwezi+Kupakia';
        };
    }
    if (title) title.textContent = item.title || '';
    if (desc) desc.textContent = item.description || '';
}

function changeLightboxImage(direction) {
    if (!lightboxImages || lightboxImages.length === 0) return;
    
    currentLightboxIndex += direction;
    
    if (currentLightboxIndex < 0) {
        currentLightboxIndex = lightboxImages.length - 1;
    }
    if (currentLightboxIndex >= lightboxImages.length) {
        currentLightboxIndex = 0;
    }
    
    showLightboxImage(currentLightboxIndex);
}

function closeLightbox() {
    const lightbox = document.getElementById('galleryLightbox');
    if (lightbox) {
        lightbox.classList.remove('active');
        document.body.style.overflow = '';
    }
}

// Close lightbox on Escape key
document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') closeLightbox();
});

// ============================================
// 9. MEDIA - SAVE (ADD/UPDATE)
// ============================================

async function saveMediaItem() {
    const type = document.getElementById('mediaType')?.value;
    const title = document.getElementById('mediaTitle')?.value.trim();
    const description = document.getElementById('mediaDescription')?.value.trim();
    const linkUrl = document.getElementById('mediaLink')?.value.trim();
    const fileUrl = document.getElementById('mediaFileUrl')?.value.trim();
    
    // ========== VALIDATION ==========
    if (!type) {
        showToastMessage('❌ Tafadhali chagua aina ya media', 'error');
        return;
    }
    
    if (!title) {
        showToastMessage('❌ Tafadhali weka kichwa cha media', 'error');
        document.getElementById('mediaTitle')?.focus();
        return;
    }
    
    let finalUrl = type === 'link' ? linkUrl : fileUrl;
    
    if (!finalUrl) {
        showToastMessage('❌ Tafadhali weka link ya media', 'error');
        return;
    }
    
    // Validate URL
    try {
        new URL(finalUrl);
    } catch (e) {
        showToastMessage('❌ Link si sahihi. Hakikisha inaanza na https://', 'error');
        return;
    }
    
    // ========== SAVE ==========
    const submitBtn = document.getElementById('mediaSubmitBtn');
    const originalText = submitBtn?.innerHTML;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        const mediaData = {
            title: title,
            type: type,
            description: description || '',
            fileUrl: finalUrl,
            sourceType: 'link',
            active: true,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (mediaEditingId) {
            // UPDATE
            await db.collection('media').doc(mediaEditingId).update(mediaData);
            showToastMessage('✅ Media imesasishwa kikamilifu!', 'success');
            mediaEditingId = null;
            resetMediaForm();
        } else {
            // ADD
            mediaData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('media').add(mediaData);
            showToastMessage('✅ Media imeongezwa kikamilifu!', 'success');
            resetMediaForm();
        }
        
        await loadMediaForAdmin();
        await loadPublicMedia();
        
    } catch (error) {
        console.error('Error saving media:', error);
        showToastMessage('❌ Imeshindwa kuhifadhi: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-plus"></i> Ongeza Media';
        }
    }
}

function resetMediaForm() {
    const form = document.getElementById('mediaUploadForm');
    if (form) form.reset();
    
    // Hide all URL groups
    const fileGroup = document.getElementById('mediaFileGroup');
    const linkGroup = document.getElementById('mediaLinkGroup');
    const fileUrlGroup = document.getElementById('mediaFileUrlGroup');
    
    if (fileGroup) fileGroup.style.display = 'none';
    if (linkGroup) linkGroup.style.display = 'none';
    if (fileUrlGroup) fileUrlGroup.style.display = 'none';
    
    // Clear inputs
    const fileUrl = document.getElementById('mediaFileUrl');
    const linkUrl = document.getElementById('mediaLink');
    if (fileUrl) fileUrl.value = '';
    if (linkUrl) linkUrl.value = '';
    
    // Reset editing
    mediaEditingId = null;
    
    // Reset button
    const submitBtn = document.getElementById('mediaSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-plus"></i> Ongeza Media';
        submitBtn.style.background = '';
        submitBtn.style.color = '';
    }
    
    const cancelBtn = document.getElementById('mediaCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'none';
}

// ============================================
// 10. MEDIA - FORM EVENT LISTENER
// ============================================

function initMediaForm() {
    const form = document.getElementById('mediaUploadForm');
    if (!form) return;
    
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', function(e) {
        e.preventDefault();
        saveMediaItem();
    });
    
    console.log('✅ Media form initialized');
}

// ============================================
// 11. MEDIA - TYPE CHANGE HANDLER
// ============================================

function handleMediaTypeChange() {
    const type = document.getElementById('mediaType')?.value;
    const fileGroup = document.getElementById('mediaFileGroup');
    const fileUrlGroup = document.getElementById('mediaFileUrlGroup');
    const linkGroup = document.getElementById('mediaLinkGroup');
    const fileUrlLabelText = document.getElementById('mediaFileUrlLabelText');
    const fileUrlHint = document.getElementById('mediaFileUrlHint');
    
    // Hide all first
    if (fileGroup) fileGroup.style.display = 'none';
    if (fileUrlGroup) fileUrlGroup.style.display = 'none';
    if (linkGroup) linkGroup.style.display = 'none';
    
    // Show relevant inputs
    if (type === 'video') {
        if (fileGroup) fileGroup.style.display = 'block';
        if (fileUrlGroup) fileUrlGroup.style.display = 'block';
        if (fileUrlLabelText) fileUrlLabelText.textContent = 'Video URL (Link ya Video) *';
        if (fileUrlHint) {
            fileUrlHint.innerHTML = '<i class="fas fa-info-circle"></i> Weka link ya YouTube, Vimeo, au video ya mtandaoni (MP4, WebM)';
        }
    } else if (type === 'document') {
        if (fileGroup) fileGroup.style.display = 'block';
        if (fileUrlGroup) fileUrlGroup.style.display = 'block';
        if (fileUrlLabelText) fileUrlLabelText.textContent = 'Document URL (Link ya Nyaraka) *';
        if (fileUrlHint) {
            fileUrlHint.innerHTML = '<i class="fas fa-info-circle"></i> Weka link ya PDF, DOC, au Google Docs';
        }
    } else if (type === 'link') {
        if (linkGroup) linkGroup.style.display = 'block';
    }
}

// ============================================
// 12. MEDIA - ADMIN LIST
// ============================================

async function loadMediaForAdmin() {
    const container = document.getElementById('mediaManageList');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> Inapakia media...</div>';
    
    try {
        const snapshot = await db.collection('media')
            .orderBy('createdAt', 'desc')
            .get();
        
        allMediaItems = [];
        snapshot.forEach(doc => {
            allMediaItems.push({ id: doc.id, ...doc.data() });
        });
        
        renderMediaAdmin(allMediaItems);
        updateMediaStats();
        
    } catch (error) {
        console.error('Error loading media:', error);
        container.innerHTML = `<p class="error-text">Imeshindwa kupakia: ${error.message}</p>`;
    }
}

function renderMediaAdmin(items) {
    const container = document.getElementById('mediaManageList');
    if (!container) return;
    
    if (!items || items.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <i class="fas fa-photo-video"></i>
                <p>Hakuna media iliyoongezwa</p>
                <small>Ongeza media kwa kutumia form hapo juu</small>
            </div>`;
        return;
    }
    
    container.innerHTML = items.map(item => {
        const typeIcon = item.type === 'video' ? 'video' : 
                        item.type === 'document' ? 'file-alt' : 'link';
        const typeColor = item.type === 'video' ? '#ef4444' : 
                         item.type === 'document' ? '#3b82f6' : '#10b981';
        
        const displayUrl = item.fileUrl.length > 60 ? 
                          item.fileUrl.substring(0, 60) + '...' : item.fileUrl;
        
        return `
            <div class="media-admin-card">
                <div class="media-admin-header">
                    <span class="media-type-icon" style="color:${typeColor};">
                        <i class="fas fa-${typeIcon}"></i>
                        ${item.type === 'video' ? '🎬 Video' : 
                          item.type === 'document' ? '📄 Document' : '🔗 Link'}
                    </span>
                    <span class="status-badge status-active">Active</span>
                </div>
                <div class="media-admin-body">
                    <h4>${escapeHtml(item.title)}</h4>
                    ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                    <div class="media-url-display">
                        <i class="fas fa-link"></i>
                        <a href="${item.fileUrl}" target="_blank" title="${escapeHtml(item.fileUrl)}">
                            ${escapeHtml(displayUrl)}
                        </a>
                    </div>
                    <small><i class="fas fa-calendar"></i> ${formatDate(item.createdAt)}</small>
                </div>
                <div class="media-admin-actions">
                    <button class="btn-sm btn-view" onclick="window.open('${item.fileUrl}', '_blank')">
                        <i class="fas fa-external-link-alt"></i> Fungua
                    </button>
                    <button class="btn-sm btn-edit" onclick="editMediaItem('${item.id}')">
                        <i class="fas fa-edit"></i> Hariri
                    </button>
                    <button class="btn-sm btn-delete" onclick="deleteMediaItem('${item.id}')">
                        <i class="fas fa-trash"></i> Futa
                    </button>
                </div>
            </div>
        `;
    }).join('');
}

function updateMediaStats() {
    const totalEl = document.getElementById('mediaTotalCount');
    if (totalEl) {
        totalEl.textContent = `Jumla: ${allMediaItems.length} media`;
    }
}

function filterMediaAdmin(type) {
    document.querySelectorAll('#adminManageMedia .filter-btn').forEach(btn => {
        btn.classList.remove('active');
    });
    const activeBtn = document.querySelector(`#adminManageMedia .filter-btn[onclick*="${type}"]`);
    if (activeBtn) activeBtn.classList.add('active');
    
    const filtered = type === 'all' ? allMediaItems : allMediaItems.filter(i => i.type === type);
    renderMediaAdmin(filtered);
}

function searchMediaItems() {
    const searchTerm = document.getElementById('mediaSearchInput')?.value.toLowerCase() || '';
    const filtered = allMediaItems.filter(item =>
        item.title?.toLowerCase().includes(searchTerm) ||
        item.description?.toLowerCase().includes(searchTerm) ||
        item.type?.toLowerCase().includes(searchTerm) ||
        item.fileUrl?.toLowerCase().includes(searchTerm)
    );
    renderMediaAdmin(filtered);
}

// ============================================
// 13. MEDIA - EDIT
// ============================================

async function editMediaItem(id) {
    const doc = await db.collection('media').doc(id).get();
    if (!doc.exists) {
        showToastMessage('❌ Media haikupatikana', 'error');
        return;
    }
    
    const item = doc.data();
    mediaEditingId = id;
    
    // Populate form
    document.getElementById('mediaType').value = item.type || '';
    document.getElementById('mediaTitle').value = item.title || '';
    document.getElementById('mediaDescription').value = item.description || '';
    
    if (item.type === 'link') {
        document.getElementById('mediaLink').value = item.fileUrl || '';
    } else {
        document.getElementById('mediaFileUrl').value = item.fileUrl || '';
    }
    
    // Trigger type change to show correct fields
    handleMediaTypeChange();
    
    // Update button
    const submitBtn = document.getElementById('mediaSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Sasisha Media';
        submitBtn.style.background = '#10b981';
        submitBtn.style.color = 'white';
    }
    
    // Show cancel button
    const cancelBtn = document.getElementById('mediaCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'inline-flex';
    
    document.getElementById('mediaUploadForm').scrollIntoView({ behavior: 'smooth' });
    showToastMessage('📝 Unahariri: ' + item.title, 'info');
}

// ============================================
// 14. MEDIA - DELETE
// ============================================

async function deleteMediaItem(id) {
    if (!confirm('Una uhakika unataka kufuta media hii? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('media').doc(id).delete();
        showToastMessage('✅ Media imefutwa!', 'success');
        await loadMediaForAdmin();
        await loadPublicMedia();
    } catch (error) {
        console.error('Error deleting:', error);
        showToastMessage('❌ Imeshindwa kufuta: ' + error.message, 'error');
    }
}

