// 15. PUBLIC MEDIA DISPLAY
// ============================================

async function loadPublicMedia() {
    const container = document.getElementById('mediaGrid');
    if (!container) return;
    
    try {
        const snapshot = await db.collection('media')
            .where('active', '==', true)
            .orderBy('createdAt', 'desc')
            .get();
        
        allMediaItems = [];
        snapshot.forEach(doc => {
            allMediaItems.push({ id: doc.id, ...doc.data() });
        });
        
        mediaFilter = 'all';
        mediaDisplayCount = 10;
        renderPublicMedia();
        
    } catch (error) {
        console.error('Error loading public media:', error);
        container.innerHTML = `<p class="error-text">Imeshindwa kupakia media</p>`;
    }
}

function renderPublicMedia() {
    const container = document.getElementById('mediaGrid');
    if (!container) return;
    
    let items = allMediaItems;
    
    if (mediaFilter !== 'all') {
        items = items.filter(item => item.type === mediaFilter);
    }
    
    const visible = items.slice(0, mediaDisplayCount);
    const hasMore = items.length > mediaDisplayCount;
    
    if (!visible.length) {
        container.innerHTML = `
            <div class="media-empty">
                <i class="fas fa-photo-video"></i>
                <h3>Hakuna media bado</h3>
                <p>Video, nyaraka na viungo vitakapoongezwa vitawonekana hapa</p>
            </div>`;
        document.getElementById('mediaLoadMore').style.display = 'none';
        return;
    }
    
    container.innerHTML = visible.map(item => {
        if (item.type === 'video') {
            // Check if it's a YouTube link
            if (item.fileUrl.includes('youtube.com') || item.fileUrl.includes('youtu.be')) {
                const videoId = getYouTubeId(item.fileUrl);
                if (videoId) {
                    return `
                        <div class="media-item">
                            <div class="video-wrapper">
                                <iframe width="100%" height="100%" 
                                        src="https://www.youtube.com/embed/${videoId}" 
                                        frameborder="0" 
                                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                                        allowfullscreen>
                                </iframe>
                            </div>
                            <div class="media-item-info">
                                <h4>${escapeHtml(item.title)}</h4>
                                ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                                <a href="${item.fileUrl}" target="_blank" class="btn-download">
                                    <i class="fab fa-youtube"></i> Tazama YouTube
                                </a>
                            </div>
                        </div>`;
                }
            }
            
            // Regular video
            return `
                <div class="media-item">
                    <div class="video-wrapper">
                        <video controls preload="metadata">
                            <source src="${item.fileUrl}" type="video/mp4">
                            Your browser does not support video.
                        </video>
                    </div>
                    <div class="media-item-info">
                        <h4>${escapeHtml(item.title)}</h4>
                        ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                        <a href="${item.fileUrl}" target="_blank" class="btn-download">
                            <i class="fas fa-external-link-alt"></i> Fungua Video
                        </a>
                    </div>
                </div>`;
        } else if (item.type === 'document') {
            return `
                <div class="media-item">
                    <div class="document-preview" onclick="window.open('${item.fileUrl}', '_blank')">
                        <i class="fas fa-file-pdf"></i>
                        <span>Bonyeza Kufungua Document</span>
                    </div>
                    <div class="media-item-info">
                        <h4>${escapeHtml(item.title)}</h4>
                        ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                        <a href="${item.fileUrl}" target="_blank" class="btn-download">
                            <i class="fas fa-download"></i> Pakua / Fungua
                        </a>
                    </div>
                </div>`;
        } else {
            // Link
            return `
                <div class="media-item">
                    <div class="link-icon">
                        <i class="fas fa-link"></i>
                    </div>
                    <div class="media-item-info">
                        <h4>${escapeHtml(item.title)}</h4>
                        ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                        <a href="${item.fileUrl}" target="_blank" rel="noopener noreferrer" class="btn-visit">
                            <i class="fas fa-external-link-alt"></i> Fungua Kiungo
                        </a>
                    </div>
                </div>`;
        }
    }).join('');
    
    document.getElementById('mediaLoadMore').style.display = hasMore ? 'block' : 'none';
}

function filterMedia(type) {
    mediaFilter = type;
    mediaDisplayCount = 10;
    
    document.querySelectorAll('.media-tab').forEach(tab => tab.classList.remove('active'));
    const activeTab = document.querySelector(`.media-tab[onclick*="${type}"]`);
    if (activeTab) activeTab.classList.add('active');
    
    renderPublicMedia();
}

function loadMoreMedia() {
    mediaDisplayCount += 10;
    renderPublicMedia();
}

// ============================================
// 16. YOUTUBE HELPER
// ============================================

function getYouTubeId(url) {
    if (!url) return null;
    
    // youtube.com/watch?v=VIDEO_ID
    if (url.includes('youtube.com/watch')) {
        const urlParams = new URLSearchParams(new URL(url).search);
        return urlParams.get('v');
    }
    
    // youtu.be/VIDEO_ID
    if (url.includes('youtu.be/')) {
        const parts = url.split('youtu.be/');
        if (parts[1]) {
            return parts[1].split('?')[0].split('#')[0];
        }
    }
    
    // youtube.com/embed/VIDEO_ID
    if (url.includes('youtube.com/embed/')) {
        const parts = url.split('youtube.com/embed/');
        if (parts[1]) {
            return parts[1].split('?')[0].split('#')[0];
        }
    }
    
    return null;
}

