// ============================================
// LOAD PUBLIC GALLERY
// ============================================

async function loadPublicGallery() {
    const container = document.getElementById('galleryGrid');
    const skeleton = document.getElementById('gallerySkeleton');
    
    if (!container) return;
    
    // Show skeleton loading
    if (skeleton) skeleton.style.display = 'grid';
    
    try {
        const snapshot = await db.collection('gallery')
            .where('active', '==', true)
            .orderBy('createdAt', 'desc')
            .get();
        
        allGalleryItems = [];
        snapshot.forEach(doc => {
            allGalleryItems.push({ id: doc.id, ...doc.data() });
        });
        
        // Hide skeleton
        if (skeleton) skeleton.style.display = 'none';
        
        galleryFilter = 'all';
        galleryDisplayCount = 12;
        renderPublicGallery();
        
        // Update stats
        document.getElementById('galleryTotalImages').textContent = allGalleryItems.length;
        document.getElementById('galleryStatsBar').style.display = allGalleryItems.length > 0 ? 'flex' : 'none';
        
    } catch (error) {
        console.error('Error loading gallery:', error);
        if (skeleton) skeleton.style.display = 'none';
        container.innerHTML = `<div class="gallery-empty">
            <i class="fas fa-exclamation-triangle"></i>
            <h3>Imeshindwa kupakia picha</h3>
            <p>${error.message}</p>
        </div>`;
    }
}

// ============================================
// RENDER PUBLIC GALLERY
// ============================================

function renderPublicGallery() {
    const container = document.getElementById('galleryGrid');
    const noResults = document.getElementById('galleryNoResults');
    const loadMoreBtn = document.getElementById('galleryLoadMore');
    const backToTop = document.getElementById('galleryBackToTop');
    
    if (!container) return;
    
    let items = allGalleryItems;
    
    // Apply filter
    if (galleryFilter !== 'all') {
        items = items.filter(item => item.type === galleryFilter);
    }
    
    // Apply pagination
    const visible = items.slice(0, galleryDisplayCount);
    const hasMore = items.length > galleryDisplayCount;
    const remaining = items.length - galleryDisplayCount;
    
    // Store for lightbox
    window._galleryVisible = visible;
    
    // Show/hide no results
    if (noResults) {
        noResults.style.display = (items.length === 0 && galleryFilter !== 'all') ? 'block' : 'none';
    }
    
    // Show/hide load more
    if (loadMoreBtn) {
        loadMoreBtn.style.display = hasMore ? 'block' : 'none';
        const remainingEl = document.getElementById('galleryRemaining');
        if (remainingEl && hasMore) {
            remainingEl.textContent = `(${remaining} zimebaki)`;
        }
    }
    
    // Show/hide back to top
    if (backToTop) {
        backToTop.style.display = galleryDisplayCount > 12 ? 'block' : 'none';
    }
    
    // Update stats
    document.getElementById('galleryShowing').textContent = visible.length;
    
    if (!visible.length && galleryFilter === 'all') {
        container.innerHTML = `
            <div class="gallery-empty">
                <i class="fas fa-images"></i>
                <h3>Hakuna picha bado</h3>
                <p>Picha zitakapoongezwa zitawonekana hapa</p>
            </div>`;
        return;
    }
    
    if (!visible.length) {
        container.innerHTML = '';
        return;
    }
    
    container.innerHTML = visible.map((item, index) => `
        <div class="gallery-item" onclick="openLightbox(${index})" title="Bonyeza kutazama">
            <div class="gallery-image-wrapper">
                <img src="${item.imageUrl}" 
                     alt="${escapeHtml(item.title)}" 
                     loading="${index < 6 ? 'eager' : 'lazy'}"
                     onerror="this.src='https://via.placeholder.com/400x300?text=Picha+Haiwezi+Kupakia'">
                <div class="gallery-overlay">
                    <i class="fas fa-search-plus"></i>
                </div>
            </div>
            <div class="gallery-item-info">
                <h4>${escapeHtml(item.title)}</h4>
                ${item.description ? `<p>${escapeHtml(item.description)}</p>` : ''}
                <span class="gallery-type-badge">
                    <i class="fas fa-${getTypeIcon(item.type)}"></i> ${escapeHtml(item.type || 'other')}
                </span>
            </div>
        </div>
    `).join('');
}

// ============================================
// GET TYPE ICON
// ============================================

function getTypeIcon(type) {
    const icons = {
        'campus': 'school',
        'events': 'calendar-alt',
        'students': 'users',
        'workshops': 'tools',
        'other': 'image'
    };
    return icons[type] || 'image';
}

// ============================================
// FILTER GALLERY
// ============================================

function filterGallery(type) {
    galleryFilter = type;
    galleryDisplayCount = 12;
    
    // Update tabs
    document.querySelectorAll('.gallery-tab').forEach(tab => {
        tab.classList.remove('active');
    });
    const activeTab = document.querySelector(`.gallery-tab[data-filter="${type}"]`);
    if (activeTab) activeTab.classList.add('active');
    
    renderPublicGallery();
    
    // Scroll to gallery
    document.getElementById('gallery-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ============================================
// LOAD MORE
// ============================================

function loadMoreGallery() {
    galleryDisplayCount += 12;
    renderPublicGallery();
    
    // Show back to top
    document.getElementById('galleryBackToTop').style.display = 'block';
}

// ============================================
// ENHANCED LIGHTBOX
// ============================================

function openLightbox(index) {
    const images = window._galleryVisible || allGalleryItems;
    if (!images || images.length === 0) return;
    
    lightboxImages = images;
    currentLightboxIndex = Math.max(0, Math.min(index, images.length - 1));
    
    const lightbox = document.getElementById('galleryLightbox');
    if (lightbox) {
        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
    }
    
    showLightboxImage(currentLightboxIndex);
    updateLightboxCounter();
}

function showLightboxImage(index) {
    const img = document.getElementById('lightboxImage');
    const title = document.getElementById('lightboxTitle');
    const desc = document.getElementById('lightboxDescription');
    const typeBadge = document.getElementById('lightboxTypeBadge');
    const date = document.getElementById('lightboxDate');
    const loader = document.getElementById('lightboxLoader');
    
    if (!lightboxImages || !lightboxImages[index]) return;
    
    const item = lightboxImages[index];
    
    // Show loader
    if (loader) loader.style.display = 'block';
    
    if (img) {
        img.style.opacity = '0';
        img.src = item.imageUrl || '';
        img.onload = function() {
            img.style.opacity = '1';
            if (loader) loader.style.display = 'none';
        };
        img.onerror = function() {
            this.src = 'https://via.placeholder.com/800x600?text=Picha+Haiwezi+Kupakia';
            this.style.opacity = '1';
            if (loader) loader.style.display = 'none';
        };
    }
    
    if (title) title.textContent = item.title || '';
    if (desc) desc.textContent = item.description || '';
    if (typeBadge) {
        typeBadge.textContent = item.type || 'other';
        typeBadge.style.display = item.type ? 'inline-block' : 'none';
    }
    if (date && item.createdAt) {
        date.textContent = formatDate(item.createdAt);
        date.style.display = 'block';
    } else if (date) {
        date.style.display = 'none';
    }
    
    updateLightboxCounter();
}

function updateLightboxCounter() {
    const counter = document.getElementById('lightboxCounter');
    if (counter && lightboxImages.length > 0) {
        counter.textContent = `${currentLightboxIndex + 1} / ${lightboxImages.length}`;
    }
}

function changeLightboxImage(direction) {
    if (!lightboxImages || lightboxImages.length === 0) return;
    
    currentLightboxIndex += direction;
    
    if (currentLightboxIndex < 0) {
        currentLightboxIndex = lightboxImages.length - 1;
    }
    if (currentLightboxIndex >= lightboxImages.length) {
        currentLightboxIndex = 0;
    }
    
    showLightboxImage(currentLightboxIndex);
}

function closeLightbox() {
    const lightbox = document.getElementById('galleryLightbox');
    if (lightbox) {
        lightbox.classList.remove('active');
        document.body.style.overflow = '';
    }
}

// Keyboard navigation
document.addEventListener('keydown', function(e) {
    const lightbox = document.getElementById('galleryLightbox');
    if (!lightbox || !lightbox.classList.contains('active')) return;
    
    if (e.key === 'Escape') {
        closeLightbox();
    } else if (e.key === 'ArrowLeft') {
        changeLightboxImage(-1);
    } else if (e.key === 'ArrowRight') {
        changeLightboxImage(1);
    }
});

// ============================================
// SHARE FUNCTIONS
// ============================================

function downloadCurrentImage() {
    if (!lightboxImages || !lightboxImages[currentLightboxIndex]) return;
    
    const item = lightboxImages[currentLightboxIndex];
    const link = document.createElement('a');
    link.href = item.imageUrl;
    link.download = item.title?.replace(/\s+/g, '_') || 'gallery_image';
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

function shareCurrentImage() {
    if (!lightboxImages || !lightboxImages[currentLightboxIndex]) return;
    
    const item = lightboxImages[currentLightboxIndex];
    const modal = document.getElementById('shareModal');
    const urlInput = document.getElementById('shareImageUrl');
    
    if (modal && urlInput) {
        urlInput.value = item.imageUrl;
        modal.style.display = 'flex';
    }
}

function closeShareModal() {
    const modal = document.getElementById('shareModal');
    if (modal) modal.style.display = 'none';
}

function copyShareLink() {
    const urlInput = document.getElementById('shareImageUrl');
    if (!urlInput) return;
    
    urlInput.select();
    urlInput.setSelectionRange(0, 99999);
    
    navigator.clipboard.writeText(urlInput.value).then(() => {
        showToastMessage('✅ Link imenakiliwa!', 'success');
    }).catch(() => {
        showToastMessage('❌ Imeshindwa kunakili', 'error');
    });
}

function shareViaWhatsApp() {
    const url = document.getElementById('shareImageUrl')?.value || '';
    const text = encodeURIComponent(`Angalia picha hii kutoka Songwe VTC: ${url}`);
    window.open(`https://wa.me/?text=${text}`, '_blank');
}

function shareViaFacebook() {
    const url = encodeURIComponent(document.getElementById('shareImageUrl')?.value || '');
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${url}`, '_blank');
}

function shareViaTwitter() {
    const url = encodeURIComponent(document.getElementById('shareImageUrl')?.value || '');
    const text = encodeURIComponent('Angalia picha hii kutoka Songwe VTC');
    window.open(`https://twitter.com/intent/tweet?url=${url}&text=${text}`, '_blank');
}

function shareViaEmail() {
    const url = document.getElementById('shareImageUrl')?.value || '';
    const subject = encodeURIComponent('Picha kutoka Songwe VTC Gallery');
    const body = encodeURIComponent(`Habari,\n\nAngalia picha hii kutoka Songwe VTC:\n${url}`);
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
}

