// ============================================
// RECENT EVENTS SYSTEM – COMPLETE
// ============================================

let allEvents = [];
let eventsDisplayCount = 6;
let eventEditingId = null;
let paragraphCounter = 0;
let eventLightboxImages = [];
let eventLightboxIndex = 0;

async function loadPublicEvents() {
    const container = document.getElementById('eventsList');
    const skeleton = document.getElementById('eventsSkeleton');
    const empty = document.getElementById('eventsEmpty');
    
    if (!container) return;
    
    if (skeleton) skeleton.style.display = 'grid';
    if (empty) empty.style.display = 'none';
    
    try {
        // Use simple query - only filter by active
        const snapshot = await db.collection('events')
            .where('active', '==', true)
            .get();
        
        allEvents = [];
        snapshot.forEach(doc => {
            allEvents.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort manually by date (newest first)
        allEvents.sort((a, b) => {
            const dateA = a.eventDate?.toDate?.() || new Date(a.eventDate || 0);
            const dateB = b.eventDate?.toDate?.() || new Date(b.eventDate || 0);
            return dateB - dateA;
        });
        
        if (skeleton) skeleton.style.display = 'none';
        
        if (allEvents.length === 0) {
            container.innerHTML = '';
            if (empty) empty.style.display = 'block';
            const featuredCard = document.getElementById('featuredEventCard');
            if (featuredCard) featuredCard.style.display = 'none';
            const loadMoreBtn = document.getElementById('eventsLoadMore');
            if (loadMoreBtn) loadMoreBtn.style.display = 'none';
        } else {
            eventsDisplayCount = 6;
            renderPublicEvents();
        }
        
    } catch (error) {
        console.error('Error loading events:', error);
        if (skeleton) skeleton.style.display = 'none';
        container.innerHTML = '<div class="events-empty"><i class="fas fa-exclamation-triangle"></i><h3>Imeshindwa kupakia: ' + error.message + '</h3></div>';
    }
}

function renderPublicEvents() {
    const container = document.getElementById('eventsList');
    const loadMoreBtn = document.getElementById('eventsLoadMore');
    const empty = document.getElementById('eventsEmpty');
    
    if (!container) return;
    
    if (allEvents.length === 0) {
        container.innerHTML = '';
        if (empty) empty.style.display = 'block';
        const featuredCard = document.getElementById('featuredEventCard');
        if (featuredCard) featuredCard.style.display = 'none';
        if (loadMoreBtn) loadMoreBtn.style.display = 'none';
        return;
    }
    
    if (empty) empty.style.display = 'none';
    
    const visible = allEvents.slice(0, eventsDisplayCount);
    const hasMore = allEvents.length > eventsDisplayCount;
    
    // First event is featured (larger card with image)
    if (allEvents[0]) {
        renderFeaturedEvent(allEvents[0]);
    }
    
    // Remaining events as compact cards
    const listEvents = allEvents.slice(1, eventsDisplayCount);
    
    if (listEvents.length === 0) {
        container.innerHTML = '';
    } else {
        container.innerHTML = listEvents.map(event => createEventCard(event)).join('');
    }
    
    if (loadMoreBtn) {
        loadMoreBtn.style.display = hasMore ? 'block' : 'none';
    }
}

// ============================================
// LOAD MORE EVENTS
// ============================================

function loadMoreEvents() {
    eventsDisplayCount += 6;
    renderPublicEvents();
}

// ============================================
// FORMAT EVENT DATE
// ============================================


// RENDER FEATURED EVENT (First Event - No Description)
// ============================================

function renderFeaturedEvent(event) {
    const card = document.getElementById('featuredEventCard');
    if (!card) return;
    
    card.style.display = 'flex';
    
    // Set image
    const imageEl = document.getElementById('featuredEventImage');
    const placeholder = document.querySelector('.featured-image-placeholder');
    
    if (imageEl) {
        if (event.imageUrl) {
            imageEl.src = event.imageUrl;
            imageEl.style.display = 'block';
            if (placeholder) placeholder.style.display = 'none';
        } else {
            imageEl.style.display = 'none';
            if (placeholder) placeholder.style.display = 'flex';
        }
        imageEl.onerror = function() {
            this.style.display = 'none';
            if (placeholder) placeholder.style.display = 'flex';
        };
    }
    
    // Set date
    const dateEl = document.getElementById('featuredEventDate');
    if (dateEl) {
        dateEl.textContent = formatEventDate(event.eventDate);
    }
    
    // Set title
    const titleEl = document.getElementById('featuredEventTitle');
    if (titleEl) {
        titleEl.textContent = event.title;
    }
    
    // Hide excerpt (no description shown)
    const excerptEl = document.getElementById('featuredEventExcerpt');
    if (excerptEl) {
        excerptEl.textContent = '';
        excerptEl.style.display = 'none';
    }
    
    // Set button
    const btn = document.getElementById('featuredEventBtn');
    if (btn) {
        btn.setAttribute('onclick', `openEventDetails('${event.id}')`);
    }
    
    // Make card clickable (but not when clicking the button)
    card.onclick = function(e) {
        if (!e.target.closest('button')) {
            openEventDetails(event.id);
        }
    };
}

function createEventCard(event) {
    const dateStr = formatEventDate(event.eventDate);
    return `
        <div class="event-card" onclick="openEventDetails('${event.id}')" title="Bonyeza kusoma zaidi">
            <!-- LEFT SIDE - Small Image -->
            <div class="event-card-image">
                ${event.imageUrl ? 
                    `<img src="${event.imageUrl}" alt="${escapeHtml(event.title)}" loading="lazy" 
                         onerror="this.style.display='none'; this.parentElement.querySelector('.event-card-placeholder').style.display='flex';">` : ''}
                <div class="event-card-placeholder" style="display:${event.imageUrl ? 'none' : 'flex'};">
                    <i class="fas fa-calendar-alt"></i>
                </div>
            </div>
            
            <!-- RIGHT SIDE - Title & Date -->
            <div class="event-card-content">
                <h4>${escapeHtml(event.title)}</h4>
                <span class="event-card-date">
                    <i class="fas fa-calendar"></i> ${dateStr}
                </span>
            </div>
        </div>
    `;
}

// ============================================
// FORMAT EVENT DATE
// ============================================

function formatEventDate(dateValue) {
    if (!dateValue) return '';
    
    let date;
    if (dateValue.toDate) {
        date = dateValue.toDate();
    } else if (typeof dateValue === 'string') {
        date = new Date(dateValue);
    } else {
        return dateValue;
    }
    
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return date.toLocaleDateString('sw-TZ', options);
}

// ============================================
// OPEN EVENT DETAILS MODAL
// ============================================

async function openEventDetails(eventId) {
    const event = allEvents.find(e => e.id === eventId);
    if (!event) {
        // Fetch from Firestore if not in local array
        const doc = await db.collection('events').doc(eventId).get();
        if (!doc.exists) return;
        event = { id: doc.id, ...doc.data() };
    }
    
    const modal = document.getElementById('eventDetailsModal');
    if (!modal) return;
    
    // Populate modal
    document.getElementById('eventDetailImage').src = event.imageUrl || '';
    document.getElementById('eventDetailDate').textContent = formatEventDate(event.eventDate);
    document.getElementById('eventDetailTitle').textContent = event.title;
    document.getElementById('eventDetailDescription').textContent = event.description || '';
    
    // Render additional paragraphs
    const paragraphsContainer = document.getElementById('eventDetailParagraphs');
    let paragraphsHtml = '';
    
    if (event.paragraphs && event.paragraphs.length > 0) {
        event.paragraphs.forEach(para => {
            paragraphsHtml += `
                <div class="detail-paragraph">
                    ${para.title ? `<h4>${escapeHtml(para.title)}</h4>` : ''}
                    <p>${escapeHtml(para.content)}</p>
                    ${para.imageUrl ? `<img src="${para.imageUrl}" alt="${escapeHtml(para.title || 'Event Image')}" loading="lazy" onclick="openEventLightbox('${para.imageUrl}')" style="cursor:pointer;">` : ''}
                </div>
            `;
        });
    }
    paragraphsContainer.innerHTML = paragraphsHtml;
    
    // Render event gallery (main image + paragraph images)
    const galleryContainer = document.getElementById('eventDetailGallery');
    const galleryGrid = document.getElementById('eventGalleryGrid');
    
    let galleryImages = [];
    if (event.imageUrl) galleryImages.push(event.imageUrl);
    if (event.paragraphs) {
        event.paragraphs.forEach(para => {
            if (para.imageUrl) galleryImages.push(para.imageUrl);
        });
    }
    
    if (galleryImages.length > 1) {
        galleryContainer.style.display = 'block';
        galleryGrid.innerHTML = galleryImages.map((url, i) => `
            <div class="event-gallery-item" onclick="openEventLightboxFromGallery(${i})">
                <img src="${url}" alt="Event Photo" loading="lazy">
            </div>
        `).join('');
        window._eventGalleryImages = galleryImages;
    } else {
        galleryContainer.style.display = 'none';
    }
    
    // Show modal
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function closeEventDetails() {
    const modal = document.getElementById('eventDetailsModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
}

// ============================================
// EVENT LIGHTBOX
// ============================================

function openEventLightbox(imageUrl) {
    const lightbox = document.getElementById('eventLightbox');
    const img = document.getElementById('eventLightboxImage');
    
    if (!lightbox || !img) return;
    
    img.src = imageUrl;
    lightbox.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function openEventLightboxFromGallery(index) {
    const images = window._eventGalleryImages || [];
    if (images.length === 0) return;
    
    eventLightboxImages = images;
    eventLightboxIndex = index;
    
    showEventLightboxImage();
    
    const lightbox = document.getElementById('eventLightbox');
    if (lightbox) lightbox.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function showEventLightboxImage() {
    const img = document.getElementById('eventLightboxImage');
    if (img && eventLightboxImages[eventLightboxIndex]) {
        img.src = eventLightboxImages[eventLightboxIndex];
    }
}

function changeEventLightboxImage(direction) {
    if (eventLightboxImages.length === 0) return;
    
    eventLightboxIndex += direction;
    if (eventLightboxIndex < 0) eventLightboxIndex = eventLightboxImages.length - 1;
    if (eventLightboxIndex >= eventLightboxImages.length) eventLightboxIndex = 0;
    
    showEventLightboxImage();
}

function closeEventLightbox() {
    const lightbox = document.getElementById('eventLightbox');
    if (lightbox) {
        lightbox.classList.remove('active');
        document.body.style.overflow = '';
    }
}

// Keyboard navigation for event lightbox
document.addEventListener('keydown', function(e) {
    const lightbox = document.getElementById('eventLightbox');
    if (!lightbox || !lightbox.classList.contains('active')) return;
    
    if (e.key === 'Escape') closeEventLightbox();
    else if (e.key === 'ArrowLeft') changeEventLightboxImage(-1);
    else if (e.key === 'ArrowRight') changeEventLightboxImage(1);
});

