// ============================================

function addParagraphField(title = '', content = '', imageUrl = '') {
    paragraphCounter++;
    const container = document.getElementById('paragraphsContainer');
    
    const paraDiv = document.createElement('div');
    paraDiv.className = 'paragraph-field';
    paraDiv.id = `paragraph-${paragraphCounter}`;
    paraDiv.innerHTML = `
        <div class="paragraph-field-header">
            <span><i class="fas fa-paragraph"></i> Aya #${paragraphCounter}</span>
            <button type="button" class="btn-remove-paragraph" onclick="removeParagraphField('paragraph-${paragraphCounter}')" title="Ondoa aya hii">
                <i class="fas fa-times"></i>
            </button>
        </div>
        <div class="form-group">
            <label><i class="fas fa-heading"></i> Kichwa cha Aya (Optional)</label>
            <input type="text" class="para-title" placeholder="Mfano: Maelezo zaidi" value="${escapeHtml(title)}">
        </div>
        <div class="form-group">
            <label><i class="fas fa-align-left"></i> Maelezo</label>
            <textarea class="para-content" rows="3" placeholder="Eleza zaidi kuhusu tukio...">${escapeHtml(content)}</textarea>
        </div>
        <div class="form-group">
            <label><i class="fas fa-image"></i> Picha ya Aya (Optional)</label>
            <div class="url-input-wrapper">
                <i class="fas fa-link input-icon-left"></i>
                <input type="url" class="para-image url-input" placeholder="https://images.unsplash.com/photo-xxx?w=800" value="${escapeHtml(imageUrl)}">
            </div>
        </div>
    `;
    
    container.appendChild(paraDiv);
    paraDiv.style.animation = 'fadeIn 0.3s ease';
}

function removeParagraphField(id) {
    const element = document.getElementById(id);
    if (element) {
        element.style.animation = 'fadeOut 0.3s ease';
        setTimeout(() => element.remove(), 300);
    }
}

// ============================================
// ADMIN - SAVE EVENT
// ============================================

async function saveEvent(e) {
    e.preventDefault();
    
    const eventId = document.getElementById('eventId')?.value;
    const imageUrl = document.getElementById('eventImage')?.value.trim();
    const title = document.getElementById('eventTitle')?.value.trim();
    const dateValue = document.getElementById('eventDate')?.value;
    const description = document.getElementById('eventDescription')?.value.trim();
    const descImage = document.getElementById('eventDescImage')?.value.trim();
    
    // Validation
    if (!title) { showToastMessage('❌ Tafadhali weka kichwa cha tukio', 'error'); return; }
    if (!dateValue) { showToastMessage('❌ Tafadhali chagua tarehe', 'error'); return; }
    if (!imageUrl) { showToastMessage('❌ Tafadhali weka link ya picha', 'error'); return; }
    
    // Collect paragraphs
    const paragraphs = [];
    const paraFields = document.querySelectorAll('.paragraph-field');
    paraFields.forEach(field => {
        const paraTitle = field.querySelector('.para-title')?.value.trim();
        const paraContent = field.querySelector('.para-content')?.value.trim();
        const paraImage = field.querySelector('.para-image')?.value.trim();
        
        if (paraContent) {
            paragraphs.push({
                title: paraTitle || '',
                content: paraContent,
                imageUrl: paraImage || ''
            });
        }
    });
    
    const submitBtn = document.getElementById('eventSubmitBtn');
    const originalText = submitBtn?.innerHTML;
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        const eventData = {
            title: title,
            eventDate: firebase.firestore.Timestamp.fromDate(new Date(dateValue)),
            imageUrl: imageUrl,
            description: description || '',
            descImage: descImage || '',
            paragraphs: paragraphs,
            active: true,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (eventId) {
            // Update
            await db.collection('events').doc(eventId).update(eventData);
            showToastMessage('✅ Tukio limesasishwa!', 'success');
        } else {
            // Add
            eventData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('events').add(eventData);
            showToastMessage('✅ Tukio limeongezwa!', 'success');
        }
        
        resetEventForm();
        await loadAdminEvents();
        await loadPublicEvents();
        
    } catch (error) {
        console.error('Error saving event:', error);
        showToastMessage('❌ Imeshindwa: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-save"></i> Hifadhi Tukio';
        }
    }
}

function resetEventForm() {
    const form = document.getElementById('eventForm');
    if (form) form.reset();
    
    document.getElementById('eventId').value = '';
    document.getElementById('eventImagePreview').style.display = 'none';
    document.getElementById('paragraphsContainer').innerHTML = '';
    paragraphCounter = 0;
    eventEditingId = null;
    
    // Reset form title
    document.getElementById('eventFormTitle').textContent = 'Ongeza Tukio Jipya';
    
    // Reset submit button
    const submitBtn = document.getElementById('eventSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Hifadhi Tukio';
        submitBtn.style.background = '';
        submitBtn.style.color = '';
    }
    
    const cancelBtn = document.getElementById('eventCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'none';
}

// ============================================
// ADMIN - LOAD EVENTS LIST
// ============================================

async function loadAdminEvents() {
    const container = document.getElementById('adminEventsList');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-state"><i class="fas fa-spinner fa-spin"></i> <span>Inapakia...</span></div>';
    
    try {
        const snapshot = await db.collection('events')
            .orderBy('eventDate', 'desc')
            .orderBy('createdAt', 'desc')
            .get();
        
        const events = [];
        snapshot.forEach(doc => events.push({ id: doc.id, ...doc.data() }));
        
        document.getElementById('adminEventCount').textContent = `Jumla: ${events.length}`;
        
        if (events.length === 0) {
            container.innerHTML = '<div class="empty-state"><i class="fas fa-calendar-times"></i><p>Hakuna matukio bado</p></div>';
            return;
        }
        
        container.innerHTML = events.map(event => `
            <div class="admin-event-card">
                <div class="admin-event-image">
                    ${event.imageUrl ? 
                        `<img src="${event.imageUrl}" alt="${escapeHtml(event.title)}" onerror="this.src='https://via.placeholder.com/60?text=No'">` :
                        '<i class="fas fa-calendar" style="font-size:2rem;color:#94a3b8;"></i>'}
                </div>
                <div class="admin-event-info">
                    <h4>${escapeHtml(event.title)}</h4>
                    <div class="event-meta">
                        <span><i class="fas fa-calendar"></i> ${formatEventDate(event.eventDate)}</span>
                        <span><i class="fas fa-paragraph"></i> ${event.paragraphs?.length || 0} aya</span>
                        <span class="status-badge ${event.active ? 'status-active' : 'status-inactive'}">${event.active ? 'Active' : 'Inactive'}</span>
                    </div>
                </div>
                <div class="admin-event-actions">
                    <button class="btn-sm btn-view" onclick="viewEvent('${event.id}')" title="Tazama">
                        <i class="fas fa-eye"></i>
                    </button>
                    <button class="btn-sm btn-edit" onclick="editEvent('${event.id}')" title="Hariri">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button class="btn-sm btn-delete" onclick="deleteEvent('${event.id}')" title="Futa">
                        <i class="fas fa-trash"></i>
                    </button>
                </div>
            </div>
        `).join('');
        
    } catch (error) {
        console.error('Error loading admin events:', error);
        container.innerHTML = `<p class="error-text">Error: ${error.message}</p>`;
    }
}

function searchAdminEvents() {
    const searchTerm = document.getElementById('eventSearchInput')?.value.toLowerCase() || '';
    const cards = document.querySelectorAll('.admin-event-card');
    
    cards.forEach(card => {
        const title = card.querySelector('h4')?.textContent.toLowerCase() || '';
        card.style.display = title.includes(searchTerm) ? 'flex' : 'none';
    });
}

// ============================================
// ADMIN - EDIT EVENT
// ============================================

async function editEvent(eventId) {
    const doc = await db.collection('events').doc(eventId).get();
    if (!doc.exists) { showToastMessage('❌ Tukio halikupatikana', 'error'); return; }
    
    const event = doc.data();
    eventEditingId = eventId;
    
    // Populate form
    document.getElementById('eventId').value = eventId;
    document.getElementById('eventImage').value = event.imageUrl || '';
    document.getElementById('eventTitle').value = event.title || '';
    document.getElementById('eventDescription').value = event.description || '';
    document.getElementById('eventDescImage').value = event.descImage || '';
    
    // Set date
    if (event.eventDate) {
        const eventDate = event.eventDate.toDate ? event.eventDate.toDate() : new Date(event.eventDate);
        document.getElementById('eventDate').value = eventDate.toISOString().split('T')[0];
    }
    
    // Show image preview
    if (event.imageUrl) {
        previewEventImage(event.imageUrl);
    }
    
    // Load paragraphs
    document.getElementById('paragraphsContainer').innerHTML = '';
    paragraphCounter = 0;
    
    if (event.paragraphs && event.paragraphs.length > 0) {
        event.paragraphs.forEach(para => {
            addParagraphField(para.title || '', para.content || '', para.imageUrl || '');
        });
    }
    
    // Update form UI
    document.getElementById('eventFormTitle').textContent = 'Hariri Tukio';
    const submitBtn = document.getElementById('eventSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Sasisha Tukio';
        submitBtn.style.background = '#10b981';
        submitBtn.style.color = 'white';
    }
    
    const cancelBtn = document.getElementById('eventCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'inline-flex';
    
    // Scroll to form
    document.getElementById('eventForm').scrollIntoView({ behavior: 'smooth' });
    showToastMessage('📝 Unahariri: ' + event.title, 'info');
}

