async function deleteEvent(eventId) {
    if (!confirm('Una uhakika unataka kufuta tukio hili? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('events').doc(eventId).delete();
        showToastMessage('✅ Tukio limefutwa!', 'success');
        await loadAdminEvents();
        await loadPublicEvents();
    } catch (error) {
        console.error('Error deleting event:', error);
        showToastMessage('❌ Imeshindwa: ' + error.message, 'error');
    }
}

