// ============================================
// ADMIN SLIDESHOW MANAGEMENT SYSTEM
// ============================================

let allSlides = [];
let slideEditingId = null;
let adminSlideFilter = 'all';

// ============================================
// HANDLE SLIDE TYPE CHANGE
// ============================================

function handleSlideTypeChange() {
    const type = document.getElementById('slideType')?.value;
    const imageGroup = document.getElementById('slideImageGroup');
    const videoGroup = document.getElementById('slideVideoGroup');
    
    if (type === 'image') {
        if (imageGroup) imageGroup.style.display = 'block';
        if (videoGroup) videoGroup.style.display = 'none';
        document.getElementById('slideImageUrl').required = true;
        if (document.getElementById('slideVideoUrl')) {
            document.getElementById('slideVideoUrl').required = false;
        }
    } else if (type === 'video') {
        if (imageGroup) imageGroup.style.display = 'none';
        if (videoGroup) videoGroup.style.display = 'block';
        if (document.getElementById('slideImageUrl')) {
            document.getElementById('slideImageUrl').required = false;
        }
        document.getElementById('slideVideoUrl').required = true;
    }
}

// ============================================
// PREVIEW SLIDE IMAGE URL
// ============================================

function previewSlideImageUrl(url) {
    const preview = document.getElementById('slideImagePreview');
    const img = document.getElementById('slidePreviewImg');
    
    if (!preview || !img) return;
    
    if (!url) {
        preview.style.display = 'none';
        return;
    }
    
    preview.style.display = 'block';
    img.src = url;
}

function clearSlideImagePreview() {
    const preview = document.getElementById('slideImagePreview');
    const input = document.getElementById('slideImageUrl');
    if (preview) preview.style.display = 'none';
    if (input) input.value = '';
}

// ============================================
// SAVE SLIDE (ADD/UPDATE)
// ============================================

async function saveSlide(e) {
    e.preventDefault();
    
    const slideId = document.getElementById('slideId')?.value;
    const type = document.getElementById('slideType')?.value;
    const title = document.getElementById('slideTitle')?.value.trim();
    const description = document.getElementById('slideDescription')?.value.trim();
    const buttonLink = document.getElementById('slideButtonLink')?.value.trim();
    const buttonText = document.getElementById('slideButtonText')?.value.trim();
    const order = parseInt(document.getElementById('slideOrder')?.value) || 0;
    const active = document.getElementById('slideActive')?.value === 'true';
    
    let mediaUrl = '';
    if (type === 'image') {
        mediaUrl = document.getElementById('slideImageUrl')?.value.trim();
    } else if (type === 'video') {
        mediaUrl = document.getElementById('slideVideoUrl')?.value.trim();
    }
    
    // Validation
    if (!title) {
        showToastMessage('❌ Tafadhali weka kichwa cha slide', 'error');
        return;
    }
    
    if (!mediaUrl) {
        showToastMessage('❌ Tafadhali weka link ya media', 'error');
        return;
    }
    
    // Validate URL
    try {
        new URL(mediaUrl);
    } catch (e) {
        showToastMessage('❌ Link si sahihi. Hakikisha inaanza na https://', 'error');
        return;
    }
    
    const submitBtn = document.getElementById('slideSubmitBtn');
    const originalText = submitBtn?.innerHTML;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        const slideData = {
            type: type,
            title: title,
            description: description || '',
            mediaUrl: mediaUrl,
            buttonLink: buttonLink || '',
            buttonText: buttonText || '',
            order: order,
            active: active,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (slideId) {
            // UPDATE
            await db.collection('slideshow').doc(slideId).update(slideData);
            showToastMessage('✅ Slide imesasishwa!', 'success');
        } else {
            // ADD
            slideData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('slideshow').add(slideData);
            showToastMessage('✅ Slide imeongezwa!', 'success');
        }
        
        resetSlideForm();
        await loadAdminSlides();
        await loadPublicSlideshow();
        
    } catch (error) {
        console.error('Error saving slide:', error);
        showToastMessage('❌ Imeshindwa: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-plus"></i> Ongeza Slide';
        }
    }
}

// ============================================
// RESET SLIDE FORM
// ============================================

function resetSlideForm() {
    const form = document.getElementById('slideForm');
    if (form) form.reset();
    
    document.getElementById('slideId').value = '';
    document.getElementById('slideImagePreview').style.display = 'none';
    slideEditingId = null;
    
    // Reset to image type
    document.getElementById('slideType').value = 'image';
    handleSlideTypeChange();
    
    // Reset form title
    document.getElementById('slideFormTitle').textContent = 'Ongeza Slide Mpya';
    
    // Reset submit button
    const submitBtn = document.getElementById('slideSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-plus"></i> Ongeza Slide';
        submitBtn.style.background = '';
        submitBtn.style.color = '';
    }
    
    const cancelBtn = document.getElementById('slideCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'none';
}

// ============================================
// INITIALIZE SLIDE FORM
// ============================================

function initSlideForm() {
    const form = document.getElementById('slideForm');
    if (!form) return;
    
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', saveSlide);
    console.log('✅ Slide form initialized');
}

// ============================================
// LOAD ADMIN SLIDES LIST
// ============================================

async function loadAdminSlides() {
    const container = document.getElementById('adminSlidesList');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-state"><i class="fas fa-spinner fa-spin"></i> <span>Inapakia...</span></div>';
    
    try {
        const snapshot = await db.collection('slideshow').get();
        
        allSlides = [];
        snapshot.forEach(doc => {
            allSlides.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by order
        allSlides.sort((a, b) => (a.order || 0) - (b.order || 0));
        
        document.getElementById('adminSlideCount').textContent = `Jumla: ${allSlides.length}`;
        
        renderAdminSlides(allSlides);
        
    } catch (error) {
        console.error('Error loading slides:', error);
        container.innerHTML = `<p class="error-text">Error: ${error.message}</p>`;
    }
}

function renderAdminSlides(slides) {
    const container = document.getElementById('adminSlidesList');
    if (!container) return;
    
    if (!slides || slides.length === 0) {
        container.innerHTML = '<div class="empty-state"><i class="fas fa-images"></i><p>Hakuna slides bado</p></div>';
        return;
    }
    
    container.innerHTML = slides.map(slide => `
        <div class="admin-slide-card ${slide.active ? '' : 'inactive'}">
            <!-- Thumbnail -->
            <div class="admin-slide-thumb">
                ${slide.type === 'video' ? 
                    `<div class="video-thumb"><i class="fas fa-play-circle"></i></div>` :
                    `<img src="${slide.mediaUrl}" alt="${escapeHtml(slide.title)}" onerror="this.src='https://via.placeholder.com/120x68?text=No+Image'">`
                }
            </div>
            
            <!-- Info -->
            <div class="admin-slide-info">
                <h4>${escapeHtml(slide.title)}</h4>
                <div class="slide-meta">
                    <span class="slide-type-badge ${slide.type}">${slide.type === 'video' ? '🎬 Video' : '🖼️ Picha'}</span>
                    <span><i class="fas fa-sort"></i> Order: ${slide.order || 0}</span>
                    <span><i class="fas fa-calendar"></i> ${formatDate(slide.createdAt)}</span>
                    <span class="status-badge ${slide.active ? 'status-active' : 'status-inactive'}">
                        ${slide.active ? 'Active' : 'Inactive'}
                    </span>
                </div>
            </div>
            
            <!-- Actions -->
            <div class="admin-slide-actions">
                <button class="btn-sm btn-view" onclick="previewSlide('${slide.id}')" title="Tazama">
                    <i class="fas fa-eye"></i>
                </button>
                <button class="btn-sm btn-edit" onclick="editSlideItem('${slide.id}')" title="Hariri">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="btn-sm btn-delete" onclick="deleteSlideItem('${slide.id}')" title="Futa">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
    `).join('');
}

// ============================================
// FILTER & SEARCH SLIDES
// ============================================

function filterAdminSlides(type) {
    adminSlideFilter = type;
    
    document.querySelectorAll('#adminManageSlideshow .filter-tab').forEach(btn => {
        btn.classList.remove('active');
    });
    const activeBtn = document.querySelector(`#adminManageSlideshow .filter-tab[onclick*="${type}"]`);
    if (activeBtn) activeBtn.classList.add('active');
    
    const filtered = type === 'all' ? allSlides : allSlides.filter(s => s.type === type);
    renderAdminSlides(filtered);
}

function searchAdminSlides() {
    const searchTerm = document.getElementById('slideSearchInput')?.value.toLowerCase() || '';
    let filtered = allSlides;
    
    if (adminSlideFilter !== 'all') {
        filtered = filtered.filter(s => s.type === adminSlideFilter);
    }
    
    if (searchTerm) {
        filtered = filtered.filter(s => s.title?.toLowerCase().includes(searchTerm));
    }
    
    renderAdminSlides(filtered);
}

// ============================================
// EDIT SLIDE
// ============================================

async function editSlideItem(slideId) {
    const doc = await db.collection('slideshow').doc(slideId).get();
    if (!doc.exists) {
        showToastMessage('❌ Slide haikupatikana', 'error');
        return;
    }
    
    const slide = doc.data();
    slideEditingId = slideId;
    
    // Populate form
    document.getElementById('slideId').value = slideId;
    document.getElementById('slideType').value = slide.type || 'image';
    document.getElementById('slideTitle').value = slide.title || '';
    document.getElementById('slideDescription').value = slide.description || '';
    document.getElementById('slideButtonLink').value = slide.buttonLink || '';
    document.getElementById('slideButtonText').value = slide.buttonText || '';
    document.getElementById('slideOrder').value = slide.order || 0;
    document.getElementById('slideActive').value = slide.active ? 'true' : 'false';
    
    if (slide.type === 'image') {
        document.getElementById('slideImageUrl').value = slide.mediaUrl || '';
        previewSlideImageUrl(slide.mediaUrl);
    } else if (slide.type === 'video') {
        document.getElementById('slideVideoUrl').value = slide.mediaUrl || '';
    }
    
    handleSlideTypeChange();
    
    // Update form UI
    document.getElementById('slideFormTitle').textContent = 'Hariri Slide';
    const submitBtn = document.getElementById('slideSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Sasisha Slide';
        submitBtn.style.background = '#10b981';
        submitBtn.style.color = 'white';
    }
    
    const cancelBtn = document.getElementById('slideCancelEditBtn');
    if (cancelBtn) cancelBtn.style.display = 'inline-flex';
    
    document.getElementById('slideForm').scrollIntoView({ behavior: 'smooth' });
    showToastMessage('📝 Unahariri: ' + slide.title, 'info');
}

// ============================================
// PREVIEW SLIDE
// ============================================

function previewSlide(slideId) {
    const slide = allSlides.find(s => s.id === slideId);
    if (!slide) return;
    window.open(slide.mediaUrl, '_blank');
}

