async function deleteSlideItem(slideId) {
    if (!confirm('Una uhakika unataka kufuta slide hii? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('slideshow').doc(slideId).delete();
        showToastMessage('✅ Slide imefutwa!', 'success');
        await loadAdminSlides();
        await loadPublicSlideshow();
    } catch (error) {
        console.error('Error deleting slide:', error);
        showToastMessage('❌ Imeshindwa: ' + error.message, 'error');
    }
}

