// COMPLETE EXAM MANAGEMENT SYSTEM
// ============================================

// Global variables for exam management
let examQuestions = [];
let examEditingId = null;
let currentMarkingSubmission = null;
let allExams = [];
let examFilter = 'all';

// ============================================
// EXAM TYPE CHANGE - Show/hide question type buttons
// ============================================
function initExamQuestionTypeButtons() {
    const addBtn = document.querySelector('.btn-add-question');
    const quickTypes = document.getElementById('quickQuestionTypes');
    
    if (addBtn && quickTypes) {
        addBtn.addEventListener('click', function() {
            quickTypes.style.display = quickTypes.style.display === 'none' ? 'flex' : 'none';
        });
    }
}

// ============================================
// CALCULATE EXAM DURATION
// ============================================
function calculateExamDuration() {
    const startTime = document.getElementById('examStartTime')?.value;
    const endTime = document.getElementById('examEndTime')?.value;
    const durationInput = document.getElementById('examDuration');
    
    if (startTime && endTime && durationInput) {
        const [startH, startM] = startTime.split(':').map(Number);
        const [endH, endM] = endTime.split(':').map(Number);
        
        let diffMinutes = (endH * 60 + endM) - (startH * 60 + startM);
        if (diffMinutes < 0) diffMinutes += 24 * 60; // Handle overnight
        
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        
        durationInput.value = `${hours}h ${minutes}m (${diffMinutes} minutes)`;
        durationInput.setAttribute('data-minutes', diffMinutes);
    }
}

// ============================================
// ADD EXAM QUESTION - FIXED (Works on single click)
// ============================================
function addExamQuestion(preSelectedType = null) {
    // If a type is passed directly, use it
    if (preSelectedType) {
        addQuestionWithType(preSelectedType);
        return;
    }
    
    // Show the type selection buttons
    const typeContainer = document.getElementById('quickQuestionTypes');
    if (typeContainer) {
        // Toggle visibility
        if (typeContainer.style.display === 'none' || typeContainer.style.display === '' || !typeContainer.style.display) {
            typeContainer.style.display = 'flex';
        } else {
            typeContainer.style.display = 'none';
        }
    }
}

// Add question with specific type
function addQuestionWithType(type) {
    console.log('Adding question of type:', type);
    
    const questionId = Date.now();
    const questionNumber = examQuestions.length + 1;
    
    const questionData = {
        id: questionId,
        number: questionNumber,
        type: type,
        question: '',
        marks: 1,
        options: ['A', 'B', 'C', 'D'],
        correctAnswer: '',
        matchingPairs: [{ a: '', b: '' }],
        expectedAnswer: '',
        wordLimit: 100,
        essayWordLimit: 500,
        imageUrl: '',
        pictureOptions: ['A', 'B', 'C', 'D'],
        pictureCorrectAnswer: ''
    };
    
    examQuestions.push(questionData);
    renderExamQuestionCard(questionData);
    updateQuestionStats();
    
    // Hide quick types after adding
    const quickTypes = document.getElementById('quickQuestionTypes');
    if (quickTypes) quickTypes.style.display = 'none';
    
    // Scroll to the new question
    setTimeout(() => {
        const card = document.getElementById(`question-${questionId}`);
        if (card) {
            card.scrollIntoView({ behavior: 'smooth', block: 'center' });
            // Highlight briefly
            card.style.boxShadow = '0 0 0 3px #3b82f6';
            setTimeout(() => {
                card.style.boxShadow = '';
            }, 1500);
        }
    }, 200);
    
    console.log('Question added. Total questions:', examQuestions.length);
}

// ============================================
// RENDER EXAM QUESTION CARD
// ============================================
function renderExamQuestionCard(question) {
    const container = document.getElementById('examQuestionsList');
    if (!container) return;
    
    const card = document.createElement('div');
    card.className = 'exam-question-card';
    card.id = `question-${question.id}`;
    
    const typeLabels = {
        'multiple_choice': 'Multiple Choice',
        'matching': 'Matching Items',
        'short_answer': 'Short Answer',
        'essay': 'Essay',
        'picture_based': 'Picture Based'
    };
    
    let previewHtml = '';
    switch(question.type) {
        case 'multiple_choice':
            previewHtml = `
                <div class="q-preview-row">
                    <span class="q-preview-badge mc">MCQ</span>
                    <span>Options: ${question.options.length}</span>
                    <span>Answer: ${question.correctAnswer || '<em>Not set</em>'}</span>
                </div>`;
            break;
        case 'matching':
            previewHtml = `
                <div class="q-preview-row">
                    <span class="q-preview-badge matching">MATCH</span>
                    <span>Pairs: ${question.matchingPairs.length}</span>
                </div>`;
            break;
        case 'short_answer':
            previewHtml = `
                <div class="q-preview-row">
                    <span class="q-preview-badge sa">SHORT</span>
                    <span>Limit: ${question.wordLimit} chars</span>
                </div>`;
            break;
        case 'essay':
            previewHtml = `
                <div class="q-preview-row">
                    <span class="q-preview-badge essay">ESSAY</span>
                    <span>Words: ${question.essayWordLimit}</span>
                </div>`;
            break;
        case 'picture_based':
            previewHtml = `
                <div class="q-preview-row">
                    <span class="q-preview-badge pic">PIC</span>
                    <span>Image: ${question.imageUrl ? '✅ Set' : '❌ Not set'}</span>
                </div>`;
            break;
    }
    
    card.innerHTML = `
        <div class="question-card-header">
            <div class="q-header-left">
                <span class="question-number">Q${question.number}</span>
                <span class="question-type-label">${typeLabels[question.type] || question.type}</span>
            </div>
            <div class="q-header-right">
                <input type="number" class="q-marks-input" value="${question.marks}" min="1" max="100" 
                       title="Marks for this question" onchange="updateQuestionMarks(${question.id}, this.value)">
                <span class="marks-label">marks</span>
                <button class="btn-sm btn-edit" onclick="editExamQuestion(${question.id})" title="Edit question details">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="btn-sm btn-delete" onclick="removeExamQuestion(${question.id})" title="Remove question">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
        <div class="question-card-body">
            <p class="question-text">${question.question || '<em>Click Edit to add question text</em>'}</p>
            ${previewHtml}
        </div>
    `;
    
    container.appendChild(card);
}

// ============================================
// EDIT EXAM QUESTION - Opens modal (COMPLETE FIXED VERSION)
// ============================================
function editExamQuestion(questionId) {
    const question = examQuestions.find(q => q.id === questionId);
    if (!question) {
        showToast('Question not found', 'error');
        return;
    }
    
    // Store reference to current editing question
    window._editingQuestion = question;
    
    const modalContent = document.getElementById('examQuestionModalContent');
    if (!modalContent) {
        console.error('examQuestionModalContent not found');
        return;
    }
    
    // Build type-specific fields
    let specificFields = '';
    
    switch(question.type) {
        // ============ MULTIPLE CHOICE ============
        case 'multiple_choice':
            specificFields = `
                <div class="form-group">
                    <label><i class="fas fa-list-ul"></i> Answer Options</label>
                    <div class="options-editor" id="mcqOptionsEditor">
                        ${question.options.map((opt, i) => `
                            <div class="option-edit-row">
                                <span class="option-letter-edit">${String.fromCharCode(65 + i)}</span>
                                <input type="text" class="option-value-input" value="${escapeHtml(opt)}" 
                                       placeholder="Option ${String.fromCharCode(65 + i)}" data-index="${i}">
                                <button type="button" class="btn-remove-option-small" 
                                        onclick="removeMCQOption(${question.id}, ${i})" title="Remove option">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        `).join('')}
                    </div>
                    <button type="button" class="btn-add-option-small" onclick="addMCQOption(${question.id})">
                        <i class="fas fa-plus"></i> Add Option
                    </button>
                </div>
                <div class="form-group">
                    <label><i class="fas fa-check-circle"></i> Correct Answer</label>
                    <select id="mcqCorrectAnswer" class="form-control">
                        <option value="">-- Select Correct Answer --</option>
                        ${question.options.map(opt => `
                            <option value="${escapeHtml(opt)}" ${question.correctAnswer === opt ? 'selected' : ''}>
                                ${opt}
                            </option>
                        `).join('')}
                    </select>
                </div>`;
            break;
            
        // ============ MATCHING ITEMS ============
        case 'matching':
            specificFields = `
                <div class="form-group">
                    <label><i class="fas fa-exchange-alt"></i> Matching Pairs (Section A ↔ Section B)</label>
                    <div class="matching-editor">
                        <div class="matching-header-row">
                            <div class="matching-col-label">Section A</div>
                            <div class="matching-col-label">Section B</div>
                            <div class="matching-col-action"></div>
                        </div>
                        <div id="matchingPairsEditor">
                            ${question.matchingPairs.map((pair, i) => `
                                <div class="matching-edit-row">
                                    <input type="text" class="matching-a-input" value="${escapeHtml(pair.a)}" 
                                           placeholder="Item ${i + 1} (A)" data-index="${i}">
                                    <input type="text" class="matching-b-input" value="${escapeHtml(pair.b)}" 
                                           placeholder="Match ${i + 1} (B)" data-index="${i}">
                                    <button type="button" class="btn-remove-option-small" 
                                            onclick="removeMatchPair(${question.id}, ${i})" title="Remove pair">
                                        <i class="fas fa-times"></i>
                                    </button>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                    <button type="button" class="btn-add-option-small" onclick="addMatchPair(${question.id})">
                        <i class="fas fa-plus"></i> Add Pair
                    </button>
                </div>`;
            break;
            
        // ============ SHORT ANSWER ============
        case 'short_answer':
            specificFields = `
                <div class="form-group">
                    <label><i class="fas fa-check-circle"></i> Expected/Model Answer (For reference when marking)</label>
                    <textarea id="shortExpectedAnswer" rows="3" placeholder="Enter the expected answer...">${escapeHtml(question.expectedAnswer || '')}</textarea>
                </div>
                <div class="form-group">
                    <label><i class="fas fa-text-width"></i> Character Limit</label>
                    <input type="number" id="shortWordLimit" value="${question.wordLimit || 100}" min="10" max="2000">
                </div>`;
            break;
            
        // ============ ESSAY ============
        case 'essay':
            specificFields = `
                <div class="form-group">
                    <label><i class="fas fa-text-width"></i> Word Limit</label>
                    <input type="number" id="essayWordLimit" value="${question.essayWordLimit || 500}" min="50" max="10000">
                </div>
                <div class="form-group">
                    <label><i class="fas fa-info-circle"></i> Marking Guidelines (Optional)</label>
                    <textarea id="essayGuidelines" rows="3" placeholder="Key points to look for when marking...">${escapeHtml(question.expectedAnswer || '')}</textarea>
                </div>`;
            break;
            
        // ============ PICTURE BASED ============
        case 'picture_based':
            specificFields = `
                <div class="form-group">
                    <label><i class="fas fa-image"></i> Picture URL *</label>
                    <input type="url" id="pictureImageUrl" value="${escapeHtml(question.imageUrl || '')}" 
                           placeholder="https://example.com/image.jpg" oninput="previewPictureQuestion(this.value)">
                    <div id="picturePreview" style="margin-top:0.5rem;${question.imageUrl ? '' : 'display:none;'}">
                        <img id="picturePreviewImg" src="${question.imageUrl || ''}" 
                             style="max-width:100%;max-height:200px;border-radius:0.5rem;"
                             onerror="this.style.display='none'">
                    </div>
                </div>
                <div class="form-group">
                    <label><i class="fas fa-list-ul"></i> Options (for picture-based MCQ)</label>
                    <div class="options-editor" id="pictureOptionsEditor">
                        ${question.pictureOptions.map((opt, i) => `
                            <div class="option-edit-row">
                                <span class="option-letter-edit">${String.fromCharCode(65 + i)}</span>
                                <input type="text" class="picture-option-input" value="${escapeHtml(opt)}" 
                                       placeholder="Option ${String.fromCharCode(65 + i)}" data-index="${i}">
                                <button type="button" class="btn-remove-option-small" 
                                        onclick="removePictureOption(${question.id}, ${i})">
                                    <i class="fas fa-times"></i>
                                </button>
                            </div>
                        `).join('')}
                    </div>
                    <button type="button" class="btn-add-option-small" onclick="addPictureOption(${question.id})">
                        <i class="fas fa-plus"></i> Add Option
                    </button>
                </div>
                <div class="form-group">
                    <label><i class="fas fa-check-circle"></i> Correct Answer</label>
                    <select id="pictureCorrectAnswer" class="form-control">
                        <option value="">-- Select Correct Answer --</option>
                        ${question.pictureOptions.map(opt => `
                            <option value="${escapeHtml(opt)}" ${question.pictureCorrectAnswer === opt ? 'selected' : ''}>
                                ${opt}
                            </option>
                        `).join('')}
                    </select>
                </div>`;
            break;
    }
    
    // Build complete modal content
    modalContent.innerHTML = `
        <div class="modal-inner-content">
            <div class="modal-header">
                <h3><i class="fas fa-edit"></i> Edit Question #${question.number}</h3>
                <span class="question-type-badge">${getQuestionTypeLabel(question.type)}</span>
            </div>
            
            <div class="modal-body">
                <!-- Question Text -->
                <div class="form-group">
                    <label><i class="fas fa-question-circle"></i> Question Text *</label>
                    <textarea id="editQuestionText" rows="3" 
                              placeholder="Enter your question here..." 
                              required>${escapeHtml(question.question)}</textarea>
                </div>
                
                <!-- Marks -->
                <div class="form-group">
                    <label><i class="fas fa-star"></i> Marks for this question</label>
                    <input type="number" id="editQuestionMarks" value="${question.marks}" min="1" max="100">
                </div>
                
                <!-- Type-Specific Fields -->
                ${specificFields}
            </div>
            
            <!-- Modal Action Buttons -->
            <div class="modal-actions" style="display:flex;gap:1rem;justify-content:flex-end;margin-top:1.5rem;padding-top:1rem;border-top:1px solid #e2e8f0;">
                <button type="button" class="btn-secondary" onclick="closeExamQuestionModal()" 
                        style="background:#64748b;color:white;border:none;padding:0.5rem 1.5rem;border-radius:0.5rem;cursor:pointer;font-weight:500;">
                    <i class="fas fa-times"></i> Cancel
                </button>
                <button type="button" class="btn-primary" onclick="saveExamQuestion(event)" 
                        style="background:#e65c1e;color:white;border:none;padding:0.5rem 1.5rem;border-radius:0.5rem;cursor:pointer;font-weight:500;">
                    <i class="fas fa-save"></i> Save Question
                </button>
            </div>
        </div>
    `;
    
    // Show modal
    const modal = document.getElementById('examQuestionModal');
    if (modal) {
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
    }
}

// ============================================
// SAVE EXAM QUESTION - Reads values directly from DOM
// ============================================
function saveExamQuestion(event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }
    
    const question = window._editingQuestion;
    if (!question) {
        showToast('No question to save', 'error');
        return;
    }
    
    // Get common fields
    const questionText = document.getElementById('editQuestionText')?.value?.trim();
    const marks = parseInt(document.getElementById('editQuestionMarks')?.value) || 1;
    
    if (!questionText) {
        showToast('Please enter question text', 'error');
        document.getElementById('editQuestionText')?.focus();
        return;
    }
    
    // Update common fields
    question.question = questionText;
    question.marks = marks;
    
    // Update type-specific fields by reading directly from DOM
    try {
        switch (question.type) {
            case 'multiple_choice':
                // Read options directly from the editor
                const mcqOptionInputs = document.querySelectorAll('#mcqOptionsEditor .option-value-input');
                question.options = Array.from(mcqOptionInputs).map(inp => inp.value.trim()).filter(v => v);
                question.correctAnswer = document.getElementById('mcqCorrectAnswer')?.value || '';
                break;
                
            case 'matching':
                // Read matching pairs directly from the editor
                const aInputs = document.querySelectorAll('#matchingPairsEditor .matching-a-input');
                const bInputs = document.querySelectorAll('#matchingPairsEditor .matching-b-input');
                question.matchingPairs = Array.from(aInputs).map((aEl, i) => ({
                    a: aEl.value.trim(),
                    b: bInputs[i]?.value.trim() || ''
                }));
                break;
                
            case 'short_answer':
                question.expectedAnswer = document.getElementById('shortExpectedAnswer')?.value || '';
                question.wordLimit = parseInt(document.getElementById('shortWordLimit')?.value) || 100;
                break;
                
            case 'essay':
                question.essayWordLimit = parseInt(document.getElementById('essayWordLimit')?.value) || 500;
                question.expectedAnswer = document.getElementById('essayGuidelines')?.value || '';
                break;
                
            case 'picture_based':
                question.imageUrl = document.getElementById('pictureImageUrl')?.value || '';
                const picOptionInputs = document.querySelectorAll('#pictureOptionsEditor .picture-option-input');
                question.pictureOptions = Array.from(picOptionInputs).map(inp => inp.value.trim()).filter(v => v);
                question.pictureCorrectAnswer = document.getElementById('pictureCorrectAnswer')?.value || '';
                break;
        }
    } catch (error) {
        console.error('Error reading question fields:', error);
    }
    
    // Refresh the question card
    const card = document.getElementById(`question-${question.id}`);
    if (card) {
        card.remove();
        renderExamQuestionCard(question);
    }
    
    // Close modal
    closeExamQuestionModal();
    
    // Update stats
    updateQuestionStats();
    
    showToast('✅ Question saved!', 'success');
    
    return false;
}

// ============================================
// CLOSE EXAM QUESTION MODAL - FIXED
// ============================================
function closeExamQuestionModal() {
    const modal = document.getElementById('examQuestionModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
    // Clear the editing reference
    window._editingQuestion = null;
}

// ============================================
// GET QUESTION TYPE LABEL
// ============================================
function getQuestionTypeLabel(type) {
    const labels = {
        'multiple_choice': '📝 Multiple Choice',
        'matching': '🔗 Matching Items',
        'short_answer': '✏️ Short Answer',
        'essay': '📄 Essay',
        'picture_based': '🖼️ Picture Based'
    };
    return labels[type] || type;
}

// ============================================
// PREVIEW PICTURE QUESTION
// ============================================
function previewPictureQuestion(url) {
    const preview = document.getElementById('picturePreview');
    const img = document.getElementById('picturePreviewImg');
    
    if (!preview || !img) return;
    
    if (!url || url.trim() === '') {
        preview.style.display = 'none';
        return;
    }
    
    preview.style.display = 'block';
    img.src = url;
    img.onerror = function() {
        this.style.display = 'none';
        preview.innerHTML += '<p style="color:#ef4444;font-size:0.8rem;">Image failed to load</p>';
    };
    img.onload = function() {
        this.style.display = 'block';
    };
}

// ============================================
// INITIALIZE EXAM FORM - ONLY SAVE EXAM BUTTON TRIGGERS SUBMISSION
// ============================================
function initExamForm() {
    const form = document.getElementById('examCreateForm');
    const saveBtn = document.getElementById('examSubmitBtn');
    
    if (form && saveBtn) {
        // Remove old form and create new one to clear all listeners
        const newForm = form.cloneNode(true);
        form.parentNode.replaceChild(newForm, form);
        
        // Get the new save button
        const newSaveBtn = document.getElementById('examSubmitBtn');
        
        if (newSaveBtn) {
            // Remove any existing onclick and add clean listener
            newSaveBtn.removeAttribute('onclick');
            newSaveBtn.type = 'button'; // IMPORTANT: Not type="submit"
            
            newSaveBtn.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                console.log('Save Examination button clicked');
                saveExamination();
            });
            
            console.log('✅ Exam form initialized - only Save Exam button triggers submission');
        }
        
        // Prevent form from submitting on Enter key
        newForm.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && e.target.tagName !== 'TEXTAREA') {
                e.preventDefault();
                return false;
            }
        });
        
        // Prevent default form submission
        newForm.addEventListener('submit', function(e) {
            e.preventDefault();
            e.stopPropagation();
            console.log('Form submit prevented - use Save Examination button');
            return false;
        });
    } else {
        console.error('Exam form or submit button not found');
        console.log('form:', form);
        console.log('saveBtn:', saveBtn);
    }
}

// ============================================
// SAVE EXAMINATION - EXTRACTED FUNCTION
// ============================================
async function saveExamination() {
    console.log('saveExamination called');
    
    const examId = document.getElementById('examEditId')?.value;
    const title = document.getElementById('examTitle')?.value.trim();
    const categoryType = document.getElementById('examCategoryType')?.value;
    const moduleCode = document.getElementById('examModule')?.value;
    const date = document.getElementById('examDate')?.value;
    const startTime = document.getElementById('examStartTime')?.value;
    const endTime = document.getElementById('examEndTime')?.value;
    const instructions = document.getElementById('examInstructions')?.value.trim();
    const durationMinutes = parseInt(document.getElementById('examDuration')?.getAttribute('data-minutes')) || 60;
    const totalMarks = parseInt(document.getElementById('examTotalMarks')?.value) || 100;
    
    // Validation
    if (!title) { showToast('❌ Please enter exam title', 'error'); return; }
    if (!categoryType) { showToast('❌ Please select exam category type', 'error'); return; }
    if (!moduleCode) { showToast('❌ Please select module', 'error'); return; }
    if (!date) { showToast('❌ Please select exam date', 'error'); return; }
    if (!startTime || !endTime) { showToast('❌ Please set start and end time', 'error'); return; }
    
    if (examQuestions.length === 0) {
        showToast('❌ Please add at least one question', 'error');
        return;
    }
    
    // Validate each question has text
    for (const q of examQuestions) {
        if (!q.question || q.question.trim() === '') {
            showToast(`❌ Question ${q.number} has no text. Please click Edit to add question text.`, 'error');
            return;
        }
    }
    
    const submitBtn = document.getElementById('examSubmitBtn');
    const originalHTML = submitBtn?.innerHTML;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    }
    
    try {
        // Clean questions
        const cleanQuestions = examQuestions.map(q => {
            const base = {
                id: q.id,
                number: q.number,
                type: q.type,
                question: q.question,
                marks: q.marks || 1
            };
            
            switch (q.type) {
                case 'multiple_choice':
                    base.options = q.options || ['A', 'B', 'C', 'D'];
                    base.correctAnswer = q.correctAnswer || '';
                    break;
                case 'matching':
                    base.matchingPairs = q.matchingPairs || [{ a: '', b: '' }];
                    break;
                case 'short_answer':
                    base.expectedAnswer = q.expectedAnswer || '';
                    base.wordLimit = q.wordLimit || 100;
                    break;
                case 'essay':
                    base.essayWordLimit = q.essayWordLimit || 500;
                    base.expectedAnswer = q.expectedAnswer || '';
                    break;
                case 'picture_based':
                    base.imageUrl = q.imageUrl || '';
                    base.pictureOptions = q.pictureOptions || ['A', 'B', 'C', 'D'];
                    base.pictureCorrectAnswer = q.pictureCorrectAnswer || '';
                    break;
            }
            
            return base;
        });
        
        const examData = {
            title,
            categoryType,
            moduleCode,
            examDate: firebase.firestore.Timestamp.fromDate(new Date(date + 'T' + startTime)),
            startTime,
            endTime,
            durationMinutes,
            totalMarks,
            instructions,
            questions: cleanQuestions,
            questionCount: cleanQuestions.length,
            status: 'active',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (examId) {
            await db.collection('examinations').doc(examId).update(examData);
            showToast('✅ Examination updated successfully!', 'success');
        } else {
            examData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            examData.createdBy = currentUser?.uid;
            examData.createdByName = currentUser?.name;
            await db.collection('examinations').add(examData);
            showToast('✅ Examination created successfully!', 'success');
        }
        
        // Add to timetable
        try {
            const existingTimetable = await db.collection('timetable')
                .where('activity', '==', `EXAM: ${title}`)
                .get();
            
            if (existingTimetable.empty) {
                await db.collection('timetable').add({
                    date: firebase.firestore.Timestamp.fromDate(new Date(date + 'T' + startTime)),
                    time: `${startTime} - ${endTime}`,
                    activity: `EXAM: ${title}`,
                    module: moduleCode,
                    type: 'examination',
                    examType: categoryType,
                    createdAt: firebase.firestore.FieldValue.serverTimestamp()
                });
            }
        } catch (e) {
            console.log('Timetable update skipped:', e);
        }
        
        // Reset form after successful save
        resetExamForm();
        
        // Refresh exam lists
        if (typeof loadAllExamData === 'function') {
            await loadAllExamData();
        }
        
    } catch (error) {
        console.error('Error saving exam:', error);
        showToast('❌ Failed to save: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalHTML || '<i class="fas fa-save"></i> Save Examination';
        }
    }
}

