// ============================================
// REMOVE EXAM QUESTION
// ============================================
function removeExamQuestion(questionId) {
    if (!confirm('Remove this question?')) return;
    
    examQuestions = examQuestions.filter(q => q.id !== questionId);
    
    // Renumber remaining questions
    examQuestions.forEach((q, i) => q.number = i + 1);
    
    // Refresh all cards
    const container = document.getElementById('examQuestionsList');
    if (container) {
        container.innerHTML = '';
        examQuestions.forEach(q => renderExamQuestionCard(q));
    }
    
    updateQuestionStats();
}

// ============================================
// UPDATE QUESTION MARKS
// ============================================
function updateQuestionMarks(questionId, value) {
    const question = examQuestions.find(q => q.id === questionId);
    if (question) {
        question.marks = parseInt(value) || 1;
        updateQuestionStats();
    }
}

// ============================================
// UPDATE QUESTION STATISTICS
// ============================================
function updateQuestionStats() {
    const statsEl = document.getElementById('questionStats');
    if (statsEl) {
        const totalMarks = examQuestions.reduce((sum, q) => sum + (parseInt(q.marks) || 0), 0);
        statsEl.textContent = `${examQuestions.length} Questions | ${totalMarks} Marks`;
    }
    
    // Update total marks field
    const totalMarksInput = document.getElementById('examTotalMarks');
    if (totalMarksInput) {
        const totalMarks = examQuestions.reduce((sum, q) => sum + (parseInt(q.marks) || 0), 0);
        totalMarksInput.value = totalMarks;
    }
}

// ============================================
// SAVE EXAMINATION - FIXED
// ============================================
document.getElementById('examCreateForm')?.addEventListener('submit', async function(e) {
    e.preventDefault();
    
    const examId = document.getElementById('examEditId')?.value;
    const title = document.getElementById('examTitle')?.value.trim();
    const categoryType = document.getElementById('examCategoryType')?.value;
    const moduleCode = document.getElementById('examModule')?.value;
    const date = document.getElementById('examDate')?.value;
    const startTime = document.getElementById('examStartTime')?.value;
    const endTime = document.getElementById('examEndTime')?.value;
    const instructions = document.getElementById('examInstructions')?.value.trim();
    const durationMinutes = parseInt(document.getElementById('examDuration')?.getAttribute('data-minutes')) || 60;
    const totalMarks = parseInt(document.getElementById('examTotalMarks')?.value) || 100;
    
    // Validation
    if (!title) { showToast('Please enter exam title', 'error'); return; }
    if (!categoryType) { showToast('Please select exam category type', 'error'); return; }
    if (!moduleCode) { showToast('Please select module', 'error'); return; }
    if (!date) { showToast('Please select exam date', 'error'); return; }
    if (!startTime || !endTime) { showToast('Please set start and end time', 'error'); return; }
    
    if (examQuestions.length === 0) {
        showToast('Please add at least one question', 'error');
        return;
    }
    
    // Validate each question has text
    for (const q of examQuestions) {
        if (!q.question || q.question.trim() === '') {
            showToast(`Question ${q.number} has no text. Please edit it.`, 'error');
            return;
        }
    }
    
    const submitBtn = document.getElementById('examSubmitBtn');
    const originalText = submitBtn?.innerHTML;
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    }
    
    try {
        // Clean questions - keep only relevant fields based on type
        const cleanQuestions = examQuestions.map(q => {
            const base = {
                id: q.id,
                number: q.number,
                type: q.type,
                question: q.question,
                marks: q.marks || 1
            };
            
            // Add type-specific fields
            switch (q.type) {
                case 'multiple_choice':
                    base.options = q.options || ['A', 'B', 'C', 'D'];
                    base.correctAnswer = q.correctAnswer || '';
                    break;
                case 'matching':
                    base.matchingPairs = q.matchingPairs || [{ a: '', b: '' }];
                    break;
                case 'short_answer':
                    base.expectedAnswer = q.expectedAnswer || '';
                    base.wordLimit = q.wordLimit || 100;
                    break;
                case 'essay':
                    base.essayWordLimit = q.essayWordLimit || 500;
                    base.expectedAnswer = q.expectedAnswer || '';
                    break;
                case 'picture_based':
                    base.imageUrl = q.imageUrl || '';
                    base.pictureOptions = q.pictureOptions || ['A', 'B', 'C', 'D'];
                    base.pictureCorrectAnswer = q.pictureCorrectAnswer || '';
                    break;
            }
            
            return base;
        });
        
        const examData = {
            title,
            categoryType,
            moduleCode,
            examDate: firebase.firestore.Timestamp.fromDate(new Date(date + 'T' + startTime)),
            startTime,
            endTime,
            durationMinutes,
            totalMarks,
            instructions,
            questions: cleanQuestions,
            questionCount: cleanQuestions.length,
            status: 'active',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (examId) {
            await db.collection('examinations').doc(examId).update(examData);
            showToast('✅ Examination updated successfully!', 'success');
        } else {
            examData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            examData.createdBy = currentUser.uid;
            examData.createdByName = currentUser.name;
            await db.collection('examinations').add(examData);
            showToast('✅ Examination created successfully!', 'success');
        }
        
        // Add to timetable
        try {
            const existingTimetable = await db.collection('timetable')
                .where('activity', '==', `EXAM: ${title}`)
                .get();
            
            if (existingTimetable.empty) {
                await db.collection('timetable').add({
                    date: firebase.firestore.Timestamp.fromDate(new Date(date + 'T' + startTime)),
                    time: `${startTime} - ${endTime}`,
                    activity: `EXAM: ${title}`,
                    module: moduleCode,
                    type: 'examination',
                    examType: categoryType,
                    createdAt: firebase.firestore.FieldValue.serverTimestamp()
                });
            }
        } catch (e) {
            console.log('Timetable update skipped:', e);
        }
        
        resetExamForm();
        await loadAllExamData();
        
    } catch (error) {
        console.error('Error saving exam:', error);
        showToast('❌ Failed to save: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText;
        }
    }
});

// ============================================
// RESET EXAM FORM
// ============================================
function resetExamForm() {
    document.getElementById('examCreateForm')?.reset();
    document.getElementById('examEditId').value = '';
    examQuestions = [];
    examEditingId = null;
    
    const container = document.getElementById('examQuestionsList');
    if (container) container.innerHTML = '';
    
    updateQuestionStats();
    
    document.getElementById('examFormTitle').textContent = 'Create New Examination';
    const submitBtn = document.getElementById('examSubmitBtn');
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-save"></i> Save Examination';
        submitBtn.style.background = '';
    }
    
    document.getElementById('examCancelEditBtn').style.display = 'none';
    document.getElementById('examDuration').value = '';
    document.getElementById('examDuration').removeAttribute('data-minutes');
}

// ============================================
// LOAD ALL EXAM DATA
// ============================================
async function loadAllExamData() {
    await Promise.all([
        loadStaffModulesForSelect(),
        loadExamsList(),
        loadViolationsList(),
        loadPendingMarkingList()
    ]);
}

// ============================================
// LOAD EXAMS LIST - FILTERED BY CURRENT STAFF
// Only shows exams created by this staff member
// ============================================
async function loadExamsList() {
    const container = document.getElementById('examsList');
    if (!container) return;
    
    if (!currentUser) {
        container.innerHTML = '<p class="text-center">Hakuna mtumiaji aliyeingia</p>';
        return;
    }
    
    container.innerHTML = '<div class="loading-spinner">Inapakia mitihani yako...</div>';
    
    try {
        // ============================================
        // FILTER: Only show exams created by THIS staff member
        // ============================================
        const snapshot = await db.collection('examinations')
            .where('createdBy', '==', currentUser.uid)
            .get();
        
        allExams = [];
        snapshot.forEach(doc => {
            allExams.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by date descending
        allExams.sort((a, b) => {
            const dateA = a.examDate?.toDate?.() || new Date(0);
            const dateB = b.examDate?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        // Update count badge
        const examCountEl = document.getElementById('examCount');
        if (examCountEl) {
            examCountEl.textContent = `${allExams.length} Mitihani (Yangu Pekee)`;
        }
        
        if (allExams.length === 0) {
            container.innerHTML = `
                <div style="text-align:center;padding:3rem;color:#64748b;">
                    <i class="fas fa-file-alt" style="font-size:3rem;display:block;margin-bottom:1rem;color:#94a3b8;"></i>
                    <h4 style="color:#475569;margin-bottom:0.5rem;">Hakuna Mitihani</h4>
                    <p style="font-size:0.9rem;">Hujaunda mtihani wowote bado.</p>
                    <p style="font-size:0.8rem;color:#94a3b8;">Tumia form hapo juu kuunda mtihani mpya.</p>
                </div>`;
            return;
        }
        
        renderExamsList(allExams);
        
        console.log(`✅ Loaded ${allExams.length} exams for staff: ${currentUser.name}`);
        
    } catch (error) {
        console.error('Error loading exams:', error);
        container.innerHTML = `<p class="error-text">Kosa: ${error.message}</p>`;
    }
}

function renderExamsList(exams) {
    const container = document.getElementById('examsList');
    if (!container) return;
    
    if (!exams || exams.length === 0) {
        container.innerHTML = '<p class="text-center">Hakuna mitihani inayofanana na vigezo</p>';
        return;
    }
    
    container.innerHTML = exams.map(exam => {
        const examDate = exam.examDate?.toDate?.()?.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric'
        }) || '-';
        
        const typeLabels = {
            'test1': 'Test 1', 'test2': 'Test 2', 'midterm': 'Midterm',
            'final': 'Final', 'assessment': 'Assessment', 'quiz': 'Quiz'
        };
        
        return `
            <div class="item-card">
                <div class="item-info">
                    <h4>${escapeHtml(exam.title)}</h4>
                    <p>
                        <span class="type-badge type-${exam.categoryType}">${typeLabels[exam.categoryType] || exam.categoryType}</span>
                        <strong>Module:</strong> ${escapeHtml(exam.moduleCode)}
                    </p>
                    <p><strong>Tarehe:</strong> ${examDate} | ${exam.startTime} - ${exam.endTime} (${exam.durationMinutes}min)</p>
                    <p><strong>Maswali:</strong> ${exam.questionCount || exam.questions?.length || 0} | <strong>Alama:</strong> ${exam.totalMarks}</p>
                    ${exam.createdByName ? `<p style="font-size:0.75rem;color:#94a3b8;"><i class="fas fa-user"></i> Imeundwa na: ${escapeHtml(exam.createdByName)}</p>` : ''}
                </div>
                <div class="item-actions">
                    <button class="btn-view" onclick="viewExamDetails('${exam.id}')">
                        <i class="fas fa-eye"></i> Tazama
                    </button>
                    <button class="btn-edit" onclick="editExistingExam('${exam.id}')">
                        <i class="fas fa-edit"></i> Hariri
                    </button>
                    <button class="btn-delete" onclick="deleteExam('${exam.id}')">
                        <i class="fas fa-trash"></i> Futa
                    </button>
                </div>
            </div>
        `;
    }).join('');
    
    // Update header to show it's private
    const header = document.querySelector('#staffExams .management-section-header h4:last-of-type');
    if (header && exams.length > 0) {
        header.innerHTML = `<i class="fas fa-list"></i> Mitihani Yangu Pekee <span style="font-size:0.7rem;color:#94a3b8;">(${exams.length})</span>`;
    }
}

// ============================================
// EDIT EXISTING EXAM
// ============================================
async function editExistingExam(examId) {
    const exam = allExams.find(e => e.id === examId);
    if (!exam) return;
    
    examEditingId = examId;
    
    // Populate form
    document.getElementById('examEditId').value = examId;
    document.getElementById('examTitle').value = exam.title || '';
    document.getElementById('examCategoryType').value = exam.categoryType || '';
    document.getElementById('examModule').value = exam.moduleCode || '';
    document.getElementById('examInstructions').value = exam.instructions || '';
    document.getElementById('examTotalMarks').value = exam.totalMarks || 100;
    
    // Set date
    if (exam.examDate) {
        const d = exam.examDate.toDate?.() || new Date(exam.examDate);
        document.getElementById('examDate').value = d.toISOString().split('T')[0];
    }
    
    document.getElementById('examStartTime').value = exam.startTime || '';
    document.getElementById('examEndTime').value = exam.endTime || '';
    calculateExamDuration();
    
    // Load questions
    examQuestions = exam.questions || [];
    
    const container = document.getElementById('examQuestionsList');
    if (container) {
        container.innerHTML = '';
        examQuestions.forEach(q => renderExamQuestionCard(q));
    }
    
    updateQuestionStats();
    
    // Update form UI
    document.getElementById('examFormTitle').textContent = 'Edit Examination';
    document.getElementById('examSubmitBtn').innerHTML = '<i class="fas fa-save"></i> Update Examination';
    document.getElementById('examSubmitBtn').style.background = '#10b981';
    document.getElementById('examCancelEditBtn').style.display = 'inline-flex';
    
    // Scroll to form
    document.getElementById('examCreateForm').scrollIntoView({ behavior: 'smooth' });
}

// ============================================
// VIEW EXAM DETAILS
// ============================================
async function viewExamDetails(examId) {
    const exam = allExams.find(e => e.id === examId);
    if (!exam) return;
    
    // Count submissions
    const submissionsSnapshot = await db.collection('examSubmissions')
        .where('examId', '==', examId)
        .get();
    
    const totalSubmissions = submissionsSnapshot.size;
    const markedSubmissions = submissionsSnapshot.docs.filter(d => d.data().status === 'marked').length;
    
    const typeLabels = {
        'test1': 'Test 1', 'test2': 'Test 2', 'midterm': 'Midterm',
        'final': 'Final', 'assessment': 'Assessment', 'quiz': 'Quiz'
    };
    
    let questionsHtml = exam.questions?.map((q, i) => `
        <div class="answer-item">
            <h5>Q${i + 1}: ${escapeHtml(q.question)} <span class="q-marks-badge">[${q.marks} marks]</span></h5>
            <p><strong>Type:</strong> ${q.type?.replace('_', ' ')}</p>
            ${q.type === 'multiple_choice' ? `<p><strong>Options:</strong> ${q.options?.join(', ')} | <strong>Answer:</strong> ${q.correctAnswer}</p>` : ''}
            ${q.type === 'matching' ? `<p><strong>Pairs:</strong> ${q.matchingPairs?.length || 0}</p>` : ''}
            ${q.imageUrl ? `<img src="${q.imageUrl}" style="max-width:200px;max-height:150px;border-radius:0.5rem;">` : ''}
        </div>
    `).join('') || '<p>No questions</p>';
    
    const modalContent = document.getElementById('examMarkingContent');
    if (modalContent) {
        modalContent.innerHTML = `
            <div class="exam-detail-view">
                <h3>${escapeHtml(exam.title)}</h3>
                <div class="exam-meta-grid">
                    <div><strong>Type:</strong> ${typeLabels[exam.categoryType] || exam.categoryType}</div>
                    <div><strong>Module:</strong> ${escapeHtml(exam.moduleCode)}</div>
                    <div><strong>Date:</strong> ${exam.examDate?.toDate?.().toLocaleDateString() || '-'}</div>
                    <div><strong>Time:</strong> ${exam.startTime} - ${exam.endTime}</div>
                    <div><strong>Duration:</strong> ${exam.durationMinutes} minutes</div>
                    <div><strong>Total Marks:</strong> ${exam.totalMarks}</div>
                    <div><strong>Submissions:</strong> ${totalSubmissions} (${markedSubmissions} marked)</div>
                </div>
                <hr>
                <h4>Questions (${exam.questions?.length || 0})</h4>
                ${questionsHtml}
            </div>
        `;
    }
    
    document.getElementById('examMarkingModal').classList.add('active');
    document.body.style.overflow = 'hidden';
}

// ============================================
// DELETE EXAM
// ============================================
async function deleteExam(examId) {
    if (!confirm('Are you sure you want to delete this examination? This cannot be undone.')) return;
    
    try {
        await db.collection('examinations').doc(examId).delete();
        showToast('Exam deleted', 'success');
        await loadExamsList();
    } catch (error) {
        console.error('Error deleting exam:', error);
        showToast('Failed to delete: ' + error.message, 'error');
    }
}

// ============================================
// LOAD VIOLATIONS - Only show violations 
// from exams created by THIS staff member
// ============================================
async function loadViolationsList() {
    const container = document.getElementById('violationsList');
    if (!container) return;
    
    if (!currentUser) {
        container.innerHTML = '<p class="text-center">Hakuna mtumiaji aliyeingia</p>';
        return;
    }
    
    try {
        // Get exams created by this staff
        const myExamsSnapshot = await db.collection('examinations')
            .where('createdBy', '==', currentUser.uid)
            .get();
        
        const myExamIds = [];
        myExamsSnapshot.forEach(doc => {
            myExamIds.push(doc.id);
        });
        
        if (myExamIds.length === 0) {
            container.innerHTML = '<p class="text-center">Hakuna auto-submitted exams</p>';
            document.getElementById('violationsCount').textContent = '0';
            return;
        }
        
        // Get violations for these exams
        let violations = [];
        
        for (let i = 0; i < myExamIds.length; i += 10) {
            const batch = myExamIds.slice(i, i + 10);
            
            const snapshot = await db.collection('examSubmissions')
                .where('examId', 'in', batch)
                .where('status', '==', 'auto_submitted')
                .get();
            
            snapshot.forEach(doc => {
                violations.push({ id: doc.id, ...doc.data() });
            });
        }
        
        document.getElementById('violationsCount').textContent = violations.length;
        
        if (violations.length === 0) {
            container.innerHTML = '<p class="text-center">Hakuna auto-submitted exams</p>';
            return;
        }
        
        container.innerHTML = violations.map(sub => {
            const reasonText = sub.submissionReason === 'time_up' ? '⏰ Muda Umeisha' :
                sub.submissionReason === 'screen_split' ? '📱 Screen Split' :
                sub.submissionReason === 'window_blur' ? '🪟 Window Blur' :
                sub.submissionReason;
            
            return `
                <div class="violation-card">
                    <div class="violation-info">
                        <h5>${escapeHtml(sub.studentName)} - ${escapeHtml(sub.examTitle)}</h5>
                        <p><strong>Sababu:</strong> ${reasonText}</p>
                        <p><strong>Imewasilishwa:</strong> ${sub.submittedAt?.toDate?.()?.toLocaleString() || '-'}</p>
                        <p><strong>Module:</strong> ${escapeHtml(sub.moduleCode)}</p>
                    </div>
                    <div class="violation-actions">
                        <button class="btn-primary btn-sm" onclick="allowRetake('${sub.id}')">
                            <i class="fas fa-redo"></i> Ruhusu Kufanya Upya
                        </button>
                        <button class="btn-secondary btn-sm" onclick="markAsComplete('${sub.id}')">
                            <i class="fas fa-check"></i> Acha
                        </button>
                    </div>
                </div>
            `;
        }).join('');
        
    } catch (error) {
        console.error('Error loading violations:', error);
        container.innerHTML = `<p class="error-text">Kosa: ${error.message}</p>`;
    }
}

// ============================================
// ALLOW RETAKE
// ============================================
async function allowRetake(submissionId) {
    if (!confirm('Allow this student to retake the exam?')) return;
    
    try {
        await db.collection('examSubmissions').doc(submissionId).delete();
        showToast('Student can now retake the exam', 'success');
        await loadViolationsList();
    } catch (error) {
        showToast('Failed: ' + error.message, 'error');
    }
}

// ============================================
// MARK AS COMPLETE
// ============================================
async function markAsComplete(submissionId) {
    try {
        await db.collection('examSubmissions').doc(submissionId).update({
            status: 'auto_submitted_final',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        showToast('Marked as complete', 'success');
        await loadViolationsList();
    } catch (error) {
        showToast('Failed: ' + error.message, 'error');
    }
}

// ============================================
// LOAD PENDING MARKING - Only show submissions 
// from exams created by THIS staff member
// ============================================
async function loadPendingMarkingList() {
    const container = document.getElementById('pendingMarkingList');
    if (!container) return;
    
    if (!currentUser) {
        container.innerHTML = '<p class="text-center">Hakuna mtumiaji aliyeingia</p>';
        return;
    }
    
    container.innerHTML = '<div class="loading-spinner">Inapakia...</div>';
    
    try {
        // First, get all exams created by this staff
        const myExamsSnapshot = await db.collection('examinations')
            .where('createdBy', '==', currentUser.uid)
            .get();
        
        const myExamIds = [];
        myExamsSnapshot.forEach(doc => {
            myExamIds.push(doc.id);
        });
        
        if (myExamIds.length === 0) {
            container.innerHTML = '<p class="text-center">Hakuna submissions zinazosubiri kusahihishwa</p>';
            document.getElementById('pendingMarkingCount').textContent = '0';
            return;
        }
        
        // Get submissions for these exams that need marking
        // Firestore 'in' query supports max 10 items
        let pending = [];
        
        // Batch the queries if more than 10 exams
        for (let i = 0; i < myExamIds.length; i += 10) {
            const batch = myExamIds.slice(i, i + 10);
            
            const snapshot = await db.collection('examSubmissions')
                .where('examId', 'in', batch)
                .where('status', 'in', ['submitted', 'auto_submitted'])
                .get();
            
            snapshot.forEach(doc => {
                pending.push({ id: doc.id, ...doc.data() });
            });
        }
        
        document.getElementById('pendingMarkingCount').textContent = pending.length;
        
        if (pending.length === 0) {
            container.innerHTML = '<p class="text-center">Hakuna submissions zinazosubiri kusahihishwa</p>';
            return;
        }
        
        container.innerHTML = pending.map(sub => `
            <div class="item-card">
                <div class="item-info">
                    <h4>${escapeHtml(sub.studentName)}</h4>
                    <p><strong>Mtihani:</strong> ${escapeHtml(sub.examTitle)}</p>
                    <p><strong>Module:</strong> ${escapeHtml(sub.moduleCode)}</p>
                    <p><strong>Imewasilishwa:</strong> ${sub.submittedAt?.toDate?.()?.toLocaleString() || '-'}</p>
                    <p><span class="status-badge status-pending">Inasubiri Kuhahihishwa</span></p>
                </div>
                <div class="item-actions">
                    <button class="btn-primary" onclick="openMarkingModal('${sub.id}')">
                        <i class="fas fa-check-double"></i> Sahihisha
                    </button>
                </div>
            </div>
        `).join('');
        
    } catch (error) {
        console.error('Error loading pending marking:', error);
        container.innerHTML = `<p class="error-text">Kosa: ${error.message}</p>`;
    }
}

// ============================================
// OPEN MARKING MODAL - FIXED
// ============================================
async function openMarkingModal(submissionId) {
    console.log('Opening marking modal for submission:', submissionId);
    
    try {
        // Check if modal elements exist
        const modal = document.getElementById('examMarkingModal');
        const content = document.getElementById('examMarkingContent');
        
        if (!modal) {
            console.error('examMarkingModal element not found');
            showToast('Modal element missing. Please refresh the page.', 'error');
            return;
        }
        
        if (!content) {
            console.error('examMarkingContent element not found');
            showToast('Modal content element missing.', 'error');
            return;
        }
        
        // Show loading
        content.innerHTML = '<div class="loading-spinner">Loading submission...</div>';
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
        
        // Fetch submission data
        const doc = await db.collection('examSubmissions').doc(submissionId).get();
        
        if (!doc.exists) {
            showToast('Submission not found', 'error');
            closeExamMarkingModal();
            return;
        }
        
        currentMarkingSubmission = { id: doc.id, ...doc.data() };
        const sub = currentMarkingSubmission;
        
        console.log('Submission loaded:', sub);
        
        // Build marking HTML
        let questionsHtml = '';
        
        if (sub.answers && sub.answers.length > 0) {
            questionsHtml = sub.answers.map((ans, idx) => {
                let answerDisplay = '';
                
                if (Array.isArray(ans.answer)) {
                    answerDisplay = ans.answer.map((a, i) => `${i + 1}. ${a || '-'}`).join('<br>');
                } else {
                    answerDisplay = ans.answer || '<em>No answer</em>';
                }
                
                let correctInfo = '';
                if (ans.type === 'multiple_choice' || ans.type === 'picture_based') {
                    correctInfo = `<p><strong>Correct Answer:</strong> ${ans.correctAnswer || 'N/A'}</p>`;
                }
                
                return `
                    <div class="marking-question-item">
                        <div class="marking-q-header">
                            <h5>Q${idx + 1}: ${escapeHtml(ans.question || 'No question')} <span class="q-marks-badge">[${ans.marks || 1} marks]</span></h5>
                        </div>
                        <div class="marking-answer">
                            <p><strong>Student's Answer:</strong></p>
                            <div class="student-answer-box">${answerDisplay}</div>
                            ${correctInfo}
                        </div>
                        <div class="marking-actions">
                            <button class="btn-correct" onclick="markQuestion(${idx}, true)" id="correctBtn${idx}">
                                ✅ Correct
                            </button>
                            <button class="btn-incorrect" onclick="markQuestion(${idx}, false)" id="incorrectBtn${idx}">
                                ❌ Incorrect
                            </button>
                            <div class="marks-input-group">
                                <label>Marks:</label>
                                <input type="number" id="qMarks${idx}" class="marks-input" 
                                       min="0" max="${ans.marks || 1}" value="${ans.marksObtained || 0}" 
                                       onchange="updateTotalMarks()">
                                <span>/ ${ans.marks || 1}</span>
                            </div>
                            <div class="remarks-input-group">
                                <input type="text" id="qRemarks${idx}" class="remarks-input" 
                                       placeholder="Remarks (optional)" value="${escapeHtml(ans.remarks || '')}">
                            </div>
                        </div>
                    </div>
                `;
            }).join('');
        } else {
            questionsHtml = '<p class="text-center">No answers found in this submission.</p>';
        }
        
        content.innerHTML = `
            <div class="marking-header">
                <h3>${escapeHtml(sub.examTitle || 'Untitled Exam')}</h3>
                <p><strong>Student:</strong> ${escapeHtml(sub.studentName || 'Unknown')} | <strong>Module:</strong> ${escapeHtml(sub.moduleCode || 'N/A')}</p>
                <p><strong>Submitted:</strong> ${sub.submittedAt?.toDate?.().toLocaleString() || '-'} | 
                   <strong>Reason:</strong> ${sub.submissionReason || 'Manual'}</p>
            </div>
            <hr>
            <div class="marking-questions">
                ${questionsHtml}
            </div>
            <div class="marking-summary">
                <h4>Total Score: <span id="totalMarksDisplay">0</span> / ${sub.totalMarks || 0}</h4>
            </div>
        `;
        
        // Initialize marks display
        setTimeout(updateTotalMarks, 200);
        
    } catch (error) {
        console.error('Error opening marking modal:', error);
        showToast('Failed to load submission: ' + error.message, 'error');
        
        // Close modal on error
        const modal = document.getElementById('examMarkingModal');
        if (modal) {
            modal.classList.remove('active');
            document.body.style.overflow = '';
        }
    }
}

// ============================================
// MARK QUESTION AS CORRECT/INCORRECT
// ============================================
function markQuestion(index, isCorrect) {
    if (!currentMarkingSubmission?.answers) return;
    
    const ans = currentMarkingSubmission.answers[index];
    const marksInput = document.getElementById(`qMarks${index}`);
    
    if (isCorrect) {
        if (marksInput) marksInput.value = ans.marks;
        document.getElementById(`correctBtn${index}`).style.background = '#10b981';
        document.getElementById(`incorrectBtn${index}`).style.background = '';
    } else {
        if (marksInput) marksInput.value = 0;
        document.getElementById(`incorrectBtn${index}`).style.background = '#ef4444';
        document.getElementById(`correctBtn${index}`).style.background = '';
    }
    
    updateTotalMarks();
}

// ============================================
// UPDATE TOTAL MARKS DISPLAY
// ============================================
function updateTotalMarks() {
    if (!currentMarkingSubmission?.answers) return;
    
    let total = 0;
    currentMarkingSubmission.answers.forEach((ans, i) => {
        const marksInput = document.getElementById(`qMarks${i}`);
        if (marksInput) {
            total += parseFloat(marksInput.value) || 0;
        }
    });
    
    const display = document.getElementById('totalMarksDisplay');
    if (display) display.textContent = total;
}

// ============================================
// SAVE EXAM MARKS - FIXED
// ============================================
async function saveExamMarks() {
    if (!currentMarkingSubmission) {
        showToast('No submission to save', 'error');
        return;
    }
    
    const submitBtn = document.querySelector('#examMarkingModal .btn-primary');
    const originalText = submitBtn?.innerHTML;
    
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    }
    
    try {
        const answers = currentMarkingSubmission.answers.map((ans, i) => {
            const marksInput = document.getElementById(`qMarks${i}`);
            const remarksInput = document.getElementById(`qRemarks${i}`);
            
            return {
                ...ans,
                marksObtained: parseFloat(marksInput?.value) || 0,
                remarks: remarksInput?.value || ''
            };
        });
        
        let totalScore = 0;
        answers.forEach(a => totalScore += a.marksObtained || 0);
        
        await db.collection('examSubmissions').doc(currentMarkingSubmission.id).update({
            answers: answers,
            score: totalScore,
            status: 'marked',
            markedBy: currentUser.uid,
            markedByName: currentUser.name || 'Staff',
            markedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ Exam marked successfully!', 'success');
        closeExamMarkingModal();
        
        // Refresh lists
        await loadPendingMarkingList();
        await loadViolationsList();
        
    } catch (error) {
        console.error('Error saving marks:', error);
        showToast('Failed to save marks: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-save"></i> Save Marks & Submit';
        }
    }
}
// ============================================
// CLOSE MARKING MODAL - FIXED
// ============================================
function closeExamMarkingModal() {
    const modal = document.getElementById('examMarkingModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
    currentMarkingSubmission = null;
}

// ============================================
// FILTER & SEARCH EXAMS
// ============================================
function filterExams(type) {
    examFilter = type;
    
    document.querySelectorAll('#staffExams .filter-tab').forEach(btn => btn.classList.remove('active'));
    const activeBtn = document.querySelector(`#staffExams .filter-tab[onclick*="${type}"]`);
    if (activeBtn) activeBtn.classList.add('active');
    
    const filtered = type === 'all' ? allExams : allExams.filter(e => e.categoryType === type);
    renderExamsList(filtered);
}

function searchExams() {
    const searchTerm = document.getElementById('examSearchInput')?.value.toLowerCase() || '';
    let filtered = allExams;
    
    if (examFilter !== 'all') {
        filtered = filtered.filter(e => e.categoryType === examFilter);
    }
    
    if (searchTerm) {
        filtered = filtered.filter(e => 
            e.title?.toLowerCase().includes(searchTerm) ||
            e.moduleCode?.toLowerCase().includes(searchTerm)
        );
    }
    
    renderExamsList(filtered);
}



