// ============================================
// LOAD STAFF MODULES FOR EXAM SELECT
// ============================================
async function loadStaffModulesForSelect() {
    if (!currentUser) return;
    
    try {
        const staffDoc = await db.collection('users').doc(currentUser.uid).get();
        const staffData = staffDoc.data();
        const assignedModules = staffData?.assignedModules || [];
        
        // Store globally for other functions
        staffAssignedModules = assignedModules;
        
        // Populate the exam module select dropdown
        const select = document.getElementById('examModule');
        if (select) {
            select.innerHTML = '<option value="">-- Chagua Module --</option>';
            
            assignedModules.forEach(module => {
                select.innerHTML += `<option value="${module.code}">${module.code} - ${module.name}</option>`;
            });
            
            // If no modules assigned, show a message
            if (assignedModules.length === 0) {
                select.innerHTML = '<option value="">-- Hakuna module ulizopangiwa --</option>';
            }
        }
        
        console.log(`Loaded ${assignedModules.length} modules for staff exam select`);
        
    } catch (error) {
        console.error('Error loading staff modules for select:', error);
        const select = document.getElementById('examModule');
        if (select) {
            select.innerHTML = '<option value="">-- Kosa kupakia moduli --</option>';
        }
    }
}

// ============================================
// LOAD STAFF MODULES (General)
// ============================================
async function loadStaffModules() {
    if (!currentUser) return;
    
    try {
        const staffDoc = await db.collection('users').doc(currentUser.uid).get();
        const modules = staffDoc.data()?.assignedModules || [];
        staffAssignedModules = modules;
        
        // Populate module selects for all forms
        const moduleSelects = [
            { id: 'courseworkModule', source: 'staffAssignedModules' },
            { id: 'examModule', source: 'staffAssignedModules' },
            { id: 'timetableModule', source: 'staffAssignedModules' }
        ];
        
        moduleSelects.forEach(({ id }) => {
            const select = document.getElementById(id);
            if (select) {
                select.innerHTML = '<option value="">-- Chagua Module --</option>';
                modules.forEach(module => {
                    select.innerHTML += `<option value="${module.code}">${module.code} - ${module.name}</option>`;
                });
            }
        });
        
    } catch (error) {
        console.error('Error loading staff modules:', error);
    }
}

// ============================================
// USER EXAM ROOM - LOAD AVAILABLE EXAMS (FIXED - Only Ongoing & Upcoming)
// ============================================
async function loadAvailableExamsForUser() {
    const container = document.getElementById('availableExamsList');
    if (!container || !currentUser) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia mitihani inayopatikana...</div>';
    
    try {
        // Get user data
        const userDoc = await db.collection('users').doc(currentUser.uid).get();
        const userData = userDoc.data();
        const enrolledCourses = userData?.enrolledCourses || [];
        const enrolledModules = userData?.enrolledModules || [];
        
        // Collect all module codes the user has access to
        let userModuleCodes = [];
        
        // Get modules from enrolled courses
        for (const courseId of enrolledCourses) {
            try {
                const modulesSnapshot = await db.collection('modules')
                    .where('courseId', '==', courseId)
                    .where('active', '==', true)
                    .get();
                
                modulesSnapshot.forEach(doc => {
                    const code = doc.data().code;
                    if (code && !userModuleCodes.includes(code)) {
                        userModuleCodes.push(code);
                    }
                });
            } catch(e) {
                console.log('Error fetching modules for course:', courseId, e);
            }
        }
        
        // Add directly enrolled modules
        for (const moduleId of enrolledModules) {
            try {
                const moduleDoc = await db.collection('modules').doc(moduleId).get();
                if (moduleDoc.exists) {
                    const code = moduleDoc.data().code;
                    if (code && !userModuleCodes.includes(code)) {
                        userModuleCodes.push(code);
                    }
                }
            } catch(e) {
                console.log('Error fetching module:', moduleId, e);
            }
        }
        
        console.log('User module codes:', userModuleCodes);
        
        // Get ALL active exams
        const examsSnapshot = await db.collection('examinations').get();
        
        const now = new Date();
        const availableExams = [];
        
        for (const doc of examsSnapshot.docs) {
            const exam = doc.data();
            
            // Skip inactive exams
            if (exam.status !== 'active') continue;
            
            // Only show exams for user's modules
            if (!userModuleCodes.includes(exam.moduleCode)) continue;
            
            // Parse exam date and time
            let examDateTime;
            try {
                examDateTime = exam.examDate?.toDate?.() || new Date(exam.examDate);
            } catch(e) {
                examDateTime = new Date();
            }
            
            const startDateTime = new Date(examDateTime);
            if (exam.startTime) {
                const [hours, minutes] = exam.startTime.split(':').map(Number);
                if (!isNaN(hours) && !isNaN(minutes)) {
                    startDateTime.setHours(hours, minutes, 0, 0);
                }
            }
            
            const endDateTime = new Date(startDateTime);
            if (exam.endTime) {
                const [endH, endM] = exam.endTime.split(':').map(Number);
                if (!isNaN(endH) && !isNaN(endM)) {
                    endDateTime.setHours(endH, endM, 0, 0);
                }
            } else {
                const duration = exam.durationMinutes || 60;
                endDateTime.setMinutes(endDateTime.getMinutes() + duration);
            }
            
            // Check if user already submitted
            let isSubmitted = false;
            
            try {
                const submissionQuery = await db.collection('examSubmissions')
                    .where('examId', '==', doc.id)
                    .where('studentId', '==', currentUser.uid)
                    .get();
                
                isSubmitted = !submissionQuery.empty;
            } catch(e) {
                console.log('Error checking submission:', e);
            }
            
            // ============================================
            // ONLY SHOW: Ongoing OR Upcoming (NOT submitted, NOT marked, NOT past)
            // ============================================
            
            // Skip if already submitted (shows in History)
            if (isSubmitted) continue;
            
            const isOngoing = now >= startDateTime && now <= endDateTime;
            const isUpcoming = now < startDateTime;
            const isPast = now > endDateTime;
            
            // Skip past exams (shows in History)
            if (isPast) continue;
            
            // Only add ongoing or upcoming
            if (isOngoing || isUpcoming) {
                const timeToStart = isUpcoming ? Math.floor((startDateTime - now) / 60000) : 0;
                
                availableExams.push({
                    id: doc.id,
                    ...exam,
                    isOngoing,
                    isUpcoming,
                    isPast: false,
                    isSubmitted: false,
                    examDateTime: startDateTime,
                    endDateTime,
                    timeToStart: timeToStart
                });
            }
        }
        
        if (availableExams.length === 0) {
            container.innerHTML = `
                <div class="empty-state-box">
                    <i class="fas fa-file-alt"></i>
                    <h4>Hakuna Mitihani Inayopatikana</h4>
                    <p>Hakuna mitihani inayoendelea au inayokuja kwa sasa.</p>
                    <p class="hint">Mitihani iliyopita na uliyofanya itaonekana kwenye Historia ya Mitihani hapa chini.</p>
                </div>`;
            return;
        }
        
        // Sort: ongoing first, then upcoming
        availableExams.sort((a, b) => {
            if (a.isOngoing && !b.isOngoing) return -1;
            if (!a.isOngoing && b.isOngoing) return 1;
            return a.examDateTime - b.examDateTime;
        });
        
        const typeLabels = {
            'test1': 'Test 1', 'test2': 'Test 2', 
            'midterm': 'Midterm Examination', 'final': 'Final Examination',
            'assessment': 'Assessment', 'quiz': 'Quiz'
        };
        
        container.innerHTML = `
            <div class="table-wrapper">
                <table class="data-table">
                    <thead>
                        <tr>
                            <th width="50">#</th>
                            <th>Jina la Mtihani</th>
                            <th width="100">Module</th>
                            <th width="100">Aina</th>
                            <th width="110">Tarehe</th>
                            <th width="120">Muda</th>
                            <th width="130">Status</th>
                            <th width="130">Kitendo</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${availableExams.map((exam, idx) => {
                            let statusBadge = '';
                            let actionButton = '';
                            
                            if (exam.isOngoing) {
                                statusBadge = '<span class="status-badge status-ongoing">🟢 Inaendelea</span>';
                                actionButton = `<button class="btn-start-exam" onclick="startExam('${exam.id}')"><i class="fas fa-play"></i> Anza Mtihani</button>`;
                            } else if (exam.isUpcoming) {
                                let timeText = '';
                                if (exam.timeToStart < 60) {
                                    timeText = `Anaanza baada ya dakika ${exam.timeToStart}`;
                                } else if (exam.timeToStart < 1440) {
                                    timeText = `Anaanza baada ya saa ${Math.floor(exam.timeToStart / 60)}`;
                                } else {
                                    timeText = `Anaanza ${exam.examDateTime.toLocaleDateString('sw-TZ', {month:'short', day:'numeric'})}`;
                                }
                                statusBadge = '<span class="status-badge status-pending">⏰ Inakuja</span>';
                                actionButton = `<small class="text-muted">${timeText}</small>`;
                            }
                            
                            return `
                                <tr class="${exam.isOngoing ? 'exam-ongoing-row' : ''}">
                                    <td class="text-center">${idx + 1}</td>
                                    <td><strong>${escapeHtml(exam.title || 'Untitled')}</strong></td>
                                    <td><span class="module-tag">${escapeHtml(exam.moduleCode || 'N/A')}</span></td>
                                    <td><span class="type-badge type-${exam.categoryType || 'quiz'}">${typeLabels[exam.categoryType] || exam.categoryType || 'Quiz'}</span></td>
                                    <td>${exam.examDateTime.toLocaleDateString('sw-TZ', {year:'numeric', month:'short', day:'numeric'})}</td>
                                    <td>${exam.startTime || '?'} - ${exam.endTime || '?'}</td>
                                    <td>${statusBadge}</td>
                                    <td class="text-center">${actionButton}</td>
                                </tr>
                            `;
                        }).join('')}
                    </tbody>
                </table>
            </div>
            
            <div class="exam-legend">
                <span><span class="status-badge status-ongoing">🟢 Inaendelea</span> = Fungua sasa kufanya mtihani</span>
                <span><span class="status-badge status-pending">⏰ Inakuja</span> = Subiri kuanza</span>
            </div>`;
        
    } catch (error) {
        console.error('Error loading available exams:', error);
        container.innerHTML = `
            <div class="empty-state-box error">
                <i class="fas fa-exclamation-triangle"></i>
                <h4>Imeshindwa Kupakia Mitihani</h4>
                <p>${error.message || 'Tafadhali jaribu tena baadaye.'}</p>
                <button class="btn-retry" onclick="loadAvailableExamsForUser()">
                    <i class="fas fa-redo"></i> Jaribu Tena
                </button>
            </div>`;
    }
}

// ============================================
// VIEW EXAM SUBMISSION (UPDATED)
// ============================================
async function viewExamSubmission(submissionId) {
    try {
        // Find the submission - first check if it was passed directly
        let sub = null;
        
        if (submissionId) {
            const doc = await db.collection('examSubmissions').doc(submissionId).get();
            if (doc.exists) {
                sub = { id: doc.id, ...doc.data() };
            }
        }
        
        if (!sub) {
            // Try to find submission for current exam
            const currentExamId = currentTakingExam?.id;
            if (currentExamId && currentUser) {
                const snapshot = await db.collection('examSubmissions')
                    .where('examId', '==', currentExamId)
                    .where('studentId', '==', currentUser.uid)
                    .get();
                
                if (!snapshot.empty) {
                    sub = { id: snapshot.docs[0].id, ...snapshot.docs[0].data() };
                }
            }
        }
        
        if (!sub) {
            showToast('Submission not found', 'error');
            return;
        }
        
        const score = sub.score !== undefined ? sub.score : 'Not marked yet';
        const total = sub.totalMarks || '-';
        const isMarked = sub.status === 'marked';
        
        let answersHtml = '';
        if (sub.answers && sub.answers.length > 0) {
            answersHtml = sub.answers.map((ans, idx) => {
                let answerDisplay = '';
                
                if (Array.isArray(ans.answer)) {
                    answerDisplay = ans.answer.map((a, i) => `${i + 1}. ${a || '<em>No answer</em>'}`).join('<br>');
                } else {
                    answerDisplay = ans.answer || '<em>No answer provided</em>';
                }
                
                const isCorrect = ans.marksObtained !== undefined && ans.marksObtained >= ans.marks;
                const isPartial = ans.marksObtained !== undefined && ans.marksObtained > 0 && ans.marksObtained < ans.marks;
                const isWrong = ans.marksObtained !== undefined && ans.marksObtained === 0;
                
                let resultBadge = '';
                if (isCorrect) {
                    resultBadge = '<span class="result-badge correct">✅ Correct</span>';
                } else if (isPartial) {
                    resultBadge = '<span class="result-badge partial">⚠️ Partial</span>';
                } else if (isWrong) {
                    resultBadge = '<span class="result-badge wrong">❌ Incorrect</span>';
                }
                
                return `
                    <div class="answer-item ${isCorrect ? 'correct' : isWrong ? 'wrong' : ''}">
                        <div class="answer-header">
                            <h5>Q${idx + 1}: ${escapeHtml(ans.question)}</h5>
                            <span class="q-marks-badge">[${ans.marks} marks]</span>
                        </div>
                        <div class="answer-body">
                            <p><strong>Your Answer:</strong></p>
                            <div class="student-answer-box">${answerDisplay}</div>
                        </div>
                        ${isMarked ? `
                        <div class="answer-result">
                            ${resultBadge}
                            <span class="marks-obtained"><strong>Marks:</strong> ${ans.marksObtained || 0}/${ans.marks}</span>
                            ${ans.remarks ? `<p class="remarks"><strong>Remarks:</strong> ${escapeHtml(ans.remarks)}</p>` : ''}
                        </div>
                        ` : '<p class="pending-note"><i class="fas fa-clock"></i> Waiting for marking...</p>'}
                    </div>
                `;
            }).join('');
        } else {
            answersHtml = '<p class="text-center">No answers found</p>';
        }
        
        const modal = document.getElementById('examQuestionModal');
        const content = document.getElementById('examQuestionModalContent');
        
        if (modal && content) {
            content.innerHTML = `
                <div class="submission-view">
                    <div class="submission-header">
                        <h3>${escapeHtml(sub.examTitle)}</h3>
                        <span class="status-badge ${isMarked ? 'status-active' : 'status-pending'}">${isMarked ? 'Imesahihishwa' : 'Inasubiri Kuhahihishwa'}</span>
                    </div>
                    
                    <div class="submission-meta">
                        <div class="meta-item"><i class="fas fa-user"></i> ${escapeHtml(sub.studentName)}</div>
                        <div class="meta-item"><i class="fas fa-book"></i> ${escapeHtml(sub.moduleCode)}</div>
                        <div class="meta-item"><i class="fas fa-star"></i> Score: <strong>${score}/${total}</strong></div>
                        <div class="meta-item"><i class="fas fa-calendar"></i> ${sub.submittedAt?.toDate?.().toLocaleString('sw-TZ') || '-'}</div>
                        ${sub.submissionReason ? `<div class="meta-item"><i class="fas fa-info-circle"></i> Reason: ${sub.submissionReason}</div>` : ''}
                    </div>
                    
                    <hr>
                    
                    <h4>Your Answers</h4>
                    <div class="answers-list">
                        ${answersHtml}
                    </div>
                </div>
            `;
            
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        }
        
    } catch (error) {
        console.error('Error viewing submission:', error);
        showToast('Error loading submission: ' + error.message, 'error');
    }
}

// ============================================
// USER EXAM HISTORY - SHOWS ALL SUBMITTED/MARKED/EXPIRED EXAMS
// ============================================
async function loadExamHistoryForUser() {
    const container = document.getElementById('examHistoryList');
    if (!container || !currentUser) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia historia ya mitihani...</div>';
    
    try {
        // Get all submissions
        const submissionsSnapshot = await db.collection('examSubmissions')
            .where('studentId', '==', currentUser.uid)
            .get();
        
        const submissions = [];
        submissionsSnapshot.forEach(doc => {
            submissions.push({ id: doc.id, ...doc.data() });
        });
        
        // Also check for past exams that were never taken (expired)
        const userDoc = await db.collection('users').doc(currentUser.uid).get();
        const userData = userDoc.data();
        const enrolledCourses = userData?.enrolledCourses || [];
        const enrolledModules = userData?.enrolledModules || [];
        
        let userModuleCodes = [];
        for (const courseId of enrolledCourses) {
            const modulesSnapshot = await db.collection('modules')
                .where('courseId', '==', courseId)
                .where('active', '==', true)
                .get();
            modulesSnapshot.forEach(doc => {
                const code = doc.data().code;
                if (code && !userModuleCodes.includes(code)) userModuleCodes.push(code);
            });
        }
        for (const moduleId of enrolledModules) {
            const moduleDoc = await db.collection('modules').doc(moduleId).get();
            if (moduleDoc.exists) {
                const code = moduleDoc.data().code;
                if (code && !userModuleCodes.includes(code)) userModuleCodes.push(code);
            }
        }
        
        // Get submitted exam IDs
        const submittedExamIds = submissions.map(s => s.examId);
        
        // Find past exams not submitted
        const now = new Date();
        const allExamsSnapshot = await db.collection('examinations').get();
        
        allExamsSnapshot.forEach(doc => {
            const exam = doc.data();
            if (exam.status !== 'active') return;
            if (!userModuleCodes.includes(exam.moduleCode)) return;
            if (submittedExamIds.includes(doc.id)) return;
            
            // Check if expired
            let examDateTime = exam.examDate?.toDate?.() || new Date(exam.examDate);
            const endDateTime = new Date(examDateTime);
            if (exam.endTime) {
                const [endH, endM] = exam.endTime.split(':').map(Number);
                if (!isNaN(endH) && !isNaN(endM)) endDateTime.setHours(endH, endM, 0, 0);
            } else {
                endDateTime.setMinutes(endDateTime.getMinutes() + (exam.durationMinutes || 60));
            }
            
            if (now > endDateTime) {
                // Expired exam - add to history
                submissions.push({
                    id: 'expired_' + doc.id,
                    examTitle: exam.title,
                    moduleCode: exam.moduleCode,
                    status: 'expired',
                    score: 0,
                    totalMarks: exam.totalMarks || 100,
                    submittedAt: endDateTime,
                    submissionReason: 'expired',
                    examId: doc.id
                });
            }
        });
        
        // Sort by date descending
        submissions.sort((a, b) => {
            const dateA = a.submittedAt?.toDate?.() || new Date(a.submittedAt || 0);
            const dateB = b.submittedAt?.toDate?.() || new Date(b.submittedAt || 0);
            return dateB - dateA;
        });
        
        if (submissions.length === 0) {
            container.innerHTML = `
                <div class="empty-state-box">
                    <i class="fas fa-history"></i>
                    <h4>Hakuna Historia ya Mitihani</h4>
                    <p>Hujafanya mtihani wowote bado.</p>
                    <p class="hint">Mitihani uliyofanya itaonekana hapa pamoja na matokeo.</p>
                </div>`;
            return;
        }
        
        container.innerHTML = `
            <h4 style="margin-bottom:1rem;">
                <i class="fas fa-history"></i> Historia ya Mitihani (${submissions.length})
            </h4>
            <div class="table-wrapper">
                <table class="data-table">
                    <thead>
                        <tr>
                            <th width="50">#</th>
                            <th>Mtihani</th>
                            <th width="100">Module</th>
                            <th width="100">Alama</th>
                            <th width="80">Daraja</th>
                            <th width="120">Status</th>
                            <th width="120">Tarehe</th>
                            <th width="100">Kitendo</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${submissions.map((sub, idx) => {
                            const score = sub.score !== undefined ? sub.score : '-';
                            const total = sub.totalMarks || '-';
                            const percentage = (total !== '-' && score !== '-') ? 
                                ((parseFloat(score) / parseFloat(total)) * 100).toFixed(1) : '-';
                            
                            // Calculate grade
                            let grade = '-';
                            let gradeClass = '';
                            if (percentage !== '-') {
                                const pct = parseFloat(percentage);
                                if (pct >= 80) { grade = 'A'; gradeClass = 'grade-a'; }
                                else if (pct >= 70) { grade = 'B'; gradeClass = 'grade-b'; }
                                else if (pct >= 60) { grade = 'C'; gradeClass = 'grade-c'; }
                                else if (pct >= 50) { grade = 'D'; gradeClass = 'grade-d'; }
                                else { grade = 'F'; gradeClass = 'grade-f'; }
                            }
                            
                            // Status display
                            let statusClass = 'status-pending';
                            let statusText = 'Inasubiri';
                            
                            if (sub.status === 'marked') {
                                statusClass = 'status-active';
                                statusText = '✓ Imesahihishwa';
                            } else if (sub.status === 'remarked') {
                                statusClass = 'status-remarked';
                                statusText = '🔄 Imesahihishwa Upya';
                            } else if (sub.status === 'submitted') {
                                statusClass = 'status-submitted';
                                statusText = 'Imewasilishwa';
                            } else if (sub.status === 'auto_submitted') {
                                statusClass = 'status-warning';
                                statusText = '⚠ Auto';
                            } else if (sub.status === 'expired') {
                                statusClass = 'status-inactive';
                                statusText = '❌ Muda Umeisha';
                            }
                            
                            const date = sub.submittedAt?.toDate?.()?.toLocaleDateString('sw-TZ', {
                                year: 'numeric', month: 'short', day: 'numeric',
                                hour: '2-digit', minute: '2-digit'
                            }) || (sub.submittedAt ? new Date(sub.submittedAt).toLocaleDateString('sw-TZ') : '-');
                            
                            const showMarks = (sub.status === 'marked' || sub.status === 'remarked');
                            const canView = sub.status !== 'expired';
                            
                            return `
                                <tr class="${showMarks ? 'has-results' : ''}">
                                    <td class="text-center">${idx + 1}</td>
                                    <td><strong>${escapeHtml(sub.examTitle || 'Unknown')}</strong></td>
                                    <td><span class="module-tag">${escapeHtml(sub.moduleCode || '-')}</span></td>
                                    <td class="text-center">
                                        ${showMarks ? 
                                            `<strong>${score}/${total}</strong><br><small>${percentage}%</small>` : 
                                            sub.status === 'expired' ? '<span class="text-muted">-</span>' : '<span class="text-muted">-</span>'}
                                    </td>
                                    <td class="text-center">
                                        ${showMarks ? 
                                            `<span class="grade-badge ${gradeClass}">${grade}</span>` : 
                                            '<span class="text-muted">-</span>'}
                                    </td>
                                    <td><span class="status-badge ${statusClass}">${statusText}</span></td>
                                    <td>${date}</td>
                                    <td class="text-center">
                                        ${canView ? 
                                            `<button class="btn-view btn-sm" onclick="viewExamResults('${sub.id}')">
                                                <i class="fas fa-eye"></i> ${showMarks ? 'Matokeo' : 'Tazama'}
                                            </button>` : 
                                            '<small class="text-muted">-</small>'}
                                    </td>
                                </tr>
                            `;
                        }).join('')}
                    </tbody>
                </table>
            </div>
        `;
        
    } catch (error) {
        console.error('Error loading exam history:', error);
        container.innerHTML = `
            <div class="empty-state-box error">
                <i class="fas fa-exclamation-triangle"></i>
                <h4>Imeshindwa Kupakia Historia</h4>
                <p>${error.message || 'Unknown error'}</p>
                <button class="btn-retry" onclick="loadExamHistoryForUser()">
                    <i class="fas fa-redo"></i> Jaribu Tena
                </button>
            </div>`;
    }
}

// ============================================
// VIEW EXAM RESULTS (For Student)
// ============================================
async function viewExamResults(submissionId) {
    try {
        const doc = await db.collection('examSubmissions').doc(submissionId).get();
        if (!doc.exists) {
            showToast('Matokeo hayakupatikana', 'error');
            return;
        }
        
        const sub = { id: doc.id, ...doc.data() };
        const isMarked = sub.status === 'marked' || sub.status === 'remarked';
        const score = sub.score !== undefined ? sub.score : '-';
        const total = sub.totalMarks || '-';
        const percentage = (total !== '-' && score !== '-') ? 
            ((parseFloat(score) / parseFloat(total)) * 100).toFixed(1) : '-';
        
        let grade = '-';
        if (percentage !== '-') {
            const pct = parseFloat(percentage);
            if (pct >= 80) grade = 'A';
            else if (pct >= 70) grade = 'B';
            else if (pct >= 60) grade = 'C';
            else if (pct >= 50) grade = 'D';
            else grade = 'F';
        }
        
        const content = document.getElementById('examResultsContent');
        if (!content) return;
        
        content.innerHTML = `
            <div class="results-header">
                <h3>${escapeHtml(sub.examTitle)}</h3>
                <p><strong>Module:</strong> ${escapeHtml(sub.moduleCode)}</p>
                <p><strong>Imewasilishwa:</strong> ${sub.submittedAt?.toDate?.().toLocaleString('sw-TZ') || '-'}</p>
            </div>
            
            ${isMarked ? `
            <div class="results-score-card">
                <div class="score-display-large">
                    <div class="score-number">${score}/${total}</div>
                    <div class="score-percentage">${percentage}%</div>
                    <div class="score-grade">Daraja: ${grade}</div>
                </div>
                ${sub.remarkedAt ? `
                <div class="remarked-notice">
                    <i class="fas fa-info-circle"></i> Imesahihishwa upya tarehe: ${sub.remarkedAt?.toDate?.().toLocaleString('sw-TZ') || '-'}
                </div>
                ` : ''}
            </div>
            ` : `
            <div class="pending-results">
                <i class="fas fa-clock"></i>
                <p>Matokeo bado hayajatolewa. Subiri mwalimu asahihishe.</p>
            </div>
            `}
            
            ${isMarked ? `
            <h4>Majibu Yako</h4>
            <div class="answers-review-list">
                ${sub.answers?.map((ans, idx) => {
                    let answerDisplay = '';
                    if (Array.isArray(ans.answer)) {
                        answerDisplay = ans.answer.map((a, i) => `${i + 1}. ${a || '<em>Hakuna jibu</em>'}`).join('<br>');
                    } else {
                        answerDisplay = ans.answer || '<em>Hakuna jibu</em>';
                    }
                    
                    const isCorrect = ans.marksObtained !== undefined && ans.marksObtained >= ans.marks;
                    const isPartial = ans.marksObtained !== undefined && ans.marksObtained > 0 && ans.marksObtained < ans.marks;
                    const isWrong = ans.marksObtained !== undefined && ans.marksObtained === 0;
                    
                    let resultClass = '';
                    let resultIcon = '';
                    if (isCorrect) { resultClass = 'correct'; resultIcon = '✅'; }
                    else if (isPartial) { resultClass = 'partial'; resultIcon = '⚠️'; }
                    else if (isWrong) { resultClass = 'wrong'; resultIcon = '❌'; }
                    
                    return `
                        <div class="answer-item ${resultClass}">
                            <div class="answer-header">
                                <span class="q-num">Q${idx + 1}</span>
                                <span class="result-icon">${resultIcon}</span>
                                <span class="marks-badge">${ans.marksObtained || 0}/${ans.marks}</span>
                            </div>
                            <p class="q-text">${escapeHtml(ans.question)}</p>
                            <div class="your-answer">
                                <strong>Jibu lako:</strong>
                                <div class="answer-box">${answerDisplay}</div>
                            </div>
                            ${ans.remarks ? `<p class="remarks"><strong>Maoni:</strong> ${escapeHtml(ans.remarks)}</p>` : ''}
                        </div>
                    `;
                }).join('')}
            </div>
            ` : ''}
        `;
        
        document.getElementById('examResultsModal').classList.add('active');
        document.body.style.overflow = 'hidden';
        
    } catch (error) {
        console.error('Error viewing results:', error);
        showToast('Error: ' + error.message, 'error');
    }
}

function closeExamResultsModal() {
    document.getElementById('examResultsModal').classList.remove('active');
    document.body.style.overflow = '';
}

