// ============================================
// START EXAM - Open Exam Taking Interface
// ============================================
async function startExam(examId) {
    try {
        // Get exam data
        const examDoc = await db.collection('examinations').doc(examId).get();
        if (!examDoc.exists) {
            showToast('Exam not found', 'error');
            return;
        }
        
        const exam = examDoc.data();
        currentTakingExam = { id: examDoc.id, ...exam };
        
        // Check if already submitted
        const submissionQuery = await db.collection('examSubmissions')
            .where('examId', '==', examId)
            .where('studentId', '==', currentUser.uid)
            .get();
        
        if (!submissionQuery.empty) {
            showToast('You have already submitted this exam', 'warning');
            return;
        }
        
        // Check if exam is ongoing
        const now = new Date();
        const examDate = exam.examDate?.toDate?.() || new Date(exam.examDate);
        const startDateTime = new Date(examDate);
        
        if (exam.startTime) {
            const [hours, minutes] = exam.startTime.split(':').map(Number);
            startDateTime.setHours(hours, minutes, 0, 0);
        }
        
        const endDateTime = new Date(startDateTime);
        if (exam.endTime) {
            const [endH, endM] = exam.endTime.split(':').map(Number);
            endDateTime.setHours(endH, endM, 0, 0);
        } else {
            const duration = exam.durationMinutes || 60;
            endDateTime.setMinutes(endDateTime.getMinutes() + duration);
        }
        
        if (now < startDateTime) {
            showToast(`Exam starts at ${startDateTime.toLocaleString()}`, 'warning');
            return;
        }
        
        if (now > endDateTime) {
            showToast('Exam time has expired', 'error');
            return;
        }
        
        // Set up the exam modal
        const modalTitle = document.getElementById('examModalTitle');
        const modalModule = document.getElementById('examModalModule');
        
        if (modalTitle) modalTitle.textContent = exam.title || 'Examination';
        if (modalModule) modalModule.textContent = `Module: ${exam.moduleCode || 'N/A'}`;
        
        // Calculate remaining time
        const remainingMinutes = Math.floor((endDateTime - now) / 60000);
        examEndTime = endDateTime;
        
        // Update total questions count
        const totalQ = exam.questions?.length || 0;
        document.getElementById('totalQuestions').textContent = totalQ;
        document.getElementById('answeredCount').textContent = '0';
        
        // Start timer
        updateExamTimer();
        examTimerInterval = setInterval(updateExamTimer, 1000);
        
        // Render questions
        renderExamQuestions(exam.questions || []);
        
        // Show the exam modal
        const modal = document.getElementById('examTakingModal');
        if (modal) {
            modal.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
        
        // Setup anti-cheat measures
        setupExamAntiCheat();
        
        // Show exam instructions if available
        if (exam.instructions) {
            setTimeout(() => {
                showToast('📋 Read instructions carefully before starting!', 'info');
            }, 1000);
        }
        
        console.log('Exam started:', exam.title, 'Remaining:', remainingMinutes, 'minutes');
        
    } catch (error) {
        console.error('Error starting exam:', error);
        showToast('Failed to start exam: ' + error.message, 'error');
    }
}


// ============================================
// RENDER EXAM QUESTIONS
// ============================================
function renderExamQuestions(questions) {
    const container = document.getElementById('examContent');
    if (!container) return;
    
    if (!questions || questions.length === 0) {
        container.innerHTML = '<p class="text-center">No questions available for this exam.</p>';
        return;
    }
    
    container.innerHTML = questions.map((q, idx) => {
        let answerHtml = '';
        
        switch(q.type) {
            case 'multiple_choice':
                answerHtml = `
                    <div class="mcq-options">
                        ${(q.options || ['A', 'B', 'C', 'D']).map(opt => `
                            <label class="mcq-option">
                                <input type="radio" name="q_${q.id}" value="${escapeHtml(opt)}" 
                                       onchange="updateAnswerProgress()">
                                <span class="option-letter">${escapeHtml(opt)}</span>
                            </label>
                        `).join('')}
                    </div>`;
                break;
                
            case 'matching':
                answerHtml = `
                    <div class="matching-answer">
                        <table class="mini-table">
                            <thead>
                                <tr>
                                    <th width="50">#</th>
                                    <th>Section A</th>
                                    <th>Your Answer (Section B)</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${(q.matchingPairs || []).map((pair, i) => `
                                    <tr>
                                        <td class="text-center">${i + 1}</td>
                                        <td>${escapeHtml(pair.a || '')}</td>
                                        <td>
                                            <input type="text" class="matching-answer-input" 
                                                   data-qid="${q.id}" data-pair="${i}" 
                                                   placeholder="Enter match from B" 
                                                   onchange="updateAnswerProgress()">
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                        <div class="section-b-list" style="margin-top:1rem;">
                            <p><strong>Section B (Options):</strong></p>
                            <div class="section-b-items">
                                ${(q.matchingPairs || []).map((pair, i) => `
                                    <span class="section-b-item">${i + 1}. ${escapeHtml(pair.b || '')}</span>
                                `).join('')}
                            </div>
                        </div>
                    </div>`;
                break;
                
            case 'short_answer':
                answerHtml = `
                    <textarea class="exam-textarea" data-qid="${q.id}" 
                              placeholder="Andika jibu lako hapa..." 
                              maxlength="${q.wordLimit || 100}" 
                              onchange="updateAnswerProgress()" 
                              oninput="updateCharCount(this, ${q.wordLimit || 100})"
                              rows="4"></textarea>
                    <small class="char-count" id="charCount_${q.id}">Max ${q.wordLimit || 100} characters</small>`;
                break;
                
            case 'essay':
                answerHtml = `
                    <textarea class="exam-textarea" data-qid="${q.id}" 
                              placeholder="Andika insha yako hapa..." 
                              style="min-height:200px;" 
                              onchange="updateAnswerProgress()" 
                              rows="8"></textarea>
                    <small class="char-count">Expected: ${q.essayWordLimit || 500} words</small>`;
                break;
                
            case 'picture_based':
                answerHtml = `
                    ${q.imageUrl ? `
                        <div class="exam-image-container">
                            <img src="${q.imageUrl}" alt="Question Image" class="exam-question-image" 
                                 onerror="this.src='https://via.placeholder.com/400x200?text=Image+Not+Found'">
                        </div>
                    ` : '<p class="text-muted">No image provided</p>'}
                    <div class="mcq-options">
                        ${(q.pictureOptions || q.options || ['A', 'B', 'C', 'D']).map(opt => `
                            <label class="mcq-option">
                                <input type="radio" name="q_${q.id}" value="${escapeHtml(opt)}" 
                                       onchange="updateAnswerProgress()">
                                <span class="option-letter">${escapeHtml(opt)}</span>
                            </label>
                        `).join('')}
                    </div>`;
                break;
        }
        
        return `
            <div class="exam-question-item" id="exam-q-${q.id}">
                <div class="exam-q-header">
                    <span class="exam-q-number">Question ${idx + 1}</span>
                    <span class="exam-q-marks">[${q.marks || 1} marks]</span>
                </div>
                <div class="exam-q-text">${escapeHtml(q.question || 'No question text')}</div>
                ${answerHtml}
            </div>
        `;
    }).join('');
    
    document.getElementById('totalQuestions').textContent = questions.length;
    document.getElementById('examProgressFill').style.width = '0%';
}


// ============================================
// UPDATE EXAM TIMER
// ============================================
function updateExamTimer() {
    if (!examEndTime) return;
    
    const now = new Date();
    const remaining = examEndTime - now;
    const timerDisplay = document.getElementById('timerDisplay');
    
    if (remaining <= 0) {
        clearInterval(examTimerInterval);
        if (timerDisplay) timerDisplay.textContent = '00:00';
        showToast('⏰ Time is up! Your exam will be submitted automatically.', 'warning');
        setTimeout(() => autoSubmitExam('time_up'), 2000);
        return;
    }
    
    const hours = Math.floor(remaining / 3600000);
    const minutes = Math.floor((remaining % 3600000) / 60000);
    const seconds = Math.floor((remaining % 60000) / 1000);
    
    let timeStr = '';
    if (hours > 0) {
        timeStr = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    } else {
        timeStr = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }
    
    if (timerDisplay) timerDisplay.textContent = timeStr;
    
    // Change color when time is low
    if (minutes < 5 && hours === 0) {
        if (timerDisplay) timerDisplay.style.color = '#ef4444';
    }
    
    // Warning at 5 minutes
    if (minutes === 5 && seconds === 0 && hours === 0) {
        showToast('⚠️ 5 minutes remaining!', 'warning');
    }
}


// ============================================
// UPDATE CHARACTER COUNT
// ============================================
function updateCharCount(textarea, maxChars) {
    const qId = textarea.getAttribute('data-qid');
    const countEl = document.getElementById(`charCount_${qId}`);
    if (countEl) {
        const remaining = maxChars - textarea.value.length;
        countEl.textContent = `${remaining} characters remaining`;
        if (remaining < 20) {
            countEl.style.color = '#ef4444';
        } else {
            countEl.style.color = '#94a3b8';
        }
    }
}


// ============================================
// UPDATE ANSWER PROGRESS
// ============================================
function updateAnswerProgress() {
    const total = parseInt(document.getElementById('totalQuestions')?.textContent || '0');
    let answered = 0;
    
    document.querySelectorAll('.exam-question-item').forEach(item => {
        const hasRadio = item.querySelector('input[type="radio"]:checked');
        const hasText = item.querySelector('textarea')?.value?.trim();
        const hasInput = item.querySelector('input[type="text"]')?.value?.trim();
        
        if (hasRadio || hasText || hasInput) answered++;
    });
    
    document.getElementById('answeredCount').textContent = answered;
    
    const progressPercent = total > 0 ? (answered / total) * 100 : 0;
    document.getElementById('examProgressFill').style.width = progressPercent + '%';
}


// ============================================
// SETUP ANTI-CHEAT
// ============================================
function setupExamAntiCheat() {
    examViolationDetected = false;
    
    // Detect tab switching / visibility change
    document.addEventListener('visibilitychange', handleVisibilityChange);
    
    // Detect window losing focus
    window.addEventListener('blur', handleWindowBlur);
    
    // Prevent right-click context menu
    document.addEventListener('contextmenu', preventContextMenu);
    
    // Prevent copy/paste
    document.addEventListener('copy', preventAction);
    document.addEventListener('paste', preventAction);
    document.addEventListener('cut', preventAction);
    
    // Prevent keyboard shortcuts for new tab/window
    document.addEventListener('keydown', preventShortcuts);
}

function handleVisibilityChange() {
    if (document.hidden && !examViolationDetected) {
        examViolationDetected = true;
        showToast('⚠️ Screen split detected! Your exam will be submitted.', 'error');
        setTimeout(() => autoSubmitExam('screen_split'), 1500);
    }
}

function handleWindowBlur() {
    if (!examViolationDetected) {
        examViolationDetected = true;
        showToast('⚠️ You left the exam window! Your exam will be submitted.', 'error');
        setTimeout(() => autoSubmitExam('window_blur'), 1500);
    }
}

function preventContextMenu(e) {
    e.preventDefault();
    return false;
}

function preventAction(e) {
    e.preventDefault();
    showToast('Copy/Paste is not allowed during exam', 'warning');
    return false;
}

function preventShortcuts(e) {
    // Block Ctrl+N, Ctrl+T, Ctrl+W, Ctrl+Shift+N, Ctrl+Shift+T
    if ((e.ctrlKey || e.metaKey) && 
        (e.key === 'n' || e.key === 't' || e.key === 'w' || e.key === 'N' || e.key === 'T' || e.key === 'W')) {
        e.preventDefault();
        if (!examViolationDetected) {
            examViolationDetected = true;
            showToast('⚠️ Attempted to open new tab/window! Exam will be submitted.', 'error');
            setTimeout(() => autoSubmitExam('keyboard_shortcut'), 1500);
        }
        return false;
    }
}


// ============================================
// CLEANUP EXAM LISTENERS
// ============================================
function cleanupExamListeners() {
    document.removeEventListener('visibilitychange', handleVisibilityChange);
    window.removeEventListener('blur', handleWindowBlur);
    document.removeEventListener('contextmenu', preventContextMenu);
    document.removeEventListener('copy', preventAction);
    document.removeEventListener('paste', preventAction);
    document.removeEventListener('cut', preventAction);
    document.removeEventListener('keydown', preventShortcuts);
}


// ============================================
// AUTO SUBMIT EXAM - FIXED
// ============================================
async function autoSubmitExam(reason) {
    if (!currentTakingExam) return;
    
    // Clear timer and listeners
    if (examTimerInterval) {
        clearInterval(examTimerInterval);
        examTimerInterval = null;
    }
    cleanupExamListeners();
    
    // Close the exam modal
    const modal = document.getElementById('examTakingModal');
    if (modal) {
        modal.style.display = 'none';
        document.body.style.overflow = '';
    }
    
    // Submit the exam data
    await submitExamData(reason);
    
    // Show message based on reason
    const messages = {
        'time_up': '⏰ Muda wako umeisha! Mtihani umewasilishwa kiotomatiki.',
        'screen_split': '⚠️ Umegundulika kugawa skrini! Mtihani umewasilishwa.',
        'window_blur': '⚠️ Umetoka kwenye dirisha la mtihani! Mtihani umewasilishwa.',
        'keyboard_shortcut': '⚠️ Umejaribu kufungua kichupo kipya! Mtihani umewasilishwa.'
    };
    
    showToast(messages[reason] || 'Mtihani umewasilishwa kiotomatiki.', 'warning');
    
    // Refresh exam lists
    setTimeout(() => {
        if (typeof loadAvailableExamsForUser === 'function') {
            loadAvailableExamsForUser();
        }
        if (typeof loadExamHistoryForUser === 'function') {
            loadExamHistoryForUser();
        }
    }, 500);
}
