async function submitExam() {
    if (!confirm('Are you sure you want to submit your exam? You cannot undo this action.')) return;
    
    clearInterval(examTimerInterval);
    cleanupExamListeners();
    
    await submitExamData('manual');
}


// ============================================
// SUBMIT EXAM DATA
// ============================================
async function submitExamData(reason) {
    if (!currentTakingExam || !currentUser) return;
    
    try {
        const answers = [];
        const questions = currentTakingExam.questions || [];
        
        questions.forEach(q => {
            const questionElement = document.getElementById(`exam-q-${q.id}`);
            let answer = null;
            
            if (q.type === 'multiple_choice' || q.type === 'picture_based') {
                const selected = questionElement?.querySelector('input[type="radio"]:checked');
                answer = selected ? selected.value : null;
            } else if (q.type === 'matching') {
                const matchingAnswers = [];
                questionElement?.querySelectorAll('.matching-answer-input').forEach(input => {
                    matchingAnswers.push(input.value || '');
                });
                answer = matchingAnswers;
            } else {
                const textarea = questionElement?.querySelector('textarea');
                answer = textarea ? textarea.value : null;
            }
            
            answers.push({
                questionId: q.id,
                question: q.question,
                type: q.type,
                answer: answer,
                marks: q.marks || 1,
                correctAnswer: q.correctAnswer || q.pictureCorrectAnswer || '',
                marksObtained: 0,
                remarks: ''
            });
        });
        
        const submissionData = {
            examId: currentTakingExam.id,
            examTitle: currentTakingExam.title,
            moduleCode: currentTakingExam.moduleCode,
            studentId: currentUser.uid,
            studentName: currentUser.name || currentUser.email,
            studentEmail: currentUser.email,
            answers: answers,
            submissionReason: reason,
            submittedAt: firebase.firestore.FieldValue.serverTimestamp(),
            status: reason === 'manual' ? 'submitted' : 'auto_submitted',
            totalMarks: currentTakingExam.totalMarks || answers.reduce((s, a) => s + a.marks, 0)
        };
        
        await db.collection('examSubmissions').add(submissionData);
        
        // Hide modal
        const modal = document.getElementById('examTakingModal');
        if (modal) {
            modal.style.display = 'none';
            document.body.style.overflow = '';
        }
        
        showToast('✅ Exam submitted successfully!', 'success');
        
        // Refresh exam lists
        if (typeof loadAvailableExamsForUser === 'function') {
            loadAvailableExamsForUser();
        }
        if (typeof loadExamHistoryForUser === 'function') {
            loadExamHistoryForUser();
        }
        
    } catch (error) {
        console.error('Error submitting exam:', error);
        showToast('Failed to submit exam: ' + error.message, 'error');
    }
    
    // Reset exam state
    currentTakingExam = null;
    examEndTime = null;
    examTimerInterval = null;
}

