// STAFF - LOAD MARKED EXAMINATIONS
// ============================================
let allMarkedExams = [];
let markedExamFilter = 'all';

// ============================================
// LOAD MARKED EXAMS - FILTERED BY CURRENT STAFF
// Only shows exams marked by this staff member
// ============================================
async function loadMarkedExams() {
    const container = document.getElementById('markedExamsList');
    if (!container) {
        console.error('markedExamsList container not found');
        return;
    }
    
    if (!currentUser) {
        container.innerHTML = '<div class="empty-state"><p>Hakuna mtumiaji aliyeingia</p></div>';
        return;
    }
    
    container.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> Inapakia mitihani uliyosahihisha...</div>';
    
    try {
        // ============================================
        // FILTER: Only show exams marked by THIS staff member
        // AND marked or remarked status
        // ============================================
        const snapshot = await db.collection('examSubmissions')
            .where('markedBy', '==', currentUser.uid)
            .get();
        
        allMarkedExams = [];
        snapshot.forEach(doc => {
            const data = doc.data();
            // Only include marked or remarked
            if (data.status === 'marked' || data.status === 'remarked') {
                allMarkedExams.push({ id: doc.id, ...data });
            }
        });
        
        // Sort by marked date (newest first)
        allMarkedExams.sort((a, b) => {
            const dateA = a.markedAt?.toDate?.() || new Date(0);
            const dateB = b.markedAt?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        // Update count badge
        const countEl = document.getElementById('markedExamsCount');
        if (countEl) {
            countEl.textContent = `Jumla: ${allMarkedExams.length} Mitihani (Yangu Pekee)`;
        }
        
        if (allMarkedExams.length === 0) {
            container.innerHTML = `
                <div class="empty-state">
                    <i class="fas fa-check-circle"></i>
                    <p>Hakuna mitihani uliyosahihisha bado</p>
                    <small>Mitihani utakayosahihisha itaonekana hapa</small>
                </div>`;
            return;
        }
        
        renderMarkedExamsList(allMarkedExams);
        
        console.log(`✅ Loaded ${allMarkedExams.length} marked exams for staff: ${currentUser.name}`);
        
    } catch (error) {
        console.error('Error loading marked exams:', error);
        container.innerHTML = `<p class="error-text">Kosa: ${error.message}</p>`;
    }
}

function renderMarkedExamsList(exams) {
    const container = document.getElementById('markedExamsList');
    if (!container) return;
    
    if (exams.length === 0) {
        container.innerHTML = '<p class="text-center">Hakuna matokeo yanayolingana</p>';
        return;
    }
    
    container.innerHTML = exams.map((sub, index) => {
        const studentName = sub.studentName || 'Unknown';
        const examTitle = sub.examTitle || 'Unknown Exam';
        const moduleCode = sub.moduleCode || 'N/A';
        const score = sub.score !== undefined ? sub.score : 0;
        const totalMarks = sub.totalMarks || 100;
        const percentage = totalMarks > 0 ? ((score / totalMarks) * 100).toFixed(1) : 0;
        const markedDate = sub.markedAt?.toDate?.()?.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'
        }) || '-';
        const markedBy = sub.markedByName || 'Mimi';
        const submissionReason = sub.submissionReason || 'Manual';
        
        // Determine grade
        let grade = 'F';
        let gradeClass = 'grade-f';
        if (percentage >= 80) { grade = 'A'; gradeClass = 'grade-a'; }
        else if (percentage >= 70) { grade = 'B'; gradeClass = 'grade-b'; }
        else if (percentage >= 60) { grade = 'C'; gradeClass = 'grade-c'; }
        else if (percentage >= 50) { grade = 'D'; gradeClass = 'grade-d'; }
        
        // Reason badge
        const reasonMap = {
            'manual': 'Manual',
            'time_up': '⏰ Time Up',
            'screen_split': '📱 Screen Split',
            'window_blur': '🪟 Window Blur'
        };
        const reasonText = reasonMap[submissionReason] || submissionReason;
        
        return `
            <div class="marked-exam-card">
                <div class="marked-exam-header">
                    <div class="student-info">
                        <div class="student-avatar-small">
                            ${studentName.charAt(0).toUpperCase()}
                        </div>
                        <div>
                            <h4>${escapeHtml(studentName)}</h4>
                            <span class="exam-module-badge">${escapeHtml(moduleCode)}</span>
                        </div>
                    </div>
                    <div class="score-display">
                        <div class="score-circle ${gradeClass}">
                            <span class="score-value">${percentage}%</span>
                            <span class="grade-letter">${grade}</span>
                        </div>
                    </div>
                </div>
                
                <div class="marked-exam-body">
                    <p><strong>Mtihani:</strong> ${escapeHtml(examTitle)}</p>
                    <div class="exam-meta-row">
                        <span><i class="fas fa-star"></i> Alama: <strong>${score}/${totalMarks}</strong></span>
                        <span><i class="fas fa-calendar-check"></i> ${markedDate}</span>
                    </div>
                    <div class="exam-meta-row">
                        <span><i class="fas fa-user-check"></i> Imesahihishwa na: <strong>Mimi</strong></span>
                        <span class="reason-badge reason-${submissionReason}">${reasonText}</span>
                    </div>
                </div>
                
                <div class="marked-exam-actions">
                    <button class="btn-view" onclick="viewMarkedExamDetails('${sub.id}')">
                        <i class="fas fa-eye"></i> Tazama Majibu
                    </button>
                    <button class="btn-remark" onclick="openRemarkModal('${sub.id}')">
                        <i class="fas fa-redo"></i> Sahihisha Upya (Remark)
                    </button>
                    <button class="btn-export-single" onclick="exportSingleResult('${sub.id}')">
                        <i class="fas fa-download"></i> Pakua
                    </button>
                </div>
            </div>
        `;
    }).join('');
}

// ============================================
// VIEW MARKED EXAM DETAILS
// ============================================
async function viewMarkedExamDetails(submissionId) {
    try {
        const doc = await db.collection('examSubmissions').doc(submissionId).get();
        if (!doc.exists) {
            showToast('Submission not found', 'error');
            return;
        }
        
        const sub = { id: doc.id, ...doc.data() };
        const score = sub.score || 0;
        const totalMarks = sub.totalMarks || 100;
        const percentage = totalMarks > 0 ? ((score / totalMarks) * 100).toFixed(1) : 0;
        
        let grade = 'F';
        if (percentage >= 80) grade = 'A';
        else if (percentage >= 70) grade = 'B';
        else if (percentage >= 60) grade = 'C';
        else if (percentage >= 50) grade = 'D';
        
        const content = document.getElementById('markedExamDetailsContent');
        if (!content) return;
        
        content.innerHTML = `
            <div class="marked-detail-header">
                <h3>${escapeHtml(sub.examTitle)}</h3>
                <div class="detail-meta">
                    <span><i class="fas fa-user"></i> ${escapeHtml(sub.studentName)}</span>
                    <span><i class="fas fa-book"></i> ${escapeHtml(sub.moduleCode)}</span>
                    <span><i class="fas fa-calendar"></i> ${sub.submittedAt?.toDate?.().toLocaleString('sw-TZ') || '-'}</span>
                </div>
                <div class="score-summary">
                    <div class="score-big">${score}/${totalMarks}</div>
                    <div class="percentage-big">${percentage}% - Grade ${grade}</div>
                </div>
            </div>
            
            <hr>
            
            <h4>Majibu ya Mwanafunzi</h4>
            <div class="answers-review-list">
                ${sub.answers?.map((ans, idx) => {
                    let answerDisplay = '';
                    if (Array.isArray(ans.answer)) {
                        answerDisplay = ans.answer.map((a, i) => `${i + 1}. ${a || '<em>No answer</em>'}`).join('<br>');
                    } else {
                        answerDisplay = ans.answer || '<em>No answer provided</em>';
                    }
                    
                    const isCorrect = ans.marksObtained !== undefined && ans.marksObtained >= ans.marks;
                    const isPartial = ans.marksObtained !== undefined && ans.marksObtained > 0 && ans.marksObtained < ans.marks;
                    const isWrong = ans.marksObtained !== undefined && ans.marksObtained === 0;
                    
                    let resultClass = '';
                    let resultIcon = '';
                    if (isCorrect) { resultClass = 'correct'; resultIcon = '✅'; }
                    else if (isPartial) { resultClass = 'partial'; resultIcon = '⚠️'; }
                    else if (isWrong) { resultClass = 'wrong'; resultIcon = '❌'; }
                    
                    return `
                        <div class="answer-review-item ${resultClass}">
                            <div class="answer-review-header">
                                <span class="question-num">Q${idx + 1}</span>
                                <span class="result-icon">${resultIcon}</span>
                                <span class="marks-badge">${ans.marksObtained || 0}/${ans.marks} marks</span>
                            </div>
                            <p class="question-text-review">${escapeHtml(ans.question)}</p>
                            <div class="student-answer-review">
                                <strong>Jibu:</strong>
                                <div class="answer-box">${answerDisplay}</div>
                            </div>
                            ${ans.remarks ? `<p class="remarks-text"><strong>Maoni:</strong> ${escapeHtml(ans.remarks)}</p>` : ''}
                        </div>
                    `;
                }).join('') || '<p>No answers found</p>'}
            </div>
        `;
        
        document.getElementById('markedExamDetailsModal').classList.add('active');
        document.body.style.overflow = 'hidden';
        
    } catch (error) {
        console.error('Error viewing marked exam:', error);
        showToast('Error: ' + error.message, 'error');
    }
}

function closeMarkedExamDetailsModal() {
    document.getElementById('markedExamDetailsModal').classList.remove('active');
    document.body.style.overflow = '';
}

// ============================================
// REMARK EXAM - OPEN REMARK MODAL
// ============================================
async function openRemarkModal(submissionId) {
    try {
        const doc = await db.collection('examSubmissions').doc(submissionId).get();
        if (!doc.exists) {
            showToast('Submission not found', 'error');
            return;
        }
        
        currentMarkingSubmission = { id: doc.id, ...doc.data() };
        const sub = currentMarkingSubmission;
        
        const content = document.getElementById('remarkModalContent');
        if (!content) return;
        
        content.innerHTML = `
            <div class="remark-header">
                <h3><i class="fas fa-redo"></i> Sahihisha Upya</h3>
                <p><strong>Mwanafunzi:</strong> ${escapeHtml(sub.studentName)}</p>
                <p><strong>Mtihani:</strong> ${escapeHtml(sub.examTitle)}</p>
                <p><strong>Module:</strong> ${escapeHtml(sub.moduleCode)}</p>
                <p><strong>Alama ya Awali:</strong> ${sub.score}/${sub.totalMarks}</p>
            </div>
            <hr>
            <div class="remark-questions">
                ${sub.answers?.map((ans, idx) => {
                    let answerDisplay = '';
                    if (Array.isArray(ans.answer)) {
                        answerDisplay = ans.answer.map((a, i) => `${i + 1}. ${a || '-'}`).join('<br>');
                    } else {
                        answerDisplay = ans.answer || '<em>No answer</em>';
                    }
                    
                    return `
                        <div class="remark-question-item" id="remark-q-${idx}">
                            <div class="remark-q-header">
                                <h5>Q${idx + 1}: ${escapeHtml(ans.question)}</h5>
                                <span class="q-marks-badge">[${ans.marks} marks]</span>
                            </div>
                            <div class="remark-answer">
                                <p><strong>Jibu la Mwanafunzi:</strong></p>
                                <div class="student-answer-box">${answerDisplay}</div>
                                ${ans.type === 'multiple_choice' || ans.type === 'picture_based' ? 
                                    `<p><strong>Jibu Sahihi:</strong> ${ans.correctAnswer || 'N/A'}</p>` : ''}
                            </div>
                            <div class="remark-marks-input">
                                <div class="marks-group">
                                    <label>Alama Mpya:</label>
                                    <input type="number" id="remarkMarks${idx}" class="marks-input" 
                                           min="0" max="${ans.marks}" value="${ans.marksObtained || 0}" 
                                           onchange="updateRemarkTotal()">
                                    <span>/ ${ans.marks}</span>
                                </div>
                                <div class="remarks-group">
                                    <label>Maoni (Optional):</label>
                                    <input type="text" id="remarkRemarks${idx}" class="remarks-input" 
                                           placeholder="Sababu ya kubadilisha alama..." 
                                           value="${escapeHtml(ans.remarks || '')}">
                                </div>
                            </div>
                            <div class="quick-actions">
                                <button type="button" class="btn-correct" onclick="setRemarkMarks(${idx}, ${ans.marks})">
                                    ✅ Full Marks
                                </button>
                                <button type="button" class="btn-incorrect" onclick="setRemarkMarks(${idx}, 0)">
                                    ❌ Zero
                                </button>
                                <button type="button" class="btn-partial" onclick="setRemarkMarks(${idx}, ${Math.floor(ans.marks / 2)})">
                                    ⚠️ Half
                                </button>
                            </div>
                        </div>
                    `;
                }).join('')}
            </div>
            <div class="remark-summary">
                <h4>Jumla Mpya: <span id="remarkTotalDisplay">0</span> / ${sub.totalMarks || 0}</h4>
            </div>
        `;
        
        // Initialize total
        setTimeout(updateRemarkTotal, 100);
        
        document.getElementById('remarkModal').classList.add('active');
        document.body.style.overflow = 'hidden';
        
    } catch (error) {
        console.error('Error opening remark modal:', error);
        showToast('Failed to load submission', 'error');
    }
}

function closeRemarkModal() {
    document.getElementById('remarkModal').classList.remove('active');
    document.body.style.overflow = '';
    currentMarkingSubmission = null;
}

// ============================================
// REMARK HELPERS
// ============================================
function setRemarkMarks(index, marks) {
    const input = document.getElementById(`remarkMarks${index}`);
    if (input) {
        input.value = marks;
        updateRemarkTotal();
    }
}

function updateRemarkTotal() {
    if (!currentMarkingSubmission?.answers) return;
    
    let total = 0;
    currentMarkingSubmission.answers.forEach((ans, i) => {
        const marksInput = document.getElementById(`remarkMarks${i}`);
        if (marksInput) {
            total += parseFloat(marksInput.value) || 0;
        }
    });
    
    const display = document.getElementById('remarkTotalDisplay');
    if (display) display.textContent = total;
}

// ============================================
// SAVE REMARK
// ============================================
async function saveRemark() {
    if (!currentMarkingSubmission) return;
    
    try {
        const answers = currentMarkingSubmission.answers.map((ans, i) => {
            const marksInput = document.getElementById(`remarkMarks${i}`);
            const remarksInput = document.getElementById(`remarkRemarks${i}`);
            
            return {
                ...ans,
                marksObtained: parseFloat(marksInput?.value) || 0,
                remarks: remarksInput?.value || '',
                remarked: true,
                previousMarks: ans.marksObtained,
                previousRemarks: ans.remarks
            };
        });
        
        let totalScore = 0;
        answers.forEach(a => totalScore += a.marksObtained || 0);
        
        await db.collection('examSubmissions').doc(currentMarkingSubmission.id).update({
            answers: answers,
            score: totalScore,
            status: 'remarked',
            remarkedBy: currentUser.uid,
            remarkedByName: currentUser.name,
            remarkedAt: firebase.firestore.FieldValue.serverTimestamp(),
            previousScore: currentMarkingSubmission.score
        });
        
        // Notify student about remark
        await db.collection('notifications').add({
            userId: currentMarkingSubmission.studentId,
            type: 'exam_remarked',
            message: `Mtihani wako "${currentMarkingSubmission.examTitle}" umesahihishwa upya. Alama Mpya: ${totalScore}/${currentMarkingSubmission.totalMarks}`,
            read: false,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ Alama zimesasishwa kikamilifu!', 'success');
        closeRemarkModal();
        
        // Refresh lists
        await loadMarkedExams();
        
    } catch (error) {
        console.error('Error saving remark:', error);
        showToast('Failed to save: ' + error.message, 'error');
    }
}

