// ============================================
// EXPORT SINGLE RESULT - FIXED
// ============================================
async function exportSingleResult(submissionId) {
    try {
        const doc = await db.collection('examSubmissions').doc(submissionId).get();
        if (!doc.exists) {
            showToast('Submission not found', 'error');
            return;
        }
        
        const sub = doc.data();
        const score = sub.score || 0;
        const totalMarks = sub.totalMarks || 100;
        const percentage = totalMarks > 0 ? ((score / totalMarks) * 100).toFixed(1) : 0;
        
        let grade = 'F';
        if (percentage >= 80) grade = 'A';
        else if (percentage >= 70) grade = 'B';
        else if (percentage >= 60) grade = 'C';
        else if (percentage >= 50) grade = 'D';
        
        let answersHtml = '';
        if (sub.answers && sub.answers.length > 0) {
            sub.answers.forEach((ans, i) => {
                let answerDisplay = '';
                if (Array.isArray(ans.answer)) {
                    answerDisplay = ans.answer.join(', ');
                } else {
                    answerDisplay = ans.answer || '-';
                }
                answersHtml += `
                    <tr>
                        <td>${i + 1}</td>
                        <td>${escapeHtml(String(ans.question || '').substring(0, 80))}...</td>
                        <td>${escapeHtml(String(answerDisplay).substring(0, 50))}</td>
                        <td>${ans.marksObtained || 0}/${ans.marks}</td>
                    </tr>
                `;
            });
        }
        
        const safeStudentName = (sub.studentName || 'student').replace(/\s+/g, '_');
        const safeModuleCode = (sub.moduleCode || 'MODULE').replace(/\s+/g, '_');
        
        const htmlContent = `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Matokeo ya Mtihani</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 40px; }
        h1 { color: #e65c1e; }
        .header { margin-bottom: 20px; }
        .score-box { background: #f0f9ff; padding: 15px; border-radius: 10px; margin: 15px 0; }
        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
        th, td { border: 1px solid #ddd; padding: 10px; text-align: left; }
        th { background-color: #e65c1e; color: white; }
    </style>
</head>
<body>
    <h1>Matokeo ya Mtihani</h1>
    <div class="header">
        <p><strong>Mwanafunzi:</strong> ${escapeHtml(sub.studentName || '-')}</p>
        <p><strong>Mtihani:</strong> ${escapeHtml(sub.examTitle || '-')}</p>
        <p><strong>Module:</strong> ${escapeHtml(sub.moduleCode || '-')}</p>
    </div>
    <div class="score-box">
        <h2>Alama: ${score}/${totalMarks} (${percentage})</h2>
        <h3>Daraja: ${grade}</h3>
    </div>
    <table>
        <thead>
            <tr><th>#</th><th>Swali</th><th>Jibu</th><th>Alama</th></tr>
        </thead>
        <tbody>${answersHtml}</tbody>
    </table>
</body>
</html>`;
        
        const blob = new Blob([htmlContent], { type: 'application/msword' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `matokeo_${safeStudentName}_${safeModuleCode}.doc`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(link.href);
        
        showToast('✅ Matokeo yamepakuliwa!', 'success');
        
    } catch (error) {
        console.error('Error exporting result:', error);
        showToast('Error: ' + error.message, 'error');
    }
}

