// ============================================
// LOAD USER DATA - ADD MARKED EXAMS CHECK
// ============================================
async function loadUserData() {
    // Refresh currentUser from Firestore
    if (currentUser && currentUser.uid) {
        try {
            const userDoc = await db.collection('users').doc(currentUser.uid).get();
            if (userDoc.exists) {
                const userData = userDoc.data();
                let enrolledCourses = (userData.enrolledCourses || []).filter(id => id && id.trim() !== '');
                
                // Clean invalid courses
                const validCourses = [];
                for (const courseId of enrolledCourses) {
                    const courseDoc = await db.collection('courses').doc(courseId).get();
                    if (courseDoc.exists) {
                        validCourses.push(courseId);
                    }
                }
                
                if (validCourses.length !== enrolledCourses.length) {
                    await db.collection('users').doc(currentUser.uid).update({
                        enrolledCourses: validCourses
                    });
                }
                
                currentUser = {
                    uid: currentUser.uid,
                    ...userData,
                    enrolledCourses: validCourses
                };
                localStorage.setItem('currentUser', JSON.stringify(currentUser));
            }
        } catch (e) {
            console.log('Could not refresh user data:', e);
        }
    }
    
    await Promise.all([
        loadUserCourses(),
        loadAvailableCoursesForUser(),
        loadUserTestResults(),
        loadUserExamResults(),
        loadUserBills(),
        loadUserTimetable(),
        loadUserNotifications(),
        loadUserCoursework()
    ]);
}

