let currentResultStudent = null;
let currentResultModule = null;
let currentCourseworkMarks = [];
let allSavedResults = [];

// ============================================
// LOAD STUDENTS FOR RESULTS (Based on Module)
// ============================================
async function loadStudentsForResults() {
    const moduleCode = document.getElementById('resultModuleSelect').value;
    const studentSelect = document.getElementById('resultStudentSelect');
    
    if (!moduleCode) {
        studentSelect.innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
        document.getElementById('courseworkMarksSection').style.display = 'none';
        document.getElementById('examMarksSection').style.display = 'none';
        return;
    }
    
    studentSelect.innerHTML = '<option value="">Inapakia wanafunzi...</option>';
    
    try {
        // Get students enrolled in courses that have this module
        const moduleQuery = await db.collection('modules').where('code', '==', moduleCode).get();
        let moduleCourseId = null;
        
        if (!moduleQuery.empty) {
            moduleCourseId = moduleQuery.docs[0].data().courseId;
        }
        
        const usersSnapshot = await db.collection('users')
            .where('role', '==', 'user')
            .where('status', '==', 'approved')
            .get();
        
        const students = [];
        
        for (const doc of usersSnapshot.docs) {
            const user = doc.data();
            const enrolledCourses = user.enrolledCourses || [];
            
            if (moduleCourseId && enrolledCourses.includes(moduleCourseId)) {
                students.push({
                    id: doc.id,
                    name: user.name || 'Unknown',
                    email: user.email || '',
                    phone: user.phone || ''
                });
            }
        }
        
        if (students.length === 0) {
            studentSelect.innerHTML = '<option value="">-- Hakuna wanafunzi kwenye moduli hii --</option>';
        } else {
            studentSelect.innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
            students.forEach(student => {
                studentSelect.innerHTML += `<option value="${student.id}">${student.name} - ${student.email}</option>`;
            });
        }
        
    } catch (error) {
        console.error('Error loading students:', error);
        studentSelect.innerHTML = '<option value="">-- Kosa --</option>';
    }
}

// ============================================
// LOAD STUDENT COURSEWORK MARKS (Auto) - FIXED
// ============================================
async function loadStudentCourseworkMarks() {
    const studentId = document.getElementById('resultStudentSelect').value;
    const moduleCode = document.getElementById('resultModuleSelect').value;
    
    if (!studentId || !moduleCode) {
        document.getElementById('courseworkMarksSection').style.display = 'none';
        document.getElementById('examMarksSection').style.display = 'none';
        return;
    }
    
    currentResultStudent = studentId;
    currentResultModule = moduleCode;
    
    document.getElementById('courseworkMarksSection').style.display = 'block';
    document.getElementById('examMarksSection').style.display = 'block';
    
    document.getElementById('resultStudentId').value = studentId;
    document.getElementById('resultModuleCode').value = moduleCode;
    
    const body = document.getElementById('courseworkMarksBody');
    body.innerHTML = '<tr><td colspan="7" class="text-center"><i class="fas fa-spinner fa-spin"></i> Inapakia alama za coursework...</td></tr>';
    
    try {
        // Get ALL coursework for this student
        const snapshot = await db.collection('coursework')
            .where('studentId', '==', studentId)
            .get();
        
        currentCourseworkMarks = [];
        
        // Filter by module and sanitize defaults
        snapshot.forEach(doc => {
            const cw = doc.data();
            if (cw.moduleCode === moduleCode) {
                // Ensure all fields have safe defaults - NO undefined values
                currentCourseworkMarks.push({
                    id: doc.id,
                    moduleCode: cw.moduleCode || '',
                    moduleName: cw.moduleName || '',
                    studentId: cw.studentId || '',
                    studentName: cw.studentName || '',
                    type: cw.type || 'unknown',
                    marks: parseFloat(cw.marks) || 0,
                    maxScore: parseFloat(cw.maxScore) || 100,
                    status: cw.status || 'submitted',
                    createdAt: cw.createdAt || firebase.firestore.Timestamp.now(),
                    createdBy: cw.createdBy || ''
                });
            }
        });
        
        // Sort by date (newest first)
        currentCourseworkMarks.sort((a, b) => {
            const dateA = a.createdAt?.toDate ? a.createdAt.toDate() : new Date(0);
            const dateB = b.createdAt?.toDate ? b.createdAt.toDate() : new Date(0);
            return dateB - dateA;
        });
        
        if (currentCourseworkMarks.length === 0) {
            body.innerHTML = `
                <tr>
                    <td colspan="7" class="text-center">
                        <div class="empty-mini-state">
                            <i class="fas fa-info-circle"></i>
                            <p>Hakuna alama za coursework zilizoingizwa kwa mwanafunzi huyu kwenye moduli hii.</p>
                            <small>Ongeza coursework kwenye sehemu ya "Coursework" kwanza.</small>
                        </div>
                    </td>
                </tr>`;
            document.getElementById('courseworkSummary').style.display = 'none';
            document.getElementById('finalResultPreview').style.display = 'none';
        } else {
            // Build table
            body.innerHTML = currentCourseworkMarks.map((cw, idx) => {
                const typeInfo = getTypeDisplay(cw.type || '');
                const statusInfo = getStatusInfo(cw.status || '');
                const maxMarks = cw.maxScore || 100;
                const marks = cw.marks || 0;
                const percentage = maxMarks > 0 ? ((marks / maxMarks) * 100).toFixed(1) : 0;
                let date = '-';
                if (cw.createdAt && cw.createdAt.toDate) {
                    date = cw.createdAt.toDate().toLocaleDateString('sw-TZ');
                } else if (cw.createdAt instanceof Date) {
                    date = cw.createdAt.toLocaleDateString('sw-TZ');
                }
                
                return `
                    <tr>
                        <td class="text-center">${idx + 1}</td>
                        <td><span class="type-badge ${typeInfo.class}">${typeInfo.text}</span></td>
                        <td class="text-center"><strong>${marks}</strong></td>
                        <td class="text-center">${maxMarks}</td>
                        <td class="text-center">
                            <span class="percentage-badge ${percentage >= 50 ? 'good' : 'poor'}">${percentage}</span>
                        </td>
                        <td><span class="${statusInfo.class}">${statusInfo.text}</span></td>
                        <td>${date}</td>
                    </tr>
                `;
            }).join('');
            
            // Calculate summary
            const totalMarks = currentCourseworkMarks.reduce((sum, cw) => sum + (parseFloat(cw.marks) || 0), 0);
            const totalMax = currentCourseworkMarks.reduce((sum, cw) => sum + (parseFloat(cw.maxScore) || 100), 0);
            const count = currentCourseworkMarks.length;
            const average = totalMax > 0 ? ((totalMarks / totalMax) * 100).toFixed(1) : 0;
            
            document.getElementById('courseworkTotalMarks').textContent = `${totalMarks.toFixed(1)} / ${totalMax}`;
            document.getElementById('courseworkCount').textContent = count;
            function fmtNum(num) {
    var n = parseFloat(num || 0);
    return n % 1 === 0 ? n.toString() : n.toFixed(1);
}
document.getElementById('courseworkAverage').textContent = fmtNum(totalMarks);
            document.getElementById('courseworkSummary').style.display = 'flex';
            
            // Auto-calculate final result
            calculateFinalResult();
        }
        
    } catch (error) {
        console.error('Error loading coursework:', error);
        body.innerHTML = `<tr><td colspan="7" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

// ============================================
// CALCULATE FINAL RESULT - SIMPLE ADDITION
// Coursework Total + Exam Marks = Final Score
// ============================================
function calculateFinalResult() {
    const examMarks = parseFloat(document.getElementById('examMarks').value) || 0;
    
    // Calculate coursework total marks
    const totalCourseworkMarks = currentCourseworkMarks.reduce((sum, cw) => sum + (parseFloat(cw.marks) || 0), 0);
    
    // SIMPLE: Coursework + Exam = Final Score
    const finalScore = totalCourseworkMarks + examMarks;
    
    // Helper function - removes .0 for whole numbers
    function fmtNum(num) {
        var n = parseFloat(num || 0);
        return n % 1 === 0 ? n.toString() : n.toFixed(1);
    }
    
    // Determine grade based on final score out of 100
    let grade = 'F';
    if (finalScore >= 80) grade = 'A';
    else if (finalScore >= 75) grade = 'B+';
    else if (finalScore >= 70) grade = 'B';
    else if (finalScore >= 60) grade = 'C';
    else if (finalScore >= 50) grade = 'D';
    
    // Update preview with formatted numbers (no .0)
    var previewBox = document.getElementById('finalResultPreview');
    if (previewBox) previewBox.style.display = 'block';
    
    var previewCoursework = document.getElementById('previewCoursework');
    if (previewCoursework) previewCoursework.textContent = fmtNum(totalCourseworkMarks);
    
    var previewExam = document.getElementById('previewExam');
    if (previewExam) previewExam.textContent = fmtNum(examMarks);
    
    var previewTotal = document.getElementById('previewTotal');
    if (previewTotal) previewTotal.textContent = fmtNum(finalScore) + ' / 100';
    
    var previewGrade = document.getElementById('previewGrade');
    if (previewGrade) previewGrade.textContent = grade;
    
    // Color the grade
    var gradeColors = {
        'A': '#10b981', 'B+': '#3b82f6', 'B': '#6366f1',
        'C': '#f59e0b', 'D': '#f97316', 'F': '#ef4444'
    };
    if (previewGrade) previewGrade.style.color = gradeColors[grade] || '#64748b';
    if (previewTotal) previewTotal.style.color = finalScore >= 50 ? '#10b981' : '#ef4444';
}

// ============================================
// SAVE EXAM RESULTS - SIMPLE ADDITION (NO .0 OR /100)
// ============================================
async function saveExamResults() {
    const studentId = document.getElementById('resultStudentId').value;
    const moduleCode = document.getElementById('resultModuleCode').value;
    const examMarks = parseFloat(document.getElementById('examMarks').value) || 0;
    const remarks = document.getElementById('finalRemarks').value.trim();
    
    // Helper function - removes .0 for whole numbers
    function fmtNum(num) {
        var n = parseFloat(num || 0);
        return n % 1 === 0 ? n.toString() : n.toFixed(1);
    }
    
    if (!studentId || !moduleCode) {
        showToast('Tafadhali chagua module na mwanafunzi', 'error');
        return;
    }
    
    if (isNaN(examMarks)) {
        showToast('Tafadhali weka alama za mtihani', 'error');
        return;
    }
    
    // Calculate coursework total marks
    const totalCourseworkMarks = currentCourseworkMarks.reduce((sum, cw) => sum + (parseFloat(cw.marks) || 0), 0);
    
    // SIMPLE: Coursework + Exam = Final Score
    const finalScore = totalCourseworkMarks + examMarks;
    
    // Determine grade
    let grade = 'F';
    if (finalScore >= 80) grade = 'A';
    else if (finalScore >= 75) grade = 'B+';
    else if (finalScore >= 70) grade = 'B';
    else if (finalScore >= 60) grade = 'C';
    else if (finalScore >= 50) grade = 'D';
    
    // Get student name
    const studentDoc = await db.collection('users').doc(studentId).get();
    const studentName = studentDoc.exists ? (studentDoc.data().name || 'Unknown') : 'Unknown';
    
    // Get module name
    const moduleQuery = await db.collection('modules').where('code', '==', moduleCode).get();
    const moduleName = moduleQuery.empty ? moduleCode : moduleQuery.docs[0].data().name;
    
    const submitBtn = document.querySelector('#examMarksSection .btn-primary');
    const originalText = submitBtn?.innerHTML;
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    }
    
    try {
        // Sanitize coursework marks
        const sanitizedCourseworkMarks = currentCourseworkMarks.map(cw => ({
            type: cw.type || 'unknown',
            marks: parseFloat(cw.marks) || 0,
            maxScore: parseFloat(cw.maxScore) || 100,
            status: cw.status || 'submitted',
            date: cw.createdAt || null
        }));
        
        const resultData = {
            studentId: studentId,
            studentName: studentName,
            moduleCode: moduleCode,
            moduleName: moduleName,
            courseworkMarks: sanitizedCourseworkMarks,
            courseworkTotalMarks: parseFloat(totalCourseworkMarks.toFixed(1)),
            courseworkCount: currentCourseworkMarks.length,
            examMarks: examMarks,
            finalScore: parseFloat(finalScore.toFixed(1)),
            finalGrade: grade,
            remarks: remarks || '',
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: currentUser ? currentUser.uid : 'unknown',
            createdByName: currentUser ? (currentUser.name || 'Staff') : 'Staff'
        };
        
        // Check if result already exists
        const existingQuery = await db.collection('examResults')
            .where('studentId', '==', studentId)
            .where('moduleCode', '==', moduleCode)
            .get();
        
        if (!existingQuery.empty) {
            const updateData = { ...resultData };
            delete updateData.createdAt;
            updateData.updatedAt = firebase.firestore.FieldValue.serverTimestamp();
            
            await db.collection('examResults').doc(existingQuery.docs[0].id).update(updateData);
            showToast('✅ Matokeo yamesasishwa!', 'success');
        } else {
            await db.collection('examResults').add(resultData);
            showToast('✅ Matokeo yamehifadhiwa!', 'success');
        }
        
        // Notify student - no /100
        await db.collection('notifications').add({
            userId: studentId,
            type: 'exam_result',
            message: `Matokeo ya moduli ${moduleName}: Coursework ${fmtNum(totalCourseworkMarks)} + Mtihani ${fmtNum(examMarks)} = ${fmtNum(finalScore)} (${grade})`,
            read: false,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        // Reload results list
        await loadSavedExamResults();
        
    } catch (error) {
        console.error('Error saving results:', error);
        showToast('Kosa: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = originalText || '<i class="fas fa-save"></i> Save Final Results';
        }
    }
}

// ============================================
// LOAD SAVED EXAM RESULTS - FILTERED BY CURRENT STAFF
// Only shows results saved by this staff member
// ============================================
async function loadSavedExamResults() {
    const body = document.getElementById('savedResultsBody');
    if (!body) return;
    
    if (!currentUser) {
        body.innerHTML = '<tr><td colspan="9" class="text-center">Hakuna mtumiaji aliyeingia</td></tr>';
        return;
    }
    
    // Helper function - removes .0 for whole numbers
    function fmtNum(num) {
        var n = parseFloat(num || 0);
        return n % 1 === 0 ? n.toString() : n.toFixed(1);
    }
    
    body.innerHTML = '<tr><td colspan="9" class="text-center"><i class="fas fa-spinner fa-spin"></i> Inapakia matokeo yako...</td></tr>';
    
    try {
        // ============================================
        // FILTER: Only show results created by THIS staff member
        // ============================================
        const snapshot = await db.collection('examResults')
            .where('createdBy', '==', currentUser.uid)
            .get();
        
        allSavedResults = [];
        snapshot.forEach(doc => {
            allSavedResults.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort manually (newest first)
        allSavedResults.sort((a, b) => {
            const dateA = a.createdAt?.toDate?.() || new Date(0);
            const dateB = b.createdAt?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        // Update count badge
        const countEl = document.getElementById('savedResultsCount');
        if (countEl) {
            countEl.textContent = `${allSavedResults.length} (Yangu Pekee)`;
        }
        
        if (allSavedResults.length === 0) {
            body.innerHTML = `
                <tr>
                    <td colspan="9" class="text-center">
                        <div style="padding:2rem;text-align:center;color:#64748b;">
                            <i class="fas fa-file-alt" style="font-size:2.5rem;display:block;margin-bottom:1rem;color:#94a3b8;"></i>
                            <h4 style="color:#475569;margin-bottom:0.5rem;">Hakuna Matokeo</h4>
                            <p style="font-size:0.9rem;">Hujaweka matokeo ya mtihani wowote bado.</p>
                            <p style="font-size:0.8rem;color:#94a3b8;">Tumia sehemu ya juu kuweka matokeo ya mwanafunzi.</p>
                        </div>
                    </td>
                </tr>`;
            return;
        }
        
        body.innerHTML = allSavedResults.map((result, idx) => {
            const gradeColors = {
                'A': '#10b981', 'B+': '#3b82f6', 'B': '#6366f1',
                'C': '#f59e0b', 'D': '#f97316', 'F': '#ef4444'
            };
            const gradeColor = gradeColors[result.finalGrade] || '#64748b';
            const date = result.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ', {
                year: 'numeric', month: 'short', day: 'numeric'
            }) || '-';
            
            const cwMarks = fmtNum(result.courseworkTotalMarks || 0);
            const examMark = fmtNum(result.examMarks || 0);
            const finalScore = fmtNum(result.finalScore || 0);
            
            return `
                <tr>
                    <td class="text-center">${idx + 1}</td>
                    <td><strong>${escapeHtml(result.studentName || '-')}</strong></td>
                    <td><span class="module-tag">${escapeHtml(result.moduleCode || '-')}</span></td>
                    <td class="text-center"><strong>${cwMarks}</strong></td>
                    <td class="text-center"><strong>${examMark}</strong></td>
                    <td class="text-center">
                        <strong style="font-size:1rem;color:${parseFloat(result.finalScore || 0) >= 50 ? '#10b981' : '#ef4444'};">
                            ${finalScore}
                        </strong>
                    </td>
                    <td class="text-center">
                        <span class="grade-badge" style="background:${gradeColor}20;color:${gradeColor};font-weight:700;">
                            ${result.finalGrade || '-'}
                        </span>
                    </td>
                    <td>${date}</td>
                    <td>
                        <div style="display:flex;gap:0.3rem;justify-content:center;">
                            <button class="btn-view btn-sm" onclick="viewResultDetails('${result.id}')" title="Tazama">
                                <i class="fas fa-eye"></i>
                            </button>
                            <button class="btn-edit btn-sm" onclick="editResult('${result.id}')" title="Hariri">
                                <i class="fas fa-edit"></i>
                            </button>
                            <button class="btn-delete btn-sm" onclick="deleteResult('${result.id}')" title="Futa">
                                <i class="fas fa-trash"></i>
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');
        
        // Update the table header to show it's private
        const sectionHeader = document.querySelector('#staffExamResults .management-section:last-of-type .management-section-header h4');
        if (sectionHeader) {
            sectionHeader.innerHTML = `<i class="fas fa-list"></i> Matokeo Yangu Pekee <span style="font-size:0.7rem;color:#94a3b8;">(${allSavedResults.length})</span>`;
        }
        
        console.log(`✅ Loaded ${allSavedResults.length} exam results for staff: ${currentUser.name}`);
        
    } catch (error) {
        console.error('Error loading saved results:', error);
        body.innerHTML = `<tr><td colspan="9" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

