// VIEW RESULT DETAILS - NO .0 OR /100
// ============================================
async function viewResultDetails(resultId) {
    const doc = await db.collection('examResults').doc(resultId).get();
    if (!doc.exists) {
        showToast('Result not found', 'error');
        return;
    }
    
    const result = doc.data();
    
    // Helper function - removes .0 for whole numbers
    function fmtNum(num) {
        var n = parseFloat(num || 0);
        return n % 1 === 0 ? n.toString() : n.toFixed(1);
    }
    
    const modal = document.getElementById('examResultsViewModal');
    const content = document.getElementById('examResultsViewContent');
    
    if (!modal || !content) return;
    
    const gradeColors = {
        'A': '#10b981', 'B+': '#3b82f6', 'B': '#6366f1',
        'C': '#f59e0b', 'D': '#f97316', 'F': '#ef4444'
    };
    
    let courseworkRows = '';
    if (result.courseworkMarks && result.courseworkMarks.length > 0) {
        courseworkRows = result.courseworkMarks.map((cw, i) => {
            const typeInfo = getTypeDisplay(cw.type || '');
            const marks = fmtNum(cw.marks || 0);
            const maxScore = fmtNum(cw.maxScore || 100);
            return `
                <tr>
                    <td>${i + 1}</td>
                    <td><span class="type-badge ${typeInfo.class}">${typeInfo.text}</span></td>
                    <td class="text-center">${marks}</td>
                    <td class="text-center">${maxScore}</td>
                </tr>
            `;
        }).join('');
    } else {
        courseworkRows = '<tr><td colspan="4" class="text-center">No coursework marks</td></tr>';
    }
    
    const cwMarks = fmtNum(result.courseworkTotalMarks || 0);
    const examMark = fmtNum(result.examMarks || 0);
    const finalScore = fmtNum(result.finalScore || 0);
    
    content.innerHTML = `
        <div class="result-detail-view">
            <div class="result-detail-header">
                <h3>${escapeHtml(result.studentName)}</h3>
                <p><strong>Module:</strong> ${escapeHtml(result.moduleName || result.moduleCode)}</p>
                <p><strong>Tarehe:</strong> ${result.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-'}</p>
                ${result.createdByName ? `<p style="font-size:0.8rem;color:#94a3b8;"><i class="fas fa-user"></i> Imeingizwa na: ${escapeHtml(result.createdByName)}</p>` : ''}
            </div>
            
            <div class="result-score-card-final" style="background:${gradeColors[result.finalGrade] || '#64748b'};">
                <div class="final-score-display">
                    <span class="final-score-number">${finalScore}</span>
                    <span class="final-grade-letter">${result.finalGrade || '-'}</span>
                </div>
            </div>
            
            <div class="result-breakdown">
                <div class="breakdown-item">
                    <span class="breakdown-label">📋 Coursework Marks</span>
                    <span class="breakdown-value">${cwMarks}</span>
                </div>
                <div class="breakdown-item">
                    <span class="breakdown-label">📝 Exam Marks</span>
                    <span class="breakdown-value">${examMark}</span>
                </div>
                <div class="breakdown-item total">
                    <span class="breakdown-label">⭐ FINAL SCORE</span>
                    <span class="breakdown-value">${finalScore}</span>
                </div>
            </div>
            
            ${result.remarks ? `<p class="result-remarks"><strong>📝 Remarks:</strong> ${escapeHtml(result.remarks)}</p>` : ''}
            
            <hr>
            
            <h4>Coursework Breakdown (${result.courseworkCount || 0} assessments)</h4>
            <div class="table-responsive">
                <table class="data-table">
                    <thead>
                        <tr>
                            <th width="50">#</th>
                            <th>Assessment Type</th>
                            <th width="80">Marks</th>
                            <th width="80">Max</th>
                        </tr>
                    </thead>
                    <tbody>${courseworkRows}</tbody>
                </table>
            </div>
        </div>
    `;
    
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function closeExamResultsViewModal() {
    const modal = document.getElementById('examResultsViewModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
}

function searchExamResults() {
    const searchTerm = document.getElementById('examResultsSearch')?.value.toLowerCase() || '';
    const body = document.getElementById('savedResultsBody');
    
    // Helper
    function fmtNum(num) {
        var n = parseFloat(num || 0);
        return n % 1 === 0 ? n.toString() : n.toFixed(1);
    }
    
    const filtered = allSavedResults.filter(r =>
        (r.studentName && r.studentName.toLowerCase().includes(searchTerm)) ||
        (r.moduleCode && r.moduleCode.toLowerCase().includes(searchTerm))
    );
    
    if (filtered.length === 0) {
        body.innerHTML = '<tr><td colspan="9" class="text-center">No matching results</td></tr>';
        return;
    }
    
    body.innerHTML = filtered.map((result, idx) => {
        const gradeColors = {
            'A': '#10b981', 'B+': '#3b82f6', 'B': '#6366f1',
            'C': '#f59e0b', 'D': '#f97316', 'F': '#ef4444'
        };
        const gradeColor = gradeColors[result.finalGrade] || '#64748b';
        const date = result.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-';
        
        return `
            <tr>
                <td class="text-center">${idx + 1}</td>
                <td><strong>${escapeHtml(result.studentName || '-')}</strong></td>
                <td><span class="module-tag">${escapeHtml(result.moduleCode || '-')}</span></td>
                <td class="text-center"><strong>${fmtNum(result.courseworkTotalMarks || 0)}</strong></td>
                <td class="text-center"><strong>${fmtNum(result.examMarks || 0)}</strong></td>
                <td class="text-center"><strong>${fmtNum(result.finalScore || 0)}</strong></td>
                <td class="text-center">
                    <span class="grade-badge" style="background:${gradeColor}20;color:${gradeColor};font-weight:700;">
                        ${result.finalGrade || '-'}
                    </span>
                </td>
                <td>${date}</td>
                <td>
                    <div style="display:flex;gap:0.3rem;">
                        <button class="btn-view btn-sm" onclick="viewResultDetails('${result.id}')">
                            <i class="fas fa-eye"></i>
                        </button>
                        <button class="btn-edit btn-sm" onclick="editResult('${result.id}')">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="btn-delete btn-sm" onclick="deleteResult('${result.id}')">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

// ============================================
// EDIT & DELETE RESULTS
// ============================================
async function editResult(resultId) {
    const doc = await db.collection('examResults').doc(resultId).get();
    if (!doc.exists) return;
    
    const result = doc.data();
    
    // Populate form
    document.getElementById('resultModuleSelect').value = result.moduleCode || '';
    await loadStudentsForResults();
    
    // Wait for students to load then select
    setTimeout(() => {
        document.getElementById('resultStudentSelect').value = result.studentId || '';
        loadStudentCourseworkMarks();
    }, 500);
    
    // Set exam marks
    setTimeout(() => {
        document.getElementById('examMarks').value = result.examMarks || '';
        document.getElementById('examWeight').value = result.examWeight || 60;
        document.getElementById('finalRemarks').value = result.remarks || '';
        calculateFinalResult();
    }, 1000);
    
    // Scroll to form
    document.getElementById('examMarksSection').scrollIntoView({ behavior: 'smooth' });
    showToast('Editing result for: ' + result.studentName, 'info');
}

async function deleteResult(resultId) {
    if (!confirm('Are you sure you want to delete this result? This cannot be undone.')) return;
    
    try {
        await db.collection('examResults').doc(resultId).delete();
        showToast('✅ Result deleted!', 'success');
        await loadSavedExamResults();
    } catch (error) {
        showToast('Error: ' + error.message, 'error');
    }
}

// ============================================
// RESET FORM
// ============================================
function resetExamResultsForm() {
    document.getElementById('resultModuleSelect').value = '';
    document.getElementById('resultStudentSelect').innerHTML = '<option value="">-- Chagua Mwanafunzi --</option>';
    document.getElementById('examMarks').value = '';
    document.getElementById('finalRemarks').value = '';
    document.getElementById('courseworkMarksSection').style.display = 'none';
    document.getElementById('examMarksSection').style.display = 'none';
    document.getElementById('finalResultPreview').style.display = 'none';
    currentCourseworkMarks = [];
    currentResultStudent = null;
    currentResultModule = null;
}

// ============================================
// LOAD MODULES FOR RESULT SELECT
// ============================================
async function loadModulesForResults() {
    if (!currentUser) return;
    
    try {
        const staffDoc = await db.collection('users').doc(currentUser.uid).get();
        const modules = staffDoc.data()?.assignedModules || [];
        
        const select = document.getElementById('resultModuleSelect');
        if (select) {
            select.innerHTML = '<option value="">-- Chagua Module --</option>';
            modules.forEach(module => {
                select.innerHTML += `<option value="${module.code}">${module.code} - ${module.name}</option>`;
            });
            
            if (modules.length === 0) {
                select.innerHTML = '<option value="">-- Hakuna module ulizopangiwa --</option>';
            }
        }
    } catch (error) {
        console.error('Error loading modules:', error);
    }
}

