        html += '<div class="summary-card"><i class="fas fa-file-alt"></i><div><span class="summary-number">' + examResultsCount + '</span><span class="summary-label">Exam Results</span></div></div>';
        html += '<div class="summary-card"><i class="fas fa-check-double"></i><div><span class="summary-number">' + markedCount + '</span><span class="summary-label">Marked Exams</span></div></div>';
