// ============================================
// ADD COURSE FORM - SUPER ADMIN
// ============================================
function initSuperAddCourseForm() {
    const form = document.getElementById('superAddCourseForm');
    if (!form) return;
    
    // Remove old listeners by cloning
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        
        const code = document.getElementById('superCourseCode')?.value?.trim().toUpperCase();
        const name = document.getElementById('superCourseName')?.value?.trim();
        const description = document.getElementById('superCourseDescription')?.value?.trim();
        const duration = document.getElementById('superCourseDuration')?.value || 'Miezi 6';
        const fee = parseFloat(document.getElementById('superCourseFee')?.value) || 0;
        const featured = document.getElementById('superCourseFeatured')?.value === 'true';
        const order = parseInt(document.getElementById('superCourseOrder')?.value) || 0;
        const icon = document.getElementById('superCourseIcon')?.value || 'book';
        
        if (!code || !name) {
            showToast('Tafadhali weka code na jina la kozi', 'error');
            return;
        }
        
        // Check if course code already exists
        const existing = await db.collection('courses').where('code', '==', code).get();
        if (!existing.empty) {
            showToast(`Kozi yenye code "${code}" tayari ipo!`, 'error');
            return;
        }
        
        const submitBtn = newForm.querySelector('button[type="submit"]');
        const originalText = submitBtn?.textContent;
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inaongeza...';
        }
        
        try {
            await db.collection('courses').add({
                code: code,
                name: name,
                description: description || '',
                duration: duration,
                fee: fee,
                active: true,
                featured: featured,
                order: order,
                icon: icon,
                createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
            
            showToast(`✅ Kozi "${name}" imeongezwa!`, 'success');
            
            // Reset form
            newForm.reset();
            
            // Refresh list
            loadCoursesList();
            
            if (typeof loadPublicCourses === 'function') {
                loadPublicCourses();
            }
            
        } catch (error) {
            console.error('Error adding course:', error);
            showToast(`❌ Imeshindwa: ${error.message}`, 'error');
        } finally {
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = originalText || 'Ongeza Kozi';
            }
        }
    });
    
    console.log('✅ Super admin add course form initialized');
}

// ============================================
// TOAST NOTIFICATION
// ============================================
function showToast(message, type = 'success') {
    // Remove existing toasts
    document.querySelectorAll('.custom-toast').forEach(t => t.remove());
    
    const toast = document.createElement('div');
    toast.className = `custom-toast toast-${type}`;
    toast.innerHTML = `
        <i class="fas fa-${type === 'success' ? 'check-circle' : type === 'error' ? 'exclamation-circle' : 'info-circle'}"></i>
        <span>${message}</span>
    `;
    toast.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: ${type === 'success' ? '#10b981' : type === 'error' ? '#ef4444' : '#f59e0b'};
        color: white;
        padding: 12px 24px;
        border-radius: 12px;
        z-index: 10000;
        display: flex;
        align-items: center;
        gap: 10px;
        box-shadow: 0 10px 25px rgba(0,0,0,0.2);
        animation: slideInRight 0.3s ease;
        font-size: 0.9rem;
        font-weight: 500;
    `;
    
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

