// Fix the super admin dropdown buttons to handle logout
function initSuperAdminDropdowns() {
    // First dropdown button
    const dropdownBtn1 = document.getElementById('superAdminDropdownBtn');
    const dropdownMenu1 = document.getElementById('superAdminDropdownMenu');
    
    if (dropdownBtn1 && dropdownMenu1) {
        // Clone to remove old listeners
        const newBtn1 = dropdownBtn1.cloneNode(true);
        dropdownBtn1.parentNode.replaceChild(newBtn1, dropdownBtn1);
        
        newBtn1.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            dropdownMenu1.classList.toggle('active');
            
            // Close other dropdown if open
            const dropdownMenu2 = document.getElementById('superAdminDropdownMenu2');
            if (dropdownMenu2) dropdownMenu2.classList.remove('active');
        });
        
        // Handle logout link in first dropdown
        const logoutLink1 = dropdownMenu1.querySelector('a[onclick*="logout"]');
        if (logoutLink1) {
            logoutLink1.addEventListener('click', function(e) {
                e.preventDefault();
                logout();
            });
        }
        
        // Handle change password link
        const passwordLink1 = dropdownMenu1.querySelector('a[onclick*="openChangePasswordModal"]');
        if (passwordLink1) {
            passwordLink1.addEventListener('click', function(e) {
                e.preventDefault();
                openChangePasswordModal();
            });
        }
    }
    
    // Second dropdown button (in the dashboard nav)
    const dropdownBtn2 = document.getElementById('superAdminDropdownBtn2');
    const dropdownMenu2 = document.getElementById('superAdminDropdownMenu2');
    
    if (dropdownBtn2 && dropdownMenu2) {
        const newBtn2 = dropdownBtn2.cloneNode(true);
        dropdownBtn2.parentNode.replaceChild(newBtn2, dropdownBtn2);
        
        newBtn2.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            dropdownMenu2.classList.toggle('active');
            
            // Close other dropdown if open
            const dropdownMenu1 = document.getElementById('superAdminDropdownMenu');
            if (dropdownMenu1) dropdownMenu1.classList.remove('active');
        });
        
        // Handle logout link in second dropdown
        const logoutLink2 = dropdownMenu2.querySelector('a[onclick*="logout"]');
        if (logoutLink2) {
            logoutLink2.addEventListener('click', function(e) {
                e.preventDefault();
                logout();
            });
        }
        
        // Handle change password link
        const passwordLink2 = dropdownMenu2.querySelector('a[onclick*="openChangePasswordModal"]');
        if (passwordLink2) {
            passwordLink2.addEventListener('click', function(e) {
                e.preventDefault();
                openChangePasswordModal();
            });
        }
    }
}

// Close dropdowns when clicking outside
document.addEventListener('click', function(e) {
    const dropdownMenu1 = document.getElementById('superAdminDropdownMenu');
    const dropdownMenu2 = document.getElementById('superAdminDropdownMenu2');
    const dropdownBtn1 = document.getElementById('superAdminDropdownBtn');
    const dropdownBtn2 = document.getElementById('superAdminDropdownBtn2');
    
    if (dropdownMenu1 && dropdownMenu1.classList.contains('active')) {
        if (!dropdownMenu1.contains(e.target) && e.target !== dropdownBtn1 && !dropdownBtn1?.contains(e.target)) {
            dropdownMenu1.classList.remove('active');
        }
    }
    
    if (dropdownMenu2 && dropdownMenu2.classList.contains('active')) {
        if (!dropdownMenu2.contains(e.target) && e.target !== dropdownBtn2 && !dropdownBtn2?.contains(e.target)) {
            dropdownMenu2.classList.remove('active');
        }
    }
});

function logout() {
    // Clear all session data
    sessionStorage.clear();
    localStorage.removeItem('currentUser');
    
    // Clear current user
    currentUser = null;
    
    // Sign out from Firebase
    auth.signOut()
        .then(() => {
            console.log('User logged out successfully');
            
            // Close all dropdowns
            document.querySelectorAll('.user-dropdown-menu, .user-info-menu').forEach(menu => {
                menu.classList.remove('active', 'show');
                menu.style.display = 'none';
            });
            
            // Close all mobile menus
            document.querySelectorAll('.mobile-menu').forEach(menu => {
                menu.classList.remove('active');
            });
            document.querySelectorAll('.menu-overlay').forEach(overlay => {
                overlay.classList.remove('active');
            });
            
            // Hide all dashboards
            document.querySelectorAll('.dashboard').forEach(dash => {
                dash.classList.remove('active');
                dash.style.display = 'none';
            });
            
            // Hide all pages
            document.querySelectorAll('.page').forEach(page => {
                page.classList.remove('active');
            });
            
            // Show only the home page
            const homePage = document.getElementById('homePage');
            if (homePage) {
                homePage.classList.add('active');
                homePage.style.display = 'block';
            }
            
            // Reset body overflow
            document.body.style.overflow = '';
            
            // Show login button in navigation
            const authNavBtn = document.getElementById('authNavBtn');
            if (authNavBtn) authNavBtn.style.display = 'block';
            
            // Hide user dropdown
            const userNavDropdown = document.getElementById('userNavDropdown');
            if (userNavDropdown) userNavDropdown.style.display = 'none';
            
            // Show success message
            showToast('✅ Umetoka kikamilifu!', 'success');
            
            // Scroll to top
            window.scrollTo(0, 0);
            
        })
        .catch((error) => {
            console.error('Logout error:', error);
            showToast('❌ Kosa wakati wa kutoka: ' + error.message, 'error');
        });
}

