// Store current editing course ID
let currentEditingCourseId = null;

// ============================================
// OPEN EDIT COURSE MODAL
// ============================================
async function openEditCourseModal(courseId) {
    try {
        // Get course data from Firestore
        const doc = await db.collection('courses').doc(courseId).get();
        
        if (!doc.exists) {
            showToast('Kozi haikupatikana', 'error');
            return;
        }
        
        const course = doc.data();
        currentEditingCourseId = courseId;
        
        // Populate form fields
        document.getElementById('editCourseId').value = courseId;
        document.getElementById('editCourseCode').value = course.code || '';
        document.getElementById('editCourseName').value = course.name || '';
        document.getElementById('editCourseDescription').value = course.description || '';
        document.getElementById('editCourseDuration').value = course.duration || 'Miezi 6';
        document.getElementById('editCourseFee').value = course.fee || 0;
        document.getElementById('editCourseIcon').value = course.icon || 'book';
        document.getElementById('editCourseFeatured').value = course.featured ? 'true' : 'false';
        document.getElementById('editCourseOrder').value = course.order || 0;
        document.getElementById('editCourseStatus').value = course.active ? 'true' : 'false';
        
        // Update preview
        updateCoursePreview();
        
        // Show modal
        const modal = document.getElementById('editCourseModal');
        if (modal) {
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        }
        
        console.log('Edit modal opened for course:', course.name);
        
    } catch (error) {
        console.error('Error opening edit modal:', error);
        showToast('❌ Imeshindwa kupakia kozi: ' + error.message, 'error');
    }
}

// ============================================
// CLOSE EDIT COURSE MODAL
// ============================================
function closeEditCourseModal(event) {
    // Only close if clicking overlay (not the modal content)
    if (event && event.target !== event.currentTarget) return;
    
    const modal = document.getElementById('editCourseModal');
    if (modal) {
        modal.classList.remove('active');
        document.body.style.overflow = '';
    }
    currentEditingCourseId = null;
    
    // Reset form
    document.getElementById('editCourseForm')?.reset();
}

// ============================================
// UPDATE COURSE PREVIEW
// ============================================
function updateCoursePreview() {
    const name = document.getElementById('editCourseName')?.value || 'Jina la Kozi';
    const duration = document.getElementById('editCourseDuration')?.value || 'Miezi 6';
    const icon = document.getElementById('editCourseIcon')?.value || 'book';
    const status = document.getElementById('editCourseStatus')?.value === 'true';
    
    // Update preview name
    const previewName = document.getElementById('editCoursePreviewName');
    if (previewName) previewName.textContent = name;
    
    // Update preview duration
    const previewDuration = document.getElementById('editCoursePreviewDuration');
    if (previewDuration) previewDuration.textContent = duration;
    
    // Update preview icon
    const previewIcon = document.getElementById('editCoursePreviewIcon');
    if (previewIcon) {
        previewIcon.innerHTML = `<i class="fas fa-${icon}" style="color:white;font-size:1.2rem;"></i>`;
    }
    
    // Update preview status
    const previewStatus = document.getElementById('editCoursePreviewStatus');
    if (previewStatus) {
        if (status) {
            previewStatus.textContent = '✅ Active';
            previewStatus.style.background = '#dcfce7';
            previewStatus.style.color = '#166534';
        } else {
            previewStatus.textContent = '❌ Inactive';
            previewStatus.style.background = '#fee2e2';
            previewStatus.style.color = '#991b1b';
        }
    }
}

// ============================================
// ADD LIVE PREVIEW LISTENERS
// ============================================
document.addEventListener('DOMContentLoaded', function() {
    // Add input event listeners for live preview
    setTimeout(() => {
        const nameInput = document.getElementById('editCourseName');
        const durationSelect = document.getElementById('editCourseDuration');
        const iconSelect = document.getElementById('editCourseIcon');
        const statusSelect = document.getElementById('editCourseStatus');
        
        if (nameInput) nameInput.addEventListener('input', updateCoursePreview);
        if (durationSelect) durationSelect.addEventListener('change', updateCoursePreview);
        if (iconSelect) iconSelect.addEventListener('change', updateCoursePreview);
        if (statusSelect) statusSelect.addEventListener('change', updateCoursePreview);
    }, 1000);
});

// ============================================
// SAVE EDITED COURSE
// ============================================
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(() => {
        const form = document.getElementById('editCourseForm');
        
        if (form) {
            // Remove old listeners by cloning
            const newForm = form.cloneNode(true);
            form.parentNode.replaceChild(newForm, form);
            
            newForm.addEventListener('submit', async function(e) {
                e.preventDefault();
                
                const courseId = document.getElementById('editCourseId')?.value;
                const name = document.getElementById('editCourseName')?.value?.trim();
                const description = document.getElementById('editCourseDescription')?.value?.trim();
                const duration = document.getElementById('editCourseDuration')?.value;
                const fee = parseFloat(document.getElementById('editCourseFee')?.value) || 0;
                const icon = document.getElementById('editCourseIcon')?.value;
                const featured = document.getElementById('editCourseFeatured')?.value === 'true';
                const order = parseInt(document.getElementById('editCourseOrder')?.value) || 0;
                const active = document.getElementById('editCourseStatus')?.value === 'true';
                
                // Validation
                if (!courseId) {
                    showToast('❌ Kozi haijatambuliwa', 'error');
                    return;
                }
                
                if (!name) {
                    showToast('❌ Tafadhali weka jina la kozi', 'error');
                    document.getElementById('editCourseName')?.focus();
                    return;
                }
                
                // Show loading
                const saveBtn = document.getElementById('editCourseSaveBtn');
                const originalHTML = saveBtn?.innerHTML;
                if (saveBtn) {
                    saveBtn.disabled = true;
                    saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
                }
                
                try {
                    // Update course in Firestore
                    await db.collection('courses').doc(courseId).update({
                        name: name,
                        description: description || '',
                        duration: duration || 'Miezi 6',
                        fee: fee,
                        icon: icon || 'book',
                        featured: featured,
                        order: order,
                        active: active,
                        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                    });
                    
                    showToast('✅ Kozi imesasishwa kikamilifu!', 'success');
                    
                    // Close modal
                    closeEditCourseModal();
                    
                    // Refresh course lists
                    if (typeof loadCoursesList === 'function') {
                        loadCoursesList();
                    }
                    
                    if (typeof loadPublicCourses === 'function') {
                        loadPublicCourses();
                    }
                    
                    // Refresh course select for modules
                    if (typeof loadCourseSelectForModules === 'function') {
                        loadCourseSelectForModules();
                    }
                    
                } catch (error) {
                    console.error('Error updating course:', error);
                    showToast('❌ Imeshindwa kuhifadhi: ' + error.message, 'error');
                } finally {
                    if (saveBtn) {
                        saveBtn.disabled = false;
                        saveBtn.innerHTML = originalHTML || '<i class="fas fa-save"></i> Hifadhi Mabadiliko';
                    }
                }
            });
            
            console.log('✅ Edit course form initialized');
        }
    }, 1000);
});

