// ============================================
// LOAD ADMINS LIST - FIXED (No composite index required)
// ============================================
async function loadAdminsList() {
    const container = document.getElementById('superAdminsList');
    const emptyState = document.getElementById('adminsEmptyState');
    const countBadge = document.getElementById('adminListCount');
    
    if (!container) {
        console.error('superAdminsList container not found');
        return;
    }
    
    container.innerHTML = '<tr><td colspan="6" class="text-center"><div class="loading-spinner">Inapakia admins...</div></td></tr>';
    
    try {
        // FIXED: Use simple query without orderBy to avoid composite index requirement
        const snapshot = await db.collection('users')
            .where('role', '==', 'admin')
            .get();
        
        allAdmins = [];
        snapshot.forEach(doc => {
            allAdmins.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort manually in JavaScript (no index needed)
        allAdmins.sort((a, b) => {
            const dateA = a.createdAt?.toDate?.() || new Date(0);
            const dateB = b.createdAt?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        console.log('Admins found:', allAdmins.length);
        console.log('Admins data:', allAdmins);
        
        // Update count badge
        if (countBadge) {
            countBadge.textContent = `Jumla: ${allAdmins.length}`;
        }
        
        if (allAdmins.length === 0) {
            container.innerHTML = '';
            if (emptyState) emptyState.style.display = 'block';
            if (countBadge) countBadge.textContent = 'Jumla: 0';
            return;
        }
        
        if (emptyState) emptyState.style.display = 'none';
        
        // Render the list
        renderAdminsList(allAdmins);
        
        console.log(`✅ Loaded ${allAdmins.length} admins (sorted manually)`);
        
    } catch (error) {
        console.error('Error loading admins:', error);
        container.innerHTML = `<tr><td colspan="6" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

// ============================================
// RENDER ADMINS LIST
// ============================================
function renderAdminsList(admins) {
    const container = document.getElementById('superAdminsList');
    const emptyState = document.getElementById('adminsEmptyState');
    
    if (!container) return;
    
    if (!admins || admins.length === 0) {
        container.innerHTML = '';
        if (emptyState) emptyState.style.display = 'block';
        return;
    }
    
    if (emptyState) emptyState.style.display = 'none';
    
    container.innerHTML = admins.map((admin, index) => {
        const initials = (admin.name || 'A').split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
        const status = admin.status || 'approved';
        const statusClass = status === 'approved' ? 'status-active' : 'status-inactive';
        const statusText = status === 'approved' ? 'Active' : 'Inactive';
        const joinDate = admin.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric'
        }) || '-';
        
        return `
            <tr id="admin-row-${admin.id}">
                <td class="text-center" style="color:#94a3b8;">${index + 1}</td>
                <td>
                    <div class="admin-name-cell">
                        <div class="admin-avatar-circle">${initials}</div>
                        <div>
                            <strong>${escapeHtml(admin.name || 'Unknown')}</strong>
                            ${admin.username ? `<small>@${escapeHtml(admin.username)}</small>` : ''}
                        </div>
                    </div>
                </td>
                <td>
                    <div style="font-size:0.85rem;">
                        <div><i class="fas fa-envelope" style="color:#94a3b8;width:16px;"></i> ${escapeHtml(admin.email || '-')}</div>
                        ${admin.phone ? `<div><i class="fas fa-phone" style="color:#94a3b8;width:16px;"></i> ${escapeHtml(admin.phone)}</div>` : ''}
                    </div>
                </td>
                <td>
                    <span class="status-badge ${statusClass}">${statusText}</span>
                </td>
                <td style="font-size:0.85rem;">${joinDate}</td>
                <td>
                    <div class="admin-actions">

<button class="btn-action btn-view" onclick="viewAdminDetails('${admin.id}')" title="Tazama">
    <i class="fas fa-eye"></i> Tazama
</button>
                        <button class="btn-action btn-edit" onclick="editAdminAccount('${admin.id}')" title="Hariri">
                            <i class="fas fa-edit"></i> Hariri
                        </button>
                        ${status === 'approved' ? `
                            <button class="btn-action btn-toggle" onclick="toggleAdminStatus('${admin.id}', 'inactive', '${escapeHtml(admin.name)}')" title="Zima">
                                <i class="fas fa-ban"></i> Zima
                            </button>
                        ` : `
                            <button class="btn-action btn-toggle activate" onclick="toggleAdminStatus('${admin.id}', 'approved', '${escapeHtml(admin.name)}')" title="Washa">
                                <i class="fas fa-check"></i> Washa
                            </button>
                        `}
                        <button class="btn-action btn-reset-password" onclick="resetAdminPassword('${admin.id}', '${escapeHtml(admin.name)}')" title="Badilisha Nenosiri">
                            <i class="fas fa-key"></i> Nenosiri
                        </button>
                        <button class="btn-action btn-delete" onclick="deleteAdminAccount('${admin.id}', '${escapeHtml(admin.name)}')" title="Futa">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

// ============================================
// UPDATE ADMIN STATS
// ============================================
function updateAdminStats() {
    const totalEl = document.getElementById('totalAdminsCount');
    const activeEl = document.getElementById('activeAdminsCount');
    const pendingEl = document.getElementById('pendingAdminsCount');
    
    if (totalEl) totalEl.textContent = allAdmins.length;
    if (activeEl) activeEl.textContent = allAdmins.filter(a => a.status === 'approved').length;
    if (pendingEl) pendingEl.textContent = allAdmins.filter(a => a.status !== 'approved').length;
}

// ============================================
// ADD/EDIT ADMIN FORM SUBMISSION
// ============================================
function initAdminForm() {
    const form = document.getElementById('superAddAdminForm');
    if (!form) return;
    
    // Clone to remove old listeners
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);
    
    newForm.addEventListener('submit', async function(e) {
        e.preventDefault();
        
        const editId = document.getElementById('adminEditId')?.value;
        const fullName = document.getElementById('superAdminFullName')?.value?.trim();
        const email = document.getElementById('superAdminEmail')?.value?.trim();
        const password = document.getElementById('superAdminPassword')?.value;
        const phone = document.getElementById('superAdminPhone')?.value?.trim();
        
        // Validation
        if (!fullName) {
            showToast('❌ Tafadhali weka jina kamili', 'error');
            return;
        }
        if (!email) {
            showToast('❌ Tafadhali weka barua pepe', 'error');
            return;
        }
        
        // If editing, password is optional
        if (!editId && (!password || password.length < 6)) {
            showToast('❌ Nenosiri lazima iwe na angalau herufi 6', 'error');
            return;
        }
        
        const submitBtn = document.getElementById('adminSubmitBtn');
        const originalText = submitBtn?.innerHTML;
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
        }
        
        try {
            if (editId) {
                // Update existing admin
                const updateData = {
                    name: fullName,
                    email: email,
                    phone: phone || '',
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                };
                
                await db.collection('users').doc(editId).update(updateData);
                showToast('✅ Admin amesasishwa kikamilifu!', 'success');
                
            } else {
                // Check if email already exists
                const existingUsers = await db.collection('users')
                    .where('email', '==', email)
                    .get();
                
                if (!existingUsers.empty) {
                    showToast('❌ Barua pepe tayari inatumika', 'error');
                    if (submitBtn) {
                        submitBtn.disabled = false;
                        submitBtn.innerHTML = originalText;
                    }
                    return;
                }
                
// Create new admin
const userCredential = await auth.createUserWithEmailAndPassword(email, password);

// Save to Firestore
await db.collection('users').doc(userCredential.user.uid).set({
    name: fullName,
    email: email,
    phone: phone || '',
    role: 'admin',
    status: 'approved',
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
});
                
                showToast('✅ Admin ameongezwa kikamilifu!', 'success');
            }
            
            // Reset form
            resetAdminForm();
            
            // Refresh list
            await loadAdminsList();
            
        } catch (error) {
            console.error('Error saving admin:', error);
            let errorMsg = error.message;
            
            if (error.code === 'auth/email-already-in-use') {
                errorMsg = 'Barua pepe tayari inatumika na mtumiaji mwingine';
            } else if (error.code === 'auth/invalid-email') {
                errorMsg = 'Barua pepe si sahihi';
            } else if (error.code === 'auth/weak-password') {
                errorMsg = 'Nenosiri ni dhaifu sana';
            }
            
            showToast('❌ Kosa: ' + errorMsg, 'error');
            
        } finally {
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = originalText || '<i class="fas fa-plus"></i> Ongeza Admin';
            }
        }
    });
    
    console.log('✅ Admin form initialized');
}

