// ============================================
// TOGGLE ADMIN STATUS
// ============================================
async function toggleAdminStatus(adminId, newStatus, adminName) {
    const action = newStatus === 'inactive' ? 'kuzima' : 'kuwasha';
    
    if (!confirm(`Una uhakika unataka ${action} admin "${adminName}"?`)) return;
    
    try {
        await db.collection('users').doc(adminId).update({
            status: newStatus,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast(`✅ Admin "${adminName}" ${newStatus === 'approved' ? 'amewashwa' : 'amezimwa'}!`, 'success');
        await loadAdminsList();
        
    } catch (error) {
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

// ============================================
// RESET ADMIN PASSWORD
// ============================================
async function resetAdminPassword(adminId, adminName) {
    const newPassword = prompt(`Weka nenosiri jipya kwa admin "${adminName}" (angalau herufi 6):`);
    
    if (!newPassword) return;
    
    if (newPassword.length < 6) {
        showToast('❌ Nenosiri lazima iwe na angalau herufi 6', 'error');
        return;
    }
    
    // Confirm
    const confirmPassword = prompt('Thibitisha nenosiri jipya:');
    if (newPassword !== confirmPassword) {
        showToast('❌ Nenosiri hazifanani', 'error');
        return;
    }
    
    try {
        // Note: Client-side cannot change other users' passwords directly
        // This requires a Cloud Function or Firebase Admin SDK
        // For now, we'll store a password reset request
        await db.collection('passwordResetRequests').add({
            userId: adminId,
            requestedBy: currentUser?.uid || 'unknown',
            requestedByName: currentUser?.name || 'Super Admin',
            newPassword: newPassword, // In production, never store plain passwords!
            status: 'pending',
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('⚠️ Ombi la kubadilisha nenosiri limesafirishwa. Wasiliana na msimamizi wa mfumo.', 'info');
        
    } catch (error) {
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

// ============================================
// DELETE ADMIN ACCOUNT
// ============================================
async function deleteAdminAccount(adminId, adminName) {
    if (!confirm(`⚠️ UNA UHAKIKA?\n\nUnataka kufuta admin "${adminName}" kabisa?\n\nHii haiwezi kurejeshwa!`)) return;
    
    // Double confirmation
    if (!confirm(`THIBITISHA: Futa admin "${adminName}"?`)) return;
    
    try {
        // Delete from Firestore
        await db.collection('users').doc(adminId).delete();
        
        // Try to delete from Authentication (may fail without admin SDK)
        try {
            const user = await auth.currentUser;
            if (user && user.uid === adminId) {
                await user.delete();
            }
        } catch (authError) {
            console.log('Could not delete auth user:', authError);
        }
        
        showToast(`✅ Admin "${adminName}" amefutwa kikamilifu!`, 'success');
        
        // Refresh list
        await loadAdminsList();
        
    } catch (error) {
        console.error('Error deleting admin:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

// ============================================
// SEARCH & FILTER ADMINS
// ============================================
function searchAdmins() {
    const searchTerm = document.getElementById('adminSearchInput')?.value?.toLowerCase() || '';
    
    let filtered = allAdmins;
    
    // Apply status filter first
    if (adminFilterType === 'approved') {
        filtered = filtered.filter(a => a.status === 'approved');
    } else if (adminFilterType === 'inactive') {
        filtered = filtered.filter(a => a.status !== 'approved');
    }
    
    // Apply search
    if (searchTerm) {
        filtered = filtered.filter(a =>
            (a.name && a.name.toLowerCase().includes(searchTerm)) ||
            (a.email && a.email.toLowerCase().includes(searchTerm)) ||
            (a.phone && a.phone.toLowerCase().includes(searchTerm))
        );
    }
    
    renderAdminsList(filtered);
    
    // Update count
    const countBadge = document.getElementById('adminListCount');
    if (countBadge) {
        countBadge.textContent = `Inaonyesha: ${filtered.length} / ${allAdmins.length}`;
    }
}

function filterAdmins(type) {
    adminFilterType = type;
    
    // Update active tab
    document.querySelectorAll('#superManageAdmins .filter-tab').forEach(btn => {
        btn.classList.remove('active');
    });
    event?.target?.classList.add('active');
    
    searchAdmins();
}


