async function openNavAuthModal(adminId) {
    try {
        const doc = await db.collection('users').doc(adminId).get();
        if (!doc.exists) {
            showToast('Admin haikupatikana', 'error');
            return;
        }
        
        const admin = doc.data();
        const navPermissions = admin.navPermissions || {};
        
        document.getElementById('navAuthModalTitle').textContent =
            `Idhini ya Urambazaji - ${admin.name || 'Admin'}`;
        
        const content = document.getElementById('navAuthContent');
        
        // Group by category
        const categories = {};
        ADMIN_NAV_SECTIONS.forEach(section => {
            if (!categories[section.category]) {
                categories[section.category] = [];
            }
            categories[section.category].push(section);
        });
        
        const categoryLabels = {
            'users': 'Usimamizi wa Watumiaji',
            'students': 'Usimamizi wa Wanafunzi',
            'staff': 'Usimamizi wa Staff',
            'courses': 'Usimamizi wa Kozi',
            'content': 'Usimamizi wa Maudhui',
            'reports': 'Ripoti na Takwimu',
            'settings': 'Mipangilio ya Mfumo'
        };
        
        let html = `
            <!-- Quick Action Buttons -->
            <div style="display:flex;gap:0.5rem;margin-bottom:1rem;flex-wrap:wrap;position:sticky;top:0;background:white;z-index:5;padding:0.5rem 0;">
                <button onclick="toggleAllNavAuth(true)" class="modal-btn modal-btn-success" style="font-size:0.75rem;">
                    <i class="fas fa-check-double"></i> Chagua Zote
                </button>
                <button onclick="toggleAllNavAuth(false)" class="modal-btn modal-btn-danger" style="font-size:0.75rem;">
                    <i class="fas fa-times-circle"></i> Ondoa Zote
                </button>
            </div>
        `;
        
        // Build category sections
        for (const [category, sections] of Object.entries(categories)) {
            html += `
                <div class="nav-auth-category" style="margin-bottom:1.25rem;">
                    <h5 style="margin:0 0 0.5rem;color:#64748b;font-size:0.75rem;text-transform:uppercase;letter-spacing:0.5px;font-weight:600;">
                        <i class="fas fa-folder"></i> ${categoryLabels[category] || category}
                    </h5>
                    <div style="display:flex;flex-direction:column;gap:0.4rem;">
                        ${sections.map(section => {
                            const isChecked = navPermissions[section.id] === true;
                            return `
                                <label class="nav-auth-item" style="display:flex;align-items:center;gap:0.75rem;padding:0.6rem 0.75rem;background:${isChecked ? '#f0fdf4' : '#f8fafc'};border-radius:0.5rem;cursor:pointer;border:1px solid ${isChecked ? '#bbf7d0' : '#e2e8f0'};transition:all 0.2s;">
                                    <input type="checkbox" 
                                           class="nav-auth-checkbox" 
                                           data-section="${section.id}" 
                                           ${isChecked ? 'checked' : ''}
                                           onchange="updateNavAuthItemStyle(this)"
                                           style="width:18px;height:18px;accent-color:#e65c1e;cursor:pointer;">
                                    <div style="flex:1;">
                                        <span style="font-weight:500;color:#1e293b;font-size:0.85rem;">
                                            <i class="fas fa-${section.icon}" style="width:20px;color:#e65c1e;"></i> 
                                            ${section.label}
                                        </span>
                                    </div>
                                    <span class="auth-status-icon" style="color:${isChecked ? '#10b981' : '#94a3b8'};font-size:0.9rem;">
                                        <i class="fas fa-${isChecked ? 'check-circle' : 'circle'}"></i>
                                    </span>
                                </label>
                            `;
                        }).join('')}
                    </div>
                </div>
            `;
        }
        
        content.innerHTML = html;
        content.setAttribute('data-admin-id', adminId);
        
        // Show modal
        const modal = document.getElementById('navAuthModal');
        if (modal) {
            modal.style.display = 'flex';
            document.body.style.overflow = 'hidden';
        }
        
        // Add scroll shadow
        setTimeout(() => {
            addModalScrollShadow('navAuthModalBody');
        }, 200);
        
    } catch (error) {
        console.error('Error:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

