// ============================================
// UPDATE NAV AUTH ITEM STYLE
// ============================================
function updateNavAuthItemStyle(checkbox) {
    const label = checkbox.closest('.nav-auth-item');
    const statusIcon = label.querySelector('.auth-status-icon');
    
    if (checkbox.checked) {
        label.style.background = '#f0fdf4';
        label.style.borderColor = '#bbf7d0';
        if (statusIcon) {
            statusIcon.innerHTML = '<i class="fas fa-check-circle"></i>';
            statusIcon.style.color = '#10b981';
        }
    } else {
        label.style.background = '#f8fafc';
        label.style.borderColor = '#e2e8f0';
        if (statusIcon) {
            statusIcon.innerHTML = '<i class="fas fa-circle"></i>';
            statusIcon.style.color = '#94a3b8';
        }
    }
}

