// ============================================
function toggleAllNavAuth(selectAll) {
    const checkboxes = document.querySelectorAll('.nav-auth-checkbox');
    checkboxes.forEach(checkbox => {
        checkbox.checked = selectAll;
        updateNavAuthItemStyle(checkbox);
    });
}

// ============================================
// SAVE NAVIGATION AUTHORIZATION
// ============================================
async function saveNavAuthorization() {
    const content = document.getElementById('navAuthContent');
    const adminId = content?.getAttribute('data-admin-id');
    
    if (!adminId) {
        showToast('❌ Admin haijatambuliwa', 'error');
        return;
    }
    
    // Collect all checkbox values
    const navPermissions = {};
    const checkboxes = document.querySelectorAll('.nav-auth-checkbox');
    
    checkboxes.forEach(checkbox => {
        const sectionId = checkbox.getAttribute('data-section');
        navPermissions[sectionId] = checkbox.checked;
    });
    
    // Count authorized sections
    const authorizedCount = Object.values(navPermissions).filter(v => v === true).length;
    
    const saveBtn = document.querySelector('#navAuthModal .btn-primary') ||
        document.querySelector('#navAuthModal button[style*="background:#e65c1e"]');
    const originalHTML = saveBtn?.innerHTML;
    
    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inahifadhi...';
    }
    
    try {
        // Update Firestore
        await db.collection('users').doc(adminId).update({
            navPermissions: navPermissions,
            navPermissionsUpdatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            navPermissionsUpdatedBy: currentUser?.uid || 'unknown',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast(`✅ Idhini zimehifadhiwa! (${authorizedCount}/${ADMIN_NAV_SECTIONS.length} sehemu)`, 'success');
        
        // Close nav auth modal
        closeNavAuthModal();
        
        // Refresh admin details modal if still open
        if (document.getElementById('adminDetailsModal')?.style.display === 'flex') {
            await viewAdminDetails(adminId);
        }
        
        // Refresh admins list
        if (typeof loadAdminsList === 'function') {
            await loadAdminsList();
        }
        
    } catch (error) {
        console.error('Error saving nav permissions:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    } finally {
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = originalHTML || '<i class="fas fa-save"></i> Hifadhi';
        }
    }
}

