// ============================================
// MODAL SCROLL DETECTION
// ============================================

/**
 * Add scroll shadow effect to modal body
 * @param {string} modalBodyId - The ID of the modal body element
 */
function addModalScrollShadow(modalBodyId) {
    const modalBody = document.getElementById(modalBodyId);
    if (!modalBody) return;
    
    function updateScrollShadow() {
        const hasScroll = modalBody.scrollHeight > modalBody.clientHeight;
        const isAtTop = modalBody.scrollTop <= 5;
        const isAtBottom = modalBody.scrollTop + modalBody.clientHeight >= modalBody.scrollHeight - 5;
        
        if (!hasScroll) {
            modalBody.style.boxShadow = 'none';
            return;
        }
        
        if (isAtTop) {
            modalBody.style.boxShadow = 'inset 0 -10px 10px -10px rgba(0,0,0,0.1)';
        } else if (isAtBottom) {
            modalBody.style.boxShadow = 'inset 0 10px 10px -10px rgba(0,0,0,0.1)';
        } else {
            modalBody.style.boxShadow = 'inset 0 10px 10px -10px rgba(0,0,0,0.1), inset 0 -10px 10px -10px rgba(0,0,0,0.1)';
        }
    }
    
    modalBody.addEventListener('scroll', updateScrollShadow);
    // Initial check
    setTimeout(updateScrollShadow, 100);
}

/**
 * Scroll to top of modal body
 * @param {string} modalBodyId - The ID of the modal body element
 */
function scrollModalToTop(modalBodyId) {
    const modalBody = document.getElementById(modalBodyId);
    if (modalBody) {
        modalBody.scrollTo({ top: 0, behavior: 'smooth' });
    }
}

/**
 * Scroll to bottom of modal body
 * @param {string} modalBodyId - The ID of the modal body element
 */
function scrollModalToBottom(modalBodyId) {
    const modalBody = document.getElementById(modalBodyId);
    if (modalBody) {
        modalBody.scrollTo({ 
            top: modalBody.scrollHeight, 
            behavior: 'smooth' 
        });
    }
}

/**
 * Check if modal has scroll and show indicator
 * @param {string} modalBodyId - The ID of the modal body element
 */
function showScrollIndicator(modalBodyId) {
    const modalBody = document.getElementById(modalBodyId);
    if (!modalBody) return;
    
    const hasScroll = modalBody.scrollHeight > modalBody.clientHeight;
    
    // Remove existing indicator
    const existingIndicator = document.querySelector('.scroll-indicator-hint');
    if (existingIndicator) existingIndicator.remove();
    
    if (hasScroll && modalBody.scrollTop <= 5) {
        const indicator = document.createElement('div');
        indicator.className = 'scroll-indicator-hint';
        indicator.innerHTML = '<i class="fas fa-chevron-down"></i> Tembeza chini kuona zaidi';
        indicator.style.cssText = `
            position: absolute;
            bottom: 80px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0,0,0,0.7);
            color: white;
            padding: 0.4rem 1rem;
            border-radius: 2rem;
            font-size: 0.75rem;
            pointer-events: none;
            animation: bounce 1.5s infinite;
            z-index: 5;
        `;
        modalBody.style.position = 'relative';
        modalBody.appendChild(indicator);
        
        // Remove after first scroll
        const removeIndicator = () => {
            indicator.remove();
            modalBody.removeEventListener('scroll', removeIndicator);
        };
        modalBody.addEventListener('scroll', removeIndicator);
        
        // Auto remove after 5 seconds
        setTimeout(() => {
            if (indicator.parentElement) indicator.remove();
        }, 5000);
    }
}

