// Add this to your main.js - it will handle ALL modals properly
document.addEventListener('DOMContentLoaded', function() {
    // Fix all modal overlays - prevent closing when scrolling
    document.querySelectorAll('.modal-overlay').forEach(overlay => {
        // Only allow close when clicking directly on the overlay (not its children)
        overlay.addEventListener('click', function(e) {
            if (e.target === this) {
                // Close the modal
                this.style.display = 'none';
                document.body.style.overflow = '';
                
                // Remove active class if it exists
                this.classList.remove('active');
            }
        });
        
        // Prevent scroll events from bubbling up
        const scrollableContent = overlay.querySelector('.modal-body, .modal-body-scrollable');
        if (scrollableContent) {
            scrollableContent.addEventListener('touchmove', function(e) {
                e.stopPropagation();
            }, { passive: false });
            
            scrollableContent.addEventListener('wheel', function(e) {
                e.stopPropagation();
            }, { passive: false });
        }
    });
    
    // Stop propagation on all modal containers
    document.querySelectorAll('.modal-container, .modal-container-scrollable').forEach(container => {
        container.addEventListener('click', function(e) {
            e.stopPropagation();
        });
        
        container.addEventListener('touchstart', function(e) {
            e.stopPropagation();
        });
    });
});  

