// ============================================
// SUPER ADMIN STAFF MANAGEMENT
// ============================================

let superStaffMembers = [];
let superStaffFilter = 'all';

async function loadSuperStaffList() {
    console.log('Loading super admin staff list...');
    
    const container = document.getElementById('superStaffTableBody');
    const emptyState = document.getElementById('superStaffEmpty');
    const countBadge = document.getElementById('superStaffCount');
    
    if (!container) {
        console.error('superStaffTableBody not found');
        return;
    }
    
    container.innerHTML = '<tr><td colspan="7" class="text-center"><div class="loading-spinner">Inapakia staff...</div></td></tr>';
    
    try {
        const snapshot = await db.collection('users')
            .where('role', '==', 'staff')
            .get();
        
        superStaffMembers = [];
        snapshot.forEach(doc => {
            superStaffMembers.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by name
        superStaffMembers.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        
        // Update stats
        document.getElementById('superTotalStaffCount').textContent = superStaffMembers.length;
        document.getElementById('superActiveStaffCount').textContent = superStaffMembers.filter(s => s.status === 'approved').length;
        document.getElementById('superInactiveStaffCount').textContent = superStaffMembers.filter(s => s.status !== 'approved').length;
        
        // Update count
        if (countBadge) countBadge.textContent = `Jumla: ${superStaffMembers.length} Staff`;
        
        if (superStaffMembers.length === 0) {
            container.innerHTML = '';
            if (emptyState) emptyState.style.display = 'block';
            return;
        }
        
        if (emptyState) emptyState.style.display = 'none';
        
        // Render
        renderSuperStaffList(superStaffMembers);
        
        console.log(`✅ Loaded ${superStaffMembers.length} staff`);
        
    } catch (error) {
        console.error('Error:', error);
        container.innerHTML = `<tr><td colspan="7" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

function renderSuperStaffList(staffList) {
    const container = document.getElementById('superStaffTableBody');
    
    if (!staffList || staffList.length === 0) {
        container.innerHTML = '<tr><td colspan="7" class="text-center">Hakuna staff wanaofanana na vigezo</td></tr>';
        return;
    }
    
    container.innerHTML = staffList.map((staff, index) => {
        const initials = (staff.name || 'S').charAt(0).toUpperCase();
        const status = staff.status || 'approved';
        const statusClass = status === 'approved' ? 'status-active' : 'status-inactive';
        const statusText = status === 'approved' ? 'Active' : 'Inactive';
        const modules = staff.assignedModules || [];
        const joinDate = staff.createdAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-';
        
        return `
            <tr>
                <td class="text-center">${index + 1}</td>
                <td>
                    <div style="display:flex;align-items:center;gap:0.75rem;">
                        <div style="width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,#e65c1e,#f97316);display:flex;align-items:center;justify-content:center;">
                            <span style="color:white;font-weight:700;">${initials}</span>
                        </div>
                        <div>
                            <strong>${escapeHtml(staff.name || 'Unknown')}</strong>
                        </div>
                    </div>
                </td>
                <td>
                    <div><i class="fas fa-envelope"></i> ${escapeHtml(staff.email || '-')}</div>
                    ${staff.phone ? `<div><i class="fas fa-phone"></i> ${escapeHtml(staff.phone)}</div>` : ''}
                </td>
                <td class="text-center">
                    <span style="padding:0.2rem 0.6rem;background:#e0e7ff;color:#4f46e5;border-radius:1rem;font-size:0.75rem;">
                        <i class="fas fa-cubes"></i> ${modules.length}
                    </span>
                </td>
                <td class="text-center">
                    <span class="status-badge ${statusClass}">${statusText}</span>
                </td>
                <td class="text-center">${joinDate}</td>
                <td class="text-center">
                    <div style="display:flex;gap:0.25rem;justify-content:center;flex-wrap:wrap;">
                        <button onclick="superViewStaffDetails('${staff.id}')" style="padding:0.3rem 0.5rem;background:#3b82f6;color:white;border:none;border-radius:0.3rem;cursor:pointer;font-size:0.7rem;"><i class="fas fa-eye"></i></button>
                        <button onclick="superEditStaffModal('${staff.id}')" style="padding:0.3rem 0.5rem;background:#f59e0b;color:white;border:none;border-radius:0.3rem;cursor:pointer;font-size:0.7rem;"><i class="fas fa-edit"></i></button>
                        ${status === 'approved' ? 
                            `<button onclick="superToggleStaffStatus('${staff.id}','inactive','${escapeHtml(staff.name)}')" style="padding:0.3rem 0.5rem;background:#64748b;color:white;border:none;border-radius:0.3rem;cursor:pointer;font-size:0.7rem;"><i class="fas fa-ban"></i></button>` :
                            `<button onclick="superToggleStaffStatus('${staff.id}','approved','${escapeHtml(staff.name)}')" style="padding:0.3rem 0.5rem;background:#10b981;color:white;border:none;border-radius:0.3rem;cursor:pointer;font-size:0.7rem;"><i class="fas fa-check"></i></button>`
                        }
                        <button onclick="superDeleteStaff('${staff.id}','${escapeHtml(staff.name)}')" style="padding:0.3rem 0.5rem;background:#ef4444;color:white;border:none;border-radius:0.3rem;cursor:pointer;font-size:0.7rem;"><i class="fas fa-trash"></i></button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

function searchSuperStaff() {
    const searchTerm = document.getElementById('superStaffSearchInput')?.value?.toLowerCase() || '';
    let filtered = superStaffMembers;
    
    if (superStaffFilter === 'active') {
        filtered = filtered.filter(s => s.status === 'approved');
    } else if (superStaffFilter === 'inactive') {
        filtered = filtered.filter(s => s.status !== 'approved');
    }
    
    if (searchTerm) {
        filtered = filtered.filter(s =>
            (s.name && s.name.toLowerCase().includes(searchTerm)) ||
            (s.email && s.email.toLowerCase().includes(searchTerm))
        );
    }
    
    renderSuperStaffList(filtered);
    document.getElementById('superStaffCount').textContent = `Inaonyesha: ${filtered.length} / ${superStaffMembers.length}`;
}

function filterSuperStaff(status) {
    superStaffFilter = status;
    
    document.querySelectorAll('#superManageStaff .filter-tab').forEach(btn => {
        btn.classList.remove('active');
        btn.style.background = 'transparent';
        btn.style.color = '#64748b';
    });
    
    if (event?.target) {
        event.target.classList.add('active');
        event.target.style.background = 'white';
        event.target.style.color = '#1e293b';
    }
    
    searchSuperStaff();
}

