async function openSuperAddStaffModal() {
    await loadModulesForSuperStaffAdd();
    document.getElementById('superStaffAddForm').reset();
    document.getElementById('superStaffAddModal').style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

function closeSuperStaffAddModal() {
    document.getElementById('superStaffAddModal').style.display = 'none';
    document.body.style.overflow = '';
}

async function loadModulesForSuperStaffAdd() {
    const container = document.getElementById('superStaffAddModulesContainer');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia moduli...</div>';
    
    try {
        const snapshot = await db.collection('modules').where('active', '==', true).orderBy('code').get();
        
        if (snapshot.empty) {
            container.innerHTML = '<p style="color:#94a3b8;text-align:center;padding:1rem;">Hakuna moduli</p>';
            return;
        }
        
        let html = '';
        snapshot.forEach(doc => {
            const mod = doc.data();
            html += `
                <label style="display:flex;align-items:center;gap:0.5rem;padding:0.35rem 0.5rem;cursor:pointer;font-size:0.85rem;border-radius:0.3rem;">
                    <input type="checkbox" data-code="${escapeHtml(mod.code)}" data-name="${escapeHtml(mod.name)}" style="accent-color:#e65c1e;">
                    <span><strong>${escapeHtml(mod.code)}</strong> - ${escapeHtml(mod.name)}</span>
                </label>
            `;
        });
        container.innerHTML = html;
    } catch (error) {
        container.innerHTML = `<p style="color:red;">Kosa: ${error.message}</p>`;
    }
}

async function saveNewSuperStaff() {
    const name = document.getElementById('superStaffAddName')?.value?.trim();
    const email = document.getElementById('superStaffAddEmail')?.value?.trim();
    const phone = document.getElementById('superStaffAddPhone')?.value?.trim();
    const password = document.getElementById('superStaffAddPassword')?.value;
    
    if (!name || !email || !password || password.length < 6) {
        showToast('❌ Jaza sehemu zote muhimu. Nenosiri lazima liwe na herufi 6+', 'error');
        return;
    }
    
    // Get selected modules
    const selectedModules = [];
    document.querySelectorAll('#superStaffAddModulesContainer input[type="checkbox"]:checked').forEach(cb => {
        selectedModules.push({ code: cb.dataset.code, name: cb.dataset.name });
    });
    
    try {
        const existingUsers = await db.collection('users').where('email', '==', email).get();
        if (!existingUsers.empty) {
            showToast('❌ Barua pepe tayari inatumika', 'error');
            return;
        }
        
        const userCredential = await auth.createUserWithEmailAndPassword(email, password);
        
        await db.collection('users').doc(userCredential.user.uid).set({
            name, email, phone: phone || '', role: 'staff',
            status: 'approved', assignedModules: selectedModules,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ Staff ameongezwa!', 'success');
        closeSuperStaffAddModal();
        await loadSuperStaffList();
        
    } catch (error) {
        showToast('❌ Kosa: ' + (error.code === 'auth/email-already-in-use' ? 'Barua pepe tayari inatumika' : error.message), 'error');
    }
}

