async function superEditStaffModal(staffId) {
    const doc = await db.collection('users').doc(staffId).get();
    if (!doc.exists) return;
    
    const staff = doc.data();
    
    document.getElementById('superStaffEditId').value = staffId;
    document.getElementById('superStaffEditName').value = staff.name || '';
    document.getElementById('superStaffEditEmail').value = staff.email || '';
    document.getElementById('superStaffEditPhone').value = staff.phone || '';
    document.getElementById('superStaffEditPassword').value = '';
    document.getElementById('superStaffEditStatus').value = staff.status || 'approved';
    document.getElementById('superStaffEditTitle').textContent = 'Hariri: ' + (staff.name || 'Staff');
    
    await loadModulesForSuperStaffEdit(staff.assignedModules || []);
    
    document.getElementById('superStaffEditModal').style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

function closeSuperStaffEditModal() {
    document.getElementById('superStaffEditModal').style.display = 'none';
    document.body.style.overflow = '';
}

async function loadModulesForSuperStaffEdit(assignedModules) {
    const container = document.getElementById('superStaffEditModulesContainer');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia moduli...</div>';
    
    try {
        const snapshot = await db.collection('modules').where('active', '==', true).orderBy('code').get();
        const assignedCodes = new Set(assignedModules.map(m => m.code));
        
        if (snapshot.empty) {
            container.innerHTML = '<p style="color:#94a3b8;">Hakuna moduli</p>';
            return;
        }
        
        let html = '';
        snapshot.forEach(doc => {
            const mod = doc.data();
            const isAssigned = assignedCodes.has(mod.code);
            html += `
                <label style="display:flex;align-items:center;gap:0.5rem;padding:0.35rem 0.5rem;cursor:pointer;font-size:0.85rem;background:${isAssigned ? '#f0fdf4' : 'transparent'};border-radius:0.3rem;border:1px solid ${isAssigned ? '#bbf7d0' : 'transparent'};">
                    <input type="checkbox" data-code="${escapeHtml(mod.code)}" data-name="${escapeHtml(mod.name)}" ${isAssigned ? 'checked' : ''} style="accent-color:#e65c1e;">
                    <span><strong>${escapeHtml(mod.code)}</strong> - ${escapeHtml(mod.name)}</span>
                </label>
            `;
        });
        container.innerHTML = html;
    } catch (error) {
        container.innerHTML = `<p style="color:red;">Kosa: ${error.message}</p>`;
    }
}

async function saveSuperStaffEdit() {
    const staffId = document.getElementById('superStaffEditId')?.value;
    const name = document.getElementById('superStaffEditName')?.value?.trim();
    const email = document.getElementById('superStaffEditEmail')?.value?.trim();
    const phone = document.getElementById('superStaffEditPhone')?.value?.trim();
    const password = document.getElementById('superStaffEditPassword')?.value;
    const status = document.getElementById('superStaffEditStatus')?.value;
    
    if (!name || !email) {
        showToast('❌ Jaza jina na barua pepe', 'error');
        return;
    }
    
    const selectedModules = [];
    document.querySelectorAll('#superStaffEditModulesContainer input[type="checkbox"]:checked').forEach(cb => {
        selectedModules.push({ code: cb.dataset.code, name: cb.dataset.name });
    });
    
    try {
        const updateData = {
            name, email, phone: phone || '', status,
            assignedModules: selectedModules,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        await db.collection('users').doc(staffId).update(updateData);
        
        if (password && password.length >= 6) {
            await db.collection('passwordChangeRequests').add({
                userId: staffId, newPassword: password,
                requestedBy: currentUser?.uid,
                status: 'pending',
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        }
        
        showToast('✅ Staff amesasishwa!', 'success');
        closeSuperStaffEditModal();
        await loadSuperStaffList();
        
    } catch (error) {
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

