// ============================================
// ADMISSION WINDOW SYSTEM
// ============================================

let currentActiveAdmissionWindow = null;
let allAdmissionWindows = [];
let selectedApplicationCourse = null;
let applicationCertFiles = { olevel: null, alevel: null };
let admissionWindowCheckInterval = null;

// ============================================
// CHECK ADMISSION STATUS ON PAGE LOAD
// ============================================
async function checkAdmissionStatus() {
    console.log('🔍 Checking admission window status...');
    
    const now = new Date();
    
    try {
        // Get all active admission windows
        const snapshot = await db.collection('admissionWindows')
            .where('status', '==', 'active')
            .get();
        
        let activeWindow = null;
        
        snapshot.forEach(doc => {
            const window = { id: doc.id, ...doc.data() };
            
            // Parse dates
            const startDate = window.startDate?.toDate?.() || new Date(window.startDate);
            const endDate = window.endDate?.toDate?.() || new Date(window.endDate);
            
            // Combine with times
            if (window.startTime) {
                const [h, m] = window.startTime.split(':').map(Number);
                startDate.setHours(h || 0, m || 0, 0, 0);
            }
            if (window.endTime) {
                const [h, m] = window.endTime.split(':').map(Number);
                endDate.setHours(h || 23, m || 59, 0, 0);
            }
            
            // Check if currently active
            if (now >= startDate && now <= endDate) {
                activeWindow = window;
                window.isActive = true;
                window.expiryDate = endDate;
            }
            
            allAdmissionWindows.push(window);
        });
        
        currentActiveAdmissionWindow = activeWindow;
        
        // Update UI
        updateAdmissionUI(activeWindow);
        
        // Start countdown timer if active
        if (activeWindow) {
            startAdmissionCountdown(activeWindow.expiryDate);
        }
        
        console.log('✅ Admission status checked:', activeWindow ? 'ACTIVE' : 'NO ACTIVE WINDOW');
        
    } catch (error) {
        console.error('Error checking admission:', error);
    }
}

// ============================================
// UPDATE ADMISSION UI ON HOMEPAGE
// ============================================
function updateAdmissionUI(activeWindow) {
    const applyBtn = document.getElementById('heroApplyBtn');
    const joinBtn = document.getElementById('heroJoinBtn');
    const noAdmission = document.getElementById('heroNoAdmission');
    
    if (activeWindow) {
        // Show Apply button
        if (applyBtn) {
            applyBtn.style.display = 'inline-block';
            applyBtn.textContent = `Tuma Maombi - ${activeWindow.name || 'Dirisha la Maombi'}`;
        }
        
        // Show "Already Applied" button
        if (joinBtn) {
            joinBtn.style.display = 'inline-block';
        }
        
        // Hide no admission message
        if (noAdmission) {
            noAdmission.style.display = 'none';
        }
    } else {
        // Hide Apply button
        if (applyBtn) {
            applyBtn.style.display = 'none';
        }
        
        // Still show login button but with modified text
        if (joinBtn) {
            joinBtn.style.display = 'inline-block';
            joinBtn.textContent = 'Ingia kwenye Akaunti Yako';
        }
        
        // Show no admission message
        if (noAdmission) {
            noAdmission.style.display = 'block';
        }
    }
}

