// ============================================
function openApplicationWindow() {
    if (!currentActiveAdmissionWindow) {
        showToast('Samahani, hakuna dirisha la maombi lililofunguliwa kwa sasa.', 'warning');
        return;
    }
    
    console.log('📝 Opening application window...');
    
    // Hide home page
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    document.getElementById('homePage').classList.remove('active');
    document.getElementById('homePage').style.display = 'none';
    
    // Show application page
    const appPage = document.getElementById('applicationPage');
    if (appPage) {
        appPage.classList.add('active');
        appPage.style.display = 'block';
        
        // Set window name
        document.getElementById('appWindowNameDisplay').textContent = currentActiveAdmissionWindow.name || 'Dirisha la Maombi';
        
        // Set active window info
        document.getElementById('appWinTitle').textContent = currentActiveAdmissionWindow.name || 'Dirisha la Maombi';
        document.getElementById('appWinDesc').textContent = currentActiveAdmissionWindow.description || 'Jaza taarifa zako kwa usahihi.';
        
        document.getElementById('appActiveWindowInfo').style.display = 'block';
        
        // Start countdown
        startAppWindowCountdown(currentActiveAdmissionWindow.expiryDate);
        
        // Load courses for this window
        loadCoursesForApplication();
        
        // Reset to step 1
        goToApplicationStep(1);
        
        // Scroll to top
        window.scrollTo(0, 0);
    }
}

