// ============================================
function closeApplicationWindow() {
    const appPage = document.getElementById('applicationPage');
    if (appPage) {
        appPage.classList.remove('active');
        appPage.style.display = 'none';
    }
    
    // Show home page
    const homePage = document.getElementById('homePage');
    if (homePage) {
        homePage.classList.add('active');
        homePage.style.display = 'block';
    }
    
    // Reset form
    resetApplicationForm();
    window.scrollTo(0, 0);
}

// ============================================
// START COUNTDOWN TIMER
// ============================================
function startAppWindowCountdown(expiryDate) {
    // Clear any existing timer
    if (admissionWindowCheckInterval) {
        clearInterval(admissionWindowCheckInterval);
    }
    
    function updateCountdown() {
        const now = new Date();
        const remaining = expiryDate - now;
        
        if (remaining <= 0) {
            document.getElementById('appWinCountdown').textContent = 'Imekwisha!';
            document.getElementById('finalSubmitBtn').disabled = true;
            document.getElementById('finalSubmitBtn').textContent = 'Dirisha Imefungwa';
            document.getElementById('finalSubmitBtn').style.opacity = '0.5';
            clearInterval(admissionWindowCheckInterval);
            showToast('Dirisha la maombi limefungwa!', 'error');
            return;
        }
        
        const days = Math.floor(remaining / (1000 * 60 * 60 * 24));
        const hours = Math.floor((remaining % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
        
        let display = '';
        if (days > 0) display += `${days}s `;
        if (hours > 0 || days > 0) display += `${hours}h `;
        display += `${minutes}m`;
        
        document.getElementById('appWinCountdown').textContent = display;
        
        // Warn when less than 1 hour remaining
        if (remaining < 3600000 && remaining > 0) {
            document.getElementById('appWinCountdown').style.color = '#ef4444';
        }
    }
    
    updateCountdown();
    admissionWindowCheckInterval = setInterval(updateCountdown, 60000); // Update every minute
}

// ============================================
// LOAD COURSES FOR APPLICATION
// ============================================
async function loadCoursesForApplication() {
    const container = document.getElementById('appCoursesGrid');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia kozi zinazopatikana...</div>';
    
    try {
        // Get courses specified for this admission window OR all active courses
        let courseIds = currentActiveAdmissionWindow?.courseIds || [];
        
        let courses = [];
        
        if (courseIds.length > 0) {
            // Load specified courses
            for (const courseId of courseIds) {
                const doc = await db.collection('courses').doc(courseId).get();
                if (doc.exists && doc.data().active) {
                    courses.push({ id: doc.id, ...doc.data() });
                }
            }
        } else {
            // Load all active courses
            const snapshot = await db.collection('courses')
                .where('active', '==', true)
                .get();
            snapshot.forEach(doc => {
                courses.push({ id: doc.id, ...doc.data() });
            });
        }
        
        if (courses.length === 0) {
            container.innerHTML = `
                <div style="grid-column:1/-1;text-align:center;padding:2rem;color:#64748b;">
                    <i class="fas fa-info-circle" style="font-size:2rem;display:block;margin-bottom:0.5rem;"></i>
                    <p>Hakuna kozi zinazopatikana kwa dirisha hili.</p>
                </div>`;
            return;
        }
        
        container.innerHTML = courses.map(course => `
            <div class="course-card app-course-card" 
                 onclick="selectApplicationCourse('${course.id}', '${escapeHtml(course.name)}', this)"
                 style="cursor:pointer;border:2px solid #e2e8f0;transition:all 0.3s ease;border-radius:1rem;padding:1.5rem;text-align:center;">
                <div class="course-icon" style="width:60px;height:60px;background:linear-gradient(135deg,#e65c1e,#f97316);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 1rem;">
                    <i class="fas fa-${course.icon || 'book'}" style="font-size:1.5rem;color:white;"></i>
                </div>
                <h4 style="font-size:1rem;color:#1e293b;margin-bottom:0.5rem;">${escapeHtml(course.name)}</h4>
                <span style="display:inline-block;padding:0.25rem 0.75rem;background:#f1f5f9;border-radius:2rem;font-size:0.75rem;color:#64748b;">
                    ${escapeHtml(course.duration || 'Miezi 6')}
                </span>
                ${course.fee ? `<p style="font-size:0.85rem;color:#e65c1e;font-weight:600;margin-top:0.5rem;">TZS ${course.fee.toLocaleString()}</p>` : ''}
            </div>
        `).join('');
        
    } catch (error) {
        console.error('Error loading courses:', error);
        container.innerHTML = `<p class="error-text">Imeshindwa kupakia kozi: ${error.message}</p>`;
    }
}

// ============================================
// SELECT COURSE FOR APPLICATION
// ============================================
function selectApplicationCourse(courseId, courseName, element) {
    // Remove selection from all cards
    document.querySelectorAll('.app-course-card').forEach(card => {
        card.style.borderColor = '#e2e8f0';
        card.style.background = 'white';
    });
    
    // Highlight selected card
    if (element) {
        element.style.borderColor = '#e65c1e';
        element.style.background = '#fff7ed';
    }
    
    selectedApplicationCourse = { id: courseId, name: courseName };
    
    // Enable next button
    const nextBtn = document.getElementById('appStep1Next');
    if (nextBtn) {
        nextBtn.disabled = false;
        nextBtn.style.opacity = '1';
    }
    
    console.log('Selected course:', selectedApplicationCourse);
}

// ============================================
// GO TO APPLICATION STEP
// ============================================
function goToApplicationStep(stepNumber) {
    // Validate current step before proceeding
    if (stepNumber > 1) {
        if (stepNumber === 2 && !selectedApplicationCourse) {
            showToast('Tafadhali chagua kozi kwanza.', 'error');
            return;
        }
        if (stepNumber === 3) {
            const name = document.getElementById('appFullName')?.value?.trim();
            const email = document.getElementById('appEmail')?.value?.trim();
            const phone = document.getElementById('appPhone')?.value?.trim();
            const kinName = document.getElementById('appKinName')?.value?.trim();
            const kinPhone = document.getElementById('appKinPhone')?.value?.trim();
            
            if (!name || !email || !phone) {
                showToast('Tafadhali jaza jina, barua pepe, na simu yako.', 'error');
                return;
            }
            if (!kinName || !kinPhone) {
                showToast('Tafadhali jaza taarifa za mzazi/mlezi.', 'error');
                return;
            }
        }
        if (stepNumber === 4) {
            // Generate summary
            generateApplicationSummary();
        }
    }
    
    // Hide all steps
    document.querySelectorAll('.app-step-content').forEach(step => {
        step.style.display = 'none';
    });
    
    // Show target step
    const targetStep = document.getElementById(`appStep${stepNumber}`);
    if (targetStep) {
        targetStep.style.display = 'block';
    }
    
    // Update progress bar
    document.querySelectorAll('.progress-step').forEach((stepEl, index) => {
        const stepNum = index + 1;
        const circle = stepEl.querySelector('.step-circle');
        const label = stepEl.querySelector('span');
        
        if (stepNum < stepNumber) {
            // Completed
            circle.style.background = '#10b981';
            circle.style.color = 'white';
            circle.textContent = '✓';
            label.style.color = '#10b981';
        } else if (stepNum === stepNumber) {
            // Active
            circle.style.background = '#e65c1e';
            circle.style.color = 'white';
            circle.textContent = stepNum;
            label.style.color = '#e65c1e';
        } else {
            // Future
            circle.style.background = '#e2e8f0';
            circle.style.color = '#64748b';
            circle.textContent = stepNum;
            label.style.color = '#64748b';
        }
    });
    
    // Scroll to top
    window.scrollTo({ top: 100, behavior: 'smooth' });
}

// ============================================
// GENERATE APPLICATION SUMMARY
// ============================================
function generateApplicationSummary() {
    const summary = document.getElementById('applicationSummary');
    if (!summary) return;
    
    const courseName = selectedApplicationCourse?.name || 'Haijachaguliwa';
    const fullName = document.getElementById('appFullName')?.value || '-';
    const email = document.getElementById('appEmail')?.value || '-';
    const phone = document.getElementById('appPhone')?.value || '-';
    const dob = document.getElementById('appDOB')?.value || '-';
    const gender = document.getElementById('appGender')?.value === 'male' ? 'Me' : 
                   document.getElementById('appGender')?.value === 'female' ? 'Ke' : '-';
    const nationality = document.getElementById('appNationality')?.value || '-';
    const address = document.getElementById('appAddress')?.value || '-';
    const kinName = document.getElementById('appKinName')?.value || '-';
    const kinRel = document.getElementById('appKinRelationship')?.value || '-';
    const kinPhone = document.getElementById('appKinPhone')?.value || '-';
    
    const olevelFile = applicationCertFiles.olevel ? '✅ Imepakiwa' : '❌ Haijapakiwa';
    const alevelFile = applicationCertFiles.alevel ? '✅ Imepakiwa' : '⚠️ Haijapakiwa (Optional)';
    
    summary.innerHTML = `
        <h4 style="margin-bottom:1rem;color:#1e293b;"><i class="fas fa-clipboard-list"></i> Muhtasari wa Maombi</h4>
        
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:0.75rem;font-size:0.9rem;">
            <div><strong style="color:#64748b;">Kozi:</strong></div>
            <div><span style="background:#fff7ed;color:#e65c1e;padding:0.2rem 0.6rem;border-radius:0.3rem;font-weight:600;">${escapeHtml(courseName)}</span></div>
            
            <div><strong style="color:#64748b;">Jina Kamili:</strong></div>
            <div>${escapeHtml(fullName)}</div>
            
            <div><strong style="color:#64748b;">Barua Pepe:</strong></div>
            <div>${escapeHtml(email)}</div>
            
            <div><strong style="color:#64748b;">Simu:</strong></div>
            <div>${escapeHtml(phone)}</div>
            
            <div><strong style="color:#64748b;">Tarehe ya Kuzaliwa:</strong></div>
            <div>${dob}</div>
            
            <div><strong style="color:#64748b;">Jinsia:</strong></div>
            <div>${gender}</div>
            
            <div><strong style="color:#64748b;">Mzazi/Mlezi:</strong></div>
            <div>${escapeHtml(kinName)} (${escapeHtml(kinRel)}) - ${escapeHtml(kinPhone)}</div>
            
            <div><strong style="color:#64748b;">O-Level Cheti:</strong></div>
            <div>${olevelFile}</div>
            
            <div><strong style="color:#64748b;">A-Level Cheti:</strong></div>
            <div>${alevelFile}</div>
        </div>
    `;
}

// ============================================
// PREVIEW CERTIFICATE FILE
// ============================================
function previewAppCertFile(event, type) {
    const file = event.target.files[0];
    if (!file) return;
    
    // Validate
    const validTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    if (!validTypes.includes(file.type)) {
        showToast('File type not supported. Use PDF, JPG, or PNG.', 'error');
        event.target.value = '';
        return;
    }
    
    if (file.size > 5 * 1024 * 1024) {
        showToast('File too large. Max 5MB.', 'error');
        event.target.value = '';
        return;
    }
    
    applicationCertFiles[type] = file;
    
    // Update preview
    const preview = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}Preview`);
    const fileName = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}FileName`);
    
    if (preview) preview.style.display = 'block';
    if (fileName) {
        fileName.textContent = `✅ ${file.name} (${(file.size / 1024).toFixed(1)} KB)`;
    }
}

// ============================================
// SUBMIT APPLICATION
// ============================================
async function submitApplication() {
    if (!selectedApplicationCourse) {
        showToast('Tafadhali chagua kozi.', 'error');
        return;
    }
    
    // Validate O-Level certificate
    if (!applicationCertFiles.olevel) {
        // Check if maybe they already have it
        if (!confirm('Hujapakia O-Level Certificate. Hii ni muhimu. Unataka kuendelea bila hiyo?')) {
            goToApplicationStep(3);
            return;
        }
    }
    
    const submitBtn = document.getElementById('finalSubmitBtn');
    const originalText = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Inatuma...';
    
    try {
        // Collect all data
        const applicationData = {
            admissionWindowId: currentActiveAdmissionWindow.id,
            admissionWindowName: currentActiveAdmissionWindow.name,
            windowNumber: currentActiveAdmissionWindow.windowNumber || 1,
            status: 'pending',
            courseId: selectedApplicationCourse.id,
            courseName: selectedApplicationCourse.name,
            personalInfo: {
                fullName: document.getElementById('appFullName')?.value?.trim() || '',
                email: document.getElementById('appEmail')?.value?.trim() || '',
                phone: document.getElementById('appPhone')?.value?.trim() || '',
                dob: document.getElementById('appDOB')?.value || '',
                gender: document.getElementById('appGender')?.value || '',
                nationality: document.getElementById('appNationality')?.value?.trim() || '',
                address: document.getElementById('appAddress')?.value?.trim() || ''
            },
            kin: {
                name: document.getElementById('appKinName')?.value?.trim() || '',
                relationship: document.getElementById('appKinRelationship')?.value || '',
                phone: document.getElementById('appKinPhone')?.value?.trim() || '',
                email: document.getElementById('appKinEmail')?.value?.trim() || ''
            },
            submittedAt: firebase.firestore.FieldValue.serverTimestamp(),
            reviewedBy: null,
            reviewRemarks: null
        };
        
        // Upload certificates
        if (applicationCertFiles.olevel) {
            const olevelUrl = await uploadApplicationCertificate(applicationCertFiles.olevel, 'olevel');
            applicationData.olevelCertificate = {
                url: olevelUrl,
                fileName: applicationCertFiles.olevel.name,
                uploadedAt: firebase.firestore.FieldValue.serverTimestamp()
            };
        }
        
        if (applicationCertFiles.alevel) {
            const alevelUrl = await uploadApplicationCertificate(applicationCertFiles.alevel, 'alevel');
            applicationData.alevelCertificate = {
                url: alevelUrl,
                fileName: applicationCertFiles.alevel.name,
                uploadedAt: firebase.firestore.FieldValue.serverTimestamp()
            };
        }
        
        // Save to Firestore
        await db.collection('applications').add(applicationData);
        
        // Update admission window count
        await db.collection('admissionWindows').doc(currentActiveAdmissionWindow.id).update({
            applicationCount: firebase.firestore.FieldValue.increment(1),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        
        showToast('✅ Maombi yako yamepokelewa! Utapata taarifa kwa njia ya simu au barua pepe.', 'success');
        
        // Close application window
        setTimeout(() => {
            closeApplicationWindow();
            resetApplicationForm();
        }, 2000);
        
    } catch (error) {
        console.error('Error submitting application:', error);
        showToast('❌ Imeshindwa kutuma maombi: ' + error.message, 'error');
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalText;
    }
}

// ============================================
// UPLOAD APPLICATION CERTIFICATE
// ============================================
async function uploadApplicationCertificate(file, type) {
    const storageRef = firebase.storage().ref();
    const fileName = `applications/certificates/${type}/${Date.now()}_${file.name}`;
    const fileRef = storageRef.child(fileName);
    
    await fileRef.put(file);
    const downloadURL = await fileRef.getDownloadURL();
    
    return downloadURL;
}

// ============================================
// RESET APPLICATION FORM
// ============================================
function resetApplicationForm() {
    selectedApplicationCourse = null;
    applicationCertFiles = { olevel: null, alevel: null };
    
    // Reset form fields
    const formFields = ['appFullName', 'appEmail', 'appPhone', 'appDOB', 'appGender', 
                        'appNationality', 'appAddress', 'appKinName', 'appKinRelationship', 
                        'appKinPhone', 'appKinEmail'];
    formFields.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    
    // Reset file inputs
    ['appOlevelFile', 'appAlevelFile'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    
    // Reset previews
    ['appOlevelPreview', 'appAlevelPreview'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
    
    // Reset course selection
    document.querySelectorAll('.app-course-card').forEach(card => {
        card.style.borderColor = '#e2e8f0';
        card.style.background = 'white';
    });
    
    // Reset next button
    const nextBtn = document.getElementById('appStep1Next');
    if (nextBtn) {
        nextBtn.disabled = true;
        nextBtn.style.opacity = '0.5';
    }
}

// ============================================
// SUPER ADMIN - SAVE ADMISSION WINDOW
// ============================================
async function saveAdmissionWindow() {
    const editId = document.getElementById('admissionWindowEditId')?.value;
    const name = document.getElementById('admissionWindowName')?.value?.trim();
    const windowNumber = document.getElementById('admissionWindowNumber')?.value;
    const academicYear = document.getElementById('admissionAcademicYear')?.value?.trim();
    const startDate = document.getElementById('admissionStartDate')?.value;
    const startTime = document.getElementById('admissionStartTime')?.value;
    const endDate = document.getElementById('admissionEndDate')?.value;
    const endTime = document.getElementById('admissionEndTime')?.value;
    const maxApplications = parseInt(document.getElementById('admissionMaxApplications')?.value) || 0;
    const status = document.getElementById('admissionWindowStatus')?.value;
    const description = document.getElementById('admissionDescription')?.value?.trim();
    
    // Validation
    if (!name) { showToast('Tafadhali weka jina la dirisha', 'error'); return; }
    if (!windowNumber) { showToast('Tafadhali chagua namba ya dirisha', 'error'); return; }
    if (!startDate || !startTime) { showToast('Tafadhali weka tarehe na muda wa kuanza', 'error'); return; }
    if (!endDate || !endTime) { showToast('Tafadhali weka tarehe na muda wa kumaliza', 'error'); return; }
    
    // Get selected courses
    const selectedCourses = [];
    document.querySelectorAll('#admissionCoursesContainer input[type="checkbox"]:checked').forEach(cb => {
        selectedCourses.push(cb.value);
    });
    
    try {
        const windowData = {
            name,
            windowNumber: parseInt(windowNumber),
            academicYear: academicYear || '',
            startDate: firebase.firestore.Timestamp.fromDate(new Date(startDate + 'T' + startTime)),
            endDate: firebase.firestore.Timestamp.fromDate(new Date(endDate + 'T' + endTime)),
            startTime,
            endTime,
            maxApplications: maxApplications || 0,
            courseIds: selectedCourses,
            status,
            description: description || '',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        
        if (editId) {
            await db.collection('admissionWindows').doc(editId).update(windowData);
            showToast('✅ Dirisha limesasishwa!', 'success');
        } else {
            windowData.applicationCount = 0;
            windowData.createdAt = firebase.firestore.FieldValue.serverTimestamp();
            await db.collection('admissionWindows').add(windowData);
            showToast('✅ Dirisha jipya limeongezwa!', 'success');
        }
        
        closeAddAdmissionWindowModal();
        await loadAdmissionWindowsList();
        await checkAdmissionStatus();
        
    } catch (error) {
        console.error('Error saving admission window:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

// ============================================
// LOAD ADMISSION WINDOWS LIST
// ============================================
async function loadAdmissionWindowsList() {
    const container = document.getElementById('admissionWindowsTableBody');
    if (!container) return;
    
    container.innerHTML = '<tr><td colspan="8" class="text-center"><div class="loading-spinner">Inapakia...</div></td></tr>';
    
    try {
        const snapshot = await db.collection('admissionWindows').get();
        
        allAdmissionWindows = [];
        snapshot.forEach(doc => {
            allAdmissionWindows.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by start date
        allAdmissionWindows.sort((a, b) => {
            const dateA = a.startDate?.toDate?.() || new Date(0);
            const dateB = b.startDate?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        // Update stats
        document.getElementById('totalAdmissionWindows').textContent = allAdmissionWindows.length;
        
        const now = new Date();
        let activeCount = 0;
        allAdmissionWindows.forEach(w => {
            const start = w.startDate?.toDate?.() || new Date(0);
            const end = w.endDate?.toDate?.() || new Date(0);
            if (now >= start && now <= end && w.status === 'active') activeCount++;
        });
        document.getElementById('activeAdmissionCount').textContent = activeCount;
        
        // Count total applications
        let totalApps = 0;
        allAdmissionWindows.forEach(w => {
            totalApps += w.applicationCount || 0;
        });
        document.getElementById('totalApplicationsCount').textContent = totalApps;
        
        // Count pending applications
        const pendingSnapshot = await db.collection('applications')
            .where('status', '==', 'pending')
            .get();
        document.getElementById('pendingApplicationsCount').textContent = pendingSnapshot.size;
        
        if (allAdmissionWindows.length === 0) {
            container.innerHTML = '';
            document.getElementById('admissionEmptyState').style.display = 'block';
            return;
        }
        
        document.getElementById('admissionEmptyState').style.display = 'none';
        
        container.innerHTML = allAdmissionWindows.map((window, index) => {
            const startDate = window.startDate?.toDate?.()?.toLocaleDateString('sw-TZ', {
                year: 'numeric', month: 'short', day: 'numeric'
            }) || '-';
            const endDate = window.endDate?.toDate?.()?.toLocaleDateString('sw-TZ', {
                year: 'numeric', month: 'short', day: 'numeric'
            }) || '-';
            const startTime = window.startTime || '00:00';
            const endTime = window.endTime || '23:59';
            
            // Calculate duration
            const durationMs = (window.endDate?.toDate?.() || new Date()) - (window.startDate?.toDate?.() || new Date());
            const durationDays = Math.floor(durationMs / (1000 * 60 * 60 * 24));
            
            // Determine status
            const now = new Date();
            const start = window.startDate?.toDate?.() || new Date(0);
            const end = window.endDate?.toDate?.() || new Date(0);
            let statusClass = 'status-inactive';
            let statusText = 'Inactive';
            
            if (window.status === 'draft') {
                statusClass = 'status-pending';
                statusText = 'Draft';
            } else if (now >= start && now <= end && window.status === 'active') {
                statusClass = 'status-active';
                statusText = '🟢 Active Sasa';
            } else if (now < start && window.status === 'active') {
                statusClass = 'status-pending';
                statusText = '⏰ Inakuja';
            } else if (now > end) {
                statusClass = 'status-inactive';
                statusText = '⏹️ Imemalizika';
            }
            
            return `
                <tr>
                    <td class="text-center">${index + 1}</td>
                    <td>
                        <strong>${escapeHtml(window.name)}</strong>
                        ${window.academicYear ? `<br><small style="color:#64748b;">${escapeHtml(window.academicYear)}</small>` : ''}
                        ${window.windowNumber ? `<br><span style="font-size:0.7rem;background:#e0e7ff;color:#4f46e5;padding:0.1rem 0.5rem;border-radius:1rem;">Dirisha #${window.windowNumber}</span>` : ''}
                    </td>
                    <td class="text-center">
                        <div>${startDate}</div>
                        <small style="color:#64748b;">${startTime}</small>
                    </td>
                    <td class="text-center">
                        <div>${endDate}</div>
                        <small style="color:#64748b;">${endTime}</small>
                    </td>
                    <td class="text-center">Siku ${durationDays}</td>
                    <td class="text-center">
                        <span style="background:#e0e7ff;color:#4f46e5;padding:0.2rem 0.6rem;border-radius:1rem;font-weight:600;">
                            ${window.applicationCount || 0}
                        </span>
                    </td>
                    <td class="text-center">
                        <span class="status-badge ${statusClass}">${statusText}</span>
                    </td>
                    <td class="text-center">
                        <div style="display:flex;gap:0.25rem;justify-content:center;">
                            <button class="btn-action btn-view" onclick="viewAdmissionApplications('${window.id}')" title="Tazama Maombi">
                                <i class="fas fa-list"></i>
                            </button>
                            <button class="btn-action btn-edit" onclick="editAdmissionWindow('${window.id}')" title="Hariri">
                                <i class="fas fa-edit"></i>
                            </button>
                            <button class="btn-action btn-delete" onclick="deleteAdmissionWindow('${window.id}')" title="Futa">
                                <i class="fas fa-trash"></i>
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');
        
    } catch (error) {
        console.error('Error loading admission windows:', error);
        container.innerHTML = `<tr><td colspan="8" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
    }
}

// ============================================
// OPEN ADD ADMISSION WINDOW MODAL
// ============================================
async function openAddAdmissionWindowModal() {
    // Reset form
    document.getElementById('admissionWindowForm').reset();
    document.getElementById('admissionWindowEditId').value = '';
    document.getElementById('admissionWindowModalTitle').textContent = 'Ongeza Dirisha la Maombi';
    document.getElementById('admissionSaveBtnText').textContent = 'Ongeza Dirisha';
    document.getElementById('admissionDeleteBtn').style.display = 'none';
    
    // Load courses
    await loadCoursesForAdmissionWindow();
    
    // Show modal
    document.getElementById('addAdmissionWindowModal').style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

// ============================================
// CLOSE ADD ADMISSION WINDOW MODAL
// ============================================
function closeAddAdmissionWindowModal() {
    document.getElementById('addAdmissionWindowModal').style.display = 'none';
    document.body.style.overflow = '';
    document.getElementById('admissionWindowEditId').value = '';
}

// ============================================
// LOAD COURSES FOR ADMISSION WINDOW
// ============================================
async function loadCoursesForAdmissionWindow(selectedCourseIds = []) {
    const container = document.getElementById('admissionCoursesContainer');
    if (!container) return;
    
    container.innerHTML = '<div class="loading-spinner">Inapakia kozi...</div>';
    
    try {
        const snapshot = await db.collection('courses')
            .where('active', '==', true)
            .get();
        
        if (snapshot.empty) {
            container.innerHTML = '<p style="color:#94a3b8;text-align:center;">Hakuna kozi</p>';
            return;
        }
        
        container.innerHTML = '';
        snapshot.forEach(doc => {
            const course = doc.data();
            const isSelected = selectedCourseIds.includes(doc.id);
            
            container.innerHTML += `
                <label style="display:flex;align-items:center;gap:0.5rem;padding:0.4rem;cursor:pointer;font-size:0.85rem;border-radius:0.3rem;${isSelected ? 'background:#f0fdf4;' : ''}">
                    <input type="checkbox" value="${doc.id}" ${isSelected ? 'checked' : ''} style="accent-color:#e65c1e;">
                    <span><strong>${escapeHtml(course.code)}</strong> - ${escapeHtml(course.name)}</span>
                </label>
            `;
        });
    } catch (error) {
        container.innerHTML = `<p style="color:red;">Kosa: ${error.message}</p>`;
    }
}

// ============================================
// EDIT ADMISSION WINDOW
// ============================================
async function editAdmissionWindow(windowId) {
    const doc = await db.collection('admissionWindows').doc(windowId).get();
    if (!doc.exists) {
        showToast('Dirisha halikupatikana', 'error');
        return;
    }
    
    const window = doc.data();
    
    // Populate form
    document.getElementById('admissionWindowEditId').value = windowId;
    document.getElementById('admissionWindowName').value = window.name || '';
    document.getElementById('admissionWindowNumber').value = window.windowNumber || '';
    document.getElementById('admissionAcademicYear').value = window.academicYear || '';
    document.getElementById('admissionWindowStatus').value = window.status || 'active';
    document.getElementById('admissionDescription').value = window.description || '';
    document.getElementById('admissionMaxApplications').value = window.maxApplications || '';
    
    // Set dates
    if (window.startDate) {
        const startDate = window.startDate.toDate ? window.startDate.toDate() : new Date(window.startDate);
        document.getElementById('admissionStartDate').value = startDate.toISOString().split('T')[0];
        document.getElementById('admissionStartTime').value = window.startTime || '00:00';
    }
    if (window.endDate) {
        const endDate = window.endDate.toDate ? window.endDate.toDate() : new Date(window.endDate);
        document.getElementById('admissionEndDate').value = endDate.toISOString().split('T')[0];
        document.getElementById('admissionEndTime').value = window.endTime || '23:59';
    }
    
    // Load courses with selection
    await loadCoursesForAdmissionWindow(window.courseIds || []);
    
    // Update modal title
    document.getElementById('admissionWindowModalTitle').textContent = 'Hariri Dirisha la Maombi';
    document.getElementById('admissionSaveBtnText').textContent = 'Sasisha Dirisha';
    document.getElementById('admissionDeleteBtn').style.display = 'inline-flex';
    
    // Show modal
    document.getElementById('addAdmissionWindowModal').style.display = 'flex';
    document.body.style.overflow = 'hidden';
}

// ============================================
// DELETE ADMISSION WINDOW
// ============================================
async function deleteAdmissionWindow(windowId) {
    if (!confirm('Una uhakika unataka kufuta dirisha hili? Haiwezi kurejeshwa.')) return;
    
    try {
        await db.collection('admissionWindows').doc(windowId).delete();
        showToast('✅ Dirisha limefutwa!', 'success');
        await loadAdmissionWindowsList();
    } catch (error) {
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

function deleteAdmissionFromEdit() {
    const windowId = document.getElementById('admissionWindowEditId')?.value;
    if (!windowId) return;
    closeAddAdmissionWindowModal();
    deleteAdmissionWindow(windowId);
}

