let applicationCertData = {
    olevel: {
        school: '',
        yearStart: '',
        yearEnd: '',
        indexNumber: '',
        division: '',
        subjects: '',
        file: null
    },
    alevel: {
        school: '',
        yearStart: '',
        yearEnd: '',
        indexNumber: '',
        division: '',
        combination: '',
        subjects: '',
        file: null
    }
};

let otherCertificates = []; // Array for additional certificates
let otherCertCounter = 0;

// ============================================
// AUTO CALCULATE STUDY DURATION
// ============================================
function autoCalculateStudyDuration(type) {
    const yearStart = parseInt(document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}YearStart`)?.value) || 0;
    const yearEnd = parseInt(document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}YearEnd`)?.value) || 0;
    const durationEl = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}Duration`);
    
    if (!durationEl) return;
    
    if (yearStart && yearEnd) {
        const duration = yearEnd - yearStart;
        
        if (duration < 0) {
            durationEl.textContent = '⚠️ Mwaka wa kuanza hauwezi kuwa mkubwa kuliko mwaka wa kumaliza';
            durationEl.style.color = '#ef4444';
        } else if (duration === 0) {
            durationEl.textContent = '📅 Mwaka mmoja (1 year)';
            durationEl.style.color = '#e65c1e';
        } else {
            durationEl.textContent = `📅 Muda wa Masomo: ${duration} miaka (${yearStart} - ${yearEnd})`;
            durationEl.style.color = '#10b981';
        }
    } else {
        durationEl.textContent = '';
    }
}

// ============================================
// ENHANCED CERTIFICATE FILE PREVIEW
// ============================================
function previewAppCertFileEnhanced(event, type) {
    const file = event.target.files[0];
    if (!file) return;
    
    // Validate file type
    const validTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    if (!validTypes.includes(file.type.toLowerCase())) {
        showToast('❌ Aina ya faili haikubaliki. Tumia PDF, JPG, au PNG.', 'error');
        event.target.value = '';
        return;
    }
    
    // Validate file size (5MB max)
    if (file.size > 5 * 1024 * 1024) {
        showToast('❌ Faili ni kubwa sana. Kiwango cha juu ni 5MB.', 'error');
        event.target.value = '';
        return;
    }
    
    // Store file
    applicationCertFiles[type] = file;
    
    // Update preview
    const preview = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}Preview`);
    const fileName = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}FileName`);
    const fileSize = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}FileSize`);
    
    if (preview) preview.style.display = 'block';
    if (fileName) {
        fileName.textContent = file.name;
    }
    if (fileSize) {
        const sizeKB = (file.size / 1024).toFixed(1);
        const sizeMB = (file.size / (1024 * 1024)).toFixed(2);
        fileSize.textContent = sizeKB > 1024 ? `${sizeMB} MB` : `${sizeKB} KB`;
    }
    
    console.log(`✅ Certificate file selected: ${type} - ${file.name}`);
}

// ============================================
// REMOVE CERTIFICATE FILE
// ============================================
function removeAppCertFile(type) {
    applicationCertFiles[type] = null;
    
    // Reset file input
    const fileInput = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}File`);
    if (fileInput) fileInput.value = '';
    
    // Hide preview
    const preview = document.getElementById(`app${type.charAt(0).toUpperCase() + type.slice(1)}Preview`);
    if (preview) preview.style.display = 'none';
    
    console.log(`Certificate file removed: ${type}`);
}

