// ============================================
// CHECK ADMISSION STATUS ON PAGE LOAD - FIXED
// ============================================
async function checkAdmissionStatus() {
    console.log('🔍 Checking admission window status...');
    
    const now = new Date();
    
    try {
        // FIXED: Use simple query without orderBy to avoid composite index requirement
        const snapshot = await db.collection('admissionWindows')
            .where('status', '==', 'active')
            .get();
        
        allAdmissionWindows = [];
        let activeWindow = null;
        
        snapshot.forEach(doc => {
            const window = { id: doc.id, ...doc.data() };
            
            // Parse dates safely
            let startDate, endDate;
            
            // Handle Firestore Timestamp objects
            if (window.startDate) {
                startDate = window.startDate.toDate ? window.startDate.toDate() : new Date(window.startDate);
            } else {
                startDate = new Date(0); // Default to past
            }
            
            if (window.endDate) {
                endDate = window.endDate.toDate ? window.endDate.toDate() : new Date(window.endDate);
            } else {
                endDate = new Date(0);
            }
            
            // Combine with times
            if (window.startTime) {
                const [h, m] = window.startTime.split(':').map(Number);
                if (!isNaN(h) && !isNaN(m)) {
                    startDate.setHours(h, m, 0, 0);
                }
            }
            if (window.endTime) {
                const [h, m] = window.endTime.split(':').map(Number);
                if (!isNaN(h) && !isNaN(m)) {
                    endDate.setHours(h, m, 0, 0);
                }
            }
            
            // Check if currently active
            const isActive = now >= startDate && now <= endDate;
            
            if (isActive) {
                activeWindow = window;
            }
            
            // Store for reference
            allAdmissionWindows.push({
                ...window,
                isActive: isActive,
                expiryDate: endDate,
                parsedStartDate: startDate,
                parsedEndDate: endDate
            });
        });
        
        // Sort manually in JavaScript (no Firestore index needed)
        allAdmissionWindows.sort((a, b) => {
            const dateA = a.parsedStartDate || new Date(0);
            const dateB = b.parsedStartDate || new Date(0);
            return dateB - dateA;
        });
        
        currentActiveAdmissionWindow = activeWindow;
        
        // Update UI
        updateAdmissionUI(activeWindow);
        
        // Start countdown timer if active
        if (activeWindow && activeWindow.expiryDate) {
            startAdmissionCountdown(activeWindow.expiryDate);
        }
        
        console.log('✅ Admission status checked:', activeWindow ? `ACTIVE - ${activeWindow.name}` : 'NO ACTIVE WINDOW');
        console.log(`Total windows loaded: ${allAdmissionWindows.length}`);
        
    } catch (error) {
        console.error('Error checking admission:', error);
        console.log('Error details:', {
            message: error.message,
            code: error.code,
            name: error.name
        });
        
        // If it's an index error, show user-friendly message
        if (error.code === 'failed-precondition' || error.message?.includes('index')) {
            console.warn('⚠️ Firestore index required. Follow the link above to create it.');
            showToast('⚠️ Mfumo unahitaji kusasishwa. Tafadhali wasiliana na msimamizi.', 'warning');
        }
        
        // Set defaults to prevent UI breakage
        currentActiveAdmissionWindow = null;
        updateAdmissionUI(null);
    }
}

// ============================================
// LOAD ADMISSION WINDOWS LIST - FIXED
// ============================================
async function loadAdmissionWindowsList() {
    const container = document.getElementById('admissionWindowsTableBody');
    if (!container) return;
    
    container.innerHTML = '<tr><td colspan="8" class="text-center"><div class="loading-spinner">Inapakia...</div></td></tr>';
    
    try {
        // FIXED: Simple query without orderBy to avoid composite index requirement
        const snapshot = await db.collection('admissionWindows').get();
        
        allAdmissionWindows = [];
        snapshot.forEach(doc => {
            const data = doc.data();
            allAdmissionWindows.push({ 
                id: doc.id, 
                ...data,
                // Pre-parse dates for sorting
                parsedStartDate: data.startDate?.toDate?.() || new Date(data.startDate || 0),
                parsedEndDate: data.endDate?.toDate?.() || new Date(data.endDate || 0)
            });
        });
        
        // Sort manually in JavaScript
        allAdmissionWindows.sort((a, b) => {
            return (b.parsedStartDate || new Date(0)) - (a.parsedStartDate || new Date(0));
        });
        
        // Update stats
        updateAdmissionStats();
        
        if (allAdmissionWindows.length === 0) {
            container.innerHTML = '';
            const emptyState = document.getElementById('admissionEmptyState');
            if (emptyState) emptyState.style.display = 'block';
            return;
        }
        
        const emptyState = document.getElementById('admissionEmptyState');
        if (emptyState) emptyState.style.display = 'none';
        
        // Render table
        renderAdmissionTable(allAdmissionWindows);
        
    } catch (error) {
        console.error('Error loading admission windows:', error);
        
        if (error.code === 'failed-precondition' || error.message?.includes('index')) {
            container.innerHTML = `<tr><td colspan="8" class="text-center">
                <div style="padding:2rem;text-align:center;">
                    <i class="fas fa-exclamation-triangle" style="font-size:2rem;color:#f59e0b;margin-bottom:0.5rem;"></i>
                    <p style="color:#64748b;">Firestore index inahitajika.</p>
                    <p style="font-size:0.8rem;color:#94a3b8;">Tafadhali fungua link kwenye console kuunda index.</p>
                    <button onclick="loadAdmissionWindowsList()" class="btn-retry" style="margin-top:0.5rem;">
                        <i class="fas fa-redo"></i> Jaribu Tena
                    </button>
                </div>
            </td></tr>`;
        } else {
            container.innerHTML = `<tr><td colspan="8" class="text-center error-text">Kosa: ${error.message}</td></tr>`;
        }
    }
}

// ============================================
// UPDATE ADMISSION STATS
// ============================================
async function updateAdmissionStats() {
    // Update window counts
    const totalEl = document.getElementById('totalAdmissionWindows');
    if (totalEl) totalEl.textContent = allAdmissionWindows.length;
    
    const now = new Date();
    let activeCount = 0;
    
    allAdmissionWindows.forEach(w => {
        if (w.parsedStartDate && w.parsedEndDate) {
            if (now >= w.parsedStartDate && now <= w.parsedEndDate && w.status === 'active') {
                activeCount++;
            }
        }
    });
    
    const activeEl = document.getElementById('activeAdmissionCount');
    if (activeEl) activeEl.textContent = activeCount;
    
    // Count total and pending applications
    try {
        const appsSnapshot = await db.collection('applications').get();
        const totalApps = appsSnapshot.size;
        
        let pendingCount = 0;
        appsSnapshot.forEach(doc => {
            if (doc.data().status === 'pending') pendingCount++;
        });
        
        const totalAppsEl = document.getElementById('totalApplicationsCount');
        if (totalAppsEl) totalAppsEl.textContent = totalApps;
        
        const pendingEl = document.getElementById('pendingApplicationsCount');
        if (pendingEl) pendingEl.textContent = pendingCount;
    } catch (error) {
        console.log('Could not fetch application counts:', error);
    }
}

// ============================================
// RENDER ADMISSION TABLE
// ============================================
function renderAdmissionTable(windows) {
    const container = document.getElementById('admissionWindowsTableBody');
    if (!container) return;
    
    const now = new Date();
    
    container.innerHTML = windows.map((window, index) => {
        const startDate = window.parsedStartDate?.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric'
        }) || '-';
        
        const endDate = window.parsedEndDate?.toLocaleDateString('sw-TZ', {
            year: 'numeric', month: 'short', day: 'numeric'
        }) || '-';
        
        const startTime = window.startTime || '00:00';
        const endTime = window.endTime || '23:59';
        
        // Calculate duration in days
        const durationMs = (window.parsedEndDate || new Date()) - (window.parsedStartDate || new Date());
        const durationDays = Math.max(0, Math.floor(durationMs / (1000 * 60 * 60 * 24)));
        
        // Determine status
        let statusClass = 'status-inactive';
        let statusText = 'Inactive';
        
        if (window.status === 'draft') {
            statusClass = 'status-pending';
            statusText = '📝 Draft';
        } else if (window.parsedStartDate && window.parsedEndDate) {
            if (now >= window.parsedStartDate && now <= window.parsedEndDate && window.status === 'active') {
                statusClass = 'status-active';
                statusText = '🟢 Active Sasa';
            } else if (now < window.parsedStartDate && window.status === 'active') {
                statusClass = 'status-pending';
                statusText = '⏰ Inakuja';
            } else if (now > window.parsedEndDate) {
                statusClass = 'status-inactive';
                statusText = '⏹️ Imemalizika';
            }
        }
        
        return `
            <tr>
                <td class="text-center">${index + 1}</td>
                <td>
                    <strong>${escapeHtml(window.name || 'Unnamed')}</strong>
                    ${window.academicYear ? `<br><small style="color:#64748b;">${escapeHtml(window.academicYear)}</small>` : ''}
                    ${window.windowNumber ? `<br><span style="font-size:0.7rem;background:#e0e7ff;color:#4f46e5;padding:0.1rem 0.5rem;border-radius:1rem;">Dirisha #${window.windowNumber}</span>` : ''}
                </td>
                <td class="text-center">
                    <div>${startDate}</div>
                    <small style="color:#64748b;">${startTime}</small>
                </td>
                <td class="text-center">
                    <div>${endDate}</div>
                    <small style="color:#64748b;">${endTime}</small>
                </td>
                <td class="text-center">Siku ${durationDays}</td>
                <td class="text-center">
                    <span style="background:#e0e7ff;color:#4f46e5;padding:0.2rem 0.6rem;border-radius:1rem;font-weight:600;">
                        ${window.applicationCount || 0}
                    </span>
                </td>
                <td class="text-center">
                    <span class="status-badge ${statusClass}">${statusText}</span>
                </td>
                <td class="text-center">
                    <div style="display:flex;gap:0.25rem;justify-content:center;">
                        <button class="btn-action btn-view" onclick="viewAdmissionApplications('${window.id}')" title="Tazama Maombi">
                            <i class="fas fa-list"></i>
                        </button>
                        <button class="btn-action btn-edit" onclick="editAdmissionWindow('${window.id}')" title="Hariri">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="btn-action btn-delete" onclick="deleteAdmissionWindow('${window.id}')" title="Futa">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

// ============================================
// VIEW ADMISSION APPLICATIONS
// ============================================
async function viewAdmissionApplications(windowId) {
    try {
        const snapshot = await db.collection('applications')
            .where('admissionWindowId', '==', windowId)
            .get();
        
        if (snapshot.empty) {
            showToast('Hakuna maombi kwa dirisha hili.', 'info');
            return;
        }
        
        // Store for use in modal
        window._currentAdmissionApplications = [];
        snapshot.forEach(doc => {
            window._currentAdmissionApplications.push({ id: doc.id, ...doc.data() });
        });
        
        // Sort by submission date
        window._currentAdmissionApplications.sort((a, b) => {
            const dateA = a.submittedAt?.toDate?.() || new Date(0);
            const dateB = b.submittedAt?.toDate?.() || new Date(0);
            return dateB - dateA;
        });
        
        // Show applications
        let html = '<h4>Maombi Yaliyopokelewa</h4>';
        html += `<p>Jumla: <strong>${window._currentAdmissionApplications.length}</strong> maombi</p>`;
        
        window._currentAdmissionApplications.forEach((app, idx) => {
            const statusColors = {
                'pending': { bg: '#fef3c7', text: '#92400e', label: 'Inasubiri' },
                'approved': { bg: '#dcfce7', text: '#166534', label: 'Imekubaliwa' },
                'rejected': { bg: '#fee2e2', text: '#991b1b', label: 'Imekataliwa' },
                'under_review': { bg: '#e0e7ff', text: '#4f46e5', label: 'Inapitiwa' }
            };
            const sc = statusColors[app.status] || statusColors['pending'];
            
            html += `
                <div style="background:white;border:1px solid #e2e8f0;border-radius:0.75rem;padding:1rem;margin-bottom:0.75rem;">
                    <div style="display:flex;justify-content:space-between;align-items:start;">
                        <div>
                            <strong>${idx + 1}. ${escapeHtml(app.personalInfo?.fullName || 'Unknown')}</strong>
                            <br><small>📧 ${escapeHtml(app.personalInfo?.email || '-')} | 📱 ${escapeHtml(app.personalInfo?.phone || '-')}</small>
                            <br><small>📚 ${escapeHtml(app.courseName || '-')}</small>
                            <br><small>📅 ${app.submittedAt?.toDate?.()?.toLocaleDateString('sw-TZ') || '-'}</small>
                        </div>
                        <span style="background:${sc.bg};color:${sc.text};padding:0.2rem 0.6rem;border-radius:1rem;font-size:0.7rem;font-weight:600;">${sc.label}</span>
                    </div>
                </div>
            `;
        });
        
        showApplicationModal(html);
        
    } catch (error) {
        console.error('Error:', error);
        showToast('❌ Kosa: ' + error.message, 'error');
    }
}

function showApplicationModal(content) {
    // Create simple modal
    const modal = document.createElement('div');
    modal.style.cssText = `
        position:fixed;top:0;left:0;width:100%;height:100%;
        background:rgba(0,0,0,0.5);z-index:9999;
        display:flex;align-items:center;justify-content:center;
    `;
    modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
    
    modal.innerHTML = `
        <div style="background:white;border-radius:1rem;width:90%;max-width:700px;max-height:80vh;overflow-y:auto;padding:1.5rem;" onclick="event.stopPropagation()">
            ${content}
            <div style="text-align:right;margin-top:1rem;">
                <button onclick="this.closest('[style*=\\'position:fixed\\']').remove()" 
                        style="background:#e65c1e;color:white;border:none;padding:0.5rem 1.5rem;border-radius:0.5rem;cursor:pointer;">
                    <i class="fas fa-times"></i> Funga
                </button>
            </div>
        </div>
    `;
    
    document.body.appendChild(modal);
}